\section{Proof of Theorem 1 }

The successful transmission probability as implied in (2) is the probability of having $P(\xi) = \mathbb{P} ({\rm SINR} \geq \xi)$ where $\xi$ is a predefined threshold. Let $g$ be a normalized gamma random variable with parameter $N$. For a constant $\mu > 0$ , the probability $\mathbb{P}(g  > \mu)$ can be tightly upper bounded as given by  (\ref{eqCoverageLambda}), where $a = N(N!^{-1/N})$ \cite{sigmaLemma}.
\begin{equation}
    \mathbb{P}(g < \mu) < [1 - e^{-a \mu}]^N
    \tag{26} \label{eqCoverageLambda}
\end{equation}
Based on that, we can rewrite (2) as given by (\ref{eqCoverageA}), where $M_n(\xi) = - \frac{\eta_L n r_0^{\alpha_L}\xi}{C_L M_r M_w}$.
\small
\begin{align}
p_s &= \mathbb{P}\left\{h_0 \geq \frac{R_0^\alpha \xi (\sigma^2 + I_L + I_N)}{(C_L M_r M_w)} \right\} \notag \\
&= 1 - \mathbb{E}_{\Phi}\Bigg\{\Bigg(1 - e^{M_n(\xi)(\sigma^2 + I_L + I_N)}\Bigg)^{N_L}\Bigg\} \notag \\
&\overset{(a)}{=}\sum_{n=1}^{N_L}(-1)^{n+1} {N_L \choose n} \mathbb{E}_{\Phi}\Bigg[ e^{M_n(\xi)(\sigma^2 + I_L + I_N)}\Bigg] \notag \\
&\overset{(b)}{=}\sum_{n=1}^{N_L}(-1)^{n+1} {N_L \choose n}
    e^{M_n(\xi)\sigma^2}
    \mathbb{E}_{\Phi_L}\Bigg[e^{M_n(\xi)I_L}\Bigg] \mathbb{E}_{\Phi_N}\Bigg[e^{M_n(\xi)I_N}\Bigg] 
  \tag{27}\label{eqCoverageA}
%(1)
\end{align}
\normalsize
(a) follows from the Binomial theorem based on the assumption that $N_L$ is an integer,  (b) comes from the fact that $\Phi_L$ and $\Phi_N$ are independent PPPs. To work on that more, we apply some concepts from stochastic geometry to compute the LoS interfering term $\mathbb{E}_{\Phi_L}\Bigg[e^{M_n(\xi)I_L}\Bigg]$ in (\ref{eqCoverageA}) as given in  (\ref{eqCoverageB}), where $g$ in  (c) is normalized gamma random variable with parameter $N_L$, $\bar{a}_k = \frac{a_k}{M_r M_w}$, $b_k$ and $a_k$ for $1\leq k\leq 4$ is defined in Table I.



\begin{align}
     &\mathbb{E}_{\Phi_L}\Bigg[ \exp\{- \frac{\eta_L n r_0^\alpha \xi I_L}{C_L M_r M_w}\}\Bigg] \notag \\ 
     &= \mathbb{E}_{\Phi_L}\Bigg[ \exp\{- \frac{\eta_L n r_0^\alpha \xi \sum_{i>0:{ x_i}\in\Phi_L} h_i D_i \left\|{x}_i\right\|^{-\alpha_L}}{M_r M_w}\}\Bigg] \notag \\
     &\overset{(c)}{=} \exp\left\{ -2 \pi \nu_r  \sum_{k=1}^4{b_k \int\limits_{0}^{R_L} \Bigg( 1 - \mathbb{E}_g \Big[ e^{-n \xi \eta_L g \bar{a}_k (\frac{r_0}{x})^{\alpha_L}} \Big] \Bigg)dx} \right\} \notag \\ 
    & \overset{(d)}{=}  e^{ \Bigg\{ -2 \pi \nu_r  \sum_{k=1}^4 b_k \int_{0}^{R_L}\Bigg( x - x/ \Big(1 + \frac{\eta_L \bar{a}_k n \xi (\frac{r_0}{x})^{\alpha_L}}{N_L}\Big)^{N_L}\Bigg)dx \Bigg\} } \notag \\ 
    &= e^{-W_n(\xi)}   \tag{28}\label{eqCoverageB}
\end{align}

 (c) follows from the probability generating functional of the PPP $\Phi_L$ \cite{cite26}, and (d) follows from computing the moment generating function of the gamma random variable g, and $\eta_L = N_L(N_L!)^{-1/N_L}$.
Likewise, for the NLoS interference $\mathbb{E}_{\Phi_N}\Bigg[e^{M_n(\xi)I_N}\Bigg]$, the small-scale fading term $g$ is a normalized gamma random variable with parameter $N_N$. Thus, it can be computed as (\ref{eqCoverageC}).

\begin{align}
 & \mathbb{E}_{\Phi_N}\Bigg[ \exp\{- \frac{n \eta_L r_0^{\alpha_L} \xi I_N}{C_L M_r M_w}\}\Bigg] \notag \\
  &= \mathbb{E}_{\Phi_N}\Bigg[ \exp\{- \frac{n \eta_L C_N r_0^{\alpha_L} \xi \sum_{i>0:{y_i} \in \Phi_N} g_i D_i \left\|{y}_i\right\|^{-\alpha_N}}{C_L M_r M_w}\}\Bigg] \notag \\
 &= e^{  \Bigg\{ -2 \pi   \nu_r  \sum_{k=1}^4 b_k \int_{R_L}^{\infty}\Bigg( x - x/ \Big(1 + \frac{\eta_L \bar{a}_k n \xi C_N r_0^{\alpha_L}}{C_L x^{\alpha_N} N_N}\Big) ^ {N_N}\Bigg) \Bigg\}} \notag
\\
&=e^{-Z_n(\xi)}  \tag{29}\label{eqCoverageC}
\end{align}


After that, combining (\ref{eqCoverageB}) and (\ref{eqCoverageC}) with (\ref{eqCoverageA}) will give us the closed form to calculate the successful allocation probability between requester x and worker y as given by (\ref{eqCoverageAllXY}).

\begin{equation}
p_{s_{xy}}(\xi) = \sum_{n=1}^{N_L}(-1)^{n+1} {N_L \choose n}
 e^{M_n(\xi) - W_n(\xi) - D_n(\xi)}
  \tag{30} \label{eqCoverageAllXY}
%(1)
\end{equation}

The distance between requester x and worker y is a random variable denoted by $r_0$, consequently, the average allocation probability for a randomly picked worker is presented as given by  (\ref{coverage_ps}).

\begin{equation}
p_s = \int_{0}^{R_L}\sum_{n=1}^{N_L} {N_L \choose n}
 \frac{2 r_0 (-1)^{n+1} e^{M_n(\xi)\sigma^2 - W_n(\xi) - Z_n(\xi)}}{R_L^2}dr_0
  \tag{31} \label{coverage_ps}
\end{equation}




\section{Proof of Theorem 2}

Let $\mathcal{S}_A = \mathcal{S}\setminus (n,0)$ be the entire state space of the ACTMC excluding the absorbing state. Then, the time to absorption from a state ${\bf z}_i \in \mathcal{S}_A$ is given by (\ref{average_time_1}), where $\bf P$ is the EDTMC given in (10), $t_{{\bf z}_i,{\bf z}_j}$ is given from (13), and $T_{\bf{z}_j}$ is the time until absorption starting from state $\bf{z}_j$.

\begin{equation}
    T_{{\bf z}_i} = \sum_{{\bf z}_j \in \mathcal{S}_A}{\bf P}({\bf z}_i, {{\bf z}_j})(t_{{\bf z}_i,{\bf z}_j} + T_{{\bf z}_j}).
      \tag{32} \label{average_time_1}
\end{equation}

For every $\bf{z}_i \neq \bf{z}_s$, where $\bf{z}_s$ is the absorption state, ${\bf T} = (T_{\bf{z}_i})_{\!\!\ \bf{z}_i \neq \bf{z}_s}$ solves  (\ref{average_time_2}), where ${\bf P}_T = {\bf P}({\bf z_i, z_j})_{\!\ 0 \leq i,j \leq n-1}$ is the transition probability of the transient states, and ${\bf w}$ is the average state sojourn time column vector, where ${\bf w}_{\bf{z}_i} = \sum_{\bf{z}_j}{\bf P}(\bf{z}_i, \bf{z}_j)/Q(\bf{z}_i, \bf{z}_j)$.
\begin{equation}
    {\bf T} = {\bf w} + {\bf P}_T {\bf T}
     \tag{33} \label{average_time_2}
\end{equation}
(\ref{average_time_2}) can also be written as given by (\ref{average_time_3}).

\begin{equation}
    {\bf T} = ({\bf I} - {\bf P}_T)^{-1} {\bf w},
     \tag{34} \label{average_time_3}
\end{equation}
where  ${\bf T}$ is a column vector whose values are the average time until absorption starting from any state $\bf z_i$. To get the time from the first state, we multiply ${\bf T}$ by $\boldsymbol{\alpha}$ to get (14).


\section{Proof of Theorem 3}

The PDF of an ordered EEDs based on their distance is given in (\ref{order_statistic_PDF}), where, $f_X(x)$ and $F_X(x)$ are the PDF, and the CDF of the distance, and $n$ is a Poisson random variable with mean $\nu_w \pi R_L^2$, which represents the average number of LoS EEDs, $k$ is the order of the desired EED.

\begin{equation}
    f_{X_{(k)}}(x) = \frac{n!}{(k-1)!(n-k)!} f_X(x) [F_X(x)]^{k-1} [1 - F_X(x)]^{n-k}
    \tag{35}  \label{order_statistic_PDF}
\end{equation}
Since $n$ follows the Poisson distribution, this can be written as (\ref{poisson_ordered}), where $V = \pi \nu_w R_L^2$.
\begin{align}
    f_{X_{(k)}}(x|n) &= \mathbb{E}[f_{X_{(k)}}(x | n)] \notag \\
    &= \sum_{i=0}^{\infty} \frac{V^i f_r(x | i)}{i!} e^{-V} 
     \tag{36} \label{poisson_ordered}
\end{align}
By embedding the order statistics, $f_{X_{(k)}}(x|n)$ can be given by (\ref{poisson_ordered_fx}).
\small
\begin{align}
    f_{X_{(k)}}(x | n) &= \sum_{i=0}^{\infty} \frac{V^i \frac{i!}{(k-1)!(i-k)!} f_X(x) [F_X(x)]^{k-1} [1 - F_X(x)]^{i-k} }{i!} e^{-V} \notag\\
    &= \frac{V^{k} e^{-V} f(x) F(X)^{k-1}}{(k-1)!} \sum_{i=0}^{\infty} \frac{V^{i-k} [1 - F(x)]^{i-k}}{(i-k)!}
     \tag{37} \label{poisson_ordered_fx}
\end{align}
\normalsize
Moreover, let $a = i-k$. Thus, when $i = 0$, $a = -k$. Consequently:
\small
\begin{equation}
     \sum_{i=0}^{\infty} \frac{V^{i-k} [1 - F(x)]^{i-k}}{(i-k)!} = \sum_{a=0}^{\infty} \frac{V^{a} [1 - F(x)]^{a}}{(a)!} + \sum_{a=-k}^{-1} \frac{V^{a} [1 - F(x)]^{a}}{(a)!}
      \tag{38} \label{coverage_tylor_ordered}
\end{equation}
\normalsize
This part follows Taylor Series expansions of exponential functions. Accordingly, the final form of $f_{X_{(k)}}(x | n)$ is given by (\ref{coverage_ordered_final}). The remaining part of the proof has already been provided in the proof of Theorem 1.


% \begin{equation}
%       f_{X_{(r)}}(x | n) = \frac{V^{r} e^{-V} \frac{2R_0}{R_L^2} (\frac{R_0^2}{R_L^2})^{r-1}}{(r-1)!} e^{-V [\frac{R_0^2 - R_L^2}{R_L^2}]}
% \end{equation}

\begin{equation}
      f_{X_{(k)}}(x | n) = \frac{V^{k} e^{-V} f(x) F(X)^{k-1}}{(k-1)!} e^{-V [F(x) - 1]}
       \tag{39} \label{coverage_ordered_final}
\end{equation}





