\subsection{Post-Recommendation Agent Behavior.}
To further assess how social interactions affect downstream agent dynamics, we analyze four key behavioral indicators across all models and interaction rounds: personality change, satisfaction ratio, acceptance rate, and negative review rate.

\begin{definition}[Personality Change]
Personality Change $\Delta_{\text{personality}}$ is defined as the average $\ell_2$ distance between each agent's final and initial Big-Five personality vectors:
\begin{equation}
    \Delta_{\text{personality}} = \frac{1}{|\mathcal{V}|} \sum_{u \in \mathcal{V}} \left\| \mathbf{b}_u^{\text{(final)}} - \mathbf{b}_u^{\text{(init)}} \right\|_2.
\end{equation}

This metric captures the extent to which an agent's personality representation has evolved after social recommendation interactions.
\end{definition}

% \begin{definition}[Interest Stability]
% Interest Stability $S_{\text{interest}}$ quantifies the consistency of an agent's item preferences before and after interaction, using Jaccard similarity between their initial and final liked item sets:
% \[
% S_{\text{interest}} = \frac{1}{|\mathcal{V}|} \sum_{u \in \mathcal{V}} \frac{|\mathcal{M}_u^{\text{(final)}} \cap \mathcal{M}_u^{\text{(init)}}|}{|\mathcal{M}_u^{\text{(final)}} \cup \mathcal{M}_u^{\text{(init)}}|}.
% \]
% \end{definition}

\begin{definition}[Satisfaction Ratio]
Satisfaction Ratio $S_{\text{sat}}$ denotes the average score agents assign to liked items, reflecting their alignment with user preference:
\begin{equation}
    S_{\text{sat}} = \frac{1}{|\mathcal{V}|} \sum_{u \in \mathcal{V}} \frac{1}{|\mathcal{A}_u|} \sum_{m \in \mathcal{A}_u} \text{score}_{u,m},
\end{equation}


where $\mathcal{A}_u = \{m \mid \text{score}_{u,m} \geq 3\}$ is the set of items liked by agent $u$ (i.e., rated 3–5), and $\text{score}_{u,m} \in \{0,1,2,3,4,5\}$.
\end{definition}

\begin{definition}[Negative Review Rate]
Exit Rate $N_{\text{exit}}$ measures the proportion of agents whose ratings for all recommended items fall below the acceptance threshold:
\begin{equation}
 N_{\text{neg}} = \frac{|\{u \in \mathcal{V} \mid \forall m \in \mathcal{R}_u, \text{score}_{u,m} \leq 2\}|}{|\mathcal{V}|},   
\end{equation}

where $\mathcal{R}_u$ is the set of items recommended to agent $u$. A higher value indicates dissatisfaction or poor personalization.
\end{definition}

\begin{definition}[Acceptance Rate]
Acceptance Rate $A_{\text{rate}}$ measures the proportion of recommended movies that were accepted (i.e., watched) by the agent population:
\begin{equation}
    A_{\text{rate}} = \frac{1}{|\mathcal{V}|} \sum_{u \in \mathcal{V}} \frac{|\mathcal{A}_u|}{|\mathcal{R}_u|},
\end{equation}

where $\mathcal{A}_u$ is the set of movies accepted (rated $\geq 3$) by agent $u$, and $\mathcal{R}_u$ is the set of all movies recommended to $u$. This metric serves as a proxy for user engagement and perceived relevance of the recommendations.
\end{definition}

