\begin{lemma}
    \label{lemma:smallness-derivation}
    Let $f : \Mcal \to [0,1]$ be a smooth function on a $d$-dimensional Riemannian manifold $\Mcal$.
    Then,
    \[
        \int_{0}^1 \Hcal^d\big(
        \{f > \lambda\}
        \big) \; \dsf \lambda
        \;\; = \;\;
        \|f\|_1.
    \]
\end{lemma}
\begin{proof}
    We simply compute
    \begin{align*}
        \int_{0}^1 \Hcal^d\big(
        \{f > \lambda\}
        \big) \; \dsf \lambda
         & =
        \int_{\lambda \in [0,1]}
        \int_{x \in \Mcal}
        \mathbf{1}_{\{f > \lambda\}}(x)\;
        \dsf x\;
        \dsf \lambda \\
         & =
        \int_{x \in \Mcal}
        \int_{\lambda \in [0,1]}
        \mathbf{1}_{\{f > \lambda\}}(x)\;
        \dsf \lambda\;
        \dsf x       \\
         & =
        \int_{x \in \Mcal}
        f(x)\;
        \dsf x
        = \|f\|_1,
    \end{align*}
    where in the second equality we used Fubini's theorem.
\end{proof}

\begin{lemma}
    \label{lemma:technical-result-regularity-loss}
    Let $f : \Mcal \to \Rbb$ be a smooth function on a Riemannian manifold.
    If $\nabla f$ does not vanish on $\{f = \lambda\}$, then $\partial \{f > \lambda\} = \{f = \lambda\}$.
\end{lemma}
\begin{proof}
    The left-to-right inclusion follows immediately from the fact that $f$ is continuous:
    \[
        \partial \{f > \lambda\} = \overline{\{f > \lambda\}} \setminus \{f > \lambda\} \subseteq \{f \geq \lambda\} \setminus \{f > \lambda\} = \{f = \lambda\}.
    \]

    For the right-to-left inclusion, it suffices to prove that
    $\{f = \lambda\} \subseteq \overline{\{f > \lambda\}}$.
    So, given $x \in \{f = \lambda\}$ we must show that every open neighborhood $U$ of $x$ intersects $\{f > \lambda\}$.
    Towards a contradiction, assume that there exists an open neighborhood $U$ of $x$ entirely contained in $\{f \leq \lambda\}$.
    Then $x$ is a maximum of $f$ restricted to $U$, and thus $\nabla f$ vanishes on $x$, a contradiction.
    % https://math.stackexchange.com/questions/4807568/given-nonvanishing-gradient-determine-if-bdy-fa-f-a?noredirect=1&lq=1
\end{proof}

\begin{lemma}
    \label{lemma:regularity-derivation}
    If $f : \Mcal \to \Rbb$ is a smooth function on a Riemannian manifold, then
    \[
        \int_0^1 \;\Hcal^{d-1}\big(\, \partial \SupLevel{f}{\lambda}\, \big)\; \dsf \lambda \;=\; \|\nabla f\|_1\,.
    \]
\end{lemma}
\begin{proof}
    We claim that $\partial \SupLevel{f}{\lambda} = \{f = \lambda\}$ for almost every $\lambda \in \Rbb$;
    the statement of the lemma follows from this claim and the coarea formula,
    which in this case says that $\int_0^1 \Hcal^{d-1}\big( \{f = \lambda\}  \big) \dsf \lambda = \|\nabla f\|_1$ (see, e.g., Appendix~A of \cite{jost-jost}, for a proof of the coarea formula).
    So let us prove the claim.
    By Saard's theorem, the set of critical values of $f$ has measure zero.
    This implies that $\nabla f$ does not vanish on almost every level set $\{f = \lambda\}$, which implies our claim, thanks to \cref{lemma:technical-result-regularity-loss}.
\end{proof}

