\section{Conclusion}

We proposed and analyzed a subgradient algorithm for non-smooth system identification of linear-time invariant systems with disturbances following a probabilistic sparsity model. While the non-asymptotic theory for this setting is well-established in the literature, existing methods rely on solvers that use primal-dual interior-point methods for second-order conic programs, leading to high computational costs. To address this, we proposed a subgradient method that enables fast exact recovery. We demonstrated that the subgradient method with the best and Polyak step sizes converges linearly to the ground-truth system dynamics after a burn-in period. Additionally, we showed that constant and diminishing step sizes lead to convergence within a neighborhood of the true solution, with the best average sub-optimality gap asymptotically approaching zero. These theoretical results are supported by numerical simulations.

Our experiments also highlight the practical effectiveness of the backtracking step size, suggesting it as a promising alternative. However, its theoretical properties remain an open question. Furthermore, our current implementation computes the full subgradient at each iteration. To improve time complexity, a partial subgradient approach, similar to stochastic gradient descent, could be explored. 

\section{Appendix}

\subsection{Proof of Theorem \ref{thm:angle-cosine}} \label{app:proof}

\begin{proofnew}
    Using the subgradient update iteration at time $T$, $\hat A^{(T+1)} = \hat A^{(T)} - \beta^{(T)}G_{\hat A^{(T)}, T} $, we have
    %
    \begin{align}
        \| \hat A^{(T+1)} - \bar A \|_F^2 & = \| (\hat A^{(T)}-  \bar A) - \beta^{(T)}G_{\hat A^{(T)}, T}  \|_F^2 \notag \\
        & = \| \hat A^{(T)}-  \bar A \|_F^2 + (\beta^{(T)})^2\| G_{\hat A^{(T)}, T} \|_F^2 \notag  \\
         & - 2 \beta^{(T)} \langle  G_{\hat A^{(T)}, T}, \hat A^{(T)}-  \bar A\rangle. \label{expansion}
    \end{align}
    %
    Substituting the step size stated in the theorem yields
    %
    \begin{align*}
        \| \hat A^{(T+1)} - \bar A \|_F^2 & = \| \hat A^{(T)}-  \bar A \|_F^2 - \frac{ (\langle G_{\hat A^{(T)}, T}, \hat A^{(T)} - \bar A \rangle)^2}{\|G_{\hat A^{(T)}, T}\|_F^2} \\
        &
         \le \sqrt{1 - \cos^2({\hat \theta_T})} \| \hat A^{(T)}- \bar A \|_F.
    \end{align*}
    % 
    The last inequality uses the  fact that $\langle G_{\hat A^{(T)}, T}, \hat A^{(T)} - \bar A \rangle = \| G_{\hat A^{(T)}, T}\|_F \| \hat A^{(T)} - \bar A\|_F \cos({\hat \theta_T})$.
\end{proofnew}

\subsection{Proof of Theorem \ref{thm:cosine-lower-bound}}

\begin{proofnew}
    Using Lemma \ref{lem: subgradient-ineq}, we can show that
    %
    \begin{align*}
        \cos({\hat \theta_T}) = \frac{ \langle  \hat{A}^{(T)} - \bar A, G_{\hat{A}^{(T)}, T} \rangle}{\| \hat{A}^{(T)} - \bar A\|_F \| G_{\hat{A}^{(T)}, T} \|_F} 
         \ge \frac{f_T(\hat A^{(T)}) - f_T(\bar A)}{\| \bar A - \hat{A}^{(T)}\|_F \| G_{\hat{A}^{(T)}, T} \|_F}.
    \end{align*}
    %
    We lower bound the difference between the objectives as
    %
    \begin{align*}
        & f_T(\hat A^{(T)}) - f_T(\bar A)  \ge \sup_{ G_{\bar A,T} \in \partial f_T(\bar A) } \left\{ \langle  \hat{A}^{(T)} - \bar A, G_{\bar A, T} \rangle \right\} \\
        & =  \sup_{ \|e_t\|\le 1, t \not \in \mathcal{K} } \left\{ \left \langle  \hat{A}^{(T)} - \bar A, -\sum_{t \in \mathcal{K}}  \hat d_t \otimes x_t - \sum_{t \not \in \mathcal{K}} e_t  \otimes x_t \right\rangle \right\}  \\
        & = \sum_{t \in \mathcal{K}} \left\langle  (\bar A -\hat{A}^{(T)}) x_t , \frac{\bar d_t}{\| \bar d_t\|_2}\right\rangle + \sum_{t \not \in K} \| (\bar A - \hat{A}^{(T)}) x_t \|_2.
    \end{align*}
    %
    The term on the right-hand side is equivalent to the condition in Corollary 3 in \cite{zhang2024exactrecoveryguaranteesparameterized} with $f(x_t) = x_t$ and $Z = \bar A - \hat{A}^{(T)}$.

    \begin{lemma} [Theorem 6 in \cite{zhang2024exactrecoveryguaranteesparameterized}] \label{lem: diff-lower-bound-haixiang}
        Suppose that the Assumptions \ref{asp:stable} and \ref{asp:subgaussian} are satisfied. Then, for any given $B \in \mathbb{R}^{n \times n}$ , the following holds  with probability at least $1-\delta$:
        %
        \begin{align*}
        \sum_{t \in \mathcal{K}} \left\langle  B - \bar A , \frac{\bar d_t}{\| \bar d_t\|_2}\right\rangle + &\sum_{t \not \in K} \| (B - \bar A) x_t \|_2 \\ & \ge \Theta \left[\frac{c  p(1-p) \|B - \bar A\|_F T }{\sigma^4}\right]
    \end{align*}
    %
    when the number of samples $T \ge T^{(burn)}(n, p, \rho, \sigma, \delta)$. 
    \end{lemma}
    %
    Using Lemma \ref{lem: diff-lower-bound-haixiang} and $B = \hat{A}^{(T)}$, if $T \ge T^{(1)}(\delta)$, we have
    %
    \begin{align} \label{eq:diff-lower}
         f_T(\hat A^{(T)}) - f_T(\bar A) & \ge \frac{c  p(1-p) \|\hat{A}^{(T)} - \bar A\|_F T }{\sigma^4}
    \end{align}
    %
    with probability at least $1-\delta$. Next, we upper-bound the norm of the subgradient as below:
    %
    \begin{align}
          \| G_{\hat{A}^{(T)}, T} \|_F^2 
         & = \Big\langle - \sum_{t=0}^{T} \partial \norm{(\bar A -\hat A^{(T)}) x_t + \bar d_t}_2 \otimes x_t, \notag \\ 
         & - \sum_{t=0}^{T} \partial \norm{(\bar A -\hat A^{(T)}) x_t + \bar d_t}_2 \otimes x_t \Big \rangle \notag  \\
         & \le \sum_{t = 0 }^T \sum_{m = 0}^T \|x_t \|_2 \|x_m \|_2 = \left( \sum_{t = 0}^{T-1} \|x_t\|_2 \right)^2. \label{eq:gradient-upper}
    \end{align}
    %
    The second-to-last inequality holds due to the norm of subgradients being at most one and the Cauchy-Schwarz inequality. We simplify the expression as $ \| G_{\hat{A}^{(T)}, T} \|_F \le  T \widetilde{\|x_T\|_2},$ where $\widetilde{\|x_T\|_2}$ is defined in the theorem statement. We combine \eqref{eq:diff-lower} and \eqref{eq:gradient-upper} with the lower bound on $\cos({\hat \theta_T})$. With probability at least $1-\delta$, when the number of samples is greater than $T \ge T^{(burn)}(n, p, \rho, \sigma, \delta)$, we have 
    %
    \begin{align*}
        \cos({\hat \theta_T})
       \ge \Theta \left( \min \left\{ 1, \frac{p(1-p)}{\sigma^4\widetilde{\|x_T\|_2} }\right\} \right)> 0.
    \end{align*}
    %

\end{proofnew}
%

\subsection{Proof of Theorem \ref{thm:polyak-result}}


\begin{proofnew}
    Using the subgradient update iteration at time $T$, $\hat A^{(T+1)} = \hat A^{(T)} - \beta^{(T)}G_{\hat A^{(T)}, T} $, we have
    %
    \begin{align}
        \| \hat A^{(T+1)} - \bar A \|_F^2 & = \| (\hat A^{(T)}-  \bar A) - \beta^{(T)}G_{\hat A^{(T)}, T}  \|_F^2 \notag \\
        & = \| (\hat A^{(T)}-  \bar A) \|_F^2 + (\beta^{(T)})^2\| G_{\hat A^{(T)}, T} \|_F^2 \notag \\ 
        &- 2 \beta^{(T)} \langle  G_{\hat A^{(T)}, T}, \hat A^{(T)} -  \bar A\rangle \notag \\
        & \le \| (\hat A^{(T)}-  \bar A) \|_F^2 + (\beta^{(T)})^2\| G_{\hat A^{(T)}, T} \|_F^2 \notag \\
        & - 2 \beta^{(T)} (f_T(\hat A^{(T)}) - f_T(\bar A)). \label{expansion_new}
    \end{align}
    %
    The last inequality uses the  fact that $(f_T(\hat A^{(T)}) - f_T(\bar A)) \ge \langle  G_{\hat A^{(T)}, T}, \hat A^{(T)}-  \bar A\rangle$ due to the properties of subgradient. Substituting the step size stated in the theorem yields
    %
    \begin{align*}
        \| \hat A^{(T+1)} - \bar A \|_F^2 & \le  \| (\hat A^{(T)}-  \bar A) \|_F^2 - \frac{ (f_T(\hat A^{(T)}) - f_T(\bar A) )^2}{\|G_{\hat A^{(T)}, T}\|_F^2} .
    \end{align*}
    % 
     In Theorem \ref{thm:cosine-lower-bound} and Corollary \ref{cor:linear-convergence-best}, it is proved that whenever the number of samples is greater than $T^{(burn)}(n, p, \rho, \sigma, \delta)$, we have  
     %
     \begin{align*}
         \frac{ (f_T(\hat A^{(T)}) - f_T(\bar A) )^2}{\|G_{\hat A^{(T)}, T}\|_F^2} \le (1-\gamma^2) \| (\hat A^{(T)}-  \bar A) \|_F^2
     \end{align*}
     %
     with probability at least $1-\delta$ where $\gamma$ is a positive constant that is less than $1$. Thus, we have convergence to the ground truth with the linear rate $\gamma$ because 
     %
     \begin{align*}
         \| \hat A^{(T+1)} - \bar A \|_F & \le  \gamma\| (\hat A^{(T)}-  \bar A) \|_F. 
     \end{align*}
     %
     The rest of the arguments are similar to those in Corollary \ref{cor:linear-convergence-best}.
\end{proofnew}





\subsection{Proof of Theorem \ref{thm:constant-step-size}}
\begin{proofnew} We first define the following Lemma.

    \begin{lemma} \label{lem:objective-difference}
    Let $D = \| \hat A^{(T^{(burn)})} - \bar A \|_F$ be the distance of the iterate to the ground-truth $\bar A$ at the end of the burn-in time. Then, the following holds:
    %
    \begin{align*}
        \sum_{t=T^{(burn)}}^{T} \beta^{(t)} & (f_t(\hat{A}^{(t)}) - f_t(\bar A)) \\ &  \le  D^2 + \sum_{t=T^{(burn)}}^{T} (\beta^{(t)})^2 \left( \sum_{\ell = 0}^t \| x_\ell\|_2 \right)^2.
    \end{align*}
\end{lemma}

    Using Lemma \ref{lem:objective-difference} and taking the minimum of the left-hand side over periods between $[T^{(burn)}, T]$ yields
    %
    \begin{align*}
        \min_{t \in [T^{(burn)}, T]} &  \left\{ \frac{1}{t} (f_t(\hat{A}^{(t)}) - f_t(\bar A))\right\}  \\ & \le 
         \frac{D^2 + \sum_{t=T^{(burn)}}^{T} (\beta^{(t)})^2 \left( \sum_{\ell = 0}^t \| x_\ell\|_2 \right)^2}{2 \sum_{t=T^{(burn)}}^{T} (\beta^{(t)}t)} .
    \end{align*}
    %
    Using Lemma \ref{lem:average-state-upper-bound}, we know that $\left( \sum_{\ell = 0}^t \| x_\ell\|_2 \right)$ can be upper-bounded by $ \Theta(t p^{1/2} /\sigma^9(1-\rho))$ with probability at least $1-\delta$ whenever $t$ is larger than the burn-in time. We have
    %
    \begin{align*}
        & \min_{t \in [T^{(burn)}, T]}  \left\{ \frac{1}{t}(f_t(\hat{A}^{(t)}) - f_t(\bar A))\right\} \\ & \le 
        \Theta\left(\frac{D^2 + \sum_{t=T^{(burn)}}^{T} (\beta^{(t)})^2 t^2 p /\sigma^{18}(1-\rho)^2}{\sum_{t=T^{(burn)}}^{T} (\beta^{(t)}t)} \right) 
    \end{align*}
    %
    with probability $1 - \delta$. Setting the step size to be $\beta^{(t)} = \beta$ implies the term on the right-hand side to be
    %
    \begin{align*}
        \Theta\left(\frac{D^2 + \frac{\beta^2p}{\sigma^{18} (1-\rho)^2}\sum_{t=T^{(burn)}}^{T} t^2}{\beta \sum_{t=T^{(burn)}}^{T} t} \right).
    \end{align*}
    %
    Minimizing the right-hand side with respect to $\beta$ results in the following constant step size: 
    %
    \begin{align*}
        \beta^{(t)} = \beta =  \Theta\left(\frac{D\sigma^9 (1-\rho)}{p^{1/2} (\sum_{t=T^{(burn)}}^T t^2)^{1/2}}\right).
    \end{align*}
    %
    Substituting this constant step size to the expression on the sub-optimality gap inequality provides the simplified upper bound that holds with probability at least $1 - \delta$:
    %
    \begin{align*}
        \min_{t \in [T^{(burn)}, T]} & \left\{ \frac{1}{t}(f_t(\hat{A}^{(t)}) - f_t(\bar A))\right\} \\
        & \le  \Theta\left(\frac{Dp ^{1/2}}{\sigma^9 (1-\rho)} \times \frac{(\sum_{t=T^{(burn)}}^T t^2)^{1/2}}{\sum_{t=T^{(burn)}}^T t}\right).
    \end{align*}
    %
\end{proofnew}

\subsection{Proof of Lemma \ref{lem:objective-difference}}

\begin{proofnew}
    Using \eqref{expansion_new} and the iterative substitution between the time periods from $T^{(burn)}(n, p, \rho, \sigma, \delta)$ to $T$, we obtain
    %
    \begin{align*}
        & \| \hat A^{(T+1)} - \bar A \|_F^2   \le 
         \| (\hat A^{(T^{(burn)})} -  \bar A) \|_F^2 \\ 
         &+ \sum_{t=T^{(burn)}}^{T} (\beta^{(t)})^2\| G_{\hat A^{(t)}, t} \|_F^2 
        - 2\sum_{t=T^{(burn)}}^{T}  \beta^{(t)} (f_t(\hat A^{(t)}) - f_t(\bar A)) \\
        & \le  D^2 + \sum_{t=T^{(burn)}}^{T} (\beta^{(t)})^2 \left( \sum_{\ell = 0}^t \| x_\ell\|_2 \right)^2  \\ 
        & - 2\sum_{t=T^{(burn)}}^{T}  \beta^{(t)} (f_t(\hat A^{(t)}) - f_t(\bar A)).
    \end{align*}
    %
    The last inequality follows from the fact that $D = \| \hat A^{(T^{(burn)})} - \bar A \|_F$ and $\| G_{\hat A^{(t)}, t} \|_F$ can be upper-bounded by $\left( \sum_{\ell = 0}^t \| x_\ell\|_2 \right)$. Since $ \| \hat A^{(T+1)} - \bar A \|_F^2 $ is nonnegative, the last term on the right-hand side can be lower-bounded by 0. Switching the term with the negative coefficient from the right-hand side to the left-hand side completes the proof.
\end{proofnew}


