\subsection{Thrust and Attitude Outputs}
\label{subsec:flat_thrust}



The model with additional thrust, altitude-varying rotor drag and inertia moment can be written as:
\begin{equation}
\begin{aligned}
\label{equ_flat_model}
    & {\bm{a}} =  - g{{\bm{z}}_W} + \left[ {1 + {F_G}\left( h \right)} \right]{T_a}{{\bm{z}}_B} - {\bm{R}}{{\bm{D}}_a}\left( h \right){{\bm{R}}^ \top }{\bm{v}}\\
    & {\bm{J}'}\left( h \right){\bm{\dot \omega }} =  - {\bm{\omega }} \times {\bm{J}'}\left( h \right){\bm{\omega }} + {{\bm{\tau }}_B},
\end{aligned}
\end{equation}
where ${T_a} = T/m$ and ${{\bm{D}}_a}\left( h \right) = {\bm{D}}\left( h \right)/m$ are the normalized accelerations.
% 将zb与下式左乘
Left multiply $\bm{z}_b$ to the following formula:
\begin{equation}
\begin{aligned}
\label{equ_flat_xyz}
    {\bm{a}} + g{{\bm{z}}_W} & + \left[ {{d_{ax}}\left( h \right){{\bm{x}}_B}^ \top {\bm{v}}} \right]{{\bm{x}}_{\bm{B}}} + \left[ {{d_{ay}}\left( h \right){{\bm{y}}_B}^ \top {\bm{v}}} \right]{{\bm{y}}_B}\\
    &  - \left[ {1 + {F_G}\left( h \right)} \right]{T_a}{{\bm{z}}_B} = 0.
\end{aligned}
\end{equation}
The reference thrust can be obtained:
\begin{equation}
\begin{aligned}
\label{equ_flat_thrust}
    T = m\frac{{{{\bm{z}}_B}^ \top \left( {{\bm{a}} + g{{\bm{z}}_W}} \right)}}{{\left[ {1 + {F_G}\left( h \right)} \right]}}.
\end{aligned}
\end{equation}

% 参考姿态的推导可以参照之前的工作。
The derivation of the reference attitude can refer to the previous works \cite{faessler2017differential,wang2022geometrically}.


% Left multiply $\bm{x}_b$ and $\bm{y}_b$ to (\ref{equ_flat_xyz}), we can get the reference attitude \cite{faessler2017differential}:


% \begin{equation}
% \begin{aligned}
% \label{equ_flat_attitude}
%     & {{\bm{x}}_B}^ \top {\bm{\alpha }} = 0,{\bm{\alpha }}{\rm{ = }}{\bm{a}} + g{{\bm{z}}_{\bm{W}}} + {d_x}\left( h \right){\bm{v}}\\
%     & {{\bm{y}}_B}^ \top {\bm{\beta }} = 0,{\bm{\beta }}{\rm{ = }}{\bm{a}} + g{{\bm{z}}_{\bm{W}}} + {d_y}\left( h \right){\bm{v}}\\
