\subsection{Proof of Lemma~\ref{lemma:alphamomentlowerbound}}
\label{app:kmomentproof}
\begin{proof}[\nopunct] We first let $g(k) = k$, i.e., we show that 
\begin{equation}
    E[K^\alpha] \geq \frac{1}{1+\alpha} 2^{\alpha D_{\alpha + 1}(P||Q)}. \label{eq:alphamomentlowerbound}
\end{equation}
To do so, we will first show that for any $k \in \mathbb{N}$, $\mathbb{P}(K = k \mid U_K = u) \leq \frac{1}{\frac{\dd P}{\dd Q}(u)}$ for $P$-almost every $u \in \mathcal{U}$. Define $\nu$ to be the probability measure generated by the joint distribution of $K$ and $U_K$, i.e., $\nu(A) \coloneqq \mathbb{P}((K, U_K) \in A)$ for each Borel set $A \subseteq \mathbb{N} \times \mathcal{U}$. Then,  
    \begin{equation}
        \mathbb{P}(K = k \mid U_K = u) = \frac{\dd \nu_k}{\dd P}(u) \leq \frac{\dd Q}{\dd P}(u) \nonumber
    \end{equation}
    $P$-almost everywhere, where $\nu_k(B) \coloneqq \nu(k \times B)$ and the inequality follows by $\nu(k \times B) \leq \sum_{k=1}^\infty \nu(k \times B) = Q(B)$ for any Borel set $B \subseteq \mathcal{U}$. All Radon-Nikodym derivatives are guaranteed to exist because $P \sim Q$. Thus, 
    \begin{equation}
        \mathbb{P}(K = k \mid U_K = u) \leq \frac{\dd Q}{\dd P}(u) = \frac{1}{\frac{\dd P}{\dd Q}(u)} \label{eq:conditionalboundpk}
    \end{equation}
    for $P$-almost every $u \in \mathcal{U}$. Let $E \subseteq \mathcal{U}$ be the set of all $u$ where \eqref{eq:conditionalboundpk} holds. For $u \in E$, writing $p_u(k) = \mathbb{P}(K = k | U_K = u)$ and $c_u = (\dd P / \dd Q)(u)$, we have that $p_u(k) \leq \frac{1}{c_u}$ for all $k$. Then, for $\qty{c_u} \coloneqq c_u - \lfloor c_u \rfloor$ the fractional part of $c_u$, we claim
    \begin{equation}
        \sum_{k=1}^\infty k^\alpha p_u(k) \geq \frac{1}{c_u} \left( \sum_{k=1}^{\lfloor c_u \rfloor } k^\alpha + \{c_u\}(\lceil c_u \rceil)^\alpha \right) \label{eq:redistribution}.
    \end{equation}
    If $p_u(k)$ does not have distribution $p_u(k) = \frac{1}{c_u}$ for $k \in \qty{1, \ldots, \lfloor c_u \rfloor}$ and $p_u(\lceil c_u \rceil) = \frac{\qty{c_u}}{c_u}$, we can move any excess probability from indices $k \geq \lceil c_u \rceil$ until it has such a distribution. Since we shift probabilities from indices $k \geq \lceil c_u \rceil$ to $k \leq \lceil c_u \rceil$ and $k^\alpha$ is increasing in $k$,~\eqref{eq:redistribution} must hold. Hence, for all $u \in E$,
    \begin{align}
        \mathbb{E}\left[K^\alpha \mid U_K = u \right] = \sum_{k=1}^\infty k^\alpha p_u(k) &\geq \frac{1}{c_u} \left( \sum_{k=1}^{\lfloor c_u \rfloor } k^\alpha + \{c_u\}(\lceil c_u \rceil)^\alpha \right) \nonumber \\
        &\geq \frac{1}{c_u}\left( \int_0^{c_u} t^\alpha \dd t \right) = \frac{1}{1 + \alpha} c_u^{\alpha} = \frac{1}{1 + \alpha} \left[ \frac{\dd P}{\dd Q}(u) \right]^\alpha, \label{eq:integrallowerbound}
    \end{align}
    where the inequality in~\eqref{eq:integrallowerbound} follows because $f(t) = t^\alpha$ is an increasing function of $t$. Taking expectation over $U \sim P$ gives, as $P(E) = 1$, the lower bound in~\eqref{eq:alphamomentlowerbound}. 

    For an arbitrary bijection $g : \mathbb{N} \rightarrow \mathbb{N}$, note that for every $k \in \mathbb{N}$,~\eqref{eq:conditionalboundpk} implies
    \begin{equation}
        \mathbb{P}(g(K) = k \mid U_K = u) = \mathbb{P}(K = g^{-1}(k) \mid U_K = u) \leq \frac{1}{\frac{\dd P}{\dd Q}(u)}, \nonumber
    \end{equation}
    for $P$-almost every $u \in \mathcal{U}$. Following the same steps as above, we can conclude that $\mathbb{E}[(g(K))^\alpha] \geq \frac{1}{1+\alpha} 2^{\alpha D_{\alpha+1}(P||Q)}$.
\end{proof}
\subsection{Proof of Lemma~\ref{lemma:geometricmoment}}
\label{app:lemmageometricproof}
\begin{proof}[\nopunct]
The case $r = 1$ holds trivially, as $\mathbb{E}[X] = \frac{1}{p}$. Let $r > 1$. We know that $X = \lceil Y \rceil$, where $Y$ is an exponential random variable with parameter $\lambda = -\ln(1-p)$. Thus, $X \leq Y + 1$ and we have
\begin{equation*}
    \mathbb{E}[Y^r] = \int_0^\infty y^r \lambda e^{-\lambda y} \dd y = \int_0^\infty \left( \frac{x}{\lambda} \right)^r e^{-x} \dd x = \frac{\Gamma(r + 1)}{\lambda^r}. 
\end{equation*}
Further, note that for any $r > 1$ and $x > 0$, $(x + 1)^r \leq 2^{r-1} (x^r + 1)$. We can therefore upper bound $\mathbb{E}[X^r]$ as 
\begin{align}
    \mathbb{E}[X^r] \leq \mathbb{E}[(Y + 1)^r] &\leq 2^{r-1} \left( \mathbb{E}[Y^r] + 1 \right) \nonumber \\
    &= 2^{r-1} \left( \frac{\Gamma(r + 1)}{\lambda^r} + 1\right) \nonumber \\
    &= 2^{r-1} \left( \frac{\Gamma(r + 1)}{\left[ -\ln(1-p) \right]^r} + 1\right) \nonumber \\
    &\leq 2^{r-1} \left( \frac{\Gamma(r+1)}{p^r} + 1 \right), \label{eq:lnbound}
\end{align}
where~\eqref{eq:lnbound} follows because $p \leq -\ln(1-p)$ for any $0 < p < 1$ and $x \mapsto x^r$ is an increasing function. 
\end{proof}
\subsection{Constant Term Analysis}
\label{app:kraftanalysis}
We herein prove the existence of the uniquely decodable encodings of $K$ used in the proofs of Theorems~\ref{thm:upperbound} and~\ref{thm:worseupperbound}. First, in Theorem~\ref{thm:upperbound}, we claim that there exists a prefix code with codeword lengths $n_k = (1 + \epsilon) \log k + c_\epsilon$, for any $\epsilon > 0$ and $c_\epsilon \leq 1 + \log (1 + \frac{1}{\epsilon})$ a constant such that $n_k$ is an integer and the code is a valid prefix code. The existence of such a code is guaranteed by the Kraft inequality, since for all $\epsilon > 0$ there exists $c_\epsilon$ such that
\begin{equation}
    \sum_{k=1}^\infty \frac{1}{k^{(1+\epsilon)}} \leq 2^{c_\epsilon}. \label{eq:kraftinequality}
\end{equation}
We can upper bound the sum in~\eqref{eq:kraftinequality} by
\begin{equation}
    \sum_{k=1}^\infty \frac{1}{k^{(1+\epsilon)}} \leq 1 + \int_{1}^\infty x^{-(1+\epsilon)} \dd x = 1 + \frac{1}{\epsilon}. \nonumber
\end{equation}
Returning to the requirement that $n_k$ be an integer, we can take the ceiling of our codeword length, imposing at most a $+1$ penalty, to get that
\begin{equation}
    c_\epsilon \leq 1 + \log(1 + \frac{1}{\epsilon}), \nonumber
\end{equation}
as claimed. Similarly, in Theorem~\ref{thm:worseupperbound} we consider a universal code with codeword lengths $n_k = \log k  + (1 + \epsilon)\log \log (k+1) + c_\epsilon$, for any $\epsilon > 0$ and $c_\epsilon \leq 1 + \log (\frac{\ln(2)}{\epsilon} + \frac{3}{2})$. By the Kraft inequality, we require that
\begin{equation}
    1 \geq \sum_{k=1}^\infty 2^{-n_k} = \sum_{k=1}^\infty \frac{1}{k\log^{(1+\epsilon)}(k+1)2^{c_\epsilon}}. \nonumber
\end{equation}
Hence, setting 
\begin{equation}
    c_\epsilon = \log (\sum_{k=1}^\infty \frac{1}{k\log^{(1+\epsilon)}(k+1)}) < \infty, \label{eq:constanttermsum}
\end{equation}
the code satisfies the Kraft inequality with equality. We can upper bound the sum in~\eqref{eq:constanttermsum} by
\begin{align}
    &\sum_{k=1}^\infty \frac{1}{k\log^{(1+\epsilon)}(k+1)}  \nonumber \\
    &= \sum_{k=1}^\infty \left[ \frac{1}{(k+1) \log^{\epsilon + 1}(k + 1)} + \frac{1}{k(k+1)\log^{1+\epsilon}(k+1)} \right]. \nonumber \\
    &\leq \frac{1}{2} + \int_{1}^\infty \frac{1}{(x+1)\log^{(1+\epsilon)}(k+1)} \dd x + \sum_{k=1}^\infty \frac{1}{k(k+1)} \nonumber \\
    &\leq \frac{1}{2} + \frac{\ln(2)}{\epsilon} + 1 = \frac{3}{2} + \frac{\ln(2)}{\epsilon}. \nonumber
\end{align}
Again imposing at most a $+1$ penalty to ensure $n_k$ is an integer, we obtain that
\begin{equation}
    c_\epsilon \leq 1 + \log(\frac{3}{2} + \frac{\ln(2)}{\epsilon}). \nonumber
\end{equation}

