\section{Additional Preliminaries}
\subsection{Propositional Logic}
We define Boolean formulas and their evaluation in the usual way and
\emph{literals} are FO-variables or their negations. For a Boolean
formula $\psi$, we denote by $\var(\psi)$ the set of variables of
formula~$\psi$. Logical operators~$\wedge$, $\vee$, $\neg$
$\rightarrow$, $\leftrightarrow$ are used in the usual meaning. A
\emph{term} is a conjunction of literals and a clause is a
\emph{disjunction} of literals.
%
$\psi$ is in \emph{conjunctive normal form (CNF)} if $\psi$ is a
conjunction of clauses and $\psi$ is in \emph{disjunctive normal form
  (DNF)} if $\psi$ is a disjunction of terms.




\subsection{First Order (FO) Logic}

\paragraph{Syntax}
A \emph{signature} is a finite
set~$\sigma = \SB R_1,\ldots, R_k, c_1,\ldots, c_\ell\SE$ with $k$,
$\ell \in \NAT_0$.
%
We call symbols~$R_1$, $\ldots$, $R_k$ \emph{relation symbols} and the
symbols~$c_1$, $\ldots$, $c_\ell$ \emph{constant symbols}.
%
We abbreviate the set of all %
constant symbols by~$\CONS_\sigma$.
%
Every $R_i$ has an arity~$\ar(R_i) \in \NAT$.
%
A $\sigma$-structure
$\AAA = (A, \sigma^\AAA) = (A,R^{\AAA}_1, \ldots, R^{\AAA}_k,
c^{\AAA}_1, \ldots, c^{\AAA}_\ell)$ consists of a non-empty set~$A$, the domain
of~$A$, an $\ar(R_i)$-ary relation $R_i^\AAA \subseteq A^{\ar(R_i)}$,
for every~$i \leq k$; and an element $c_j^\AAA \in A$ for every
$j \leq \ell$.
%
%
%
We abbreviate by $\VAR_1$ the set of all FO-variables.
%
%
We define the set~$\FO[\sigma]$ of formulas inductively as follows:
%
\begin{itemize}
\item[(A1)] $R(v_1, \ldots, v_k) \in \FO[\sigma]$ for all relation
  symbols~$R \in \sigma$ where
  $v_1, \ldots, v_{\ar(R)}\in \VAR_1 \cup \CONS_\sigma$.
%
\item[(A2)] $v = v' \in \FO[\sigma]$ for all
  $v, v' \in \VAR_1 \cup \CONS_\sigma$.
%
\item[(BC)] Let $\psi_1$, $\psi_2 \in \FO[\sigma]$, then
  $\neg \psi_1 \in \FO[\sigma]$,
  $\psi_1 \rightarrow \psi_2 \in \FO[\sigma]$,
  $\psi_1 \vee \psi_2 \in \FO[\sigma]$,
  $\psi_1 \leftrightarrow \psi_2 \in \FO[\sigma]$, and
  $\psi_1 \wedge \psi_2 \in \FO[\sigma]$.
%
\item[(Q1)] Let $\psi \in \FO[\sigma]$ and $x \in \VAR_1$,
  $\exists \psi \in \FO[\sigma]$ and $\forall \psi \FO[\sigma]$.
%
  %
\end{itemize}
Formulas constructed from (A1) and (A2) are called \emph{atomic}.
%
If it is clear from the context, we omit stating the
signature~$\sigma$ and just assume that it is arbitrary one.

%
\paragraph{Interpretations}
Let $\sigma$ be a signature. A $\sigma$-interpretation
$I=(\AAA,\beta)$ consists of a $\sigma$-structure~$\AAA$ and an
assignment~$\beta: \VAR_1 \rightarrow A$, which maps every variable to
a value from~$A$. %
%
Let $x \in \VAR_1$, $a \in A$, and $\beta: \VAR_1 \rightarrow A$, 
%
then the
\emph{assignment}~$\extend{\beta}{a}{x}: \VAR_1 \rightarrow A$ is
defined as follows:
$(\extend{\beta}{a}{x})(y) \eqdef \{a \SM y = x\} \cup \{ \beta(y) \SM
y \neq x\}$.


\paragraph{Semantics}
Let $\sigma$ be a signature, $I = (\AAA, \beta)$ a
$\sigma$-interpretation and $\phi \in \FO[\sigma]$.
%
We define the models relation~$I \models \phi$ inductively on the
formula~$\phi$ that is constructed according to the corresponding
rules stated above:
\begin{itemize}
\item[(A1)]
  %
  $I \models \phi$ if and only if
  $(\beta(v_1), \ldots, \beta(v_k)) \in R^\AAA$.
\item[(A2)] %
  $I \models \phi$ if and only if $\beta(v) = \beta(v')$.
  %
\item[(BC)]
  %
  %
  %
  \begin{enumerate}
  \item $\phi = \neg \phi_1$, then $I \models \phi$\\
    if and only if $I \models \phi_1$ does not hold;
%
  \item $\phi = (\phi_1 \vee \phi_2)$, then $I \models \phi$\\
    if and only if $I \models \phi_1$ and $I \models \phi_2$;
%
  \item $\phi = (\phi_1 \wedge \phi_2)$, then $I \models \phi$\\
    if and only if $I \models \phi_1$ and $I \models \phi_2$;
%
  \item $\phi = (\phi_1 \rightarrow \phi_2)$, then $I \models \phi$\\
    if and only if $I \models \phi_1$ then also $I \models \phi_2$;
%
  \item $\phi = \phi_1 \leftrightarrow \phi_2$, then $I \models \phi$\\
    if and only if $I \models \phi_1$ if and only if
    $I \models \phi_2$.
  \end{enumerate}
\item[(Q1)]
  \begin{enumerate}
  \item $\phi = \exists x \psi$, then $I \models \psi$ if and only
    if\\ there is an~$a \in A$, such that
    $(\AAA, \extend{\beta}{a}{x}) \models \psi$;
  \item $\phi = \forall x \psi$, then $I \models \psi$ if and only
    if\\
    for all~$a \in A$ it is true that
    $(\AAA, \extend{\beta}{a}{x}) \models \psi$.
  \end{enumerate}
\end{itemize}

%
The set~$\free(\phi)$ consists of variables that are \emph{unbounded}
in $\phi$. We define them inductively on the formula~$\phi$ that is
constructed according to the corresponding rules stated above:
%
\begin{itemize}
\item[(A1)] $\free(\phi) \eqdef \{v_1,\ldots, v_k \} \cap \VAR_1$,
\item[(A2)] $\free(\phi) \eqdef \{v, v'\} \cap \VAR_1$,
\item[(BC)]
  %
  %
  %
  $\phi = \neg \phi_1$, then $\free(\phi) \eqdef \free(\phi_1)$ and \\
  $\phi = (\phi_1 \circ \phi_2)$, then
  $\free(\phi) \eqdef \free(\phi_1) \cup \free(\phi_2)$ where
  $\circ \in \{\vee, \wedge, \rightarrow, \leftrightarrow \}$.
\item[(Q1)] $\phi = \exists x \psi$ or $\phi = \forall x \psi$, then
  $\free(\phi) \eqdef \free(\psi) \setminus \{x\}$.
\end{itemize}
%
%
We call a formula~$\phi \in \FO[\sigma]$ \emph{sentence}, if $\phi$
has no free variables, i.e., $\free(\phi) = \emptyset$.


\paragraph{Ordered Structures}
We call a structure~$\AAA$ \emph{ordered} if its signature contains a
$2$-ary relation symbol~$<$, such that its relation~$<^\AAA$ is a
strict linear ordering on the universe~$A$,~i.e., $<^\AAA$ is
irreflexive, asymmetric, transitive, connected.
%
%
Furthermore, the relation $\first^\AAA(a)$ is true only if $a\in A$
the smallest element, and $\last^\AAA(a)$ is true only if $a \in A$ is
the largest element, and $\suc$ is the successor relation with respect
to~$<^\AAA$. In other words, $(a,b) \in \suc$ if and only if
$a <^\AAA b$ and there is no $c$ such that $a<^\AAA c <^\AAA b$.


\subsection{Second Order (SO) Logic}

\paragraph{Syntax}
The set~$\VAR_2 \eqdef \SB V^k_i \SM k,i \in \NAT \SE$ consists of all
SO-variables, sometimes also called \emph{predicate variables}.
%
The variable~$\VAR^k_i$ has arity $\ar(\VAR^k_i)=k$.
%
The set of all formulas~$\SO[\sigma]$ is defined inductively by the rules %
%
(A1), (A2), (BC), and (Q1) from the FO-logic above as well as %
%
the following rules (A3) and (Q2).
%
\begin{itemize}
\item[(A3)] Let $X \in \VAR_2$ of arity $k \eqdef \ar(X)$,
  $v_1,\ldots,v_k \in \VAR_1 \cup \CONS_\sigma$, then
  $X(v_1, \ldots, v_k)\in \SO[\sigma]$.
  %
\item[(Q2)] Let $\psi \in \SO[\sigma]$ and $X \in \VAR_2$, then (i)
  $\exists X \psi \in \SO[\sigma]$ and (ii)
  $\forall X \psi \in \SO[\sigma]$.
\end{itemize}
%
Formulas built from (A1), (A2), and (A3) are called \emph{atomic}.


If $\phi \in \SO[\sigma]$, we mean by $\free(\phi)$ the set of all
first- or second-order variables that occur unbounded in~$\phi$.
%
We write $\phi(x_1, \ldots, x_s, X_1, \ldots, X_t)$ to indicate that
$\free(\phi)=\{x_1, \ldots, x_s, X_1, \ldots, X_t\}$.
%
We call an $\SO[\sigma]$-formula~$\phi$ a \emph{sentence} if
$\free(\phi) = \emptyset$.

\paragraph{Semantics}
The $\SO$-semantics extends semantics of $\FO$ as follows.
%
Let $\AAA$ be a $\sigma$-structure.
%
\begin{itemize}
\item[(Q2)] $\AAA\models \exists X \phi$ if and only if there is a
  relation~$X^\AAA \subseteq A^k$, such that
  $(\AAA,X^\AAA) \models \phi$.
\end{itemize}
%
The SO-logic is sometimes also known as~$\Sigma^1_k$.

\subsection{Quantified Constraint Satisfaction Problems (QCSPs) and Validity of Quantified Boolean Formulas ($\QBFS$)}\label{appendix:prelimns:qcsp}
We define \emph{Constraint Satisfaction Problems (CSPs)} over finite domains 
and their evaluation~\cite{FergusonOSullivan07} in the usual way. 
A CSP~$\mathcal{C}$ is a set of constraints 
and we denote by~$\var(\mathcal{C})$ %
the set of \emph{(constraint) variables} of~$\mathcal{C}$.
These constraint variables are over a (fixed) finite domain~$\mathcal{D}=\{0,\ldots\}$ 
consisting of at least two values (at least ``Boolean'').
%
An \emph{assignment} is a mapping~$\iota: \dom(\iota) \rightarrow \mathcal{D}$
defined for a set~$\dom(\iota)$ of variables.
%
%
We say an assignment~$\iota'$ \emph{extends}~$\iota$
(by~$\dom(\iota')\setminus \dom(\iota)$) if
$\dom(\iota') \supseteq \dom(\iota)$ and~$\iota'(y) = \iota(y)$ for
any~$y\in \dom(\iota)$.
%
Further, we let an \emph{assignment~$\alpha|_X$ restricted to~$X$} be
the assignment~$\alpha$ restricted to~$X$, where~$(\alpha|_X)(y)=\alpha(y)$ for~$y\in X\cap\dom(\alpha)$.
%
%
A \emph{constraint}~$C\in\mathcal{C}$ restricts certain variables~$\var(C)$ of~$C$
and contains assignments to $\mathcal{D}$.
More precisely, each~$c\in C$ with~$C\in\mathcal{C}$ is an \emph{allowed assignment}~$c: \var(C) \rightarrow \mathcal{D}$ 	
  of each variable~$v\in\var(C)$ to~$\mathcal{D}$.
%
Formally, $\mathcal{C}$ is \emph{satisfiable}, if there is an assignment~$A: \var(\mathcal{C}) \rightarrow \mathcal{D}$, 
called \emph{satisfying assignment}, such that for every~$C\in \mathcal{C}$
there is an allowed assignment~$c\in C$, where assignment $A|_{\var(C)}$ restricted to~$\var(C)$ equals~$c$. 

Let $\ell\geq 0$ be an integer. A \emph{quantified CSP (QCSP)}~$Q$  is of the form
$Q_{1} V_1.  Q_2 V_2.\cdots$ $Q_\ell V_\ell. \mathcal{C}$ where
$Q_i \in \{\forall, \exists\}$ for $1 \leq i \leq \ell$, $V_\ell=\exists$, and
$Q_j \neq Q_{j+1}$ for $1 \leq j \leq \ell-1$; and where $V_i$ are
disjoint, non-empty sets of constraint variables with
$\bigcup^\ell_{i=1}V_i = \var(\mathcal{C})$; and $\mathcal{C}$ is a CSP.
%
We call $\ell$ the \emph{quantifier rank} of~$Q$ and let $\matr(Q)\eqdef \mathcal{C}$.
%
The evaluation of QCSPs is defined as follows. %
%
Given a QCSP~$Q$ and an assignment~$\iota$, then~$Q[\iota]$ is a
QCSP that is obtained from~$Q$, where every occurrence of
any~$x\in \dom(\iota)$ in~$\matr(Q)$ is replaced by~$\iota(x)$, and
variables that do not occur in the result are removed from preceding
quantifiers accordingly.
%
A QCSP~$Q$ \emph{evaluates to true}, or is valid, if~$\ell=0$
and the CSP $\matr(Q)$ is satisfiable. Otherwise,
i.e., if~$\ell \neq 0$, we distinguish according to~$Q_1$.
If~$Q_1=\exists$, then~$Q$ evaluates to true if and only if there
exists an assignment~$\iota: V_1\rightarrow \mathcal{D}$ such
that~$Q[\iota]$ evaluates to true.  If~$Q_1=\forall$,
then~$Q[\iota]$ evaluates to true if for any
assignment~$\iota: V_1 \rightarrow\mathcal{D}$, $Q[\iota]$ evaluates to
true.

For brevity, we denote constraints by a formula using equality $=$
between variables and elements of the domain~$\mathcal{D}$,
negation $\neg$, which inverts (in-)equality expressions, as well as disjunction $\vee$, conjunction $\wedge$, and implication~$\rightarrow$,
which can be easily transformed into CSPs as defined above.
Further, we use for any Boolean variable~$v\in\var(Q)$ the expression ``$v$'', as a shortcut for~$v=1$.
%

If QCSP formula~$Q$ is over the Boolean domain, we refer to the formula simply as \emph{quantified Boolean Formula (QBF)} and $\QBFS$.

\subsection{Counting Complexity}\label{appendix:prelimns:counting}
We follow standard terminology in this area \cite{DurandHermannKolaitis05,HemaspaandraVollmer95a}.
In particular, we will make use of complexity classes preceded with the sharp-dot operator `$\#\cdot$'.
%
A \emph{witness} function is a function $w\colon\Sigma^*\to\mathcal P^{<\omega}(\Gamma^*)$, where $\Sigma$ and $\Gamma$ are alphabets, mapping to a finite subset of $\Gamma^*$. Such functions associate with the counting problem ``given $x\in\Sigma^*$, find $|w(x)|$''.
%
If $\mathcal C$ is a decision complexity class then $\#\cdot\mathcal C$ is the class of all counting problems whose  witness function $w$ satisfies (1.) $\exists$ polynomial $p$ such that for all $y\in w(x)$, we have that $|y|\leqslant p(|x|)$, and (2.) the decision problem ``given $x$ and $y$, is $y\in w(x)$?'' is in $\mathcal C$.
A \emph{parsimonious} reduction between two counting problems $\#A,\#B$ preserves the cardinality between the corresponding witness sets and is computable in polynomial time.
A \emph{subtractive} reduction between two counting problems $\#A$ and $\#B$ is composed of two functions $f,g$ between the instances of $A$ and $B$ such that $B(f(x))\subseteq B(g(x))$ and $|A(x)|=|B(g(x))|-|B(f(x))|$, where $A$ and $B$ are respective witness functions.




\newcommand{\MC}{\textsc{Mc}\xspace}
\subsection{Descriptive Complexity}

The \textsc{Model Checking} problem for a logic~$\LLL$ and
class~$\mathsf{F}$ of structures asks to decide, for a given a
sentence~$\Phi \in \LLL$ and a structure~$\AAA \in \mathsf{F}$,
whether $\AAA \models \Phi$.
%
\emph{Data complexity} is the complexity of the \textsc{Model
  Checking} problem assuming that $\Phi$ is fixed. More precisely, the
data complexity of \textsc{Model Checking} for logic~$\LLL$ is in the
complexity class~$\mathcal{K}$, if for every sentence~$\Phi \in \LLL$,
$L_\Phi$ can be recognized in~$\mathcal{K}$ where
$L_\Phi(\AAA) \eqdef \SB \enc(\AAA) \SM \AAA \in \mathsf{F}, \AAA
\models \Phi \SE$ and $\enc$ refers to the standard encoding,
see,~e.g.,~\cite{GradelKolaitisLibkin07}.
%
\emph{Combined complexity} is the complexity of
recognizing the satisfaction relation on finite structures.
%
More formally, the combined complexity of \textsc{Model Checking} for
logic~$\LLL$ is in complexity class~$\mathcal{K}$, if for every
sentence~$\Phi \in \LLL$, $L$ can be recognized in~$\mathcal{K}$ where
$L(\AAA,\Phi) \eqdef \SB \enc(\AAA).\enc(\Phi) \SM \AAA \in
\mathsf{F}, \AAA \models \Phi \SE$.

\subsection{Parameterized Complexity}\label{appendix:prelimns:parameterized}
\paragraph{Nice Tree Decompositions (TDs)}
For a node~$t \in N$, we say that $\type(t)$ is $\leaf$ if
$\children(t,T)=\langle \rangle$; $\join$ if
$\children(t,T) = \langle t',t''\rangle$ where
$\chi(t) = \chi(t') = \chi(t'') \neq \emptyset$; $\intr$
(``introduce'') if $\children(t,T) = \langle t'\rangle$,
$\chi(t') \subseteq \chi(t)$ and $|\chi(t)| = |\chi(t')| + 1$; $\rem$
(``remove'') if $\children(t,T) = \langle t'\rangle$,
$\chi(t') \supseteq \chi(t)$ and $|\chi(t')| = |\chi(t)| + 1$. If for
every node $t\in N$, $\type(t) \in \{ \leaf, \join, \intr, \rem\}$ and
bags of leaf nodes and the root are empty, then the TD is called
\emph{nice}.


