\subsection{Qualitative Reasoning}\label{appendix:qualitative}
%
\begin{restatelemma}[lem:transform]
\begin{lemma}
  %
  %
  Given a sentence~%
  $\Phi\in \Sigma^1_k[\sigma]$ in CDNF and a
  finite structure~$\AAA$, %
  %
  deciding whether $\AAA \models \Phi$  is
  %
  %
  (i)~$\NEXPl{k-1}$-com\-plete and
  %
  (ii)~$\SIGMA{k+1}$-complete if every 
  %
  predicate $R_i$ in $\Phi$ has arity at most~$m$ for some arbitrary but
  fixed constant~$m\geq 1$.
\end{lemma}
\end{restatelemma}
%
%
%
%
%

\begin{proof}
  Case (i)
  \emph{Membership:} Since the formulas are a special case, membership
  follows directly from Proposition~\ref{prop:socompl}.
  %
  \emph{Hardness:} %
  %
  Any sentence $\phi$ and structure $\AAA$ as in Proposition~\ref{prop:socompl}
  can be transformed in polynomial time into a CDNF sentence $\Phi'$ and a structure $\AAA'$
  such that $\AAA\models \Phi$ iff $\AAA'\models \Phi'$
  %
  To this end, we can employ as in \cite{EiterGottlobGruevich96} SO-Skolemization and an ordering $<$ of the domain $A$ of $\AAA$ with 
  auxiliary relations and predicates for quantifier elimination to obtain a prenex sentence $\Phi_0 \in \Sigma^1_k[\sigma_0]$ with FO-part $\exists\vec{y}\psi_0$ resp.{} $\forall\vec{y}\psi_0$ such that
  $\AAA\models \Phi$ iff $\AAA_0\models \Phi_0$, where $\AAA_0$ extends $\AAA$.

  To transform $\phi_0$ into CNF for odd $k$,
  %
  we replace sub-formulas $\psi(\vx)$ by $P_\psi(\vx)$ where we add $P_\psi$ to $R_k$ (quantify existentially), and recursively state for
  $\phi(\vx) \leftrightarrow (\phi_1(\vx) \wedge \phi_2(\vx))$ that
  $P_\phi(\vx) \leftrightarrow (P_{\phi_1} (\vx) \wedge
  P_{\phi_2}(\vx))$ etc.\ We convert the equivalences into CNF and add the conjunct $P_{\phi}(\vx)$. 
  %
  For even $k$, we use $\exists\vec{y}\phi_0 = \neg\forall\vec{y}\neg\phi_0$ and proceed similarly ($\neg\phi_0$ is CNF).
  %
  %
  %
  %
  %
  %
  %

  %
  We establish Case~(ii) as follows.
  %
  %
    \emph{Membership:} %
   We proceed by induction on $k\geq 1$. In the base case $\Phi = \exists R_1\forall\vec{x}\psi$, we can in polynomial time guess extensions $R^\AAA$ for the predicates $R$ in $R_1$ and check with an coNP oracle whether $(\AAA,\beta)\models \psi$ for each assignment $\beta$ to $\vec{x}$; hence the problem is in $\Sigma^p_2$. In the induction step, we can likewise guess extensions for $R_1$, and 
   put them into the structure, i.e., extend $\AAA$ to $\AAA_1$ over $\sigma\cup R_1$; by the induction hypothesis, we can decide $\AAA_1\models \neg(\forall R_2\cdots Q_k R_k\phi)$ using an $\Sigma^p_{k}$ oracle. Thus deciding $\AAA \models \Phi$ is in $\Sigma^p_{k+1}$.
  %

%
\emph{Hardness:} %
  %
  %
  %
  %
  %
 We may assume w.l.o.g\ that a fixed sentence $\Phi\in \Sigma^1_{k+1}[\sigma]$
 as in item (ii) of Proposition~\ref{prop:socompl} is 
 w.l.o.g.{} in CDNF form; indeed, the transformation in (i) depends only on $\Phi$ but not on the structure $\AAA$. Moreover, we may assume that $\sigma$ contains
 for each $a\in A$ a single constant $c$ such that $c^\AAA = a$ denoted $c_A$ (fresh constants can be added, multiple $c$ with $c^\AAA=a$ removed).

  %
  We reduce $\Phi$ into a formula $\Phi'$ with
  one quantifier block less, by grounding the FO-variables and
  replacing ground atoms in ``scope'' of the last block by FO-atoms; in that, we %
  represent tuples
  $(a_1,\ldots,a_r)$ of elements over $A$ 
  in the domain $A'$ of a structure $\AAA'$ over $\sigma'$ to achieve $m=1$. 
  This works in polynomial time, and $\AAA \models \Phi$ iff  $\AAA' \models \Phi'$. 

  In detail, let $\AAA=(A,\sigma^\AAA)$ be a
  $\sigma$-structure and $\Phi\in \Sigma^1_{k+1}[\sigma]$,
  $\Phi = \exists R_1 \forall R_2 \ldots Q_{k+1}R_{k+1}.\phi$, in CDNF form. Assume that  $k{+}1$ is odd, i.e., $\phi = \forall\vec{x}\psi(\vec{x})$, where
 $\psi$ is a quantifier-free CNF. 
  Let $\psi_A = \bigwedge_{\theta} \psi(\vec{x}\theta)$ be the grounding
  of $\psi$ over $\AAA$, i.e., the conjunction of all formulas
  $\psi(\vec{x}\theta)$ where $\theta$ is any replacement of each 
  variable in $\vec{x}$ with some $c_a$, $a \in A$; clearly $\psi_A$ is
  a CNF and constructible in polynomial time. We let
  $A' = A \cup \{ '\vec{a}\,' \mid
  R \in R_\Phi,  \vec{a} \in A^{ar(R)} \}$, where $R_\Phi = R_1\cup\cdots\cup R_k$, and replace each atom
  $R(\vec{c})$ in $\psi_A$, $R \in R_\Phi$, by
  $R'('\vec{c}\,')$, where $R'$ is a fresh unary predicate variable for
  $R$, and $'\vec{c}\,'$ is a fresh constant symbol, resulting in $\psi'_A$. Furthermore, let $\Phi_A' = \exists R'_1 \forall R'_2 \ldots Q_k R'_k Q_{k+1}R'_{k+1}.\psi'_{C_A}$.
  %
    We then have $\AAA \models \Phi$  iff $\AAA \models \exists R_1 \forall R_2 \ldots Q_{k+1}R_{k+1}.\psi_A$  iff
    $\BBB \models \Phi_A'$,  where $\mathcal{B} =(B,\sigma_{\psi_A}^\mathcal{B})$ is the $\sigma_{\psi_A}$-structure, $\sigma_{\psi_A} =$ $ \sigma\cup \{ '\vec{c}\,' \mid R(\vec{c})\in \psi_A\}$ such that $B= A$ and $\sigma_{\psi_A}^\BBB$ extends $\sigma^\AAA$ with mapping each $'\vec{c}\,'$ to $'(c_1^\AAA,\ldots,c_n^\AAA)'$ where $\vec{c}= c_1,\ldots,c_n)$. 

   It remains to eliminate $Q_{k+1}R_{k+1}$, i.e.,
  $\exists R'_{k+1}$ from $\Phi_A'$. To this end, we use a fresh
  unary relation $\gat$ that holds a single, arbitrary element $a_{\gat} \in
  A'$; intuitively, $\gat(x)$ evaluates to true if $x$ is assigned $a$ 
  and to false otherwise. We modify $\Phi_A'$ as follows. For each atom $R'('\vec{c}\,')$ in
  $\Phi_A'$, where $R' \in R'_{k+1}$,  we introduce a variable
  $x_{R'('\vec{c}\,')}$ and (a) replace $R'('\vec{c}\,')$ by
  $\gat(x_{R'('\vec{c}\,')})$ and (b) add $\exists x_{R'('\vec{c}\,')}$
  after $\exists R_{k+1}$. Finally, we drop $\exists R_{k+1}$.
  The resulting formula $\Phi'=\exists R'_1 \forall R'_2 \ldots
  Q_k R'_k.\phi'$ is in CDNF, and for the $\sigma'$-structure
  $\AAA' = (A',{\sigma'}^{\AAA'})$ where $\sigma' $ extends $\sigma_{\psi_A}$ with mapping $\gat$ to $\{ a_{\gat}\}$, we then have $\BBB \models \Phi_A'$ iff  
  $\AAA' \models \Phi'$. 

  Since $\Phi'$ is of the desired form and 
  all steps are feasible in polynomial time, $\Sigma^p_{k+1}$-hardness
  for odd $k+1$ and $m=1$ is shown. For even $k+1$, we can proceed similarly as
  in (i), using  $\exists\vec{x}\psi = \neg\forall\vec{x}\neg\psi$.
  This shows $\Sigma^p_{k+!}$- hardness, and thus Case~(ii) of
  the lemma.

 Furthermore, we can eliminate FO-atoms over $\sigma$ from $\psi_A$ by
 evaluating them over $\AAA$; then we can set $\sigma' = \{ \gat\}$,
 and all predicate and relation symbols in $\Phi'$ have arity~1.
%
%
\end{proof}

\begin{restatelemma}[lem:epihorn]
\begin{lemma}
  Let~$\prog \in \NonNeg$. %
  %
  Then, deciding whether~$\prog$ admits a world view is
  %
  in \Ptime{} if $P$ is ground,
  %
  \coNP-complete if $P$ is non-ground and has bounded arity, and
  %
  \EXP-complete if $P$ is non-ground.
  %
\end{lemma}
\end{restatelemma}
\begin{proof}[Proof (Sketch).]
\emph{Membership:} %
  Let $P \in \NonNeg$. We replace each occurrence of $\kop p$ and $\mop p$ in $P$ by $p$.
  %
  Then, we simply check consistency of $P$.
  %
  Since $P$ is Horn, the program has a either a unique answer set or none.
  %
  In the latter case, we are trivially done as the program has no world view.
  %
  In the former case, the program has a unique least model (see e.g.,~\cite{Truszczynski11b}).
  %
  Thus, we set $\kop p$ and $\mop p$ according to the value 
  in the unique least model.
  %
  %
  If $P$ is non-ground and has bounded arity, checking consistency of $P$ is in \coNP~\cite{EiterFaberFink07}.
  %
  %
  %
  %
  %
  %
  Finally, we use the same argument as in the proof of Theorem~\ref{thm:quali} 
  for the non-ground case. Grounding an ELP~$\eprog$ leads to an exponentially 
  larger program $\grd(\eprog)$ and $\Ptime$ becomes $\EXP$, cf.~\cite{GottlobLeoneVeith99}.\\
  %
  \emph{Hardness:} %
     For both non-ground cases, hardness follows immediately from the respective complexity results in ASP~\cite{EiterFaberFink07,GottlobLeoneVeith99}.
\end{proof}


