\begin{restatecorollary}[cor:quantitative:barity]
\begin{lemma}
Let~$\prog$ be a non-ground ELP of constant arity and $i=2$ if $\prog \in \Disj$, and $i=1$ if $\prog \in \Normal \cup \Tight$, and $i=0$ if $\prog \in \NonNeg$. Then, computing plausibility level~$L(\eprog,\emptyset)$  is~$\sharpd{\dpc{i+1}}$-complete.
\end{lemma}    
\end{restatecorollary}

\begin{proof}
\emph{Membership:}
    %
    We can employ the membership construction for the bounded arity case as done in the proof of Theorem~\ref{thm:quali}. 
    %
    However, we ask for finding the number of WVs. Thus, by the definition of the dot-class~$\sharpd{C}$, the class~$C$ states the complexity %
    of verifying a witness (i.e., a WV).
    %
    Since verifying a WV requires a call to~$\Sigma_{i+1}^\Ptime$ and a call to $\Pi_{i+1}^\Ptime$, this results in $\dpc{i+1}$~\cite{ShenEiter16}. Hence%
    , we obtain membership for $\sharpd{\dpc{i+1}}$.

\emph{Hardness:}
    %
    The constructions work similarly to the proof of Lemma~\ref{cor:quantitative:propositional} by observing that with non-ground programs of bounded arity, we can evaluate a conjunctive query, see, e.g.,~\cite{EiterFaberFink07}.
    %
    %
    We briefly sketch hardness for
    %
    the case $i{=}2$. To this end, we reduce from $\exists Y. \forall Z. \exists Q. \varphi(X,Y,Z,Q)) \wedge \neg(\exists U. \forall V. \exists W. \psi(X,U,V,W))$ with~$\varphi$ and~$\psi$ in 3-CNF.
    %
    %
We construct an epistemic program
$P=\{x \leftarrow \eneg \hat x, \hat x \leftarrow \eneg x \mid x\in X\} \cup \{a \vee \hat a \mid a\in Y\cup Z \cup Q \cup U \cup V \cup W\} \cup \{q\leftarrow \eneg q, \eneg \neg sat_\psi, \leftarrow \neg sat_\varphi\}$.
%
This program models epistemic guesses over variables in~$X$ and guesses over~$Y\cup Z\cup Q \cup U \cup V \cup W$. 
%
We saturate over~$Z$ and~$V$ by
$P_{sat}=\{a \leftarrow sat_\varphi, \hat a \leftarrow sat_\varphi \mid a\in Z\} \cup \{a \leftarrow sat_\psi, \hat a \leftarrow sat_\psi \mid a\in V\}$.

It remains to define~$sat_\psi$ and $sat_\varphi$.
%
As above, let~$\varphi=\{c_1,\ldots,c_{|\varphi|}\}$ and for any~$c_i\in\varphi$ and~$\ell\in c_i$, let~$f(\ell)=\ell$ if~$\ell$ is a variable and~$f(\ell)=\hat v$ with~$v=\var(\ell)$ otherwise.
%

Further, let~$\prec$ be any arbitrary, but fixed total order among all variables in~$\varphi\cup\psi$.
%
We refer to the $\prec$-ordered vector of variables in a set~$Q$ that are contained in a clause~$c_i\in\varphi$, by~$\vec Q_{i}$.
Observe that since both formulas~$\varphi$ and~$\psi$ are in 3-CNF, for any of these vectors $|\vec Z_i|\leq 3$.
%
For a literal~$\ell$, $pol(\ell)$ refers to its polarity, which is~$1$ if~$\ell$ is a variable and~$0$ otherwise.
%
We define 
$P_\varphi{=}$\\
\mbox{~}$\quad\{sat_\varphi {\leftarrow} sat_{c_1}(\vec Q_1), \ldots sat_{c_{|\varphi|}}(\vec Q_{|\varphi|})\} \,{\cup}$\\
\mbox{~}$\quad\{bin(0), bin(1)\}\,\cup $\\
\mbox{~}$\quad\{sat_{c_i}(\vec Q_i) \leftarrow f(\ell), bin(q_1), \ldots, bin(q_o) \;\mid $\\ 
\mbox{~}$\qquad\qquad\qquad\qquad c_i \in \varphi, \ell\in c, \var(\ell)\in X\cup Y \cup Z, $\\
\mbox{~}$\qquad\qquad\qquad\qquad\qquad\qquad\qquad\quad\; \vec Q_i=\langle q_1, \ldots, q_o \rangle\} \cup$\\ 
\mbox{~}$\quad \{sat_{c_i}(\langle q_1, \ldots, q_{j-1}, pol(q_j), q_{j+1}, \ldots, q_o \rangle) \leftarrow $\\
\mbox{~}$\qquad\qquad\qquad\qquad\qquad\qquad\qquad bin(q_1), \ldots, bin(q_o) \mid$\\
\mbox{~}$\qquad\qquad\qquad\qquad\qquad\qquad\quad c_i \in \varphi, \ell\in c, \var(\ell)=q_j, $\\
\mbox{~}$\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad \vec Q_i=\langle q_1, \ldots, q_o \rangle\}$.
%

\noindent Analogously to above, we define~$P_{\psi}$ (see also the proof of Lemma~\ref{cor:quantitative:propositional}.
%
%
\noindent Indeed, there is a bijection between WVs of $P\cup P_{sat} \cup P_\varphi \cup P_\psi$ and satisfying assignments over~$X$ of~$\exists Y. \forall Z. \exists Q. \varphi(X,Y,Z,Q) \wedge \neg(\exists U. \forall V. \exists W. \psi(X,U,V,W))$. 
%
    %
\end{proof}


