	\; C_{t^*}{\neq} C_t\},\\
  P'_{C_t}\,{=}\,\SB\usat_{C_t}(\langle\theta\rangle)\gets \mid t\text{ in }T, \theta: V_4(C_t) \to \Delta,  %
	%
	\\
	%
	%
	\theta\notin \{\varphi|_{V_4(C_t)} \mid \varphi\in C_t\}, C_t\neq \emptyset\SE,
 \end{flalign*}
 Finally, we define unsatisfiability, consistency, and saturate.
 \vspace{-.35em}
 \begin{flalign*}
 P_{usat}\,{=}\,\SB\usat{}\gets \usat_{C_t}(\langle V_4(C_t) \rangle) \mid t\text{ in }T\}, \\
	%
	P_{cons}\,{=}\,\SB v \hspace{-.25em}\gets\hspace{-.25em} \eneg v,\eneg \neg \usat\}, \\ %
	P_{saturate}\,{=}\,\SB v(d) \hspace{-.3em}\gets\hspace{-.3em}\usat \SM v\in V_3, d\in\dom(v)\SE.
	\end{flalign*}%
	%
	%
	%
	%

 Observe that~$\prog$ admits a world view %
 if and only if~$Q$ is evaluates to true. 
	%
	Further, observe that~$d$ is linear in~$d'$.
	%

	Then, we construct a TD~$\mathcal{T}\eqdef(T,\chi)$
	of~$G_\prog$, whose width~$k$ is linear in~$k'$ and where~$\chi$ is defined for a node~$t$ of~$T$ by
	%
	%
	%
	$\chi(t)\eqdef \chi'(t) \cup \{\usat, \usat_{\varphi_t}, \usat_{\varphi_{t'}}, \usat_{C_t} \mid t'\in\children(t)\}$.
