\section{Derivation of training and sampling algorithm}\label{sec_algorithm}
%
Given a standard Brownian motion $B_t$ in $\mathbb{R}^d$, a $\mu: \mathbb{R}^d \rightarrow \mathbb{R}^d$ and $R: \mathbb{R}^d \rightarrow \mathbb{R}^{d \times d}$, a  stochastic process $X_t$ satisfies the SDE $\mathrm{d} X_t = \mu(X_t) \mathrm{d}t +R(X_t) \mathrm{d}B_t$ with initial condition $x \in \mathbb{R}^d$ if $X_t = x + \int_0^t \mu(X_s) \mathrm{d} s + \int_0^t R(X_s) \mathrm{d} B_s$. 
%
\begin{lemma}[\bf It\^o's Lemma]\label{Lemma_Ito}
Let $\psi: \mathbb{R}^d \rightarrow \mathbb{R}^k$  be a second-order differentiable function, and let $X(t) \in \mathbb{R}^d$ be an It\^o diffusion.
%
 Then for all  $t \geq 0$ and all $ i \in [k]$, we have 
 %
     $ \mathrm{d} \psi(X_t) [i] =  \nabla \psi(X_t)[i]^\top \mathrm{d} X_t + \frac{1}{2} \mathrm{d} X_t^\top\nabla^2 \psi(X_t)[i] \mathrm{d}X_t. $
\end{lemma}
%
\noindent
 The {\em transition kernel} $p_{t|\tau}(y|x)$ is the probability (density) that $X$ takes the value $y$ at time $t$ conditional on $X$ taking the value $x$ at time $\tau$.
%
 Given an initial distribution $\pi$, the probability density at time $t$ is  $p_t(x) = \int_{\mathcal{M}} p_{t|0}(x|z) \pi(z) \mathrm{d}z$.
%
%
For any diffusion $X_t$,  $t \in[0,T]$,  its {\em time-reversal} $Y_t$ is the stochastic process such that $Y_t = X_{T-t}$ for  $t \in [0,T]$.
%
$Y_t$ is also a diffusion, governed by an SDE.
%
 In the special case where $X_t$ has identity covariance, $\mathrm{d} X_t = b(X_t)\mathrm{d}t + \mathrm{d}B_t$, the reverse diffusion satisfies \cite{anderson1982reverse}
%
\begin{eqnarray}
    \label{eq_reverse_diffusion2}
 \mathrm{d}Y_t  = -b(Y_t)\mathrm{d}t  + \nabla \log p_{t}(Y_t) \mathrm{d}t + \mathrm{d}B_t.
\end{eqnarray}
%}
%
%
 One can also define diffusions on Riemannian manifolds, in which case $\mathrm{d}B_t$ is the derivative of Brownian motion on the tangent space (see \cite{hsu2002stochastic}).
%
Below we show the key steps in deriving our diffusion model, training algorithm (Algorithm \ref{alg_training_manifold}), and sampling algorithm (Algorithm \ref{alg_sampling_manifold}).

\smallskip
\noindent
\textbf{Forward diffusion.} 
%
Let $Z_t$ 
be a diffusion on $\mathbb{R}^d$ initialized at $q_0 = \psi(\pi)$. 
%
We choose $Z_t$ to be the Ornstein-Uhlenbeck process,  $\mathrm{d}Z_t = -\frac{1}{2}Z_t \mathrm{d}t + \mathrm{d}B_t$, whose stationary distribution is $N(0,I_d)$.
%
$Z_t$ is easy to sample as it has a closed-form Gaussian transition kernel $q_{t|\tau}$.
%
 Let $X_t := \varphi(Z_t)$, the projection of $Z_t$ onto $\mathcal{M}$.
%
$X_t$ is our model's forward diffusion.

\smallskip
\noindent
\textbf{Reverse diffusion SDE.}
Let $Y_t$ $:=$ $X_{T-t}$ denote the time-reversal of $X_t$.
%
$Y_t$ is a diffusion on $\mathcal{M}$, and its distribution at time $T$ equals  the target distribution $\pi$. 
It follows the SDE:
%
\begin{eqnarray}\label{eq_r1}
\mathrm{d}Y_t = f^{\star}(Y_t, t)\mathrm{d}t + g^{\star}(Y_t, t)\mathrm{d}B_t,
\end{eqnarray}
%
for some functions $f^\star(x,t): \mathcal{M}\times[0,T] \rightarrow \mathcal{T}_x\mathcal{M}$ and $g^\star(x,t) : \mathcal{M} \rightarrow \mathcal{T}_x\mathcal{M} \times \mathcal{T}_x\mathcal{M}$.
%
 Here $\mathrm{d}B_t$ is the derivative of standard Brownian motion on $\mathcal{M}$'s tangent space.
 %
We write $\mathrm{d}B_t \equiv \mathrm{d}B_t^x$ when $x \in \mathcal{M}$ is clear from context.


%
We cannot directly apply \eqref{eq_reverse_diffusion2} to derive a tractable SDE for the reverse diffusion $Y_t$ on $\mathcal{M}$, as the transition kernel $p_{t|\tau}$ of the forward diffusion $X_t$ on $\mathcal{M}$ lacks a closed form expression.
%
Instead, we first use \eqref{eq_reverse_diffusion2} to obtain an SDE for the reverse diffusion of $Z_t \in \mathbb{R}^d$, 
%
$\mathrm{d}H_t =(H_t/2 + 2 \nabla \log q_{T-t}(H_t) )\mathrm{d}t + \mathrm{d} B_t$. 
%
 We use It\^o's Lemma to project this SDE onto $\mathcal{M}$, giving an SDE for $Y_t$  (see  Section \ref{sec_lemma_training_proof}),
 %
\begin{equation}\label{eq_f1}
  \mathrm{d}Y_t \, \textrm{$=$} \,  \mathbb{E}  [(\nabla \varphi(H_t)^\top 
\textrm{$+$} 
%
\frac{\mathrm{d} H_t^\top}{2} \nabla^2 \varphi(H_t))\mathrm{d}H_t \big | \varphi(H_t)\textrm{$=$}Y_t]. 
\end{equation}
%}

 \smallskip
\noindent
 \textbf{Training algorithm's objective function.} 
From \eqref{eq_f1}, we show one can train a model $f$,  $g$ for $f^\star$, $g^\star$ 
by solving an optimization problem (Lemma \ref{lemma_training}).
%
{Here, $f,g \in \mathcal{C}(\mathbb{R}^d, \mathbb{R}^d)$  are continuous functions from $\mathbb{R}^d$ to $\mathbb{R}^d$} and $t \sim \mathrm{Unif[0,1]}$, and $J_\varphi$ denotes the Jacobian of $\varphi$.
%
 \begin{equation}\label{objective_f}
 \min_{f}  \mathbb{E}_{t} \mathbb{E}_{b \sim \pi} [ \|  (\nabla \varphi(Z_{T-t}))^\top \frac{Z_{T-t}-\psi(b)e^{-(T-t)/2}}{e^{-(T-t)}-1}\nonumber\\
 + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(Z_{T-t}))  -  f(\varphi(Z_{T-t}), t) \|^2  | Z_0 = \psi(b)]
\end{equation}
and
\begin{equation}\label{objective_g}
 \min_{g}  \mathbb{E}_{t} \mathbb{E}_{b \sim \pi} [ \| J_{\varphi}(Z_{T-t}))^\top J_{\varphi}(Z_{T-t})
 - g(\varphi(Z_{T-t}),t)^2 \|_F^2  | Z_0 = \psi(b)].    
 \end{equation}
%
\textbf{Sublinear computation of training objective.}
%
For manifolds with non-zero curvature, such as the sphere, \(\mathrm{SO}(n)\), and \(\mathrm{U}(n)\), our forward and reverse diffusions differ from prior works and incorporate a spatially-varying covariance term to account for curvature. This allows the forward diffusion to be computed as a projection \(\varphi\) of the Ornstein-Uhlenbeck process in \(\mathbb{R}^d \equiv \mathbb{R}^{n \times n}\) (or \(\mathbb{C}^{n \times n}\)) onto the manifold.
%
For \(\mathrm{SO}(n)\) or \(\mathrm{U}(n)\), \(\varphi\) is computed by one singular value decomposition \(U^\ast \Lambda U\) of the Gaussian matrix \(Z_{T-t} + Z_{T-t}^\ast\), requiring \(O(n^\omega) = O(d^{\frac{\omega}{2}})\) arithmetic operations, where \(d = \Theta(n^2)\) is the manifold dimension. This enables computation of the drift term's gradient \eqref{objective_f} in \(O(d^{\frac{\omega}{2}})\) arithmetic operations  and one gradient evaluation of $f$.




To train the reverse diffusion's SDE, we also need to model the covariance term \eqref{objective_g}, a \(d \times d = n^2 \times n^2\) matrix. To achieve a  per-iteration runtime sublinear in the $d^2 = n^4$ matrix entries, we leverage the special structure of the covariance matrix, which arises from the manifold's symmetries. 
%
For example, the forward diffusion \(U(t) \in \mathrm{SO}(n)\) (or \(U(t) \in \mathrm{U}(n)\)) is governed by the following system of SDEs:
%
\begin{eqnarray}\label{eq_DBM_projection}
 \textrm{d} u_i(t) \textrm{$=$} \sum _{j \in [n] \backslash \{i\}}  \left( \alpha_{i j}(t) \textrm{d}B_{ij} u_j(t) \textrm{$-$}  
\frac{\beta_{i j}(t)}{2} u_i(t) \right) \textrm{d}t,
\end{eqnarray}
%
where $\alpha_{ij}(t) := \mathbb{E}\left [\nicefrac{1}{(\lambda_i(t) - \lambda_j(t))} | \varphi(Z_t) = U(t)\right]$ and  $\beta_{ij}(t) := \mathbb{E}\left[\nicefrac{1}{(\lambda_i(t) - \lambda_j(t))^2} | \varphi(Z_t) = U(t)\right]$
%
 $\forall i,j \in [n]$.
%
To train a model for this covariance term with sublinear runtime, we exploit the symmetries of the underlying group. These symmetries ensure the covariance term in \eqref{eq_DBM_projection} is fully determined by \(n^2\) scalar terms \(\alpha_{ij}(t)\) for \(i, j \in [n]\) and the \(n \times n\) matrix \(U\). 
%
Thus, it suffices to train a model \(\mathcal{A}(U, t) \in \mathbb{R}^{n \times n}\) for these \(n^2\) terms by minimizing the objective $
\|\mathcal{A}(U, t) - A\|_F^2$,
where \(A\) is the \(n \times n\) matrix with entries \(A_{ij} = \nicefrac{1}{(\lambda_i(t) - \lambda_j(t))}\), and \(\lambda_i(t)\) is the \(i\)th diagonal entry of \(\Lambda \equiv \Lambda(t)\). A similar method applies to efficiently train the covariance term for the sphere (see Appendix \ref{appendix_use_cases}).


\smallskip
\noindent
\textbf{Sampling algorithm.}
%
 To (approximately) sample from $\pi$, we approximate the drift and covariance terms of the %SDE for the 
 reverse diffusion \eqref{eq_r1} via trained models $\hat{f}, \hat{g}$ obtained by solving \eqref{objective_f} (in practice, $\hat{f}, \hat{g}$  are neural networks $\hat{f}_\theta, \hat{g}_\phi$, and $\theta, \phi$  outputs of Algorithm \ref{alg_training_manifold}).\
 %
  We initialize this SDE at $\varphi(N(0,I_d))$, the pushforward of $N(0,I_d)$ onto $\mathcal{M}$ with respect to\  $\varphi$.
%
 \begin{equation}\label{eq_reverse_SDE3b}
  \mathrm{d}\hat{Y}_t  = \hat{f}(\hat{Y}_t,t) \mathrm{d}t + \hat{g}(\hat{Y}_t,t)\mathrm{d}B_t, \quad \hat{Y}_0 \sim \varphi(N(0,I_d)).
 \end{equation}
% }
 %
%
To generate samples, we numerically simulate the SDE \eqref{eq_reverse_SDE3b} for  $\hat{Y}_T$ by discretizing it with a small time-step $\Delta>0$: 
 %{
\begin{equation}\label{eq_finite_difference} 
 \hat{y}_{i+1}  = \mathrm{exp}\left(\hat{y}_i, \, \, \hat{f}(\hat{y}_i,t) \Delta + \hat{g}(\hat{y}_i,t)\sqrt{\Delta}\xi_i \right), 
 \end{equation}
 $i \in \{0,\ldots,\nicefrac{T}{\Delta} \}$,  initialized at  $\hat{y}_0 \sim \varphi(N(0,I_d))$.
%

      \begin{algorithm}[H]
%
\caption{Training algorithm} 
\label{alg_training_manifold}
%

\begin{algorithmic}[1]
% \small
\REQUIRE {Oracle for a ``projection'' $\varphi: \mathbb{R}^d \rightarrow \mathcal{M}$, and  its gradient}
%
\REQUIRE {Oracle for %an ``inverse'' 
map $\psi: \mathcal{M}  \rightarrow \mathbb{R}^d$ s.t. $\varphi(\psi(x)) = x$  $\forall x \in \mathcal{M}$}
%
\REQUIRE {Dataset $D = \{x_0^1,\ldots,x_0^m\} \subseteq \mathcal{M}$. Hyperparam.\ $T>\,$0}
%
\REQUIRE {Models $f_{\hat{\theta}}: \mathcal{M} \times [0,T] \rightarrow   \mathcal{T} \mathcal{M}$ and $g_{\hat{\phi}}: \mathcal{M} \times [0,T] \rightarrow \mathcal{T} \mathcal{M}\times \mathcal{T} \mathcal{M}$.  $\hat{\theta} \in \mathbb{R}^{a_1}$, $\hat{\phi} \in \mathbb{R}^{a_2}$ denote trainable parameters}
%

\REQUIRE {Initial parameters $\theta_0 \in \mathbb{R}^{a_1}$, $\phi_0 \in \mathbb{R}^{a_2}$}
%

\REQUIRE {Hyperparameters: Number of stochastic gradient descent iterations $r\in \mathbb{N}$. Step size $\eta>0$, batch size  $\mathfrak{b}$}


\STATE Define,  $\forall \hat{\theta} \in \mathbb{R}^{a_1}$ $\hat{z} \in \mathbb{R}^d$, $b, x \in \mathcal{M}$, $\hat{t} \in [0,T]$, the objective function
%
$F(\hat{\theta}; b, \hat{z},  \hat{x}, \hat{t}):= \|(\nabla \varphi(\hat{z}))^\top  \frac{\hat{z}-\psi(b)e^{-(T-t)/2}}{e^{-(T-t)}-1}   + \frac{1}{2}\mathrm{tr}( \nabla^2 \varphi(\hat{z}))  -  f(\hat{x}, \hat{t}) \|^2$
%

\STATE Define $\forall \hat{\theta} \in \mathbb{R}^{a_2}$ $\hat{z} \in \mathbb{R}^d$, $b, x \in \mathcal{M}$, $\hat{t} \in [0,T]$, the objective 
%
$G(\hat{\phi}; b, \hat{z},  \hat{x}, \hat{t}):= \|J_{\varphi}(\hat{z})^\top J_{\varphi}(\hat{z}) - (g_{\hat{\phi}}(\hat{x}, \hat{t}))^2 \|_F^2$




\STATE Set $\theta \leftarrow \theta_0$,  $\phi \leftarrow \phi_0$

\FOR {$i = 1, \ldots, r$}

\STATE Sample a random batch $S \subseteq [m]$ of size $\mathfrak{b}$,

\STATE Sample $t \sim \mathrm{Unif}([0,T])$

\FOR {$j \in S$}

\STATE Sample $\xi \sim N(0, I_d)$

\STATE Set $z_j \leftarrow  \psi(x_0^j) e^{-\frac{1}{2}(T-t)} + \sqrt{1-e^{-(T-t)}} \, \xi$


\STATE Set $x_j \leftarrow \varphi(z_j)$




\ENDFOR


  \STATE Compute $\Gamma \leftarrow \frac{1}{\mathfrak{b}}\sum_{j \in S} \nabla_\theta F(\theta; x_0^j, z_j,  x_j, t)$ \label{line_F}

  \STATE $\theta \leftarrow  \theta - \eta \Gamma$

  \STATE Compute $\Upsilon \leftarrow \frac{1}{\mathfrak{b}}\sum_{j \in S} \nabla_\phi G(\phi; x_0^j, z_j,  x_j, t)$ \label{line_G}

  \STATE $\phi \leftarrow  \phi - \eta \Upsilon$

\ENDFOR

  \STATE {\bf output:} {Parameters $\theta, \phi$ for the models $f_{\theta}$ and $g_{\phi}$}

\end{algorithmic}
\end{algorithm}




        \begin{algorithm}[H]
%
\caption{Sampling algorithm} \label{alg_sampling_manifold}
%
\begin{algorithmic}[1]
%\small
\REQUIRE {An oracle which returns the value of the exponential map $\mathrm{exp}(x,v)$ on some  manifold $\mathcal{M}$, for any $x \in \mathcal{M}$, $v \in \mathcal{T}_x \mathcal{M}$}
%

\REQUIRE {An oracle for the ``projection'' map $\varphi: \mathbb{R}^d \rightarrow \mathcal{M}$}
%
\REQUIRE {Models $f_{\hat{\theta}}: \mathcal{M} \times [0,T] \rightarrow   \mathcal{T} \mathcal{M}$ and $g_{\hat{\phi}}: \mathcal{M} \times [0,T] \rightarrow \mathcal{T} \mathcal{M}\times \mathcal{T} \mathcal{M}$.  $\hat{\theta} \in \mathbb{R}^{a_1}$, $\hat{\phi} \in \mathbb{R}^{a_2}$ denote trainable parameters}



\REQUIRE {Parameters $\theta, \phi$ (from output of Algorithm \ref{alg_training_manifold})}, 
%
\REQUIRE {$T>0$, $N \in \mathbb{N}$, $\Delta>0$ such that $\nicefrac{T}{\Delta} \in N\mathbb{Z}$.}


\STATE Sample $z_0 \sim N(0,I_d)$, and Set $\hat{y}_0 \leftarrow \varphi(z_0)$


\FOR {$i = 0,1, \ldots, \nicefrac{T}{\Delta} -1$}

%
\STATE Sample $\xi \sim N(0,I_d)$.

\STATE Set $\hat{y}_{i+1} \leftarrow \mathrm{exp}\left(\hat{y}_i, \, \, \hat{f}(\hat{y}_i,i\Delta) \Delta + \hat{g}(\hat{y}_i,i\Delta)\sqrt{\Delta}\xi_i \right)$


\ENDFOR

\STATE {\bf output} {$\hat{y}_{\nicefrac{T}{\Delta}}$}
\end{algorithmic}
\end{algorithm}



\section{Overview of proof of sampling guarantees (Theorem \ref{thm_sampling_Manifold_best})}
\label{sec:proof_outline}

In this section, we first present the main highlights and novel techniques used to establish our sampling guarantees.
Next, we provide a detailed outline of the proof, explaining how these techniques come together to validate our sampling guarantees (Section \ref{sec_proof_overview}).


Girsanov transformations, used in prior works to bound accuracy, do not apply to our diffusion due to its spatially varying covariance. We adopt an optimal transport approach, selecting an optimal coupling between the ``ideal'' diffusion \(Y_t\), governed by the SDE \(\mathrm{d}Y_t = f^{\star}(Y_t, t)\mathrm{d}t + g^{\star}(Y_t, t)\mathrm{d}B_t\), and the diffusion \(\hat{Y}_t\), where \(f^{\star}, g^{\star}\) are replaced by our trained model \(\hat{f}, \hat{g}\), within an error \(\epsilon\).
%
 We first construct a simple coupling between $Y_t$ and $\hat{Y}_t$ by setting the underlying $B_t$ in their SDEs equal.  
  Applying comparison theorems for manifolds of non-negative curvature to the coupled SDEs, we prove a generalization of Gronwall's inequality to SDEs on manifolds (Lemma \ref{Gronwall}).
%
\begin{equation}\label{eq_r2_b} 
W_2(\hat{Y}_t, Y_t)\leq (\rho^2(\hat{Y}_0, Y_0) + \epsilon) e^{c t},
\end{equation}
 where $\rho$ is geodesic distance on $\mathcal{M}$ and $W_2$ the Wasserstein distance.
 %
 \eqref{eq_r2_b} holds if $f^\star, g^\star$ are $c$-Lipschitz on {\em all} of $\mathcal{M}$. 

\smallskip
\noindent
 {\bf  Showing  ``average-case'' Lipschitzness.}
$\varphi$ is not in general Lipschitz.
%
 E.g., on $\mathrm{SO}(n)$ and $\mathrm{U}(n)$,  $\varphi(Z)$ has singularities at points where the eigengaps of $Z+Z^\ast$ vanish. 
 %
 By using tools from random matrix theory, we instead show $\varphi$ satisfies an ``average-case'' Lipschitzness, on a set $\Omega_t$ on which the diffusion $Z_t \in \mathbb{R}^d$ remains w.h.p. (Lemma \ref{Lemma_average_case_Lipschitz}).
%
  Next, we show that for $f^\star$, $g^\star$ to be $c$-Lipschitz {\em everywhere} on $\mathcal{M}$, it is sufficient for $\varphi$ to only satisfy average-case Lipschitzness.
 %
  To do this, we express $f^\star$ (and $g^\star$) as an integral over the eigenvalues $\Lambda$ of $Z_t + Z_t^\ast = U \Lambda U^\ast$,
  %
\begin{equation*}
f^\star(U, t) \propto 
%
 \int \left[\nabla \varphi(Z)^\top \nabla \log q_{T-t|0}(Z) { + } \cdots \right] \mathbbm{1}_{\Omega_t}(Z) \mathrm{d} \Lambda
 \end{equation*}
%
 Due to the manifold's symmetries, we observe $\Omega_t$ (and the entire integrand) depend only on $\Lambda$, not the eigenvectors $U \in \mathrm{U}(n)$.
 %
   This allows us to show the integral ``smooths out'' the singularities of $\varphi$, and that $f^\star(U, t)$ (and $g^\star$) are $\mathrm{poly}(d)$-Lipschitz at {\em every} $U \in \mathrm{U}(n)$ on the manifold (Lemma \ref{lemma_Lipschitz}).

\smallskip
\noindent
{\bf Improved coupling to obtain $\mathrm{poly}(d)$ bounds.}
%
 While we have shown our model's SDE is $c=\mathrm{poly(d)}$-Lipschitz on $\mathcal{M}$, after times $\tau > \frac{1}{c} = \frac{1}{\mathrm{poly(d)}},$ our Wasserstein bound \eqref{eq_r2_b} grows exponentially with $d$.
%
To overcome this, we define a new coupling between $Y_t, \hat{Y}_t$ which we ``reset'' after time intervals of length $\tau = \nicefrac{1}{c}$ by converting our Wasserstein bound into a total variation (TV) bound after each interval. 
%
   Key to converting the bound is to show that w.h.p. the projection $\varphi$ has $\mathrm{poly}(d)$-Lipschitz Jacobian everywhere in a ball of radius $\nicefrac{1}{\mathrm{poly}(d)}$ around our diffusion. 
%
 By alternating between Wasserstein and TV bounds, we get error bounds which grow proportional to $\nicefrac{T}{\tau}= \mathrm{poly(d)}$ (Lemma \ref{Lemma_Wasserstein_to_TV_conversion}).

\smallskip
\noindent
{\bf Handling instability on $\mathrm{SO}(n)$.} 
These proof ideas extend easily to the torus and sphere. For \(\mathrm{SO}(n)\), an additional challenge arises: w.h.p., gaps between neighboring eigenvalues become exponentially small in \(d\) over short time intervals due to weaker ``electrical repulsion'' between eigenvalues of real-valued random matrices. During these intervals, the diffusion moves at \(\exp(d)\) velocity.
%
Despite this, we show that a step size of \(1/\mathrm{poly}(d, \frac{1}{\delta})\) suffices to simulate a random solution to the SDE with a  distribution \(\delta\)-close to the correct one. 
During these intervals, interactions between eigenvectors nearly separate into slow-moving eigenvectors and pairs of fast-moving eigenvectors, with a simple transition kernel from the invariant measure on \(\mathrm{SO}(2)\) (see Section \ref{appendix_SO_sketch}).




\subsection{Proof outline of Theorem \ref{thm_sampling_Manifold_best}}\label{sec_proof_overview}

In the following, for any random variable $X$ we denote its probability distribution by $\mathcal{L}_X$.
%
As already mentioned, previous works use Girsanov's theorem to bound the accuracy of diffusion methods.  However, Girsanov transformations do not exist for our diffusion as it has a non-constant covariance term which varies with the position $x$.  Thus, we depart from previous works and instead use an optimal transport approach based on a carefully chosen optimal coupling between the ``ideal diffusion'' $Y_t$ and the algorithm's process $\hat{y}_t$
%
Specifically, denoting by $\mu_t$ the distribution of $Y_t$ and by $\nu_t$ the distribution of $\hat{Y}_t$, the goal is to bound the Wasserstein optimal transport distance $W_2(\mu_t,\nu_t) := \inf_{\kappa \in \mathcal{K}(\mu_t,\nu_t)} \mathbb{E}_{(Y_t, \hat{Y}_t)}[\rho^2(\hat{Y}_t, Y_2)]$ where $\mathcal{K}(\mu,\nu)$ is the collection of all couplings of the distributions $\mu$ and $\nu$, and $\rho$ is the geodesic distance on $\mathcal{M}$. 
%
Towards this end, we would like to find a coupling $\kappa$ which (approximately) minimizes  $\mathbb{E}_{(Y_t \sim \mu_t, \hat{Y}_t \sim \nu_t)}[\rho^2(\hat{Y}_t, Y_2)]$ at any given time $t$.

 As a first attempt, we consider the simple coupling where we couple the ``ideal'' reverse diffusion $Y_t$,
%
\begin{equation}
\mathrm{d}Y_t = f^{\star}(Y_t, t)\mathrm{d}t + g^{\star}(Y_t, t)\mathrm{d}B_t,
\end{equation}
%
and the reverse diffusion $\hat{Y}_t$ given by our trained model $\hat{f}, \hat{g}$,
%
\begin{equation} 
\mathrm{d}\hat{Y}_t = \hat{f}(\hat{Y}_t, t)\mathrm{d}t + \hat{g}(Y_t, t)\mathrm{d}B_t.
\end{equation}
%
To couple these two diffusions, we set their Brownian motion terms $\mathrm{d}B_t$ to be equal to each other at every time $t$.
%
In a similar manner, we can also couple $\hat{Y}_t$ and the discrete-time algorithm $\hat{y}_i$ by setting the Gaussian term $\xi_i$ in the stochastic finite difference equation  \eqref{eq_finite_difference} to be equal to $\xi_i = \frac{1}{\sqrt{\Delta}}\int_{\Delta i}^{\Delta (i+1)}\mathrm{d}B_t \mathrm{d}t$ for every $i$.

\medskip
\noindent
{\bf Step 1: Bounding the Wasserstein distance for everywhere-Lipschitz SDEs.}
%
To bound the Wasserstein distance $W_2(Y_t, \hat{y}_t) \leq W_2(Y_t, \hat{Y}_t) +  W_2(\hat{Y}_t, \hat{y}_t)$, we first prove a generalization of Gronwall's inequality to Stochastic differential equations on manifolds (Lemma \ref{Gronwall}).
%
 Gronwall's inequality \cite{gronwall1919note} says that if $R: [0,T] \rightarrow \mathbb{R}$  satisfies the differential inequality $\frac{\mathrm{d}}{\mathrm{d}}R(t) \leq \beta(t) R(t)$ for all $t>0$, where the coefficient $\beta(t): [0,T] \rightarrow \mathbb{R}$ may also be a function of $t$, then the solution to this differential inequality satisfies $R(t) \leq R(0) e^{\int_0^t \beta(s) \mathrm{d}s}.$


 Towards this end, we first couple $Y_t$ and $\hat{Y}_t$ by setting their Brownian motion terms $\mathrm{d}B_t$ equal to each other and then derive an SDE for the squared geodesic distance $\rho^2(\hat{Y}_t, Y_t)$ using It\^o's lemma.
 %
Taking the expectation of this SDE gives an ODE for  $\mathbb{E}[\rho^2(\hat{X}_t, X_t)]$,
 %
\begin{align} 
&\mathrm{d} \mathbb{E}[\rho^2(\hat{X}_t, X_t)] \nonumber\\
%
&\quad =  \mathbb{E} \left[\nabla \rho^2(\hat{X}_t, X_t)^\top \begin{pmatrix} f^\star(X_t, t)\\  \hat{f}(\hat{X}_t, t)  \end{pmatrix} \,  + 
%
 \frac{1}{2} \mathrm{Tr} \begin{pmatrix}  g^\star(X_t,t) \, \, 0\\   \hat{g}(X_t,t) \, \, \, \, \, 0  \end{pmatrix}^\top \nabla^2 \rho^2(\hat{X}_t, X_t) \begin{pmatrix}  g^\star(X_t,t) \, \, 0\\   \hat{g}(X_t,t) \, \, \, \, \, 0  \end{pmatrix}  \right]  \mathrm{d}t.
\end{align}
%
To bound each term on the r.h.s., we first observe that, roughly speaking, due to the non-negative curvature of the manifold, by the Rauch comparison theorem \cite{rauch1951contribution}, each derivative on the r.h.s.\ is no larger than in the Euclidean case $\mathcal{M} = \mathbb{R}^d$ where $\rho^2(\hat{X}_t, X_t) = \|\hat{X}_t- X_t\|_2^2$.  Hence we have that
%
\begin{align*} \left|\nabla \rho^2(\hat{X}_t, X_t)^\top \begin{pmatrix} f^\star(X_t, t)\\  \hat{f}(\hat{X}_t, t)  \end{pmatrix} \right| \leq 2\|\hat{X}_t - X_t\| \times
%
\|f^\star(X_t, t)-  \hat{f}(\hat{X}_t, t)\|
%
\leq 2 \|\hat{X}_t - X_t\| (c\|\hat{X}_t - X_t\| + \epsilon),
\end{align*}
as long as we can show that $f^\star$ is $c$- Lipschitz for some $c>0$ (see Step 2 below).
%
Bounding the covariance term in a similar manner, and applying Gronwall's lemma to the differential inequality, we get that 
%
\begin{equation}\label{eq_r2} 
W_2(\hat{Y}_t, Y_t)\leq \mathbb{E}[\rho^2(\hat{Y}_t, Y_t)] \leq (\rho^2(\hat{Y}_0, Y_0) + \epsilon) e^{c t}.
\end{equation}

\smallskip
\noindent
{\bf Step 2: Showing that our diffusion satisfies an ``average-case'' Lipschitz condition.}
% 
To apply \eqref{eq_r2}, we must first show that the drift and diffusion terms $f^\star$ and $g^\star$ are Lipschitz on $\mathcal{M}$. 
%
Towards this end, we would ideally like to apply bounds on the derivatives of the projection map $\varphi : \mathbb{R}^d \rightarrow \mathcal{M}$ which defines our diffusion $Y_t$.
%
Unfortunately, in general, $\varphi$ may not be differentiable at every point.
%
This is the case for the sphere, where the map $\varphi(z) = \frac{z}{\|z\|}$ has a singularity at $z=0$.
%
 This issue also arises in the case of the unitary group and orthogonal group, since the derivative of the spectral decomposition $\varphi(z) = U^\ast \Lambda U$ has singularities at any matrix $z$ which has an eigenvalue gap $\lambda_{i}-\lambda_{i+1} = 0$.

 To tackle this challenge, we show that, for the aforementioned symmetric manifolds, the forward diffusion $Z_t$ in $\mathbb{R}^d$ remains in some set $\Omega_t  \subseteq \mathbb{R}^d$ with high probability $1-\alpha$, on which the map $\varphi(Z_t)$ has derivatives bounded by $\mathrm{poly}(d)$ (Assumption \ref{assumption_Lipschitz} and Lemma \ref{Lemma_average_case_Lipschitz}).
 %
 We then show how to ``remove'' the rare outcomes of our diffusion that do not fall inside $\Omega_t$. 
 %
 As our forward diffusion $X_t$ (and thus the reverse diffusion $Y_t=X_{T-t}$) remains at every $t$  inside $\Omega_t$ with probability $\geq 1-\alpha$, removing these ``bad'' outcomes only adds a cost of $\alpha$ to the total variation error.


\medskip
\noindent
{\em Showing that $\varphi$ has $\mathrm{poly}(d)$ derivatives w.h.p. (showing that Assumption \ref{assumption_Lipschitz} holds).}
%
 We first consider the sphere, which is the simplest case (aside from the trivial case of the torus, where the derivatives of $\varphi$ are all $O(1)$ at every point).
%
In the case when data is on the sphere, which we embed as a unit sphere in $\mathbb{R}^d$, one can easily observe that e.g. $\|\nabla \varphi(z)\| \leq O(1)$ for any $z$ outside a ball of radius $r \geq \Omega(1)$ centered at the origin.
%
As the volume of a ball of radius $r = \alpha$ is $\frac{1}{r^d}$, one can use standard Gaussian concentration inequalities to show that the Brownian motion $X_t$ will remain outside this ball for time $T$ with probability roughly $1-O(\frac{1}{r^d T})$.


 We next show that the Lipschitz property holds for the unitary group $\mathrm{U}(n)$.
 %
 %
  We first recall results from random matrix theory which allow us to bound the eigenvalue gaps of a matrix with Gaussian entries.
 %
 Specifically, these results say that roughly speaking, if $X_0$ is any matrix and $X_t = X_0 + B(t)$, where $B(t)$ is a symmetric matrix with iid $N(0, t)$  entries undergoing Brownian motion, one has that the eigenvalues $\gamma_1(t) \geq \cdots \geq \gamma_n(t)$ of $X_t$ satisfy for all $s \geq 0$ (see e.g. \cite{anderson2010introduction, mangoubi2023private, mangoubi2025private}),
 %
\begin{equation}\label{eq_r3}  
    \mathbb{P} \left( \bigcap_{t \in [t_0, T]} 
    \left\{ \gamma_{i+1}(t) - \gamma_i(t) \leq s \frac{1}{\mathrm{poly}(n) \sqrt{t} } \right\} \right) 
    \leq O\left(s^{\frac{1}{2}}\right).
\end{equation}
%
Thus, if we define $\Omega_t$ to be the set of outcomes of such that $\gamma_{i+1}(t) - \gamma_i(t) \leq \alpha^2 \frac{1}{\mathrm{poly}(n) \sqrt{t}}$, we have that $\mathbb{P}(X_t \in \Omega_t \, \, \, \forall t \in [t_0,T]) \geq 1- \alpha$.


 Our high-probability bound on $\Omega_t$ allows us to show that $\varphi$ satisfies a Lipschitz property at ``most'' points $\Omega_t$.
 %
 However, if we wish to apply \eqref{eq_r2}, we need to show that drift term $f^\star$ and covariance term $g^\star$ in our diffusion satisfy a Lipschitz property at {\em every} point in $\mathbb{R}^d$.
 %
 Towards this end, we first make a small modification to the objective function which allows us to exclude outcomes $\{X_t\}_{t\in [0,T]}$ of the forward diffusion such that $X_t \notin \Omega_t$ for some $t \in [0, T]$.
%
Specifically, we multiply the objective function \eqref{objective_f} by the indicator function $\mathbbm{1}_{\Omega_t}(z)$. 
%
As determining whether a point $z\in \Omega_t$ requires only checking the eigenvalue gaps (when $\mathcal{M}$ is the unitary or orthogonal group), computing $\mathbbm{1}_{\Omega_t}(z)$ can be done efficiently using the singular value decomposition.

\medskip
\noindent
{\em Bounding the Lipschitz constant of  $f^\star$ and $g^\star$.}
Recall that (when, e.g., $\mathcal{M}$ is one of the aforementioned symmetric manifolds) we may decompose any $z \in \mathbb{R}^d$ as $z \equiv z(U, \Lambda)$ where $U \in \mathcal{M}$.
%
Note that $\mathbbm{1}_{\Omega_t}(z)$ is {\em not} a continuous function of $z$. 
%
However, we will show that, as $\mathbbm{1}_{\Omega_t}(z(U,\Lambda))$ depends only on $\Lambda$, multiplying our objective function by $\mathbbm{1}_{\Omega_t}$ does not make $f^\star$ and $g^\star$ discontinuous (and thus does not prevent them from being Lipschitz).
%
This is because $f^\star$ and $g^\star$ are given by conditional expectations conditioned on $U$, and can thus be decomposed as integrals over $\Lambda$.
%
%
Towards this end we express $f^\star$ as an integral over the parameter $\Lambda$,
%
\begin{align*}
 f^\star(U, t) =
%
  c_U  \int_{\Lambda \in \mathcal{A}} 
%
\left[ \nabla \varphi(z(U,\Lambda))^\top \nabla \log q_{T-t|0}(z(U,\Lambda)) 
%
  + \frac{1}{2}\mathrm{tr}\nabla^2 \varphi(z(U,\Lambda))\right] q_{T-t}(z(U,\Lambda))
%
\mathbbm{1}_{\Omega_t}(\Lambda) \mathrm{d} \Lambda ,
\end{align*}
%
 where $c_U$ 
 is a normalizing constant.
%
 Differentiating with respect to\ $U$,
%
\begin{align}\label{eq_r5}
&\frac{\mathrm{d}}{\mathrm{d}U} f^\star(U, t) = \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}} \bigg[ 
%
\frac{\mathrm{d}}{\mathrm{d}U}   (\nabla \varphi(z(U,\Lambda))^\top \nabla_U \log q_{T-t|0}(z(U,\Lambda)) \nonumber\\ %
& \qquad \qquad \qquad  \qquad \qquad \qquad \qquad \qquad  + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U,\Lambda)))) \mathbbm{1}_{\Omega_t}(\Lambda) \, \, \bigg | \, \, V=U \bigg] + \cdots,
% %
\end{align}
%
where ``$\cdots$'' includes three other similar terms.
%
To bound the terms on the r.h.s. of \eqref{eq_r5}, we apply Assumption \ref{assumption_Lipschitz} which says that the operator norms of $\nabla \varphi$, $\nabla^2 \varphi$, $\frac{\mathrm{d}}{\mathrm{d}U}\nabla \varphi$ and $\frac{\mathrm{d}}{\mathrm{d}U}\nabla^2 \varphi$ are all bounded above by $\mathrm{poly}(d)$ whenever $z \in \Omega_t$.
%
 To bound the term $\nabla_U \log q_{T-t|0}(z(U,\Lambda))$ we note that  $\nabla \log q_{T-t|0}(z(U,\Lambda))$ is the drift term of the reverse diffusion in Euclidean space.
 %
This term was previously shown to be $d C^2$-Lipschitz for all $t \geq \Omega(\frac{1}{d})$ when the support of the data distribution in $\mathbb{R}^d$ lies in a ball of radius $C$ (see, e.g., Proposition 20 of  \cite{chen2023sampling}).
%
Thus, plugging in the above bounds into \eqref{eq_r5} we have that $\|\frac{\mathrm{d}}{\mathrm{d}U} f^\star(U, t)\|_{2 \rightarrow 2} \leq \mathrm{poly}(d)$.
%
A similar calculation shows that $\|\frac{\mathrm{d}}{\mathrm{d}U} g^\star(U, t)\|_{2 \rightarrow 2} \leq \mathrm{poly}(d)$.
%
This immediately implies that $f^\star(U,t)$ and $g^\star(U,t)$ are $\mathrm{poly}(d)$-Lipschitz at {\em every} $U \in \mathcal{M}$.







\medskip
\noindent
{\bf Step 3: Improving the coupling to obtain polynomial-time bounds.}
%
Now that we have shown that $f^\star$ and $g^\star$ are $\mathrm{poly}(d)$-Lipschitz, we can apply \eqref{eq_r2} to bound the Wasserstein distance:
%
$W_2(\hat{Y}_{t+\tau}, Y_{t+\tau})\leq (\rho^2(\hat{Y}_t, Y_t) + \epsilon) e^{c \tau} \qquad \forall \tau \geq 0,$
%
where $c \leq \mathrm{poly}(d)$.

%
Moreover, with slight abuse of notation, we may define $\hat{y}_{t+\tau}$ to be a continuous-time interpolation of the discrete process $\hat{y}$.
%
Applying \eqref{eq_r2} to this process we get that, roughly,
%
$W_2(\hat{Y}_{t+\tau}, \hat{y}_{t+\tau})\leq (\rho^2(\hat{y}_t, Y_t) + \epsilon + \Delta) e^{c \tau}$ for $\tau \geq 0$.
%
Thus, we get a bound on the Wasserstein error,
%
\begin{align}\label{eq_r6}
W_2(Y_{t+\tau}, \hat{y}_{t+\tau}) \leq W_2(\hat{Y}_{t+\tau}, Y_{t+\tau}) + W_2(\hat{Y}_{t+\tau}, \hat{y}_{t+\tau}) \leq  (\rho^2(\hat{y}_t, Y_t) + \epsilon + \Delta) e^{c \tau}, \qquad \tau \geq 0.
\end{align}
%
Unfortunately, after times $\tau > \frac{1}{c} = \frac{1}{\mathrm{poly(d)}},$ this bound grows exponentially with the dimension $d$.
%
To overcome this challenge, we define a new coupling between $Y_t$ and $\hat{Y}_t$ which we ``reset'' after time intervals of length $\tau = \frac{1}{c}$ by converting our Wasserstein bound into a total variation bound after each time interval.
%
  Towards this end, we use the fact that if at any time $t$ the total variation distance satisfies $\|\mathcal{L}_{Y_t} - \mathcal{L}_{\hat{y}_t}\|_{\mathrm{TV}}\leq \alpha$, then there exists a coupling such that $Y_t = \hat{Y}_t$ with probability at least $1-\alpha$.
  %
  In other words, w.p. $\geq 1-\alpha$, we have $\rho(\hat{y}_{t+\tau}, Y_{t+\tau}) = 0$, and we can apply inequality \eqref{eq_r6} over the next time interval of $\tau$ without incurring an exponential growth in time.
  %
Repeating this process $\frac{T}{\tau}$ times, we get that $\|\mathcal{L}_{Y_T} - \mathcal{L}_{\hat{y}_T}\| \leq \alpha \times \frac{T}{\tau}$, where the TV error grows only {\em linearly} with $T$.

\medskip
\noindent
{\em Converting Wasserstein bounds on the manifold to TV bounds.}
To complete the proof, we still need to show how to convert the Wasserstein bound into a TV bound (Lemma \ref{Lemma_Wasserstein_to_TV_conversion}).
%
Towards this end, we begin by showing that the transition kernel $\tilde{p}_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| H_{t+\tau})$ of the reverse diffusion $H_t$ in $\mathbb{R}^d$ is close to a Gaussian in KL distance:  
%
\begin{equation*}
D_{\mathrm{KL}} (N(H_{t+\tau} + \hat{\Delta} \nabla \tilde{p}_{T-t-\tau}(H_{t+\tau}), \hat{\Delta} I_d) \, \| \, \tilde{p}_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| H_{t+\tau} )) \leq \frac{\alpha \tau}{T}.
\end{equation*}
%
One can do this via Girsanov's theorem, since, unlike the diffusion $Y_t$ on the manifold, the reverse diffusion in Euclidean space $H_t$ {\em does} have a constant diffusion term (see e.g. Theorem 9 of \cite{chen2023sampling}).

Next, we use the fact that with probability at least $1-\alpha \frac{\tau}{T}$ the map $\varphi$ in a ball of radius $\frac{1}{\mathrm{poly}(d)}$ about the point $H_{t+\tau}$ has $c$-Lipschitz Jacobian where $c=\mathrm{poly}(d)$, and that the inverse of the exponential map $\mathrm{exp}(\cdot)$ has $O(1)$-Lipschitz Jacobian, to show that the transition kernel $p_t$ of $Y_t = \varphi(H_t)$ satisfies
%
\begin{equation*}
D_{\mathrm{KL}} (\nu_1 \, \| \, p_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| Y_{t+\tau} ) ) \leq (1+\hat{\Delta} c)^d \frac{\alpha \tau}{T} \leq 2\frac{\alpha \tau}{T}
\end{equation*}
%
 if we choose $\hat{\Delta} \leq O(\frac{1}{c d})$, where $\nu_1:= \mathrm{exp}_{Y_{t+\tau}}(N(Y_{t+\tau} + \hat{\Delta} f^\star(Y_{t+\tau},t+\tau), \, \, \hat{\Delta} g^{\star 2}(Y_{t+\tau},t+\tau) I_d))$.


Next, we plug in our Wasserstein bound $W(Y_{t+\tau}, \hat{y}_{t+\tau}) \leq O(\epsilon)$ 
into the formula for the KL divergence between two Gaussians to bound $\|\mathcal{L}_{Y_{t+\tau+\hat{\Delta}}} - \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}\|_{\mathrm{TV}}$.
%
Specifically, noting that $\mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}|\hat{y}_{t}} = \mathrm{exp}_{\hat{y}_{t+\tau}}(N(\hat{y}_{t+\tau} + \hat{\Delta} f(\hat{y}_{t+\tau},t+\tau), \hat{\Delta} g^2(\hat{y}_{t+\tau},t+\tau) I_d))$, we have that 
%
\begin{eqnarray*}
    D_{\mathrm{KL}} \big(\nu_1, \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}|\hat{y}_{t+\tau}} \big) 
    &=& \mathrm{Tr} \left( \big(g^{\star 2}(Y_{t+\tau}, t+\tau) \big)^{-1} g^2(\hat{y}_{t+\tau}, t+\tau) \right) \\
    & &  - d + \log \frac{\det g^{\star 2}(Y_{t+\tau}, t+\tau)}{\det g^2(\hat{y}_{t+\tau}, t+\tau)} + w^\top \big( \hat{\Delta} g^{\star 2}(Y_{t+\tau}, t) \big)^{-1} w.
\end{eqnarray*}
where $w:=Y_{t+\tau} - \hat{y}_{t+\tau} + \hat{\Delta}(f^\star(Y_{t+\tau}, t+\tau) - f(\hat{y}_{t+\tau}, t+\tau))$.
%
Since with probability $\geq 1-\alpha \frac{\tau}{T}$ we have $g^\star(Y_{t+\tau}) \succeq \mathrm{poly}(d)$, plugging in the error bounds $\|f^\star(Y_{t+\tau},t) - f(Y_{t+\tau},t)\| \leq \epsilon$ and $\|g^\star(Y_{t+\tau},t) - g(Y_{t+\tau},t)\|_F \leq \epsilon$ and the $c$-Lipschitz bounds on $f^\star$ and $g^\star$, where $c = \mathrm{poly}(d)$, (Assumption \ref{assumption_Lipschitz}), we get that $D_{\mathrm{KL}}(\nu_1, \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}) \leq O(\epsilon^2 c^2)$.
%
 Thus, by Pinsker's inequality, we have
%
\begin{eqnarray}\label{eq_r7}
 \|\mathcal{L}_{Y_{t+\tau+\hat{\Delta}}} - \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}\|_{\mathrm{TV}} - \|\mathcal{L}_{Y_{t}} - \mathcal{L}_{\hat{y}_{t}}\|_{\mathrm{TV}} 
%
&\leq & \sqrt{D_{\mathrm{KL}} (\nu_1 \, \| \, p_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| Y_{t+\tau} ))} \nonumber\\
%
& 
 \qquad &  \qquad + \sqrt{D_{\mathrm{KL}}(\nu_1 \| \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}} |\hat{y}_{t} })} \leq O(\epsilon c).
\end{eqnarray}
%

\smallskip
\noindent
\textbf{Step 4: Bounding the accuracy.}
%
Recall that $q_t$ is the distribution of the forward diffusion $Z_t$ in Euclidean space after time $t$, which is an Ornstein-Uhlenbeck process.
% 
Standard mixing bounds for the Ornstein-Uhlenbeck process imply that, $\|q_t - N(0,I_d)\|_{TV} \leq O(Ce^{-t})$ for all $t>0$ (see e.g. \cite{bakry2014analysis}), where $C \leq \mathrm{poly}(d)$ is the diameter of the support of $\psi(\pi)$. 
%
Thus, it is sufficient to choose $T = \log(\frac{C}{\epsilon})$ to ensure $\|\mathcal{L}_{Y_{T}} - \pi \|_{\mathrm{TV}} = \|q_T - N(0,I_d) \|_{\mathrm{TV}} \leq O(\epsilon)$.

As \eqref{eq_r7} holds for all $t \in \tau \mathbb{N}$, the distribution $\nu = \mathcal{L}_{\hat{y}_{T}}$ of our sampling algorithm's output satisfies, since $\tau = \frac{1}{c}$,
\[
\|\pi - \nu\|_{\mathrm{TV}}  
= \|\mathcal{L}_{Y_{T}} - \pi \|_{\mathrm{TV}} 
+ \|\mathcal{L}_{Y_{T}} - \nu\|_{\mathrm{TV}} 
\leq O\left(\epsilon + \epsilon c \frac{T}{\tau} \right) 
= O\left(\epsilon c^2 \log\left(\frac{d C}{\epsilon} \right) \right) 
= \tilde{O}(\epsilon \times \mathrm{poly}(d)).
\]
%
\noindent
 \textbf{Step 5:  Bounding the runtime.}
 Since our accuracy bound requires $T = \log(\nicefrac{d C}{\epsilon})$, and requires a time-step size of $\Delta = cd \leq \frac{1}{\mathrm{poly}(d)}$, the number of iterations is bounded by 
% %
$\frac{T}{\Delta} = cd T \leq O\left(\mathrm{poly}(d)   \times \log\left(\nicefrac{d C}{\epsilon}\right)\right).$



\medskip
\noindent
{\bf Step 6: Extension of sampling guarantees to special orthogonal group.}
%
Similar techniques can be used in the case of the special orthogonal group.
%
   However, in the case of the special orthogonal group we encounter the additional challenge that, with high probability $\Omega(1)$, the gaps between neighboring eigenvalues $\gamma_{i+1}(t) - \gamma_i(t)$ may become exponentially small in $d$, over very short time intervals of length $O(\frac{1}{e^d})$.
   %
   %
   Over these intervals our diffusion moves at $\exp(d)$ velocity. 
   %
  Despite this, we show that a $1/\mathrm{poly}(d, \frac{1}{\delta})$ step size is sufficient to simulate a {\em random} solution to its SDE with {\em probability distribution} $\delta$-close to the correct distribution.
  %   
 Specifically, from the matrix calculus formula for $\varphi$ one can show that the SDE for the eigenvectors of the forward diffusion satisfy (these evolution equations, discovered by Dyson, are referred to as Dyson Brownian motion \cite{dyson1962brownian})
%
\begin{eqnarray}
    \mathrm{d} \gamma_i(t) &=& \mathrm{d}B_{ii}(t) + \sum_{j \neq i} \frac{\mathrm{d}t}{\gamma_i(t) - \gamma_j(t)}, 
    \label{eq_dyson_eigenvalue_overview} \\
    \mathrm{d} u_i(t) &=& \sum_{j \neq i} \frac{\mathrm{d}B_{ij}(t)}{\gamma_i(t)- \gamma_j(t)} u_j(t) 
    - \frac{1}{2} \sum_{j \neq i} \frac{\mathrm{d}t}{(\gamma_i(t) - \gamma_j(t))^2} u_i(t), 
    \quad \forall i \in [n].
    \label{eq_dyson_eigenvector_overview}
\end{eqnarray}
%
 Roughly speaking, this implies that only the interactions in \eqref{eq_dyson_eigenvector_overview} between eigenvectors with neighboring eigenvalues which fall below $O(\frac{1}{n^{10}})$ are significant, while interactions between eigenvectors with larger eigenvalue gaps are negligible over these short time interval.
 %
 Thus, one can analyze the evolution of the eigenvectors over these short time intervals as a collection of separable two-body problems consisting of interactions between pair(s) of eigenvectors with closed-form transition kernel given by the invariant measure on $\mathrm{SO}(2)$.
 %
  For a detailed sketch of how one can extend our proof to the case of the special orthogonal group, see Section \ref{appendix_SO_sketch}.


\section{Empirical results}\label{sec_empirical}

 We provide proof-of-concept simulations to compare the quality and efficiency of our algorithms to key prior works.

\medskip
\noindent
 {\bf Datasets.}
%
We evaluate the quality of samples generated by our model on synthetic datasets from the torus \(\mathbb{T}_d\), the special orthogonal group \(\mathrm{SO}(n)\), and the unitary group \(\mathrm{U}(n)\). The torus provides a simple, zero-curvature geometry for initial validation, while \(\mathrm{SO}(n)\) and \(\mathrm{U}(n)\) test the model on more complex geometries. 
%
Datasets include unimodal wrapped Gaussians on \(\mathbb{T}_d\), multimodal Gaussian mixtures on \(\mathrm{SO}(n)\), and time-evolution operators of a quantum oscillator with random potentials on \(\mathrm{U}(n)\), for varying dimensions \(d = n^2\).
%
We also separately analyze per-iteration runtime to study scaling across dimensions, requiring only a single training step and limited computational resources.


For the torus $\mathbb{T}_d$, following several works \cite{de2022riemannian, zhu2024trivialized}, we train diffusion models 
on data sampled from wrapped Gaussians on tori of different dimensions $d \in\{2, 10, 50, 100, 1000 \}$,
 with mean $0$ and covariance $0.2 I_d$ (see Appendix \ref{appendix_datasets} for definition of wrapped Gaussian).
 %
 %
 For $\mathrm{U}(n)$,
 following~\cite{zhu2024trivialized}, we use a dataset on $\mathrm{U}(n)$ of %30K
  unitary matrices representing time-evolution operators $e^{itH}$ of a quantum %Harmonic
   oscillator.
   %
    In our simulations, we 
%
 consider a wider range of $n \in \{3,5,9, 12, 15\}$ (corresponding to manifold dimensions $d = \frac{n(n-1)}{2} \in \{3, 10, 36, 66, 105\}$) when evaluating sample quality, and $n \in \{ 3, 5, 10, 30, 50 \}$ ($d \in \{3, 45, 435, 1225\}$) when evaluating runtime.
%
   Here $t$ is time, $H = \frac{\hbar}{2m}\Delta - V$ is a Hamiltonian, and $\Delta$ is the Laplacian. 
   %
$V$ is a random potential $V(x) = \frac{\omega^2}{2}\| x - x_0 \|^2$ with angular momentum $\omega$ sampled uniformly on $[2, 3]$ and $x_0\sim \mathcal{N}(0, 1)$. 
%
%
As $\Delta, V$ are infinite-dimensional operators, matrices in $\mathrm{U}(n)$ are obtained by retaining the  (discretized) top-$n$ eigenvectors of $\Delta, V$.
%
For $\mathrm{SO}(n)$, following \cite{zhu2024trivialized}, we use datasets sampled from a mixture of a small number $k$ of wrapped Gaussians on $\mathrm{SO}(n)$. We set $k=2$ and use the same values of $n$ as on $\mathrm{U}(n)$.

\medskip
\noindent
\textbf{Algorithm.}  We use Algorithm~\ref{alg_training_manifold}  to train our model, and Algorithm~\ref{alg_sampling_manifold}  to generate samples. Each algorithm takes as input a projection map \(\varphi\) and restricted inverse \(\psi\), with choices for \(\mathbb{T}_d\), \(\mathrm{SO}(n)\), and \(\mathrm{U}(n)\) detailed in Section~\ref{sec_results}. 
%
For \(\mathrm{SO}(n)\) and \(\mathrm{U}(n)\), we use the projection map \(\hat{\varphi}\) defined in Section~\ref{sec_results}, as it suffices to generate high-quality samples in our simulations.
%
In both algorithms, the drift function \(\hat{f}(\cdot, \cdot)\) for the reverse diffusion is parameterized by a neural network. Details on the network architecture, training iterations, batch size, and hardware are provided in Appendix~\ref{sec_training_details}.\footnote {Our code can be found at \href{https://github.com/mangoubi/Efficient-Diffusion-Models-for-Symmetric-Manifolds}{github.com/mangoubi/Efficient-Diffusion-Models-for-Symmetric-Manifolds}}

%
 The function $\hat{g}(\cdot, \cdot)$, which models the covariance in our model's reverse diffusion SDE, vanishes on $\mathbb{T}_d$.
%
On $\mathrm{SO}(n)$, $\mathrm{U}(n)$, $\hat{g}$ is a $n^2 \times n^2$ matrix.
%
 This matrix has a special structure (see Section \ref{sec_algorithm}),  
 allowing it to be parameterized by $d = n^2$ numbers.
%
 We may thus parametrize $\hat{g}(x, t)$ by a neural net with inputs $x$ of dimension $d$,  $t$ of dimension $1$, and output dimension $d$.
  Network architecture is the same as for $\hat{f}(\cdot, \cdot)$.


\medskip
\noindent
{\bf Benchmarks.}
We compare samples generated by our model to those from RSGM \cite{de2022riemannian}, TDM \cite{zhu2024trivialized}, and a ``vanilla'' Euclidean diffusion model. RSGM and TDM are included as they have demonstrated improved sample quality and runtime over previous manifold generative models, such as Moser Flow \cite{rozen2021moser} on \(\mathbb{T}_d\) and \(\mathrm{SO}(3)\). TDM also outperforms RSGM and Flow Matching \cite{chen2024flow} on higher-dimensional torus datasets and shows better sample quality on \(\mathrm{SO}(n)\) and \(\mathrm{U}(n)\), where RSGM and RDM \cite{huang2022riemannian} lack experiments for \(n > 3\).
%
All models are trained with the same iterations, batch size, and architecture (see Appendix~\ref{sec_training_details}). 

For the Euclidean diffusion model, samples are constrained to the manifold \(\mathcal{M}\) by preprocessing via \(\tilde{\varphi}\) and postprocessing via \(\tilde{\psi}\). For \(\mathcal{M} = \mathbb{T}_d\), \(\tilde{\varphi}(x)[i] = x[i] \mod 2\pi\), and \(\tilde{\psi}\) is its inverse on \([0, 2\pi)^d\). For \(\mathrm{SO}(n)\) and \(\mathrm{U}(n)\), \(\tilde{\varphi}(X)\) computes the \(U\) from the singular value decomposition \(X = U\Sigma V^\ast\), and \(\tilde{\psi}\) is the usual embedding.

RSGM and TDM are trained using their divergence-based ISM objective, which is prohibitively slow for large dimensions. To fully train these models and evaluate their sample quality, we follow their implementation and use a stochastic estimator for the ISM divergence. We do not compare to TDM on the torus, as their specialized heat kernel objective does not generalize beyond the torus or Euclidean space. 

We do not compare to SCRD \cite{lou2023scaling}, as their implementation is limited to efficient heat kernel expansion for \(\mathrm{SO}(n)\) and \(\mathrm{U}(n)\) with \(n = 3\). For \(n > 3\), the cost of their expansion grows exponentially with \(n\), making it infeasible for higher dimensions.

\medskip
\noindent
\textbf{Metrics.} For the torus, as in \cite{de2022riemannian, zhu2024trivialized}), we evaluate the quality of generated samples by computing their log-likelihood.
%
  For $\mathrm{SO}(n)$ and $\mathrm{U}(n)$, we use the Classifier Two-Sample Test (C2ST) metric \cite{lopez-paz2017revisiting}.
  %
    The C2ST metric was previously used in e.g. \cite{leach2022denoising} to evaluate sample quality of diffusion models on $\mathrm{SO}(n)$ for $n=3$.
  %
  It measures the ability of a classifier neural network to differentiate between generated samples and samples in a test dataset. 
  %
   This metric allows one to evaluate sample quality in settings where computing the likelihood may be intractable, as may be the case for diffusion models on $\mathrm{SO}(n)$ and $\mathrm{U}(n)$ for larger $n$.  
   %
   We use the C2ST metric on $\mathrm{SO}(n)$ and $\mathrm{U}(n)$ instead of log-likelihood, as we found that computing log-likelihood for $n>3$ poses additional computational challenges, while C2ST can be computed efficiently. 
%
 See Appendix \ref{appendix_evaluation_metrics} for definitions of log-likelihood and C2ST, and additional details.


\medskip
\noindent
\textbf{Results for generated sample quality.} 
%
 For the torus, we compare our model, a Euclidean diffusion model, and RSGM on a dataset sampled from a wrapped Gaussian on the $d$-dimensional torus for different values of $d$.
%
 Our model has the lowest negative log-likelihood (NLL) for $d \geq 10$, and its NLL degrades with the dimension at a much slower rate than the Euclidean model and RSGM  (Table \ref{torus_nll_table}; lower NLL indicates better-quality sample generation).
% 

For $\mathrm{U}(n)$, we train our model, a Euclidean diffusion model, RSGM, and TDM on a dataset on $\mathrm{U}(n)$ comprised of discretized quantum oscillator time-evolution operators, for $n \in \{3, 5,  9, 12, 15\}$. 
%
 For $n \geq 9$, our model achieves the lowest C2ST score; a lower C2ST score indicates higher-quality sample generation
 (Figure \ref{un_table}, top).
 %
  Visually, we observe our model's generated samples more closely resemble the target distribution than benchmark models' for $n \geq 9$ (see Figure \ref{un_table}, bottom, for $n=15$,  Appendix \ref{appendix_visual_results} for other $n$).
%  
Improvements on $\mathrm{SO}(n)$ were similar to those on $\mathrm{U}(n)$  (see Appendix \ref{appendix_visual_results}).

