\section{Full proof of Theorem \ref{thm_sampling_Manifold_best}}\label{appendix_proof_overview}

In the following, we denote by $\rho(x,y)$ the geodesic distance between $x,y \in \mathcal{M}$, and by $\Gamma_{x \rightarrow y}(v)$ the parallel transport of a vector $v \in \mathcal{T}_x$ from $x$ to $y$.
%
For convenience, we denote $\varphi_i(\cdot) := \varphi(\cdot)[i]$.
%
Recall that we have assumed that $\psi(\mathcal{M})$ is contained in a ball of radius $C = \mathrm{poly}(d)$.
%
We will prove our results under the more general assumption (Assumption \ref{assumption_Concentration}($\psi, \pi, C$)), which is satisfied whenever $\psi(\mathcal{M}) \leq C$.

\medskip
\noindent
\begin{assumption}[\bf Bounded Support ($\psi, \pi, C$)]\label{assumption_Concentration}
The pushforward of $\psi(\pi)$ of $\pi$ with respect to the map $\psi: \mathcal{M} \rightarrow \mathbb{R}^d$ has support on a ball of radius $C$ centered at $0$.
\end{assumption}

\subsection{Correctness of the training objective functions}  \label{sec_lemma_training_proof}


\begin{lemma}\label{lemma_training}
 $f^\star$ and $g^\star$ are solutions to the following optimization problems:
%
 \begin{align*}
  &\min_{f \in \mathcal{C}(\mathbb{R}^d, \mathbb{R}^d)}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \bigg[ \bigg\|  (\nabla \varphi(Z_{T-t}))^\top \frac{Z_{T-t}-\psi(b)e^{-\frac{1}{2}(T-t)}}{e^{-(T-t)}-1}\nonumber\\
%
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(Z_{T-t}))  -  f(\varphi(Z_{T-t}), t) \bigg\|^2 \bigg | Z_0 = \psi(b)\bigg],\\
%
 &\min_{g \in \mathcal{C}(\mathbb{R}^d, \mathbb{R}^{d\times d})}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \left[ \left\| ( J_{\varphi}(Z_{T-t}))^\top J_{\varphi}(Z_{T-t}) - (g(\varphi(Z_{T-t}),t))^2 \right\|_F^2 \bigg | Z_0 = \psi(b)\right],
 \end{align*}
 %
 where $J_{\varphi}$ denotes the Jacobian of $\varphi$.
\end{lemma}


\begin{proof}

{\bf Step 1:  Obtaining an expression for the reverse diffusion SDE in $\mathbb{R}^d$.}
%
We cannot in general directly apply \eqref{eq_reverse_diffusion2} to obtain a tractable expression for the SDE of the reverse diffusion $Y_t$ in $\mathcal{M}$, since we do not have a tractable formula for the transition kernel $p_t$ of the forward diffusion $X_t$ on $\mathcal{M}$.
%
Instead, we will first obtain an SDE for the reverse diffusion of $Z_t$ in $\mathbb{R}^d$, and then ``project'' this SDE onto $\mathcal{M}$.
%
Let $H_t := Z_{T-t}$ denote the time-reversed diffusion of $Z_t$.
%
$H_t$ is a diffusion in $\mathbb{R}^d$.
%
From \eqref{eq_reverse_diffusion2}, we have that the SDE for the reverse diffusion $H_t$ on $\mathbb{R}^d$ is given by the following formula:
%
\begin{equation}\label{eq_reverse_diffusion3b_2}
\mathrm{d}H_t =\left(\frac{1}{2}H_t + 2 \nabla \log q_{T-t}(H_t) \right)\mathrm{d}t + \mathrm{d} W_t,
\end{equation}
%
 where $W_t$ is a standard Brownian motion on $\mathbb{R}^d$.
%
Equation \eqref{eq_reverse_diffusion3b_2} can be re-written as
%
\begin{equation}\label{eq_reverse_diffusion3}
\mathrm{d}H_t =  \left(\frac{1}{2}H_t + 2 \mathbb{E}_{b \sim q_{0|t}(\cdot|H_t)}[\nabla \log q_{T-t|0}(H_t|b) ]\right)\mathrm{d}t + \mathrm{d} W_t.
\end{equation}
%
The r.h.s. of \eqref{eq_reverse_diffusion3} is tractable since we have a tractable expression for the transition kernel $q_{T-t|0}$ (it is just a time re-scaling of a Gaussian kernel, the transition kernel of Brownian motion).

\smallskip
\noindent
{\bf Step 2:  Obtaining an expression for the reverse diffusion SDE in $\mathcal{M}$.}
Note that there exists a coupling between $Z_t$ and $H_t$ such that $H_t = Z_{T-t}$ and that $Y_t = X_{T-t}$ for all $t\in [0,T]$.
%
Thus, under this choice of coupling, we have that $Y_t = X_{T-t} = \varphi(Z_{T-t}) = \varphi(H_{t})$ for all $t\in [0,T]$.
%
In the special case when there is only one datapoint $x_0$, the SDE for the reverse diffusion $Y_t$ on $\mathcal{M}$  can be obtained by applying It\^o's lemma (Lemma \ref{Lemma_Ito}) to $Y_t = \varphi(H_t)$:
%
\begin{equation}\label{eq_Ito}
\mathrm{d}Y_t[i] = \nabla \varphi_i(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi_i(H_t)) \mathrm{d}H_t \qquad \qquad \forall i \in [d].
\end{equation}
%
In the following, to simplify notation, we drop the ``$i$'' index from the notation $\varphi_i$ and $\mathrm{d}Y_t[i]$.
%
Unfortunately, the r.h.s. of \eqref{eq_Ito} is not a (deterministic) function  of $Y_t = \varphi(H_t)$, since $\varphi$ is not an invertible map.
%
 To solve this problem, we can take the conditional expectation of \eqref{eq_Ito} with respect to $Y_t=\varphi(H_t)$:

 \begin{equation}\label{eq_Ito2}
\mathrm{d}Y_t = E[\mathrm{d}Y_t | Y_t] =  E[\mathrm{d}Y_t | \varphi(H_t)] = E\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t \bigg | \varphi(H_t)\right].
\end{equation}
 %
  The drift term on the r.h.s. of \eqref{eq_Ito2}  is a deterministic function of $Y_t$.
  %
 %
 Denote this function by $f^\star:  \mathcal{M} \times [0,T] \rightarrow \mathcal{T} \mathcal{M}$ for any input $x \in \mathcal{M}$ and output in the tangent space $\mathcal{T}_x \mathcal{M}$ of $\mathcal{M}$ at $x$.
%

Moreover, by \eqref{eq_reverse_diffusion2}, the covariance term on the r.h.s. of \eqref{eq_Ito2} must be the same as the covariance term for the forward diffusion $Y_t$ on $\mathcal{M}$.
%
This covariance term can be obtained from the covariance term $\mathrm{d}W_t$ on $\mathbb{R}^d$, via It\^o's lemma, implying that the covariance term is  $\mathbb{E}[\nabla \varphi(H_t)[i]^\top\mathrm{d}W_t |\varphi(H_t)]$, $i \in [d]$.
%
 Using the notation for the Jacobian, this covariance term can be written more concisely as 
  $\mathbb{E}[J_\varphi(H_t)^\top\mathrm{d}W_t |\varphi(H_t)]$.
%
 Thus, the diffusion term is also a deterministic function $g^\star$ of $Y_t = \varphi(H_t)$, where  $g^\star(Y_t)$ is a symmetric $d\times d$ matrix,
%
%
\begin{equation}\label{eq_diffusion_term1}
E[J_{\varphi}(H_t)\mathrm{d}W_t|\varphi(H_t)] = g^\star(Y_t,t)\mathrm{d}\tilde{W}_t,
\end{equation}
%
 where $\tilde{W}_t$ is a standard Brownian motion on $\mathcal{M}$.
 %


 Since $\mathrm{d}W_t$ is the derivative of a standard Brownian motion in $\mathbb{R}^d$, and $\mathrm{d}\tilde{W}_t$ is the derivative of a standard Brownian motion on the tangent space of $\mathcal{M}$, we have that
 %
 \begin{equation}\label{eq_diffusion_term3}
E[ J_{\varphi}(H_t)^\top J_{\varphi}(H_t) |\varphi(H_t)] = (g^\star(Y_t,t))^2.
\end{equation}
%
%
% 
 Thus, \eqref{eq_Ito2} can be expressed as:
 %
\begin{equation}\label{eq_Ito9}
\mathrm{d}Y_t =  E\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t \bigg| \varphi(H_t)\right] = f^\star(Y_t, t) \mathrm{d}t + g^\star(Y_t,t)\mathrm{d}\tilde{W}_t.
\end{equation}
%
%
In the more general setting when there is more than one datapoint, \eqref{eq_Ito9} generalizes to:
  \begin{eqnarray}\label{eq_reverse_SDE2}
\mathrm{d}Y_t &= & \mathbb{E}_{b\sim \pi}\left[ E\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t \bigg| \varphi(H_t), H_T = b\right]\right]\\
%
&= &f^\star(Y_t, t) \mathrm{d}t + g^\star(Y_t,t)\mathrm{d}\tilde{W}_t.
\end{eqnarray}
 %
 Since $Y_t = \varphi(H_t)$, we can bring $f^\star(Y_t,t) \mathrm{d}t$ and $g^\star(Y_t,t)\mathrm{d}\tilde{W}_t$ inside the conditional expectation:

\begin{equation*}
\mathbb{E}_{b\sim \pi}\left[E\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t -  f^\star(Y_t, t)\mathrm{d}t \bigg| \varphi(H_t), H_T = b\right]\right] =  g^\star(Y_t,t)\mathrm{d}\tilde{W}_t .
\end{equation*}
%
We can re-write this as
% 
\begin{align*}
&\mathbb{E}_{b\sim \pi}\left [ E_{\varphi(H_t)}\left[E_{H_t|\varphi(H_t)}\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t -  f^\star(Y_t, t)\mathrm{d}t\bigg| H_t, H_T = b\right]\right]\right]\\
%
& =  g^\star(Y_t,t)\mathrm{d}\tilde{W}_t.
\end{align*}
%
This simplifies to 
%
\begin{equation}\label{eq_Ito7}
\mathbb{E}_{b\sim \pi}\left[\nabla \varphi(H_t)^\top \mathrm{d}H_t + \frac{1}{2}(\mathrm{d} H_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d}H_t -  f^\star(Y_t, t)\mathrm{d}t \bigg| H_T = b\right] = g^\star(Y_t,t)\mathrm{d}\tilde{W}_t.
\end{equation}
%
%
where the expectation is taken over the outcomes of $H_t$.
%
  Plugging in \eqref{eq_reverse_diffusion3} into \eqref{eq_Ito7}, and separating the drift and the diffusion terms on both sides of the equation (and noting that the higher-order differentials $(\mathrm{d}t)^2$ and $\mathrm{d}W_t\mathrm{d}t$ vanish), we get that the drift terms satisfy
%
\begin{align}\label{eq_Ito7b}
&\mathbb{E}_{b\sim \pi}\bigg[(\nabla \varphi(H_t))^\top\left(H_t + 2 \nabla \log q_{T-t|0}(H_t|b) \right)\mathrm{d}t+ \frac{1}{2}(\mathrm{d} W_t)^\top (\nabla^2 \varphi(H_t)) \mathrm{d} W_t -  f^\star(Y_t, t)\mathrm{d}t  \bigg| H_T = b\bigg] = 0.
\end{align}
%
%
Noting that $(\mathrm{d} W_t[i])^2 =  \mathrm{d}t$ and $\mathrm{d} W_t[i] \mathrm{d} W_t[j] = 0$ for all $i \neq j$, we get

\begin{align}\label{eq_Ito7c}
&\mathbb{E}_{b\sim \pi}\bigg[(\nabla \varphi(H_t))^\top\left(H_t + 2 \nabla \log q_{T-t|0}(H_t|b) \right)\mathrm{d}t + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(H_t))\mathrm{d}t  -  f^\star(Y_t, t)\mathrm{d}t  \bigg| H_T = b\bigg] = 0.
\end{align}
%
Dividing both sides by $\mathrm{d}t$, we get an expression for the drift term $f^\star$
%
\begin{align}\label{eq_Ito7d}
&\mathbb{E}_{b\sim \pi}\bigg[(\nabla \varphi(H_t))^\top\left(H_t + 2 \nabla \log q_{T-t|0}(H_t|b) \right)+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(H_t))  -  f^\star(Y_t, t) \bigg| H_T = b\bigg] = 0.
\end{align}


\noindent
Finally, from \eqref{eq_diffusion_term3}, we have that diffusion term $g^\star$ satisfies
\begin{equation}\label{eq_diffusion_term2}
\mathbb{E}_{b\sim \pi}\left[E\left[J_{\varphi}(H_t)^\top J_{\varphi}(H_t) - (g^\star(Y_t,t))^2 \bigg|\varphi(H_t)\right]\, \, \bigg|H_T=b\right]=0.
\end{equation}
%

\smallskip
\noindent
{\bf Step 3:  Training the drift term.} 
 %
 From \eqref{eq_Ito7d}, we have that the  function $f^\star$ is the solution to the following optimization problem: 
 %
 \begin{align}\label{eq_opt_manifold3}
&\min_{f}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \bigg[ \bigg\| (\nabla \varphi(H_t))^\top\left(\frac{1}{2}H_t + 2 \nabla \log q_{T-t|0}(H_t|b) \right) + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(H_t))  -  f(Y_t, t) \bigg\|^2 \bigg | H_T = b\bigg].
 \end{align}
%
   where the inner expectation is taken over $b \sim \pi$ and over the outcomes of $H_t$ at time $t$ conditioned on $H_T=b$ (Note that $Y_t = \varphi(H_t)$ is a deterministic function of $H_t$).

Now, $H_t|\{H_T=b\}$ has the same probability distribution as $Z_{T-t}|\{Z_0 = b\}$ (and that $Y_t|\{H_T=b\}$ has the same probability distribution as $X_{T-t}|\{Z_0 = b\}$).
%
Thus, we can re-write \eqref{eq_opt_manifold3} as
%
 \begin{align}\label{eq_opt_manifold4}
\min_{f}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \bigg[ \bigg\|& (\nabla \varphi(Z_{T-t}))^\top\left(Z_{T-t} + 2 \nabla \log q_{T-t|0}(Z_{T-t}|b) \right)\nonumber\\
%
&+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(Z_{T-t}))  -  f(X_{T-t}, t) \bigg\|^2 \bigg | Z_0 = b\bigg],
 \end{align}
%

\smallskip
\noindent
{\bf Step 4:  Training the diffusion term.} 
 %
 From \eqref{eq_diffusion_term2} we have that $g^\star$ is the solution to the following optimization problem: 
 %
  \begin{equation*}
\min_{g}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \left[ \left\|  J_{\varphi}(H_t)^\top J_{\varphi}(H_t) - (g(Y_t,t))^2 \right\|_F^2 \bigg | H_T = b\right],
 \end{equation*}
 %
 where $\|\cdot\|_F$ is the Frobenius norm.
 %
 Since $H_t|\{H_T=b\}$ has the same probability distribution as $Z_{T-t}|\{Z_0 = b\}$ (and $Y_t|\{H_T=b\}$ has the same probability distribution as $X_{T-t}|\{Z_0 = b\}$), we can re-write \eqref{eq_opt_manifold3} as
%
  \begin{equation*}
\min_{g}  \mathbb{E}_{t \sim \mathrm{Unif}([0,1])} \mathbb{E}_{b \sim \pi} \left[ \left\| J_{\varphi}(Z_{T-t})^\top J_{\varphi}(Z_{T-t}) - (g(X_{T-t},t))^2 \right\|_F^2 \bigg | Z_0 = b\right].
 \end{equation*}
%
\end{proof}

\subsection{Proof of Lemma \ref{Gronwall}}

In the proof of Theorem \ref{thm_sampling_Manifold_best} we will use the following lemma.
%
\bigskip
\begin{lemma}[\bf Gronwall-like inequality for SDEs on a manifold of non-negative curvature] \label{Gronwall}
Suppose that $\mathcal{M}$ is a Riemannian manifold with non-negative curvature, and let $\rho(x,y)$ denote the geodesic distance between any $x,y \in \mathcal{M}$.
%
Suppose also that $X_t$ and $\hat{X}_t$ are two diffusions on $\mathcal{M}$ such that
%
$$\mathrm{d}X_t = b(X_t, t) + \sigma(X_t,t) \mathrm{d}W_t,$$
%
and
$$\mathrm{d}\hat{X}_t = \hat{b}(\hat{X}_t, t) + \hat{\sigma}(X_t,t) \mathrm{d}W_t,$$
%
where $b$ is $C_1(t)$-Lipschitz and $\sigma$ is $C_2(t)$-Lipschitz at every time $t \in [0,T]$. 
%
%
Moreover, assume that $$\|b(x,t) - \hat{b}(x,t)\| \leq \epsilon$$ and $$\|\sigma(x,t) - \hat{\sigma}(x,t)\|_F^2 \leq \epsilon$$ for all $x \in \mathcal{M}$, $t \in [0,T]$.
%
Then there exists a coupling between $X_t$ and $\hat{X}_t$ such that, for all $t \geq 0$,
%
\begin{align*}
 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] \leq \left(\mathbb{E}[\rho^2(\hat{X}_0, X_0)] + \inf_{s\in[0,t]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\right)  e^{\int_0^t (2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}.
\end{align*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{Gronwall}]

We first couple $X_t$ and $\hat{X}_t$ by setting their underlying Brownian motion terms $\mathrm{d}W_t$ to be equal to each other. 
%
Next, we compute the distance $\rho^2(\hat{X}_t, X_t)$ using It\^o's Lemma.
%
Letting  $h(x,y):= \rho^2(x, y)$, by It\^o's Lemma we have that
%
\begin{eqnarray*}
\mathrm{d} \rho^2(\hat{X}_t, X_t) &=& \mathrm{d} h(\hat{X}_t, X_t)\\
%
&=&  \nabla h(\hat{X}_t, X_t)^\top \begin{pmatrix} b(X_t, t)\\  \hat{b}(\hat{X}_t, t)  \end{pmatrix} \mathrm{d}t\\
%
& &   + \frac{1}{2} \mathrm{Tr} \left[\begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix}^\top [\nabla^2h(\hat{X}_t, X_t)] \begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix} \right] \mathrm{d}t\\
%
  & &  +\nabla h(\hat{X}_t, X_t)^\top \begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix} \mathrm{d}\begin{pmatrix} W_t \\ \hat{W}_t \end{pmatrix}.
\end{eqnarray*}
\noindent
Therefore,
\begin{eqnarray}\label{eq_p1}
\mathrm{d} \mathbb{E}[\rho^2(\hat{X}_t, X_t)]
%
&=&  \mathbb{E} \left[\nabla h(\hat{X}_t, X_t)^\top \begin{pmatrix} b(X_t, t)\\  \hat{b}(\hat{X}_t, t)  \end{pmatrix} \right] \mathrm{d}t\nonumber\\
%
& & + \frac{1}{2} \mathbb{E}\left[ \mathrm{Tr} \left[\begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix}^\top [\nabla^2h(\hat{X}_t, X_t)] \begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix} \right] \right] \mathrm{d}t\nonumber\\
%
  & & +0.
\end{eqnarray}
Now, since $\mathcal{M}$ has non-negative curvature, by the Rauch comparison theorem we have
%
\begin{eqnarray}\label{eq_p2}
\bigg|\nabla h(\hat{X}_t, X_t)^\top \begin{pmatrix} b(X_t, t)\\  \hat{b}(\hat{X}_t, t)  \end{pmatrix}\bigg| &\leq & 2 \rho(\hat{X}_t, X_t) \times \|\hat{b}(\hat{X}_t, t) - \Gamma_{X_t \rightarrow \hat{X}_t}(b(X_t, t))\| \nonumber\\
%
&\leq  & 2 \rho(\hat{X}_t, X_t) \times\left(\| b(\hat{X}_t, t) - \Gamma_{X_t \rightarrow \hat{X}_t}(b(X_t, t))\| + \|b(\hat{X}_t, t) - \hat{b}(\hat{X}_t, t)\| \right) \nonumber\\
%
&\leq & 2 \rho(\hat{X}_t, X_t) \times (C_1(t) \rho(\hat{X}_t, X_t) + \epsilon).
\end{eqnarray}
%
where the last inequality holds since $b$ is $C_1(t)$-Lipschitz.
%
Moreover, since $\mathcal{M}$ has non-negative curvature, by the Rauch comparison theorem we also have that
%
\begin{align}\label{eq_p3}
&\frac{1}{2} \mathrm{Tr} \left[\begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix}^\top [\nabla^2h(\hat{X}_t, X_t)] \begin{pmatrix}  \sigma(X_t,t) & 0\\   \hat{\sigma}(X_t,t) & 0  \end{pmatrix} \right] \nonumber\\
%
&\qquad \qquad \leq \left \|  \hat{\sigma}(\hat{X}_t, t) - \Gamma_{X_t \rightarrow \hat{X}_t}(\sigma(X_t, t)) \right\|_F^2\nonumber\\
%
&\qquad \qquad \leq \left(\left \|  \sigma(\hat{X}_t, t) - \Gamma_{X_t \rightarrow \hat{X}_t}(\sigma(X_t, t)) \right\|_F + \left\|  \hat{\sigma}(\hat{X}_t, t) -   \sigma(\hat{X}_t, t) \right\|_F \right)^2 \nonumber\\
%
&\qquad \qquad\leq 3\left \|  \sigma(\hat{X}_t, t) - \Gamma_{X_t \rightarrow \hat{X}_t}(\sigma(X_t, t)) \right\|_F^2 + 3\left\|  \hat{\sigma}(\hat{X}_t, t) -   \sigma(\hat{X}_t, t) \right\|_F^2\nonumber\\
%
&\qquad \qquad\leq 3C_2(t)^2 \rho^2(\hat{X}_t, X_t) + 3\epsilon^2.
%
\end{align}
\noindent
Plugging \eqref{eq_p2} and \eqref{eq_p3} into \eqref{eq_p1}, we have
%
\begin{equation}
    \frac{\mathrm{d}}{\mathrm{d}t} \mathbb{E}[\rho^2(\hat{X}_t, X_t)] \leq 2 \mathbb{E}[C_1(t) \rho^2(\hat{X}_t, X_t) + \epsilon \rho(\hat{X}_t, X_t)] + 3C_2(t)^2 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] + 3\epsilon^2 \qquad \forall t \geq 0.
\end{equation}
\noindent
Hence,
%
\begin{eqnarray*}
    \frac{\mathrm{d}}{\mathrm{d}t} \mathbb{E}[\rho^2(\hat{X}_t, X_t)] &\leq & 2 \mathbb{E}[C_1(t) \rho^2(\hat{X}_t, X_t) + \rho^2(\hat{X}_t, X_t)] + 3C_2(t)^2 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] + 5\epsilon^2\\
    %
    &=& 2 \mathbb{E}[C_1(t) \rho^2(\hat{X}_t, X_t) + \rho^2(\hat{X}_t, X_t)] + 3C_2(t)^2 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] + 5\epsilon^2\\
    %
    &=& (2C_1(t) +3C_2(t)^2 + 2)\mathbb{E}[\rho^2(\hat{X}_t, X_t)] + 5\epsilon^2.
\end{eqnarray*}
\noindent
Let $\tau \in [0, T]$ be some number, and define $R(t) := \mathbb{E}[\rho^2(\hat{X}_t, X_t)] + \inf_{s\in[0,\tau]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}$ for all $t \in [0,\tau]$.
%
Then we have,
\begin{equation} \label{eq_p4}
 \frac{\mathrm{d}}{\mathrm{d}t} R(t) \leq (2C_1(t) +3C_2(t)^2 + 2) R(t), \qquad \forall t \geq 0.
\end{equation}
%
Thus, plugging \eqref{eq_p4} into Gronwall's lemma, we have, for all $t \geq 0$,
%
\begin{eqnarray*}  R(t) &\leq & R(0) e^{\int_0^t (2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}\\
 %
&=& \left(\mathbb{E}[\rho^2(\hat{X}_0, X_0)] + \inf_{s\in[0,\tau]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\right) e^{\int_0^t 2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}.
\end{eqnarray*}
%
Thus, 
\begin{align*}
 &\mathbb{E}[\rho^2(\hat{X}_t, X_t)] + \inf_{s\in[0,\tau]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\\
 %
 &\qquad \qquad \leq \left(\mathbb{E}[\rho^2(\hat{X}_0, X_0)] + \inf_{s\in[0,T]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\right) e^{\int_0^t 2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}.
\end{align*}
%
Hence, for all $t \geq 0$,
\begin{align*}
 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] \leq \left(\mathbb{E}[\rho^2(\hat{X}_0, X_0)] + \inf_{s\in[0,\tau]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\right)  e^{\int_0^t 2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}.
\end{align*}
%
Plugging in $\tau = t$ in the above equation, we have,  for all $t \geq 0$,
%
\begin{align*}
 \mathbb{E}[\rho^2(\hat{X}_t, X_t)] \leq \left(\mathbb{E}[\rho^2(\hat{X}_0, X_0)] + \inf_{s\in[0,t]}\frac{5\epsilon^2}{2C_1(s) +3C_2(s)^2 + 2}\right)  e^{\int_0^t 2C_1(s) +3C_2(s)^2 + 2 \mathrm{d}s}.
\end{align*}
%\ref
%
\end{proof}

\subsection{Proof that average-case Lipschitzness holds on symmetric manifolds of interest (Lemma \ref{Lemma_average_case_Lipschitz})}

\begin{lemma}[\bf Average-case Lipschitzness]\label{Lemma_average_case_Lipschitz}
%
For the unitary group, Assumption~\ref{assumption_Lipschitz} holds with \( L_1 = O(d^{1.5} \sqrt{T} \alpha^{-1/3}) \) and \( L_2 = O(d^2 T \alpha^{-2/3}) \).
%
For the sphere, it holds for $L_1 = L_2 =  O(\alpha^{-\frac{1}{d}})$. 
%
For the Torus it holds for $L_1 =L_2 = 1$. 
\end{lemma}


\begin{proof}

For the torus, the map $\varphi(x)$ has $\nabla \varphi(x) = I_d$ at every $x\in \mathbb{R}^d$, which implies that Assumption \ref{assumption_Lipschitz}  is satisfied for $L_1 = L_2 =1.$ 

\noindent
{\em Sphere.}
%
In the case of the sphere, which we embed via the map $\psi$ as a unit sphere in $\mathbb{R}^d$, one can easily observe that e.g. $\|\nabla \varphi(z)\| \leq O(1)$ for any $z$ outside a ball of radius $r \geq \Omega(1)$ centered at the origin.
%
As the volume of a ball of radius $r = \alpha$ is $\frac{1}{r^d}$ times the volume of the unit ball, one can use standard Gaussian concentration inequalities to show that the Ornstein-Uhlenbeck process $Z_t$, which is a Gaussian process, will remain outside this ball for time $T$ with probability at least $1- 4\frac{1}{r^d T}$.

Moreover, by standard Gaussian concentration inequalities \cite{rudelson2013hanson}, we have that $\|Z_t\| \leq  2\sqrt{Td} \log(\frac{1}{\alpha})$ with probability at least $1-2 \alpha$ for all $t \in [0,T]$.
%
This motivates defining the set $\Omega_t := \{z \in \mathbb{R}^d:  (4\frac{1}{\alpha T})^{\frac{1}{d}} \leq \|z\|  \leq 2\sqrt{Td} \log(\frac{1}{\alpha})\}$, as we then have
%
$$\mathbb{P}(Z_t \in \Omega_t \, \, \forall \, \, t \in [0,T]) \geq 1- \alpha.$$
%
Since $\|z\| \geq (4\frac{1}{\alpha T})^{\frac{1}{d}}$ for any $z \in \Omega_t$ and any $t\in[0,T]$, we must have that


\begin{equation*}
\begin{aligned}
    \|\nabla \varphi(z(U, \Lambda))\|_{2 \rightarrow 2} &\leq  3\left(4\frac{1}{\alpha T}\right)^{\frac{2}{d}} = L_1, \\
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U}  \nabla \varphi(z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq  3\left(4\frac{1}{\alpha T}\right)^{\frac{2}{d}} = L_1,\\
%
    \|\nabla^2 \varphi(z(U, \Lambda))\|_{2 \rightarrow 2} &\leq  3\left(4\frac{1}{\alpha T}\right)^{\frac{3}{d}}  = L_2,\\
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U}  \nabla \varphi(z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq 3\left(4\frac{1}{\alpha T}\right)^{\frac{3}{d}}  = L_2,\\
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U} (z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq \|x\|,
\end{aligned}
\end{equation*}

\paragraph{Unitary group.}
%
 We next show that the Lipschitz property holds for the unitary group $\mathrm{U}(n)$.
 %
 Similar techniques can be used for the case of the special orthogonal group, and we omit those details.
 %
 We first recall results from random matrix theory which allow us to bound the eigenvalue gaps of a matrix with Gaussian entries.
 %
 Specifically, these results say that, roughly speaking, if $Z_0 \in \mathbb{C}^{n \times n}$ is any matrix and $Z_t = Z_0 + B(t)$, where $B(t)$ is a matrix with (complex) iid $N(0, t)$  entries undergoing Brownian motion, one has that the eigenvalues $\gamma_1(t) \geq \cdots \geq \gamma_n(t)$ of $Z_t + Z_t^\ast$ satisfy (see e.g. \cite{anderson2010introduction, mangoubi2023private, mangoubi2025private})
 %
\begin{equation}\label{eq_r3b}
 \mathbb{P}\left( \inf_{s\in [t_0, T]}(\gamma_{i+1}(t) - \gamma_i(t)) \leq s \frac{1}{\mathrm{poly}(d) \sqrt{t} } \right) \leq O(s^{\frac{1}{2}}) \qquad \forall s \geq 0.
\end{equation}
%
Thus, if we define $\Omega_t$ to be the set of outcomes of $Z_t$ such that $\gamma_{i+1}(t) - \gamma_i(t) \leq \alpha^2 \frac{1}{\mathrm{poly}(n) \sqrt{t}}$, we have that $\mathbb{P}(Z_t \in \Omega_t \, \, \, \forall t \in [t_0,T]) \geq 1- \alpha$.



From the matrix calculus formulas for $\nabla \varphi(U^\top \Lambda U)$, $\frac{\mathrm{d}}{\mathrm{d} U} \nabla \varphi(U^\top \Lambda U)$, $\nabla \varphi(U^\top \Lambda U)$, and $\frac{\mathrm{d}}{\mathrm{d} U} \nabla^2 \varphi(U^\top \Lambda U)$, we have that, for all $z(U, \Lambda) = U \Lambda U^\top \in \Omega_t$,
%
\begin{equation*}
\begin{aligned}
    \|\nabla \varphi(z(U, \Lambda))\|_{2 \rightarrow 2} &\leq \sum_{i=1}^d \frac{1}{\lambda_{i+1}-\lambda_i} \leq d^{1.5}\sqrt{t} \alpha^{-\frac{1}{3}} = L_1,\\[3mm]
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U}  \nabla \varphi(z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq \| \Lambda\|_{2 \rightarrow 2} \sum_{i=1}^d \frac{1}{\lambda_{i+1}-\lambda_i}\\
    %
    & \leq \left(C+ \sqrt{T}d \log\left(\frac{1}{\alpha}\right)\right) \times \sum_{i=1}^d \frac{1}{\lambda_{i+1}-\lambda_i} \leq d^{1.5}\sqrt{t} \alpha^{-\frac{1}{3}}  = L_1,\\[3mm]
%
    \left\|\nabla^2 \varphi(z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq \sum_{i=1}^d \frac{1}{(\lambda_{i+1}-\lambda_i)^2} \leq d^2 t \alpha^{-\frac{2}{3}}  = L_2,\\[3mm]
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U}  \nabla \varphi(z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq \| \Lambda\|_{2 \rightarrow 2} \sum_{i=1}^d \frac{1}{(\lambda_{i+1}-\lambda_i)^2} \\
    %
      &\leq \left(C+ \sqrt{T}d \log\left(\frac{1}{\alpha}\right)\right) \times \sum_{i=1}^d \frac{1}{(\lambda_{i+1}-\lambda_i)^2} \leq d^2 t \alpha^{-\frac{2}{3}}  = L_2,\\[3mm]
%
    \left\|\frac{\mathrm{d}}{\mathrm{d} U} (z(U, \Lambda))\right\|_{2 \rightarrow 2} &\leq \| \Lambda\|_{2 \rightarrow 2} 
\end{aligned}
\end{equation*}
%
%
since $\lambda_{i+1}-\lambda_i \leq \alpha^{\frac{1}{3}} \frac{1}{\sqrt{d} \sqrt{t}}$ for all $i \in [d]$ and $\|\Lambda\|_{2 \rightarrow 2} \leq 2\sqrt{T d} \log(\frac{1}{\alpha})$ whenever $z(U,\Lambda) \in \Omega_t$
%


\end{proof}



\subsection{Proof of Lipschitzness of $f^\star$ and $g^\star$ on all of $\mathcal{M}$ (Lemma \ref{lemma_Lipschitz})}



Recall that we denote by  $q_{t|\tau}(y|x)$ the transition kernel of the Ornstein-Uhlenbeck process $Z_t$ at any  $x,y \in \mathbb{R}^d$, and by  $q_t(x) = \int_{\mathcal{M}} q_{t|0}(x|z) \pi(z) \mathrm{d}z$ the distribution of $Z_t$ at any time $t\geq 0$.
%
We will use the following Proposition of  \cite{chen2023sampling}:
%
\begin{proposition}[\bf Proposition 20 of  \cite{chen2023sampling}]\label{prop_score_Lipschitz}
    %
Suppose that $\psi(\pi)$ has support on a ball of radius $C>0$.
%
For any $\alpha>0$, define the ``early stopping time'' $t_0:= \min(\frac{\alpha}{C}, \frac{\alpha^2}{d})$. 
%
 Then the drift term $\nabla \log q_{t}(\cdot)$ of the reverse diffusion SDE in Euclidean space is $O(\frac{1}{\alpha^2}d C^2(\min(C, \sqrt{d})^2))$-Lipschitz at every time $t> t_0$.
%
 Moreover, $W_2(q_{t_0}, \pi) \leq \alpha$.
 \end{proposition}

\noindent
 Recall that we denote by $\Gamma_{x\rightarrow y}(v)$ the parallel transport of a vector $v$ from $x$ to $y$.

\begin{lemma}\label{lemma_Lipschitz}

Suppose that Assumption \ref{assumption_Lipschitz}($\varphi, L_1,L_2, \alpha$) and Assumption \ref{assumption_Concentration}($\psi, \pi, C$) both hold.
 Then for every $t \in [t_0,T]$,
%
\begin{equation}
       \|f^\star(x,t) - \Gamma_{x \rightarrow y}(f^\star(x,t))\| \leq \mathcal{C}\times   \rho(x, y), \qquad \qquad  \forall x,y \in \mathcal{M}
    \end{equation}
    %
    %
    and 
    %
    \begin{equation}
      \|g^\star(y,t) - \Gamma_{x\rightarrow y}(g^\star(x,t)) \|_F \leq \mathcal{C}  \times \rho(x, y) \qquad \qquad \forall x,y \in \mathcal{M}
    \end{equation}
    %
    where $\mathcal{C} := (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^4 \times L_3^2 \times L_1 + (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^2 \times L_3 \times L_2$ and $t_0:= \min(\frac{\alpha}{C}, \frac{\alpha^2}{d})$,
    %
    and $L_3= O(\frac{1}{\alpha^2}d C^2(\min(C, \sqrt{d})^2))$.




\end{lemma}

\begin{proof}
Recall that (when, e.g., $\mathcal{M}$ is one of the aforementioned symmetric manifolds) we may decompose any $z \in \mathbb{R}^d$ as $z \equiv z(U, \Lambda)$ where $U \in \mathcal{M}$.

We have the following expression for $f^\star(U,t)$
%
\begin{align*}
f^\star(U, t) =   c_U \int_{\Lambda \in \mathcal{A}} 
%
\bigg[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t|0}(z(U, \Lambda)) 
%
&+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\bigg]\nonumber \\
%
&\qquad \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda ,
\end{align*}
%
 where $c_U = \left(\int_{\Lambda \in \mathcal{A}}  q_{T-t}(z(U, \Lambda)) \mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda\right)^{-1} $ is a normalizing constant.
%
Then
\begin{align} \label{eq_g11}
\frac{\mathrm{d}}{\mathrm{d}U} f^\star(U, t)
%
&=  c_U \times \frac{\mathrm{d}}{\mathrm{d}U} \int_{\Lambda \in \mathcal{A}} 
%
\left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
