\left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right]\nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda. 
\end{align}
%
For the first term on the r.h.s. of \eqref{eq_g11} we have,
%
\begin{align*}
    c_U\times \frac{\mathrm{d}}{\mathrm{d}U} \int_{\Lambda \in \mathcal{A}}& 
%
\left[ (\nabla_U \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right]\nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
    &=c_U\times \int_{\Lambda \in \mathcal{A}} 
%
\left(\frac{\mathrm{d}}{\mathrm{d}U}  \left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right]\right) \nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&\qquad +c_U\times \int_{\Lambda \in \mathcal{A}} 
%
 \left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right] \nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times \frac{\mathrm{d}}{\mathrm{d}U}  q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
 &=c_U\times \int_{\Lambda \in \mathcal{A}} 
%
\left(\frac{\mathrm{d}}{\mathrm{d}U}  \left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right]\right) \nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&\qquad +c_U\times \int_{\Lambda \in \mathcal{A}} 
%
 \left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right]\\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \times \nabla_U \log q_{T-t}(z(U, \Lambda)) \times q_{T-t}(z(U, \Lambda)) 
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
