&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times \nabla_U \log q_{T-t}(z(U, \Lambda)) \mathbbm{1}_\Omega(\Lambda)  \bigg | V=U \bigg].\\
\end{align*}
%
For the second term on the r.h.s. of \eqref{eq_g11} we have,
%
 \begin{align*}
\frac{\mathrm{d}}{\mathrm{d}U} c_U &= c_U^2 \int_{\Lambda \in \mathcal{A}} \frac{\mathrm{d}}{\mathrm{d}U} (q_{T-t}(z(U, \Lambda))) \mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&= c_U^2 \int_{\Lambda \in \mathcal{A}} \frac{\mathrm{d}}{\mathrm{d}U} (e^{\log q_{T-t}(z(U, \Lambda))}) \mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&= c_U^2 \int_{\Lambda \in \mathcal{A}}  \nabla_U \log q_{T-t}(z(U, \Lambda)) (e^{\log q_{T-t}(z(U, \Lambda))}) \mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&= c_U^2 \int_{\Lambda \in \mathcal{A}}  \nabla_U \log q_{T-t}(z(U, \Lambda)) \times q_{T-t}(z(U, \Lambda)) \mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
&= c_U \times \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\left [\nabla_U \log q_{T-t}(z(U, \Lambda)) \mathbbm{1}_\Omega(\Lambda) \, \big | \, V=U  \right]\\
%
\end{align*}
%
and hence,

\begin{align*}
&(\frac{\mathrm{d}}{\mathrm{d}U} c_U) \times \int_{\Lambda \in \mathcal{A}} 
%
\left[ (\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right] \nonumber \\
%
&\qquad \qquad \qquad \qquad \qquad \qquad  \times q_{T-t}(z(U, \Lambda))
%
\mathbbm{1}_\Omega(\Lambda) \mathrm{d} \Lambda \\
%
 &=\mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\left [\nabla_U \log q_{T-t}(z(U, \Lambda))\mathbbm{1}_\Omega(\Lambda)  \, \big | \, V=U  \right] \\
 %
 &\qquad \times  \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\bigg[ \bigg((\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda))\\
%
&\qquad \qquad \qquad \qquad \qquad \qquad + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\bigg) \mathbbm{1}_\Omega(\Lambda)  \, \bigg | \, V=U \bigg].
%
\end{align*}
\noindent
Thus
\begin{align} \label{eq_g2}
\frac{\mathrm{d}}{\mathrm{d}U} f^\star(U, t)
%
&=  \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\bigg [ 
%
\frac{\mathrm{d}}{\mathrm{d}U}  \bigg( (\nabla \varphi(z(U, \Lambda)))^\top \nabla_U \log q_{T-t|0}(z(U, \Lambda)) \nonumber\\
%
&\qquad \qquad \qquad \qquad \qquad + \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\bigg) \mathbbm{1}_\Omega(\Lambda) \bigg | V=U \bigg], \nonumber\\
%
&\qquad +\mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\bigg [  
%
 \left( (\nabla \varphi(z(U, \Lambda)))^\top \nabla_U \log q_{T-t}(z(U, \Lambda)) 
%
+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda)))\right) \nonumber\\
%
&\qquad \qquad \qquad \qquad \qquad \qquad \times \nabla_U \log q_{T-t}(z(U, \Lambda)) \mathbbm{1}_\Omega(\Lambda)  \bigg | V=U \bigg] \nonumber\\
%
&\qquad + \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\left [\nabla_U \log q_{T-t}(z(U, \Lambda))\mathbbm{1}_\Omega(\Lambda)  \, \big | \, V=U  \right] \nonumber \\
 %
 &\qquad \qquad \times  \mathbb{E}_{z(U,\Lambda) \sim q_{T-t}}\bigg[ \bigg((\nabla \varphi(z(U, \Lambda)))^\top \nabla \log q_{T-t}(z(U, \Lambda))\\
%
&\qquad \qquad \qquad \qquad \qquad \qquad+ \frac{1}{2}\mathrm{tr}(\nabla^2 \varphi(z(U, \Lambda))) \bigg)\mathbbm{1}_\Omega(\Lambda)  \, \bigg | \, V=U \bigg].
\end{align}

\noindent
Moreover, by standard Gaussian concentration inequalities and Assumption \ref{assumption_Concentration}, without loss of generality we have that $\|z(U,\Lambda)\|_F \leq C+ \sqrt{T}d \log(\frac{1}{\alpha})$ for all $z(U,\Lambda) \in \Omega_t$.
%
From Proposition \ref{prop_score_Lipschitz} we have that $\nabla \log p_{T-t|0}(z(U, \Lambda))$ is $L_3$-Lipschitz where $L_3:= O(\frac{1}{\alpha^2}d C^2(\min(C, \sqrt{d})^2))$ and hence that
%
\begin{align}\label{eq_g14}
\|\nabla_U \log p_{T-t|0}(z(U, \Lambda))\|_{2\rightarrow 2} &\leq \|\frac{\mathrm{d}}{\mathrm{d} U} (z(U, \Lambda))\|_{2 \rightarrow 2} \times \|\nabla \log p_{T-t|0}(z(U, \Lambda))\|_{2\rightarrow 2} \nonumber\\
%
&\leq \|\frac{\mathrm{d}}{\mathrm{d} U} (z(U, \Lambda))\|_{2 \rightarrow 2} \times L_3 \times \|z(U,\Lambda)\|_F  \nonumber\\
%
&\leq L_3 \times \|z(U,\Lambda)\|_F^2 \nonumber\\
%
&\leq  L_3 \times \left (C+ \sqrt{T}d \log(\frac{1}{\alpha}) \right)^2,
\end{align}
%
where the third inequality holds by Assumption \ref{assumption_Lipschitz}, and the last inequality holds since $\|z(U,\Lambda)\|_F \leq C+ \sqrt{T}d \log(\frac{1}{\alpha})$ for all $z(U,\Lambda) \in \Omega_t$.
%
Thus, plugging Assumption \ref{assumption_Lipschitz} and \eqref{eq_g14} into \eqref{eq_g2}, we have that
%
\begin{align}\label{eq_g5}
\left\|\frac{\mathrm{d}}{\mathrm{d}U} f^\star(U, t) \right\|_{2 \rightarrow 2} 
%
\leq (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^4 \times L_3^2 \times L_1 + (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^2 \times L_3 \times L_2.
%
\end{align}
%
Replacing $f^\star$ with $g^\star$ in the above calculation, we also get that
%
\begin{align}\label{eq_g6}
\left\|\frac{\mathrm{d}}{\mathrm{d}U} g^\star(U, t)  \right\|_{2 \rightarrow 2}
%
\leq (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^4 \times L_3^2 \times L_1 + (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^2 \times L_3 \times L_2.
\end{align}
%
Thus, \eqref{eq_g5} and \eqref{eq_g6} imply that
%
\begin{equation}
       \|f^\star(y,t) - \Gamma_{x \rightarrow y}(f^\star(x,t))\| \leq \mathcal{C}\times   \rho(x, y), \qquad \qquad  \forall x,y \in \mathcal{M}
    \end{equation}
    %
    %
    and 
    %
    \begin{equation}
      \|g^\star(y,t) - \Gamma_{x\rightarrow y}(g^\star(x,t)) \|_F \leq \mathcal{C}  \times \rho(y, x) \qquad \qquad \forall x \in \mathcal{M},
    \end{equation}
    %
    where $\mathcal{C} := (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^4 \times L_3^2 \times L_1 + (C+ \sqrt{T}d \log(\frac{1}{\alpha}))^2 \times L_3 \times L_2$.



\end{proof}


\subsection{Wasserstein to TV conversion on the manifold (Lemma \ref{Lemma_Wasserstein_to_TV_conversion})}
\begin{lemma}[\bf Wasserstein to TV conversion on the manifold]\label{Lemma_Wasserstein_to_TV_conversion}
%
There is a number $c \leq \mathrm{poly(d)}$ such that for every $t\in[t_0,T]$ and any $\tau \leq \frac{1}{c}$ we have
%
\begin{align}
 \|\mathcal{L}_{Y_{t+\tau+\hat{\Delta}}} - \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}\|_{\mathrm{TV}}& - \|\mathcal{L}_{Y_{t}} - \mathcal{L}_{\hat{y}_{t}}\|_{\mathrm{TV}} \nonumber\\
%
&\leq  \sqrt{D_{\mathrm{KL}} (\nu_1 \, \| \, p_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| Y_{t+\tau} ))} + 
\sqrt{D_{\mathrm{KL}}(\nu_1 \| \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}} |\hat{y}_{t} })} \leq O(\epsilon c).
\end{align}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{Lemma_Wasserstein_to_TV_conversion}]
Now that we have shown that $f^\star$ and $g^\star$ are $\mathrm{poly}(d)$-Lipschitz (by Lemmas \ref{Lemma_average_case_Lipschitz} and \ref{lemma_Lipschitz}), we can apply Lemma \ref{Gronwall} to bound the Wasserstein distance:
%
$W_2(\hat{Y}_{t+\tau}, Y_{t+\tau})\leq (\rho^2(\hat{Y}_t, Y_t) + \epsilon) e^{c \tau} \qquad \forall \tau \geq 0,$
%
where $c \leq \mathrm{poly}(d)$.

%
Moreover, with slight abuse of notation, we may define $\hat{y}_{t+\tau}$ to be a continuous-time interpolation of the discrete process $\hat{y}$.
%
Applying \eqref{eq_r2} to this process we get that, roughly,
%
$W_2(\hat{Y}_{t+\tau}, \hat{y}_{t+\tau})\leq (\rho^2(\hat{y}_t, Y_t) + \epsilon + \Delta) e^{c \tau}$ for $\tau \geq 0$.
%
Thus, we get a bound on the Wasserstein error,
%
\begin{equation}\label{eq_r6b}
W_2(Y_{t+\tau}, \hat{y}_{t+\tau}) \leq W_2(\hat{Y}_{t+\tau}, Y_{t+\tau}) + W_2(\hat{Y}_{t+\tau}, \hat{y}_{t+\tau}) \leq  (\rho^2(\hat{y}_t, Y_t) + \epsilon + \Delta) e^{c \tau} \qquad \tau \geq 0
\end{equation}
%
Unfortunately, after times $\tau > \frac{1}{c} = \frac{1}{\mathrm{poly(d)}},$ this bound grows exponentially with the dimension $d$.
%

To overcome this challenge, we define a new coupling between $Y_t$ and $\hat{Y}_t$ which we ``reset'' after time intervals of length $\tau = \frac{1}{c}$ by converting our Wasserstein bound into a total variation bound after each time interval.
%
  Towards this end, we use the fact that if at any time $t$ the total variation distance satisfies $\|\mathcal{L}_{Y_t} - \mathcal{L}_{\hat{y}_t}\|_{\mathrm{TV}}\leq \alpha$, then there exists a coupling such that $Y_t = \hat{Y}_t$ with probability at least $1-\alpha$.
  %
  In other words, w.p. $\geq 1-\alpha$, we have $\rho(\hat{y}_{t+\tau}, Y_{t+\tau}) = 0$, and we can apply inequality \eqref{eq_r6b} over the next time interval of $\tau$ without incurring an exponential growth in time.
  %
Repeating this process $\frac{T}{\tau}$ times, we get that $\|\mathcal{L}_{Y_T} - \mathcal{L}_{\hat{y}_T}\| \leq \alpha \times \frac{T}{\tau}$, where the TV error grows only {\em linearly} with $T$.

\paragraph{Converting Wasserstein bounds on the manifold to TV bounds.}
To complete the proof, we still need to show how to convert the Wasserstein bound into a TV bound.
%
Towards this end, we begin by showing that the transition kernel $\tilde{p}_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| H_{t+\tau})$ of the reverse diffusion $H_t$ in $\mathbb{R}^d$ is close to a Gaussian in KL distance over short time steps $\hat{\Delta}$:  $$D_{\mathrm{KL}} (N(H_{t+\tau} + \hat{\Delta} \nabla \tilde{p}_{T-t-\tau}(H_{t+\tau}), \hat{\Delta} I_d) \, \| \, \tilde{p}_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| H_{t+\tau} )) \leq \frac{\alpha \tau}{T}.$$
%
One can do this using Girsanov's theorem, since, unlike the diffusion $Y_t$ on the manifold, the reverse diffusion in Euclidean space $H_t$ {\em does} have a constant diffusion term (see e.g. Theorem 9 of \cite{chen2023sampling}).

Next, we use the fact that with probability at least $1-\alpha \frac{\tau}{T}$ the map $\varphi$ in a ball of radius $\frac{1}{\mathrm{poly}(d)}$ about the point $H_{t+\tau}$ has $c$-Lipschitz Jacobian where $c=\mathrm{poly}(d)$, and that the inverse of the exponential map $\mathrm{exp}(\cdot)$ has $O(1)$-Lipschitz Jacobian, to show that the transition kernel $p_t$ of $Y_t = \varphi(H_t)$ satisfies
%
$$D_{\mathrm{KL}} (\nu_1 \, \| \, p_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| Y_{t+\tau} )) \leq (1+\hat{\Delta} c)^d \frac{\alpha \tau}{T} \leq 2\frac{\alpha \tau}{T},$$ if we choose $\hat{\Delta} \leq O(\frac{1}{c d})$, where $\nu_1:= \mathrm{exp}_{Y_{t+\tau}}(N(Y_{t+\tau} + \hat{\Delta} f^\star(Y_{t+\tau},t+\tau), \, \, \hat{\Delta} g^{\star 2}(Y_{t+\tau},t+\tau) I_d))$.


Next, we plug in our Wasserstein bound $W(Y_{t+\tau}, \hat{y}_{t+\tau}) \leq O(\epsilon)$  
into the formula for the KL divergence between two Gaussians to bound $\|\mathcal{L}_{Y_{t+\tau+\hat{\Delta}}} - \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}\|_{\mathrm{TV}}$.
%
Specifically, noting that $\mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}|\hat{y}_{t}} = \mathrm{exp}_{\hat{y}_{t+\tau}}(N(\hat{y}_{t+\tau} + \hat{\Delta} f(\hat{y}_{t+\tau},t+\tau), \hat{\Delta} g^2(\hat{y}_{t+\tau},t+\tau) I_d))$, we have that 
%
\begin{align*}
    D_{\mathrm{KL}}(\nu_1, \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}|\hat{y}_{t+\tau}}) &=  \mathrm{Tr}\left((g^{\star 2}(Y_{t+\tau}, t+\tau))^{-1} g^2(\hat{y}_{t+\tau}, t+\tau)\right)\\
    %
    &\qquad - d + \log \frac{\mathrm{det}\, g^{\star 2}(Y_{t+\tau}, t+\tau)}{\mathrm{det} \, g^2(\hat{y}_{t+\tau}, t+\tau)}
%
 +  w^\top (\hat{\Delta}g^{\star 2}(Y_{t+\tau}, t))^{-1} w,
\end{align*}
%
where $w:=Y_{t+\tau} - \hat{y}_{t+\tau} + \hat{\Delta}(f^\star(Y_{t+\tau}, t+\tau) - f(\hat{y}_{t+\tau}, t+\tau))$.
%
Since with probability $\geq 1-\alpha \frac{\tau}{T}$ we have $g^\star(Y_{t+\tau}) \succeq \mathrm{poly}(d)$, plugging in the error bounds $\|f^\star(Y_{t+\tau},t) - f(Y_{t+\tau},t)\| \leq \epsilon$ and $\|g^\star(Y_{t+\tau},t) - g(Y_{t+\tau},t)\|_F \leq \epsilon$ and the $c$-Lipschitz bounds on $f^\star$ and $g^\star$ due to Lemmas \ref{Lemma_average_case_Lipschitz} and \ref{lemma_Lipschitz}, where $c = \mathrm{poly}(d)$, we get that $D_{\mathrm{KL}}(\nu_1, \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}) \leq O(\epsilon^2 c^2)$.
%
 Thus, by Pinsker's inequality, we have
%
\begin{align}\label{eq_r7b}
 \|\mathcal{L}_{Y_{t+\tau+\hat{\Delta}}} - \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}}}\|_{\mathrm{TV}} & - \|\mathcal{L}_{Y_{t}} - \mathcal{L}_{\hat{y}_{t}}\|_{\mathrm{TV}} \nonumber\\
%
&\leq  \sqrt{D_{\mathrm{KL}} (\nu_1 \, \| \, p_{t+\tau+\hat{\Delta} | t+\tau}(\, \cdot \,| Y_{t+\tau} ))} + 
\sqrt{D_{\mathrm{KL}}(\nu_1 \| \mathcal{L}_{\hat{y}_{t+\tau+\hat{\Delta}} |\hat{y}_{t} })} \leq O(\epsilon c).
%
\end{align}
\end{proof}

\subsection{Completing the proof of Theorem \ref{thm_sampling_Manifold_best}}

\paragraph{Bounding the accuracy.}
%
Recall that $q_t$ is the distribution of the forward diffusion $Z_t$ in Euclidean space after time $t$, which is an Ornstein-Uhlenbeck process.
% 
Standard mixing bounds for Ornstein-Uhlenbeck process imply that $$\|q_t - N(0,I_d)\|_{TV} \leq O(Ce^{-t})$$ for all $t>0$ (see e.g. \cite{bakry2014analysis}). 
%
Thus, it is sufficient to choose $T = \log(\frac{1}{C\epsilon})$ to ensure that  $$\|\mathcal{L}_{Y_{T}} - \pi \|_{\mathrm{TV}} = \|q_T - N(0,I_d) \|_{\mathrm{TV}} \leq O(\epsilon).$$
%
As Lemma \ref{Lemma_Wasserstein_to_TV_conversion} holds for all $t \in [t_0,T]$,  the distribution $\nu = \mathcal{L}_{\hat{y}_{T}}$ of our sampling algorithm's output satisfies

$\|\pi- \nu\|_{\mathrm{TV}}  =  \|\mathcal{L}_{Y_{T}} - \pi \|_{\mathrm{TV}} +  \|\mathcal{L}_{Y_{T}} - \nu\|_{\mathrm{TV}} \leq O(\epsilon) + O(\epsilon c \times \frac{T}{\tau}) = O(\epsilon \times \mathrm{poly}(d))$.

\smallskip
\noindent
 \textbf{Bounding the runtime of the sampling algorithm.}
 Since our accuracy bound requires $T = \log(\frac{d}{\epsilon C})$, and requires a time-step size of $\Delta \leq \frac{1}{\mathrm{poly}(d)}$, the number of iterations is bounded by 
% %
$$\frac{T}{\Delta} \leq O\left(\mathrm{poly}(d)   \times \log\left(\frac{d}{\epsilon C}\right)\right).$$


\subsection{Proof sketch for extension of sampling guarantees to special orthogonal group}\label{appendix_SO_sketch}


%
Similar techniques to those used in the case of the complex unitary group can be used to bound the accuracy and runtime of our sampling algorithm in the case of the real special orthogonal group.
%
   However, in the case of the special orthogonal group we encounter the additional challenge that, due to weaker ``electrical repulsion'' between eigenvalues of real-valued random matrices, with high probability $\Omega(1)$ the gaps between neighboring eigenvalues $\gamma_{i+1}(t) - \gamma_i(t)$ may become  exponentially small in $d$, over very short time intervals of length $O(\frac{1}{e^d})$.
%
To overcome this challenge, we first note that, one can show that the gaps between {\em non-neighboring} eigenvalues do satisfy a polynomial lower bound at every time $t$ w.h.p. (see e.g.  \cite{anderson2010introduction, mangoubi2023private, mangoubi2025private}):
%
\begin{equation}\label{eq_r3c}  
\mathbb{P} \left( \bigcap_{t\in [t_0, T]} 
\left\{ \gamma_{i+2}(t) - \gamma_i(t) \leq s \frac{1}{\sqrt{n} \sqrt{t} } \right\} \right) 
\leq O\left(s^{1.5}\right).
\end{equation}
%
Moreover, one can also show that, except over at most $O(n^{1.5})$ ``bad'' time intervals $[\tau_j,\tau_j + \Delta_j]$, each of length e.g. $O(\frac{1}{n^5})$, the gaps between all neighboring eigenvalues are at least $\frac{1}{n^{10}}$. 
%




From the matrix calculus formula for $\varphi$ one can show that the SDE for the eigenvectors of the forward diffusion satisfy (these evolution equations, discovered by Dyson, are referred to as Dyson Brownian motion \cite{dyson1962brownian})
%
\begin{eqnarray}
\mathrm{d} \gamma_i(t) &=& \mathrm{d}B_{ii}(t) + \sum_{j \neq i} \frac{\mathrm{d}t}{\gamma_i(t) - \gamma_j(t)}, \label{eq_dyson_eigenvalue}\\
%
\mathrm{d} u_i(t) &=& \sum_{j \neq i} \frac{\mathrm{d}B_{ij}(t)}{\gamma_i(t)- \gamma_j(t)} u_j(t) - \frac{1}{2} \sum_{j \neq i} \frac{\mathrm{d}t}{(\gamma_i(t) - \gamma_j(t))^2} u_i(t) \qquad \forall i \in [n]. \label{eq_dyson_eigenvector}
\end{eqnarray}
%
%
From \eqref{eq_r3c}, one can see that over the ``bad'' time intervals  $[a_i,b_i]$, each eigenvalue $\gamma_i(t)$ has at most one neighboring eigenvalue, say $\gamma_{i+1}(t)$, with small gap $\gamma_i(t) - \gamma_{i+1}(t) \leq O(\frac{1}{\sqrt{d}})$ w.h.p.
%
%
 Roughly speaking, this implies that only the interactions in \eqref{eq_dyson_eigenvector} between eigenvectors with neighboring eigenvalues which fall below $O(\frac{1}{n^{10}})$ are significant, while interactions between eigenvectors with larger eigenvalue gaps are negligible over these short time intervals.
 %
 Thus, one can analyze the evolution of the eigenvectors \eqref{eq_r3b} over these short time intervals as a collection of separable two-body problems consisting of interactions between pair(s) of eigenvectors.
 %


More precisely, using \eqref{eq_dyson_eigenvalue}, one can show that over the bad time intervals $[\tau_j,\tau_j + \Delta_j]$, any eigenvalue gap which falls below $\frac{1}{n^{10}}$, also remains below $\frac{1}{n^{8}}$ over a time sub-interval of length at least $\Omega(\frac{1}{(n^{8})^2})$ w.h.p.
 %
 This is because eigenvalues $\gamma_i(t)$ and $\gamma_{i+1}(t)$ in \eqref{eq_dyson_eigenvalue} repel with an ``electrical force'' proportional to $\frac{1}{\gamma_i(t) - \gamma_{i+1}(t)}$, which implies that the eigenvalues gaps expand at a rate proportional to $\sqrt{t}$ (the stochastic term $\mathrm{d}B_{ii}(t)$ also leads to the same  $\sqrt{t}$ expansion rate).
 %
Thus, using the evolution equations \eqref{eq_dyson_eigenvector}, one can show that, over the short bad intervals, the distribution of $[u_i(\tau_j + \Delta_j), u_{i+1}(\tau_j + \Delta_j)]  | U(\tau_j)$ is   $\frac{1}{\mathrm{poly}(d)}$-close in Wasserstein distance to the invariant (Haar) measure with respect to  the action of $\mathrm{SO}(2)$ on $[u_i(\tau_j), u_{i+1}(\tau_j)]$.
%
This is because (by the It\^o isometry) the time-averaged variance in $u_i(t)$ over this time interval is proportional to $\frac{1}{\Delta_j} \int_{\tau_j}^{\tau_j+\Delta_j}\frac{1}{(\gamma_i(t)- \gamma_j(t))^2} \mathrm{d}t \approx \int_{n^{10}}^{n^{8}} {\frac{1}{(\sqrt{t})^2}} \mathrm{dt} = \log(\frac{1}{n^{8}}) - \log(\frac{1}{n^{10}}) = (10 - 8) \log(n) = \Omega(\log(n))$.
%
But the diameter of the 2-dimensional manifold (which is isomorphic to $\mathrm{SO}(2)$) on which $u_i(t)$ and $u_{i+1}(t)$ (approximately) lie is $O(1)$.
%
Thus, after the time interval  $[\tau_j,\tau_j + \Delta_j]$, the two neighboring eigenvectors $[u_i(\tau_j + \Delta_j), u_{i+1}(\tau_j + \Delta_j)]  | U(\tau_j)$ are (approximately) distributed according to the Haar measure with respect to the action of $\mathrm{SO}(2)$ on $[u_i(\tau_j), u_{i+1}(\tau_j)]$.
%
Thus, one can show that as long as one uses a numerical step size $\Delta \leq O(\frac{1}{\mathrm{poly}(d)})$, the transition kernel of both the continuous-time reverse diffusion $Y_t$ and the numerical simulation $\hat{y}_t$ over the time interval  $[\tau_j,\tau_j + \Delta_j]$ will be very close (within Wasserstein distance $\frac{\Delta}{\mathrm{poly}(d)}$) to the Haar measure on the action of $\mathrm{SO}(2)$ on $[u_i(\tau_j), u_{i+1}(\tau_j)]$.
%
As the Lipschitz property does hold outside the bad intervals $[\tau_j,\tau_j + \Delta_j]$, the remainder of the proof follows in the same way as for the case of $\mathrm{U}(n)$.





\section{Conclusion and future work}

We introduce a new diffusion model with a spatially varying covariance structure, enabling efficient training on symmetric manifolds with non-zero curvature. By leveraging manifold symmetries, we ensure the reverse diffusion satisfies an ``average-case'' Lipschitz condition, which underpins both the accuracy and efficiency of our sampling algorithm.

Our approach improves training runtime and sample quality on symmetric manifolds, significantly narrowing the gap between manifold-based diffusion models and their Euclidean counterparts. Furthermore, the model naturally extends to conditional generation: given a conditioning variable $y$, one can feed $y$ as an additional input to the learned drift and covariance functions, mirroring conditional diffusion models in Euclidean settings.

Several open directions remain. One is to extend our framework to more general manifolds—such as the manifold of positive semi-definite matrices, or other domains admitting a projection oracle satisfying suitable average-case smoothness properties (see Appendix~\ref{section_non_symmetric}). Another direction is to handle distributions supported on a union of manifolds with varying dimensions, such as the GEOM-DRUGS dataset \cite{jing2022torsional}, which lies on a union of tori.

Finally, while our method yields polynomial-in-$d$ bounds on sampling accuracy—improving upon prior works that lacked such guarantees—tightening this dependence remains an important challenge for future research.

