\section{Additional simulation details}\label{sec_simulation_details}

\subsection{Datasets} \label{appendix_datasets}

%
 Given a $d$-dimensional Riemannian manifold $\mathcal{M}$, a number of mixture components $k \in \mathbb{N}$, points $m_1,\ldots, m_k \in \mathcal{M}$ and covariance matrices $C_1,\ldots, C_k \in \mathbb{R}^{d \times d}$, we say that a random variable is distributed according to a wrapped Gaussian distribution with means  $m_1,\cdots, m_k$ and covariances $C_1,\cdots, C_k$ (with equal weights on each component) if its distribution is equal to that of a random variable $X$ sampled as follows:

\begin{enumerate}
\item Sample an index $i$ at random from $\{1,\ldots, k\}$.
%
\item Sample $Z \sim N(0, C_i)$
%
\item Set  $X = \mathrm{exp}_{m_i}(Z)$,
\end{enumerate}
%
where $\mathrm{exp}_{x}(\cdot)$ denotes the exponential map at any point $x \in \mathcal{M}$.


 \smallskip
\noindent
{\bf Datasets on the Torus $\mathbb{T}_d$.}
The synthetic dataset is sampled from a single-wrapped Gaussian distribution, with mean at the origin,  $(0, \ldots, 0)^T$ and covariance matrix $0.2 I_d$. A total of 30,000 points were sampled as the training dataset, and 10,000 were sampled as a test dataset to compute the log-likelihood of the generative model outputs.

\smallskip
\noindent
{\bf Datasets on the special orthogonal group $\mathrm{SO}(n)$.}
The dataset is constructed by first picking 2 random means $m_1, m_2 \in \mathrm{SO}(n)$ sampled from the uniform measure on the orthogonal group $\mathrm{SO}(n)$  (i.e., the invariant measure with respect to actions by the orthogonal group). We then sample 40,000 matrices from the wrapped Gaussian mixture distribution on $\mathrm{SO}(n)$ with means $m_1, m_2$ and covariance $0.2 I_d$.
%
30,000 of these matrices are used for training, and the remaining 10,000 matrices comprise the test dataset used to evaluate the C2ST score of the generative model outputs.

\smallskip
\noindent
{\bf Datasets on the unitary group $\mathrm{U}(n)$.}
%
 We use a dataset on $\mathrm{U}(n)$ of 
  unitary matrices representing time-evolution operators $e^{itH}$ of a quantum 
   oscillator.
   %
%
   Here $t$ is time, $H = \frac{\hbar}{2m}\Delta - V$ is a Hamiltonian, and $\Delta$ is the Laplacian. 
   %
$V$ is a random potential $V(x) = \frac{\omega^2}{2}\| x - x_0 \|^2$ with angular momentum $\omega$ sampled uniformly on $[2, 3]$ and $x_0\sim \mathcal{N}(0, 1)$. 
%
%
As $\Delta, V$ are infinite-dimensional operators, matrices in $\mathrm{U}(n)$ are obtained by retaining the  (discretized) top-$n$ eigenvectors of $\Delta, V$.
%

\subsection{Neural Network architecture, Training Hyperparameters, and hardware} \label{sec_training_details}

\textbf{Torus.} 
%
%
  In the case of the torus, the neural network architecture consists of a 4-layer MLP with a hidden dimension of $k$, with a $\sin$ activation function.
  %
   We set $k = 512$ for $d < 1000$ and $k = 2048$ for $d = 1000$. 

   The models were trained with a batch size of 512, with an appropriate variance scheduler.
%
   For each model, we trained the neural networks for 50K iterations when $d < 1000$, and for $100K$ iterations when $d = 1000$. 



\noindent
  \textbf{Special Orthogonal Group.} 
%
%
  In the case of the special orthogonal group, the neural network architecture consists of a 4-layer MLP with a hidden dimension $k = 512$, with a $\sin$ activation function.


  %
   For each model, the neural networks were trained for 100K iterations, with a batch size of 512, and an appropriate variance scheduler.



\noindent
\textbf{Unitary Group.} 
%
Following TDM~\cite{zhu2024trivialized}, when training each model on the unitary group,  we use a more complicated neural network than on the torus and special orthogonal group, to accommodate the more complicated quantum evolution operator datasets used in our simulations on the unitary group.
%
For both the drift and diffusion terms, let $(X_i, t_i)$ be inputs into the neural network, where $X_i\in\mathrm{U}(n)$ and $t_i\in [0, T]$ is time.  
%
 The output of the neural network is then given by \[
\hat{X_i} = \mathrm{MLP}(\mathrm{N_G}(\mathrm{MLP_S}(X_i), \mathrm{Emb}_\mathrm{sin}(t_i)))
\] 
where $\mathrm{MLP}$ is a 2-layer multi-layer perceptron of dimension $D$, $\mathrm{MLP_S}$ is $k$ skip-connected MLP layers of dimension $D$, $\mathrm{Emb_\mathrm{sin}}$ is a sinusoid
embedding of dimension $D$, and $\mathrm{N_G}$ denotes group normalization. In our simulations, we set $k = 8$ and $D = 512$. 
%
For the drift term $\hat{f}(\cdot, \cdot)$ in each of the models, the final output is given by $X_{\mathrm{drift}} = \mathrm{proj}_{T_{X_i}\mathrm{U}(n)}(\hat{X})$, where $\mathrm{proj}_{T_{X_i}\mathrm{U}(n)}$ is the projection onto the tangent space at $X_i$. 
%
For the diffusion term $\hat{g}(\cdot, \cdot)$ in our model, the neural network outputs a vector of dimension $d$. 
%


  For each model, the neural networks were trained for 80K iterations, with a batch size of 512, and an appropriate variance scheduler. 

