    \includegraphics{figures/paper/ablation_inversion.pdf}%
    \caption{
        \textbf{Inversion method ablation.}
        Replacing the exact DDIM inversion~\cite{hong2024exact} in our pipeline (\cref{fig:overview}) with naive DDIM~\cite{song2021denoising} or edit-friendly DDPM~\cite{huberman2024edit} inversion has a disastrous effect on its performance, here on object removal.
    }
    \label{fig:ablation_inversion}%
