\section{Preliminaries}\label{sec:prelims}


%%%%%%%%%%%
%%%%%%%%%%%
\subsection{Groups}
All groups are assumed to be finite. Let $\text{Sym}(n)$ denote the symmetric group on $n$ letters. The \textit{normal closure} of a subset $S \subseteq G$, denoted $\text{ncl}_{G}(S)$, is the smallest normal subgroup of $G$ that contains $S$. The \textit{socle} of a group $G$, denoted $\text{Soc}(G)$, is the subgroup generated by the minimal normal subgroups of $G$. If $G$ has no abelian normal subgroups, then $\text{Soc}(G)$ decomposes uniquely as the direct product of non-abelian simple factors. The \textit{solvable radical} $\text{Rad}(G)$ is the unique maximal solvable normal subgroup of $G$. Every finite group can be written as an extension of $\text{Rad}(G)$ by the quotient $G/\text{Rad}(G)$, the latter of which has no abelian normal subgroups. We refer to the class of groups without abelian normal subgroups as \textit{Fitting-free}.

%%%%%%%%%%%%
%%%%%%%%%%%%
\subsection{Computational Complexity}
We assume that the reader is familiar with standard complexity classes such as $\textsf{P}, \textsf{NP}, \textsf{L}$, and $\textsf{NL}$. For a standard reference on circuit complexity, see \cite{VollmerText}. We consider Boolean circuits using the \textsf{AND}, \textsf{OR}, \textsf{NOT}, and \textsf{Majority}, where $\textsf{Majority}(x_{1}, \ldots, x_{n}) = 1$ if and only if $\geq n/2$ of the inputs are $1$. Otherwise, $\textsf{Majority}(x_{1}, \ldots, x_{n}) = 0$. In this paper, we will consider $\textsf{DLOGTIME}$-uniform circuit families $(C_{n})_{n \in \mathbb{N}}$. For this,
one encodes the gates of each circuit $C_n$ by bit strings of length $O(\log n)$. Then the circuit family $(C_n)_{n \geq 0}$
is called \emph{\textsf{DLOGTIME}-uniform}  if (i) there exists a deterministic Turing machine that computes for a given gate $u \in \{0,1\}^*$
of $C_n$ ($|u| \in O(\log n)$) in time $O(\log n)$ the type of gate $u$, where the types are $x_1, \ldots, x_n$, \textsf{NOT}, \textsf{AND}, \textsf{OR}, or \textsf{Majority} gates,
and (ii) there exists a deterministic Turing machine that decides for two given gates $u,v \in \{0,1\}^*$
of $C_n$ ($|u|, |v| \in O(\log n)$) and a binary encoded integer $i$ with $O(\log n)$ many bits
in time $O(\log n)$ whether $u$ is the $i$-th input gate for $v$.


\begin{definition}
Fix $k \geq 0$. We say that a language $L$ belongs to (uniform) $\textsf{NC}^{k}$ if there exist a (uniform) family of circuits $(C_{n})_{n \in \mathbb{N}}$ over the $\textsf{AND}, \textsf{OR}, \textsf{NOT}$ gates such that the following hold:
\begin{itemize}
\item The $\textsf{AND}$ and $\textsf{OR}$ gates take exactly $2$ inputs. That is, they have fan-in $2$.
\item $C_{n}$ has depth $O(\log^{k} n)$ and uses (has size) $n^{O(1)}$ gates. Here, the implicit constants in the circuit depth and size depend only on $L$.

\item $x \in L$ if and only if $C_{|x|}(x) = 1$. 
\end{itemize}
\end{definition}

Now the complexity class $\textsf{NC}$ is defined as:
\[
\textsf{NC} := \bigcup_{k \in \mathbb{N}} \textsf{NC}^{k}.
\]


%%%%%%%%


\subsection{Permutation Group Algorithms}

In this paper, we will consider groups specified succinctly by generating sequences. The first model we will consider is that of permutation groups. Here, a group $G$ is specified by a sequence $S$ of permutations from $\Sym(n)$. 

Alternatively, we will consider the more general quotients of permutation groups model, which we will refer to as the \textit{quotients model}. To the best of our knowledge, this model was first introduced by Kantor and Luks \cite{KantorLuksQuotients}. Here, we will be given $K \trianglelefteq G \leq \Sym(n)$, represented in the following way:
\begin{itemize}
    \item $G, K$ are both specified by a generating sequence of permutations in $\Sym(n)$, and 
    \item Each element of $\textbf{G} := G/K$ is specified by a single coset representative.
\end{itemize}

The computational complexity for both the permutation group and quotients models will be measured in terms of $n$. We recall a standard suite of problems with known $\textsf{NC}$ solutions in the setting of permutation groups.

\begin{lemma}[{\cite{BabaiLuksSeress}}]\label{PermutationGroupsNC}\label{lem:Order-NC}
Let $G$ be a permutation group. The following problems are in $\textsf{NC}$:
\begin{enumerate}[label=(\alph*)]
\item Compute the order of $G$.
\item Whether a given permutation $\sigma$ is in $G$; and if so, exhibit a word $\omega$ such that $\sigma = \omega(S)$. 

\item Find the kernel of any action of $G$.
\item Find the pointwise stabilizer of $B \subseteq [m]$.
\item Find the normal closure of any subset of $G$.

\item For $H \leq \Sym(n)$ such that $G$ normalizes $H$, compute $C_{G}(H)$.

\item For $H \leq \Sym(n)$ such that $G$ normalizes $H$, compute $G \cap H$.
\end{enumerate}
\end{lemma}

\noindent We easily extend a subset of these problems to the setting of quotients. 

\begin{lemma} \label{QuotientsNC}
Let $\textbf{G} = G/K$ be a quotient of a permutation group. The following problems are in $\textsf{NC}$:
\begin{enumerate}[label=(\alph*)]
\item Compute the order of $\textbf{G}$.

\item Given a permutation $\sigma$, test whether $\sigma K$ is in $\textbf{G}$; and if so, exhibit a word $\omega$ that evaluates to $\sigma K$. 

\end{enumerate}
\end{lemma}

\begin{proof}
We proceed as follows.
\begin{enumerate}[label=(\alph*)]
\item As $G, K$ are permutation groups, we can compute $|G|, |K|$ in $\textsf{NC}$ \cite{BabaiLuksSeress}.

\item We note that $\sigma K \in \textbf{G}$ if and only if $\sigma \in G$. So we use the $\textsf{NC}$ constructive membership test from \cite{BabaiLuksSeress} to test whether $\sigma \in G$.  \qedhere
 \end{enumerate}
\end{proof}


\begin{lemma} \label{lem:List}
Let $K \trianglelefteq G \leq \Sym(n)$, and let $\textbf{G} := G/K$. If $|\textbf{G}| \leq n^{O(1)}$, then we can list $\textbf{G}$ in $\textsf{NC}$.
\end{lemma}

\begin{proof}
We begin by computing $|\textbf{G}|$ in $\textsf{NC}$ (Lemma~\ref{QuotientsNC}). Now let $S$ be the set of generators we are given for $\textbf{G}$. Wolf \cite{Wolf} showed that we can write down $\langle S \rangle$ in $O(\log |\textbf{G}|)$ rounds. We recall Wolf's procedure here. Let $T_{0} = S$. Now for $i \geq 0$, we construct $T_{i+1}$ by computing $xy$, for each $x, y \in T_{i}$. Our procedure terminates when $|T_{i}| = |\textbf{G}|$. 

We note that Wolf is considering quasigroups given by their multiplication tables, in which case we can multiply two elements in $\textsf{AC}^{0}$. However, we are dealing with quotients of permutation groups. In particular, any element of $\textbf{G}$ is represented as a permutation in $\Sym(n)$. Note that multiplying two permutations is $\textsf{FL}$-computable \cite{COOK1987385}. Thus, given $T_{i}$, we can compute $T_{i+1}$ in $\textsf{L}$. The result follows.
\end{proof}







\subsection{Background on Simple Groups} \label{subsec: simplegroup}
In this section, we examine classical simple groups, exceptional simple groups of Lie type, and other essential concepts related to simple groups. For a comprehensive treatment of the relevant details concerning simple groups, the reader is referred to \cite[Section 2.2]{DharaPhDThesis}. For a more in-depth exploration, further references include \cite{carter-book}, \cite{KleidmanLiebeck}, and \cite{WLS}.

\noindent \subparagraph*{Classical Simple Groups.} Let $V$ be a vector space of dimension $d$ over $\mathbb{F}_{q}$, where $q=p^{e}$. We write $\mathrm{GL}(d,q)$ to denote the \emph{general linear group}, which is the group of all invertible linear transformations from $V$ to $V$. The \emph{special linear group} (denoted by $\mathrm{SL}(d,q)$) is a subgroup of $\mathrm{GL}(d,q)$ containing all invertible linear transformations with determinant $1$. The center $Z({\rm{GL}}(d,q))$ consists of all transformation of the form $T(x)=\beta x$ for $\beta (\neq 0) \in \mathbb{F}_{q}$. The factor group $\mathrm{SL}(d,q)/Z(\mathrm{SL}(d,q)$ is called the \emph{projective special linear group} and is denoted by $\PSL(d,q)$. It is known that $\PSL(d,q)$ is a simple group with few exceptions \cite{carter-book,WLS}.

Now we define the simple group $\PSp(2d, q)$. Let $V$ be a vector space of dimension $2d$ over $\mathbb{F}_{q}$, where $q=p^{e}$. The symplectic classical group $\mathrm{Sp}(2d,q)$ is the set of invertible linear transformations of a $2d$-dimensional vector space over the field $\mathbb{F}_{q}$ which preserves a non-degenerate alternating, skew-symmetric bilinear form (see, e.g., \cite[Page~13]{KleidmanLiebeck}). It is known that any non-degenerate, skew-symmetric, bilinear form can be represented with respect to some basis by the matrix \[X= \begin{bmatrix}
    0 & 1 & & & & & & & \\
    -1 & 0 & &  & &   & \bf{0} & &  \\
   & & 0 & 1  & &  & & &\\
 & & -1 & 0 & &  & & & \\
   & \bf{0}  & & & &\ddots & & & \\
   & & & & & & & 0 & 1   \\
   & & & & & & & -1 & 0   \\
\end{bmatrix}.\] 

Let $T$ be the matrix corresponding to a linear transformation $\tau$. We have that $\tau \in {\rm{Sp}}(2d,q)$ if and only if $T^tXT=X$, where $T^t$ is the transpose of $T$. The center  $Z({\rm{Sp}}(2d,q))$ consists of the linear transformations $f(x)=\beta x$ where $\beta=\pm 1$. The factor group ${\mathrm{Sp}}(2d,q)/Z({\rm{Sp}}(2d,q))$ is called \emph{projective symplectic group} $\PSp(2d,q)$. The group $\PSp(2d,q)$ is a simple  provided ${d} \geq 2$ except when ${\rm PSp}(4,2)$. In the case when $\mathbb{F}_{q}$ is of characteristic $2$, we have $\PSp(2d,q)={\mathrm{Sp}}(2d,q)$.


Let us now define the simple group $\POmegaPlus(2d, q)$.  Let $V$ be vector space of dimension $m \geq 2$ over  $\mathbb{F}_{q}$, where $q=p^{e}$ and $p$ odd. Let $Q$ be a quadratic form whose associated bilinear form is $\mathfrak{f}_{Q}$. Then, the isometries of $V$ are called orthogonal linear transformation; they comprise the orthogonal group ${\rm{O}}(V, Q)$ \cite{LarryBook, WLS}. Thus 

\[{\rm{O}}(V,Q)=\{\tau \in \mathrm{GL}(m,q) | Q(\tau u)= Q(u) \text{ for all } u \in V\} \leq   \mathrm{GL}(m,q)\]


We denote by $\Omega(V,Q)$ the commutator subgroup of ${\rm{O}}(V,Q)$. Let $Z({\rm{O}}(V,Q))$ be the center of ${\rm{O}}(V,Q)$. Then the corresponding projective group is defined as \[\mathrm{P\Omega}(V,Q)=\Omega(V,Q)/(Z({\rm{O}}(V,Q)) \cap \Omega(V,Q)).\]

Now assume that $m=2d$. In this case, there are two non-equivalent quadratic forms on $V$, say $Q$ and $Q'$; these forms give rise to two different orthogonal groups (see, e.g., section 1.4, \cite{carter-book}, \cite{KleidmanLiebeck}). These quadratic forms are represented by the following matrices $X$ and $X'$, respectively,

$$X=\begin{bmatrix}
    0 & I_{d} \\
    I_{d} & 0
\end{bmatrix} \text{ and } X'= \begin{bmatrix}
    0_{d-1} & & & I_{d-1} & 0 & 0\\

    &  & & & \vdots & \vdots \\
    I_{d-1} &  &  & 0_{d-1}  & 0 & 0\\
    0 & & \ldots & 0 & 1 & 0 \\
    0 & & \ldots & 0 & 0 & - \epsilon 
\end{bmatrix},$$

where $\epsilon$ is a non-square element in $\mathbb{F}_{q}$. The orthogonal groups corresponding to these quadratic forms are denoted by
$O^{+}(2d,q)=O(V,Q)$ and $O^{-}(2d,q)=O(V,Q')$, respectively. Similarly, $\Omega^{+}(2d, q)$ is the commutator subgroup of $O^{+}(2d, q)$, and $\Omega^{-}(2d, q)$ is the commutator subgroup of $O^{-}(2d, q)$. The associated simple groups corresponding to $O^{+}(2d,q)$ and $O^{-}(2d,q)$ are denoted by $\mathrm{P\Omega}^{+}(2d,q)$ and  $\mathrm{P\Omega}^{-}(2d,q)$, respectively (see, e.g., \cite[Pages~4-7]{carter-book}). The groups ${\rm P}\Omega^{+}(2{d},q)$ and ${\rm P}\Omega^{-}(2{d},q)$ are simple when ${d} \geq 4$.


Now we describe various automorphisms of $\SL(d,q)$, $\Omega^+(2d,3)$ ($d \geq 4$), or $\mathrm{Sp}(4, 2^{e})$ ($e \geq 2$)(see \cite{carter-book} for more details). 


\begin{definition}\label{def:automorphisms}
Let $G$ be one of the following: $\SL(d,q)$, $\Omega^+(2d,3)$ ($d \geq 4$), or $\mathrm{Sp}(4, 2^{e})$ ($e \geq 2$). We introduce several automorphisms.
\begin{enumerate}[label=(\alph*)]
\item An automorphism $\mathbbm{i} : G \to G$ is called an \emph{inner automorphism} if there exists a matrix $F \in G$ such that $\mathbbm{i}(U) = F^{-1}UF$ for all $U \in G$.

\item An automorphism $\mathbbm{d} : G \to G$ is called a \emph{diagonal automorphism} if there exists a diagonal matrix $F \in \text{GL}(d,q)$ such that $\mathbbm{d}(F) = F^{-1}UF$ for all $U \in G$.

\item Let $\sigma$ be an automorphism of the field $\mathbb{F}_{q}$. A \emph{field automorphism} $\mathbbm{f}_{\sigma} : G \to G$ is defined as $\mathbbm{f}_{\sigma}([u_{ij}]) = [\sigma(u_{ij})]$, where $[u_{ij}]$ denotes the matrix in $G$ whose $(i,j)$th entry is $u_{ij}$.

Let $q=p^e$. Let us consider the Frobenius automorphism $\sigma_0$ of $\aut(\mathbb{F}_q)$ given by $a \mapsto a^p$. The automorphism $\sigma_0$ is a generator of $\aut(\mathbb{F}_q)$ of order $e$. Therefore, $\mathbbm{f}_{\sigma}=\mathbbm{f}_{\sigma_0}^{t'}$ for some $1 \leq t' \leq e$.

\item The \emph{graph automorphism} $\mathbbm{g} : G \to G$ is defined as $\mathbbm{g}(U) = (U^{t})^{-1}$ for all $U \in G$. Here, $U^{t}$ denotes the transpose of $U$.
\end{enumerate}
\end{definition}



A map $f: V \rightarrow V$ is called \emph{semi-linear transformation} of $V$ if there is an automorphism $\sigma \in \aut(\mathbb{F}_{q})$ such that for all $u,v \in V$ and $\beta \in \mathbb{F}_{q}$, $f(u+v)=f(u)+f(v)$ and $f(\beta v)=\sigma(\beta) f(v)$. A semi-linear transformation $f$ is invertible if $\{v\in V \mid f(v)=0\}=\{0\}$. The group of all invertible semi-linear transformation is called \emph{general semi-linear group} denoted by $\Gamma{\rm L}(d,q)$ \cite{KleidmanLiebeck}. The \emph{projective general semi-linear group}, ${\rm P}\Gamma{\rm L}(d,q)$, is obtained by factoring out the scalars in $\Gamma{\rm L}(d,q)$. However, for the current purpose the only fact that we need regarding ${\rm P}\Gamma{\rm L}(d,q)$ is that it can be regarded as a subgroup of $\aut(\SL(d,q))$ and automorphisms of $\SL(d,q)$ that contain the graph automorphisms $\mathbbm{g}$ in its decomposition are exactly the elements in $\aut(\SL(d,q)) \setminus {\rm P}\Gamma{\rm L}(d,q)$ \cite{KleidmanLiebeck,carter-book}.  



\noindent \subparagraph*{Exceptional Groups of Lie Type.} In this section, we define the Chevalley generators for $\mathcal{L}(\mathbb{F}_{q}) \in \{\G(3^e), \F(2^e), \Esix(q)\}$. Unlike, the classical simple groups, the exceptional simple groups of Lie type do not have matrix representations. Thus, we opt for this Chevalley presentation. Additionally, the Chevalley generator framework provides a well-established method for studying the automorphisms of these groups. Let use now define the Chevalley generators of the simple group $\mathcal{L}(\mathbb{F}_{q})$ from \cite[Chapter 3-4, 7]{carter-book}.  


Let $\mathcal{L}$ be a Lie algebra over $\mathbb{C}$. Let $\Phi$ be a root system corresponding to $\mathcal{L}$ and $\Pi \subsetneq \Phi$ be a fundamental system of roots. Let $\mathcal{L}_{\mathbb{Z}}$ be the subset of $\mathcal{L}$ of all linear combinations of basis elements with coefficient in the ring $\mathbb{Z}$ of integers. Define $\mathcal{L}_{\mathbb{F}_q}$ using the tensor product as follows: $\mathcal{L}_{\mathbb{F}_q}= \mathbb{F}_q  \otimes \mathcal{L}_{\mathbb{Z}}$ (see e.g., \cite[Section~4.4, Page 62]{carter-book}). The automorphisms of $\mathcal{L}_{\mathbb{F}_q}$ are the Chevalley generators of $\mathcal{L}(\mathbb{F}_{q})$. For each $r \in \Phi$ and $\beta \in \mathbb{F}_q$, $x_{r}(\beta)$ is an automorphisms of $\mathcal{L}_{\mathbb{F}_q}$. The action of $x_{r}(\beta)$ on the generating set of $\mathcal{L}_{\mathbb{F}_q}$ has been explicitly defined in \cite[Chapters~3-4, 7]{carter-book} for the comprehensive details.


We have $\mathcal{L}(\mathbb{F}_{q}) = \langle \{x_{r}(\beta) \mid r \in \Phi \text{ and } \beta \in \mathbb{F}_{q}\} \rangle$ (see e.g., \cite[Section~4.4, Page~64]{carter-book}). E.g., let $\mathcal{L}=\G$, then $\mathcal{L}(\mathbb{F}_{q})= \G(q)$ is the exceptional group of Lie type obtained from $\mathcal{L}$. Also, we have $\G(q) = \langle \{ x_{r}(\beta) \mid r \in \Phi \text{ and } \beta \in \mathbb{F}_q\} \rangle$ and $|\Phi|=12$. Similarly, we can define the Chevalley generators for $\F(2^e), \Esix(q)$. In case of $\F(2^e)$, $|\Phi|=2^7 3^2$, and in case of $\Esix(q)$, we have $|\Phi|=2^7 3^4 5$ (see  \cite[Page~43]{carter-book}). Therefore, the size of the Chevalley generators is polynomial in $q$. Additionally, note that, since $|\Phi|$ is bounded by a constant the size of a generating set $\{h_{r}, r \in \Pi, e_r, r \in \Phi \}$ of $\mathcal{L}_{\mathbb{F}_q}$ is also bounded by a constant. 



Let us now describe the automorphisms of the Chevalley group $\mathcal{L}(\mathbb{F}_{q})$ (see e.g., \cite[Chapter~12]{carter-book}). Notice that it is enough to define the automorphism at the Chevalley generators of the group $\mathcal{L}(\mathbb{F}_{q})$. 

There are four types of automorphism of a finite simple groups known as the inner automorphism, diagonal automorphism, field automorphism, and graph automorphism. Any automorphism of $\mathcal{L}(\mathbb{F})$ can be decomposed as a product of these four automorphisms \cite{carter-book}. We first define the inner and diagonal automorphisms of $\mathcal{L}(\mathbb{F}_{q})$.

Let $P=\mathbb{Z}\Phi$ be the set of all linear combination of elements of $\Phi$ with rational integer coefficients. $P$ is the additive group generated by the roots of $\mathcal{L}$. A homomorphism from $P$ into the multiplicative group $\mathbb{F}^{*}_{q}$ is called $\mathbb{F}_{q}$-character of $P$. The $\mathbb{F}_{q}$-character of $P$ forms a multiplicative group and each $\mathbb{F}_{q}$-character $\chi$ gives rise to an automorphism $h(\chi)$ of $\mathcal{L}_{\mathbb{F}_{q}}$. The automorphisms $\mathcal{L}_{\mathbb{F}_{q}}$ of the form $h(\chi)$ form a subgroup $\hat{H}$ of the full automorphism group of $\mathcal{L}_{\mathbb{F}_{q}}$ (see e.g., \cite[Section~7.1, Page~98]{carter-book}). Let $H$ be the subgroup of $\hat{H}$ generated by the automorphisms $h_{r}(\beta)$ for all $r\in \Phi$, $\beta \in \mathbb{F}^{*}_{q}$. Then $G=\mathcal{L}(\mathbb{F}_{q})$ normalized by $\hat{H}$ in the group of all automorphisms of $\mathcal{L}_{\mathbb{F}_{q}}$. Thus, if $h(\chi) \in \hat{H}$ and $g \in G$, then a map $g \rightarrow h(\chi) g h(\chi)^{-1}$ is an automorphism of $G$. If $h(\chi) \in \hat{H} \setminus H$, then the automorphism is called a \emph{diagonal automorphism} of $G$. If $h(\chi) \in H$, then the automorphism is called an \emph{inner automorphism} of $G$ (see e.g., \cite[Section~12.2, Page~200]{carter-book}).


Any automorphism $\sigma_0$ of the field $\mathbb{F}_{q}$ induces a field automorphism, say $\mathbbm{f}_{\sigma_0}$, of $\mathcal{L}(\mathbb{F}_{q})$.
It is defined in the following manner: $\mathbbm{f}_{\sigma_0}: \mathcal{L}(\mathbb{F}_{q}) \rightarrow \mathcal{L}(\mathbb{F}_{q})$, $\mathbbm{f}_{\sigma_0}(x_{r}(\beta))=x_{r}(\sigma_0(\beta))$ for $r \in \Phi$. The set of field automorphisms of $\mathcal{L}(\mathbb{F}_{q})$ is a cyclic group isomorphic to $\aut(\mathbb{F}_{q})$ (see e.g., \cite[Section~12.2, Page~200]{carter-book}).

The graph automorphisms of the Chevalley group $\mathcal{L}(\mathbb{F}_{q})$ arise from the symmetries of the Dynkin diagram. A symmetry of the Dynkin diagram of $\mathcal{L}$ is a permutation $\varrho$ of the nodes of the diagram such that the number of bonds joining nodes $i.j$ is the same as the number of bonds joining $\varrho(i),\varrho(j)$ for any $i\neq j$. Let $r \in \Phi$, $\beta \in \mathbb{F}_{q}$, and let $r \rightarrow {\bar r}$ be a map of $\Phi$ into itself arising from a symmetry of the Dynkin diagram of $\mathcal{L}$ (see e.g., \cite[Sections~12.2-12.4]{carter-book} and \cite[Section~2]{auto-Chevalley-groups}).  The graph automorphisms $\mathbbm{g}$ of the Chevalley groups $\mathcal{L}(\mathbb{F}_{q}) \in \{\G(3^e), \F(2^e), \Esix(q)\}$ are defined in the following ways (\cite{carter-book}): 

\begin{enumerate}
    \item if $\mathcal{L}(\mathbb{F}_{q})=\G(3^e)$,
    $$  \mathbbm{g} (x_{r}(\beta))=x_{\bar {r}}(\beta^{\lambda(\bar {r})}),$$
    where $\lambda(\bar {r_i})=1$ if $r$ is short root and $3$ if $r$ is long root.

    \item $\mathcal{L}(\mathbb{F}_{q})=\F(2^e)$,
    $$  \mathbbm{g} (x_{r}(\beta))=x_{\bar {r}}(\beta^{\lambda(\bar {r})}),$$
    where $\lambda(\bar {r_i})=1$ if $r$ is short root and $2$ if $r$ is long root.

    \item $\mathcal{L}(\mathbb{F}_{q})=\Esix(q)$,
    $$  \mathbbm{g} (x_{r}(\beta))=x_{\bar {r}}(\gamma_{r} z),$$
    where $\gamma_{r} \in \mathbb{Z}$ can be chosen so that $\gamma_{r}=1$ if $r \in \Pi$, $\gamma_{r}=-1$ if $-r \in \Pi$.
\end{enumerate}

\begin{theorem}(cf. \cite[Theorem 12.5.1, p. 211]{carter-book})\label{carter Thm-decomposition}
Let $G$ be a classical simple group or an exceptional simple group of Lie type defined over a field $\mathbb{F}$. Then every automorphisms of $G$ can be decomposed as $ \mathbbm{idgf}$, where $\mathbbm{i}$, $\mathbbm{d}$,  and $\mathbbm{f}$ are inner, diagonal, field automorphisms respectively, and $\mathbbm{g}$ is the graph automorphism.
\end{theorem}





\subsubsection{Constructive Recognition Algorithm for Classical Simple Groups}
In this section, we recall the framework for constructive recognition of finite simple groups given as either permutation groups or their quotients.  

\begin{theorem} \label{thm:ConstructiveRecognition}
Let $K \trianglelefteq G \leq \Sym(n)$, and let $\mathbf{G} := G/K$. If $\mathbf{G}$ is a non-abelian simple group, then we can, in polynomial-time, determine the name $S$ of $\mathbf{G}$, as well as construct an isomorphism $\varphi$ from $\mathbf{G}$ to an isomorphic copy $\mathbf{G}_{1}$ of $\mathbf{G}$. Furthermore, if $\textbf{G}$ is a classical simple group, then the following hold:
\begin{enumerate}
\item The elements of $\mathbf{G}_{1}$ are matrices acting on an $\mathbb{F}_{p}$-vector space $V$ of dimension $O(\log n)$,
\item The isomorphism $\varphi$ comes with a basis $\beta$ for $V$ and a data structure that:
\begin{enumerate}
\item Given a permutation $g \in \textbf{G}$, we can, in polynomial-time, construct the corresponding matrix representation $T$ with respect to $\beta$, and 
\item Given a matrix $T \in S$, we can, in polynomial-time, construct the corresponding permutation $g \in \textbf{G}$. 
\end{enumerate}

If $K = 1$, then this correspondence is $\textsf{NC}$-computable. 
\end{enumerate}
\end{theorem}

\begin{proof}
For $K = 1$, the $\textsf{NC}$ bound is due to Kantor, Luks, and Mark \cite{KantorLuksMark, MarkThesis}. For quotients of permutation groups, the polynomial-time bound is due to Kantor \cite{kantorPrimeOrderElement} (see also  \cite[\textbf{P12}]{KantorLuksQuotients}). 
\end{proof}






\subsection{The Minimal Faithful Permutation degree of Simple and Almost simple groups}
\begin{lemma}\label{Minper-Simple}
Let $G, K \leq \Sym(n)$ with $K \trianglelefteq G$. Let $\textbf{S} = G/K$ be a simple group then we can  compute $\mu(\mathbf{S})$ in polynomial-time. Furthermore, if $K = 1$, then we can compute $\mu(\mathbf{S})$ in $\textsf{NC}$.
\end{lemma}
\begin{proof}
We first use \Cref{thm:ConstructiveRecognition} to identify the type of $\mathbf{S}$. Now if $\mathbf{S}\cong A_n$ then clearly, $\mu(\mathbf{S})=n$. If $\mathbf{S}$ is either a classical simple group or an exceptional group of Lie type, then we use \cite[Table~4]{TableDegreesimple}. If $\mathbf{S}$ is a sporadic simple group, we refer to \cite{Atlas}. For the explicit value, refer to \cite[Page~10]{thesis-chamberlain}.

For the complexity bounds, we note that \Cref{thm:ConstructiveRecognition} yields polynomial-time bounds in the general case (quotients of permutation groups), and $\textsf{NC}$ bounds when $K = 1$ (permutation groups). The result now follows.
\end{proof}


Let $S$ be a simple group, then a group $A$ with $S \leq A \leq \aut(S)$ is called an \emph{almost simple group}. A normal subgroup $H\neq 1$ of $G$ is called \emph{minimal normal} if the only normal subgroups of $G$ contained in $H$ are $1$ and $H$. A minimal normal subgroup $H$ of a finite group $G$ is either simple or a direct product of isomorphic simple groups (see e.g., \cite[Page~106]{rotman}). 

