\subsection{Background on Representation Theory}
A \emph{representation} of a group $G$ is a homomorphism $\eta:G \rightarrow {\rm{GL}}(V)$ for some finite-dimensional non-zero vector space $V$. A subspace $W$ of $V$ is called $G$-\emph{invariant} if for all $g \in G$ and $w \in W$, we have $\eta_g(w) \in W$. A representation $\eta:G \rightarrow {\rm{GL}}(V)$ is called \emph{irreducible} if the only $G$-invariant subspaces of $V$ are ${0}$ and $V$. Let $V$ and $W$ be two finite dimensional vector spaces over a field $\mathbb{F}$. 

\begin{definition}\label{def-equivalentOfRep.}
Let $G$ be a group. We say that two representations $\vartheta: G \rightarrow {\rm{GL}}(V)$ and $\psi:G \rightarrow {\rm{GL}}(W)$ are \emph{equivalent} if there is an isomorphism $f:V \rightarrow W$ such that  $f\circ \vartheta_g = \psi_g \circ f$ for all $g \in G$. We write $\vartheta \sim \psi$.
\end{definition}

\begin{lemma}\cite{serre1977}\label{thm-schur}(Schur's Lemma) Let $\vartheta: G \rightarrow {\rm{GL}}(V)$ and $\psi:G \rightarrow {\rm{GL}}(W)$ be irreducible representations of a group $G$. Let $f: V \rightarrow W$ be a linear map such that $f \circ \vartheta=\psi \circ f$, then either $f$ is invertible or $f = 0$. 
\end{lemma}

\begin{lemma}\label{lem: Irreducibility}
Let $G$ be one of the following: $\SL(d,q)$, or ${\rm{Sp}}(4, 2^{e})$ ($e \geq 2$). Let $\vartheta: G \rightarrow {\rm{GL}}(d,q)$ be a non-trivial representation of $G$ over a vector space $\mathbb{F}_q^d$ then $\vartheta$ is irreducible.
\end{lemma}

\begin{proof}
Suppose that $\vartheta$ is not irreducible. Let $W \neq 0$ be a proper $G$-invariant subspace of $\mathbb{F}_q^d$. Consider $0 \neq w \in W \subsetneq \mathbb{F}_q^d$. Note that $\{w\}$ can be extended to a basis of $\mathbb{F}_q^d$ , say $\beta := \{w,b_2,\ldots,b_d\}$. Consider a linear transformation, say $T: \mathbb{F}_q^d \rightarrow \mathbb{F}_q^d$ defined as follows: $T(w)=b_2$, $T(b_2)=-w$, and $T(b_i)=b_i$ for all $i \geq 3$. It is easy to see that $\det(T)=1$ and hence $T \in \mathrm{SL}(d,q)$. Now, as $W$ is a $G$-invariant subspace of  $\mathbb{F}_q^d$, we have $T \cdot w =b_2 \in W$. Similarly, we can show that $b_i \in W$ for each $i \geq 3$. This contradicts that $W$ is a proper subspace of  $\mathbb{F}_q^d$. Thus, $\vartheta$ is irreducible when $G=\mathrm{SL}(d,q)$.

For $G=\mathrm{Sp}(d,q)$, where $d$ is even. Observe that the linear transformation $T$ defined above satisfies  $T^{t}XT = X$, where $X$ is the following matrix:
\[X= \begin{bmatrix}
    0 & 1 & & & & & & & \\
    -1 & 0 & &  & &   & \bf{0} & &  \\
   & & 0 & 1  & &  & & &\\
 & & -1 & 0 & &  & & & \\
   & \bf{0}  & & & &\ddots & & & \\
   & & & & & & & 0 & 1   \\
   & & & & & & & -1 & 0   \\
\end{bmatrix}.\] 
Thus, $T \in \mathrm{Sp}(d,q)$ (cf. \Cref{subsec: simplegroup}). In particular, when $d=4$ and $q=2^e$, we get $T \in  \mathrm{Sp}(4,2^e)$. 

Now, as $W$ is a $G$-invariant subspace of  $\mathbb{F}_q^d$, we have $T \cdot w =b_2 \in W$. Similarly, we can show that $b_i \in W$ for each $i \geq 3$. This contradicts the assumption that $W$ is a proper subspace of $\mathbb{F}_q^d$. Thus, $\vartheta$ is irreducible when $G=\mathrm{Sp}(4,2^e)$.
\end{proof}


\begin{lemma}[cf. {\cite[Proposition~2.10.6]{KleidmanLiebeck}}] \label{lem:OmegaIrreducible}
Let $d \geq 2$, and let $q = p^{k}$ for some prime $p > 2$ and some $k \geq 1$. For $U \in \Omega^{+}(2d,q)$ and $\alpha \in \Aut(\Omega^{+}(2d,q))$, define $\psi_{U}^{(\alpha)} : \mathbb{F}_{q}^{2d} \to \mathbb{F}_{q}^{2d}$ by $\psi_{U}^{(\alpha)}(v) = \alpha(U) \cdot v$.

Define the representation $\psi^{(\alpha)} : \Omega^{+}(2d,q) \to \text{GL}(2d,q)$ by $\psi^{(\alpha)}(U) = \psi_{U}^{(\alpha)}$. We have that $\psi^{(\alpha)}$ is irreducible.
\end{lemma}

\begin{proof}
Note that $\psi^{(\text{id})}$ is the natural representation of $\Omega^{+}(2d,q)$. This is irreducible by \cite[Proposition~2.10.6]{KleidmanLiebeck}. Now for any $\alpha \in \Aut(\Omega^{+}(2d,q))$, we have that $\text{Im}(\psi^{(\text{id})}) = \text{Im}(\psi^{(\alpha)})$. The result now follows.
\end{proof}




\section{Computing Socle of Fitting-free Group}

In this section, we will establish the following.

\begin{proposition} \label{prop:ComputeSocleFittingFree}
Let $G \leq \Sym(n)$ be a Fitting-free permutation group. We can compute generators for $\Soc(G)$ in $\textsf{NC}$. Furthermore, we can in $\textsf{NC}$, decompose $\Soc(G)$ into a direct product of non-abelian simple groups.
\end{proposition}

We first recall the following standard lemma.

\begin{lemma}[cf. \cite{Holt2005HandbookOC}] \label{lem:HandbookSocle}
Let $G$ be Fitting-free. We have that for any $N \trianglelefteq G$, $\Soc(G) = \Soc(N) \times \Soc(C_{G}(\Soc(N)))$.   
\end{lemma}

We also grateful to Joshua A. Grochow \cite{GrochowLemmas} for sharing the following key lemmas and their proofs.

\begin{lemma}[{\cite{GrochowLemmas}}] \label{lem:normal-subgroup-FF}
If $G$ is Fitting-free and $N \unlhd G$, then $N$ is Fitting-free and $\Soc(N) = \Soc(G) \cap N$.
\end{lemma}

\begin{proof}
Every subgroup of $N$ that is normal in $G$ is also normal in $N$, so $\Soc(N)$ cannot contain any non-minimal normal subgroups of $G$. And since $\Soc(N)$ is characteristic in $N$, it is normal in $G$, and thus $\Soc(N) \subseteq \Soc(G) \cap N$.

In the opposite direction, suppose $S \leq N \cap \Soc(G)$ is a minimal normal subgroup of $G$. Then $S$ is a direct product of non-abelian simple groups since $G$ is Fitting-free. As $S$ is normal in $N$ and a direct product of non-abelian simple groups, it is contained in $\Soc(N)$ (see also \cite[Lemma~4.3]{GLDescriptiveComplexity}). Thus $N \cap \Soc(G) \leq \Soc(N)$, so the two are equal. Finally, since $\Soc(N)$ is a normal subgroup of $\Soc(G)$, and the latter is a direct product of non-abelian simple groups, so is the former. But then $N$ contains no abelian normal subgroups, so is Fitting-free.
\end{proof}


\begin{lemma}[\cite{GrochowLemmas}]\label{lem:socle}
Suppose $G$ is Fitting-free and $1 \leq N_1 \leq \dotsb \leq N_r = G$ is a normal series (all $N_i$ are normal in $G$) such that each factor $N_{i+1} / N_{i}$ is a direct product of simple groups, and is either abelian, or contains no abelian direct factors. Define inductively $M_1 := N_1$, $M_i := M_{i-1} \times (N_i \cap C_G(M_{i-1}))$. Then for all $i$, we have $M_i = \Soc(N_i)$, and in particular, $M_r = \Soc(G)$.
\end{lemma}

\begin{proof}
By induction on $i$. For $i=1$: Since $G$ is Fitting-free and $N_1 = M_1$ is a normal subgroup, it cannot be abelian, so by assumption it is a direct product of non-abelian simple groups and thus $M_1 = N_1 = \Soc(N_1)$. 

Now suppose that $M_i = \Soc(N_i)$ for some $i \geq 1$; we will show the same holds for $i+1$. 


\textbf{Case 1:} $\Soc(N_i) = \Soc(N_{i+1})$. By induction we have $M_i = \Soc(N_i)$. Since $N_{i+1}$ is Fitting-free, we have that $1 = C_{N_{i+1}}(\Soc(N_{i+1}))$. But the latter is the same as $C_G(\Soc(N_{i+1})) \cap N_{i+1} = C_G(\Soc(N_i)) \cap N_{i+1} = C_G(M_i) \cap N_{i+1}$. Thus $M_{i+1} = M_i = \Soc(N_{i+1})$.

\textbf{Case 2:} $\Soc(N_{i+1}) \neq \Soc(N_i)$. By Lemma~\ref{lem:normal-subgroup-FF}, $N_i \cap \Soc(G) = \Soc(N_i)$ and $N_{i+1} \cap G = \Soc(N_{i+1})$, thus $\Soc(N_i) \lneq \Soc(N_{i+1})$. Since $\Soc(N_i)$ is characteristic in $N_i$ which is normal in $G$, we have that $\Soc(N_i)$ is also normal in $G$. Hence $\Soc(N_i)$ is also normal in $\Soc(N_{i+1})$. Since all these socles are direct products of non-abelian simple groups, there is some $S \leq G$ that is a direct product of non-abelian simple groups such that $\Soc(N_{i+1}) = \Soc(N_i) \times S$. By the definition of $M_{i+1}$, it is then necessary and sufficient to show $N_{i+1} \cap C_G(M_i) = S$.

As $S$ centralizes $\Soc(N_i) = M_i$, we have that $S$ is contained in both $N_{i+1}$ and $C_G(M_i)$. Therefore $S \leq N_{i+1} \cap C_G(M_i)$. 

In the opposite direction, suppose $g \in N_{i+1} \cap C_G(M_i)$; we will show that $g$ must be in $S$. Since $C_{N_{i+1}}(\Soc(N_{i+1})) = 1$, $g$ must not centralize all of $\Soc(N_{i+1})$. But since $g$ centralizes $M_i = \Soc(N_i)$, $g$ must not centralize $S$. Let $N$ be the normal closure of $g$ in $G$. Since $N_{i+1} \unlhd G$, we have $N \leq N_{i+1}$ and hence $N \unlhd N_{i+1}$. Additionally, since $M_i = \Soc(N_i)$, we have argued above that $M_i \unlhd G$, and since the centralizer of a normal subgroup is normal, $C_G(M_i)$ is also normal in $G$, and thus $N \leq C_G(M_i)$. Since $N$ is normal in $G$, it is Fitting-free, and we have $\Soc(N) = N \cap \Soc(G) \leq N_{i+1} \cap \Soc(G) = \Soc(N_{i+1})$. Since $N \leq C_G(M_i) = C_G(\Soc(N_i))$, we must have $\Soc(N) \cap \Soc(N_i) = 1$. But $\Soc(N) \leq \Soc(N_{i+1}) = \Soc(N_i) \times S$, and $\Soc(N)$ is normal in $N_{i+1}$, so---since these socles are all direct products of non-abelian simple groups---we must have $\Soc(N) \leq S$, and $g$ does not centralize $\Soc(N)$. But if $g$ is not in $\Soc(N)$, then $N$ is not a direct product of non-abelian simple groups so we must in fact have $g \in \Soc(N) \leq S$, as claimed.

Therefore $S = N_{i+1} \cap C_G(M_i)$, and $M_{i+1} = M_i \times S = \Soc(N_{i+1})$. \end{proof}


\begin{proof}[Proof of Proposition~\ref{prop:ComputeSocleFittingFree}]
Babai, Luks, and Seress \cite{BabaiLuksSeress} established that there exists an $\textsf{NC}$-computable series
\[
1 = N_{0} \leq N_{1} \leq \ldots \leq N_{r} = G
\]
of length $r \in O(\log^{c} n)$ (Kantor, Luks, and Mark \cite{KantorLuksMark} determined that $c = 2$) such that for all $i \in [r]$, $N_{i} \trianglelefteq G$ (see \cite[Sec.~3.6]{KantorLuksMark}) and each $N_{i}/N_{i-1}$ is a direct product of simple groups (semisimple). In particular, $N_{i}/N_{i-1}$ is either abelian, or has no abelian direct factor. We crucially take advantage of both the length of the series, as well as the fact that the successive quotients are semisimple to compute $\Soc(G)$ in $\textsf{NC}$.

We proceed inductively along the series. We begin with $N_{1}$. As $G$ is Fitting-free, $N_{1}$ is the direct product of non-abelian simple groups. By Lemma~\ref{lem:normal-subgroup-FF}, $N_{1} = \Soc(N_1) \trianglelefteq \Soc(G)$. By Lemma~\ref{lem:HandbookSocle}, $\Soc(G) = N_1 \times \Soc(C_{G}(N_1))$.

Define $M_{1} := N_{1} (= \Soc(N_1))$. And for $i > 1$, define $M_{i} := M_{i-1} \times (N_{i} \cap C_{G}(M_{i-1}))$. As each $N_{i}$ is normal in $G$, we have that each $M_{i}$ is normal in $G$. Now by Lemma~\ref{PermutationGroupsNC}(f), we may compute $C_{G}(M_{i-1})$ in $\textsf{NC}$, provided we are given generators for $M_{i-1}$. By Lemma~\ref{PermutationGroupsNC}(g), we may then compute $C_{G}(M_{i-1}) \cap N_{i}$ in $\textsf{NC}$. Thus, we may compute $M_{i}$ in $\textsf{NC}$, provided we are given generators for $M_{i-1}$. As $r \in O(\log^{2} n)$, we may compute $M_{1}, \ldots, M_{r}$ in $\textsf{NC}$. By Lemma~\ref{lem:socle}, we have that $M_{r} := \Soc(G)$. 



Once we have generators for $\Soc(G)$, we may decompose $\Soc(G)$ into a direct product of non-abelian simple groups in $\textsf{NC}$ using \cite{BabaiLuksSeress} (see also the discussion following the proof of \cite[Proposition~2.1]{BCGQ}). The result now follows.
\end{proof}





\begin{remark}
In the setting of both permutation groups and their quotients, the socle is polynomial-time computable \cite{KantorLuksQuotients}. However, obtaining $\textsf{NC}$ bounds is a long-standing open problem. Extending Proposition~\ref{prop:ComputeSocleFittingFree} to the setting of quotients is also non-trivial. We rely crucially on the $\textsf{NC}$ algorithm of Babai, Luks, and Seress \cite{BabaiLuksSeress} to compute the centralizer of a normal subgroup $H$ in $\textsf{NC}$. Kantor and Luks \cite[Section~6]{KantorLuksQuotients} note that the techniques for computing $C_{G}(H)$ in the setting of permutation groups appear not to work for  quotients. Instead, Kantor and Luks bring to bear the extensive machinery for computing Sylow subgroups of permutation groups in order to compute cores of quotients. Kantor and Luks then reduce computing $C_{G}(H)$ to computing an appropriate core. It is unclear how to compute cores of quotients in $\textsf{NC}$.
\end{remark}


\begin{proposition} \label{prop:MinimalNormalFittingFree}
Let $K \trianglelefteq G \leq \Sym(n)$, and let $\textbf{G} := G/K$ be Fitting-free. Suppose we are given the non-abelian simple factors of $\Soc(G)$. Then in $\textsf{NC}$, we can compute the set of minimal normal subgroups of $\textbf{G}$ (Proposition~\ref{prop:MinimalNormalFittingFree}).
\end{proposition}

\begin{proof}
The conjugation action of $\textbf{G}$ on $\Soc(\textbf{G})$ induces a permutation action on the non-abelian factors of $\Soc(\textbf{G})$. There are $\leq \log |G| \leq \log n! \sim n \log n$ such factors. View \textbf{G} as a permutation group $G^{*}$, with the non-abelian simple factors as the permutation domain. For every given orbit $\mathcal{O}$ of $G^{*}$, the members of $\mathcal{O}$ are precisely the factors of a single non-abelian simple factor of a minimal normal of $\textbf{G}$. Furthermore, all such minimal normal subgroups of $\textbf{G}$ are realized in this way. Now computing orbits in a permutation group is $\textsf{NC}$-computable \cite{McKenzieThesis}. The result now follows.
\end{proof}

Finally, we will show that if we are given a non-abelian simple factor $S$ is a non-abelian simple factor of the socle, for a Fitting-free group $\textbf{G}$, we can compute $N_{\textbf{G}}(S)$ in $\textsf{NC}$.



\begin{proposition}\label{Normalizer}
Let $G, K \leq \Sym(n)$ with $K \trianglelefteq G$. Let $\textbf{G} = G/K$. Suppose that $\textbf{G}$ is Fitting-free, and we are given the non-abelian simple factors of $\Soc(\textbf{G})$. Let $S$ be such a simple factor. Computing $N_{\textbf{G}}(S)$ is $\textsf{NC}$-reducible to \algprobm{Pointwise Stabilizer}. In particular, we can compute $N_{\textbf{G}}(S)$ in $\textsf{NC}$.
\end{proposition}

\begin{proof}
The conjugation action of $\textbf{G}$ on $\Soc(\textbf{G})$ induces a permutation action on the non-abelian simple factors of $\Soc(\textbf{G})$. There are $\leq \log |\textbf{G}| \leq \log n! \sim n \log n$ such factors. View $\textbf{G}$ as a permutation group $G^{*}$, with the non-abelian simple factors as the permutation domain. 

We claim that can, in $\textsf{NC}$, we can decide whether an element of $\textbf{G}$ fixes $S$ setwise. Given generators for $S$ and some $g \in \textbf{G}$, we can use \algprobm{Membership} to test whether $\langle S \rangle = \langle S \rangle^{g}$. By Lemma~\ref{PermutationGroupsNC}, \algprobm{Membership} is $\textsf{NC}$-computable. Thus, we can decide in $\textsf{NC}$ whether an element of $G^{*}$ stabilizes $S$ as a point. The point stabilizer $\text{Stab}_{G^{*}}(S) = N_{\textbf{G}}(S)$. By Lemma~\ref{PermutationGroupsNC}, \algprobm{Point Stabilizer} is $\textsf{NC}$-computable. The result follows.
\end{proof}










\section{Lifting of Automorphisms}

\subsection{Lifting Automorphisms of $\text{PSL}(d,q)$ to Automorphisms of $\text{SL}(d,q)$}

In this section, we extend the work of \cite[Section~3]{DasThakkarMPD} to show that we can lift an automorphism of $\text{PSL}(d,q)$ to an automorphism of $\text{SL}(d,q)$ in polynomial-time for the setting of quotients and in $\textsf{NC}$ for the permutation groups. Throughout this section, we will fix $n$ and consider quotients of permutation groups of $\Sym(n)$. We begin with the following observation. 

\begin{observation} \label{obs:PSLd}
Let $G, K \leq \Sym(n)$, with $K \trianglelefteq G$. Let $\textbf{G} := G/K$. Suppose that $\text{PSL}(d,q) \leq \textbf{G}$. Then (i) $d \in O(\sqrt{n \log n})$, and (ii) $q \leq n$. 
\end{observation}

\begin{proof}
We note that $|\text{PSL}(d,q)| \in q^{O(d^2)} \leq |\textbf{G}| \leq |G|$. It follows that $d^{2} \log q \leq \log |G| \leq \log n! \leq n \log n$, which establishes (i). However, this only provides the bound that $\log q \leq n \log n$. To see that $q \leq n$, let $q'$ be the largest prime power such that $\text{PSL}(d, q') \leq \Sym(n)$. In this case, $q' \leq n$ \cite{KantorSeress}. Clearly, $q \leq q'$, and so $q \leq n$, as desired.  
\end{proof}

In light of Observation~\ref{obs:PSLd}, we may assume without loss of generality that $d, q$ are given in unary. Throughout this section, let $Z \leq \text{SL}(d, q)$ denote the subgroup of all nonzero scalar transformations of $\mathbb{F}_{q}^{d}$. Note that $Z = Z(\text{SL}(d,q))$. 

\begin{proposition}[{\cite[Proposition~3.1]{DasThakkarMPD}}] \label{prop-UniEle}
Let $d \geq 3$, $p$ be prime, and $e$ such that $q = p^{e}$. Suppose that $(d, q) \not \in \{(3,2), (4,2)\}$. Each coset of $\text{SL}(d,q)/Z$ has at most one element of order $p$. 
\end{proposition}

\begin{theorem}[\cite{Dieudonne}]
$\Aut(\text{PSL}(d,q)) \cong \Aut(\text{SL}(d,q))$. 
\end{theorem}

Let $\Psi : \Aut(\text{SL}(d,q)) \to \Aut(\text{PSL}(d,q))$ be the map that takes $\alpha \in \Aut(\text{SL}(d,q))$ to the map $\overline{\alpha} : \text{PSL}(d,q) \to \text{PSL}(d,q)$, where $\overline{\alpha}(UZ) = \alpha(U)Z$. Das and Thakkar established \cite[Proposition~3.3]{DasThakkarMPD} that $\Psi$ is indeed an isomorphism. 


\begin{lemma}[cf. {\cite[Lemma~3.4]{DasThakkarMPD}}]\label{construct-alpha}
Given $\lambda \in \Aut(\text{PSL}(d,q))$ by its action on a generating set of $\text{PSL}(d, q)$, we can find $\alpha \in \Aut(\text{SL}(d,q))$ such that $\lambda = \overline{\alpha}$. Moreover, $\alpha$ is specified by its action on a generating set of size $O(qd^{2})$. 

If $\text{PSL}(d,q)$ is given as a quotient of permutation groups $G/K$, where $K \trianglelefteq G \leq \Sym(n)$, our procedure is polynomial time computable. Furthermore, if $K = 1$, then our procedure is $\textsf{NC}$-computable.
\end{lemma}

\begin{proof}
As $q$ is given in unary, we may write down $\mathbb{F}_{q}$ in $\textsf{NC}$ (by writing down the Cayley tables for $(\mathbb{F}_{q}, +)$ and $(\mathbb{F}_{q}^{\times}, \times)$). For $i, j \in [d]$, let $e_{i,j}$ be the $d \times d$ matrix with $1$ in the $(i,j)$ entry and $0$ otherwise. Furthermore, in $\textsf{NC}$, we may write down the following set:
\[
L = \{ I + \beta e_{i,j} \mid \beta \in \mathbb{F}_{q}^{*}; i, j \in [d] \text{ s.t. } i \neq j \}.
\]
Note that $\text{SL}(d,q) = \langle L \rangle$ (see e.g., \cite[Page~185]{carter-book}). For each $T \in L$, we construct a permutation $g_{T} \in \Sym(n)$ such that the map $T \mapsto g_{T}$ extends to an isomorphism. By Theorem~\ref{thm:ConstructiveRecognition}, this step is polynomial-time computable for quotients of permutation groups, and $\textsf{NC}$-computable for permutation groups.

For each $U \in L$, $\text{ord}(U) = p$, which is coprime to $|Z| = \text{gcd}(d, q-1)$. Let $m_{2} : \text{SL}(d,q) \to \text{PSL}(d, q)$ be the canonical projection map, with kernel $Z$. We have the following commutative diagram: 

$$ \begin{tikzcd}
\mathrm{SL}(d,q) \arrow{r}{\alpha} \arrow[swap]{d}{m_2} & \mathrm{SL}(d,q) \arrow{d}{m_2} \\
\PSL(d,q) \arrow{r}{\lambda}& \PSL(d,q)
\end{tikzcd}.$$ 

From the above diagram, we have that $m_{2} \circ \alpha = \lambda \circ m_{2}$. Now observe that if $U \in L$, then $\text{ord}(\alpha(U)) = \text{ord}(U) = p$. Furthermore, observe that there exists some $V \in \text{SL}(d,q)$ such that $\lambda(m_{2}(U)) = VZ$.

We now need to define the image $\alpha(U)$ for each $U \in L$. As $\text{ord}(U) = p$ and $\alpha \in \Aut(\text{SL}(d,q))$, we have that $\text{ord}(\alpha(U)) = p$. As the diagram is commutative, $\alpha(U)$ is an element of the coset $VZ$. So we have that $\alpha(U), m_{2}(\alpha(U)) \in VZ$. However, by \cite[Proposition~3.1]{DasThakkarMPD}, there is at most one element of $VZ$ of order $p$. Hence, $\alpha(U) = m_{2}(\alpha(U))$. As $|Z| = \text{gcd}(d, q-1) \leq n$, we can in $\textsf{NC}$, Lemma~\ref{lem:List}, list $Z$ and hence $VZ$. Thus, we can in $\textsf{NC}$ find $\alpha(U) = m_{2}(\alpha(U))$. 

Now for each $U \in L$, we can in $\textsf{NC}$, construct a word over the specified generating set of $\text{PSL}(d,q)$ (see Lemma~\ref{QuotientsNC} for quotients of permutation groups, and Lemma~\ref{PermutationGroupsNC} for permutation groups). Thus, we can in $\textsf{NC}$, evaluate $\lambda(m_{2}(U))$. The corresponding word, in particular, yields a coset representative of $VZ$. As we have written down $Z$, we can identify $V$ in $\textsf{NC}$. The result now follows.
\end{proof}



We now turn to identifying the type of a given automorphism $\alpha$ of $\text{SL}(d,q)$. We follow the strategy of Das and Thakkar \cite{DasThakkarMPD}. Let $G = \text{SL}(d,q)$ and $V = \mathbb{F}_{q}^{d}$, where $q = p^{e}$ for some prime $p$ and some $e > 0$. Consider a representation $\vartheta : \text{SL}(d,q) \to \text{GL}(d,q)$, which takes $U$ to $\vartheta_{U}$, where $\vartheta_{U} : V \to V$ is defined by $\vartheta_{U}(v) = U \cdot v$. Similarly, consider the representation $\psi^{(\alpha)} : \text{SL}(d,q) \to \text{GL}(d,q)$ which takes $U \in \text{SL}(d,q)$ to $\psi_{U}^{(\alpha)} : V \to V$ defined by $\psi_{U}^{(\alpha)}(v) = \alpha(U) \cdot v$. Note that we can define $\vartheta, \psi^{(\alpha)}$ analogously for ${\rm{Sp}}(4, 2^e)$ ($e \geq 2$). By Lemma~\ref{lem: Irreducibility}, both $\vartheta_{U}$ and $\psi^{(\alpha)}$ are irreducible.

Das and Thakkar \cite[Remark~3.5]{DasThakkarMPD} noted that $\vartheta \sim \psi^{(\alpha)}$ if and only if there exists $F \in \text{GL}(d, q)$ such that for all $U \in \text{SL}(d,q)$, we have that $FUF^{-1} = \alpha(U)$.

\begin{lemma}[cf. {\cite[Lemma~3.6]{DasThakkarMPD}}]\label{lem-type-checking}
Let $G$ be one of the following: $\SL(d,q)$ ($(d, q) \not \in \{ (3,2), (4,2)\})$, ${\rm{Sp}}(4, 2^e)$ ($e \geq 2$). Let $\alpha$ be an automorphism of $G$. Suppose that $\alpha$ is specified by its action on a generating set $B$ of $G$. Furthermore, suppose that $\vartheta$ and $\psi^{(\alpha)}$ are irreducible. Then in $\textsf{NC}^{2}$, we can decide if $\vartheta \sim \psi^{(\alpha)}$. 
\end{lemma}



\begin{proof}[Proof of Lemma~\ref{lem-type-checking}]
We follow the strategy of \cite[Lemma~3.6]{DasThakkarMPD}. Our goal is to find an $F \in \text{GL}(d, q)$ such that for all $U \in G$, we have that $FUF^{-1} = \alpha(U)$. Let $B = \{ U_1, \ldots, U_b\}$ be a generating set for $G$. Consider the following system of linear equations:
\[
FU_{j} = \alpha(U_{j})F, \text{ for all } j \in [b],
\]

\noindent where the entries of $F$ are the unknowns. This is a homogeneous system of $bd^{2}$ equations with $d^{2}$ unknowns. We can solve this system of equations in $\textsf{NC}^{2}$ using Gaussian elimination \cite{MulmuleyRank}. If there is a unique $F = 0$, then there is no invertible matrix $F$ satisfying $FU = \alpha(U)F$ for all $U \in G$. In this case, $\vartheta \not \sim \psi^{(\alpha)}$. Otherwise, there is a non-zero solution satisfying $F\alpha(U) = UF$. But by Lemma~\ref{thm-schur}, we have that $F$ is invertible. So $\vartheta \sim \psi^{(\alpha)}$. The result now follows.
\end{proof}

\begin{observation}[{\cite[Observation~3.7]{DasThakkarMPD}}]\label{Observation-typechecking-PSL}
Let $G$ be one of the following: $\SL(d,q)$, ${\rm{Sp}}(4, 2^e)$ ($e \geq 2$). Let $\alpha \in \aut(G)$. Then the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item The irreducible representations $\vartheta, \psi^{(\alpha)}$ are equivalent,
\item there exists $F \in \mathrm{GL}(d,q)$ such that $\alpha(U)=F^{-1}UF$ for all $U \in G$, and 
\item $\alpha$ is an inner or diagonal automorphism of $G$.
\end{enumerate}
\end{observation}





\subsection{Lifting Automorphisms of $\POmegaPlus(2d,3)$ to Automorphisms of $\Omega^+(2d,3)$}

In this section, we extend the work of \cite[Section~7]{DasThakkarMPD} to show that we can lift an automorphism of of $\POmegaPlus(2d, 3)$ to an automorphism of $\Omega^{+}(2d,3)$, in polynomial-time for the setting of quotients and in $\textsf{NC}$ for the permutation groups. Throughout this section, we will fix $n$ and consider quotients of permutation groups of $\text{Sym}(n)$. Note that $|\Omega^{+}(2d, q)| \leq q^{O(d^3)}$. So by a similar argument as in Observation~\ref{obs:PSLd} (see also \cite{KantorSeress}), we have that $d \in O(\sqrt{n \log(n)})$. In particular, we may assume that $d$ is given in unary. We will restrict attention to the case $q = 3$.


\begin{proposition}[{\cite[Proposition~7.1]{DasThakkarMPD}}]\label{prop-UniEle-POmega}
Let $d \geq 4$ then each cosets of $Z=Z(\rm{O}^+(2d,3)) \cap \Omega^+(2d,3)$ in $\Omega^+(2d,3)$ has at most one element of order $3$.
\end{proposition}






\begin{theorem}[cf. {\cite[Theorem 4.5]{DasThakkarMPD}}]
\noindent 
\begin{enumerate}[label={(\roman*)},itemindent=1em]\label{Thm-Iso-POmegga-Omega}
\item[(i)] \cite{dieudonne1951} $\aut(\POmegaPlus(2d,q)) \cong \aut(\Omega^+(2d,q))$.

\item[(ii)] Let $\Psi:\aut(\Omega^+(2d,3))  \rightarrow \aut(\POmegaPlus(2d,3))$ be the map that takes $\alpha \in \aut(\Omega^+(2d,3))$ to $\bar{\alpha}$, where $\bar{\alpha}:\POmegaPlus(2d,3) \rightarrow \POmegaPlus(2d,3)$ is defined as $\bar{\alpha}(UZ)=\alpha(U)Z$. Then the map $\Psi:\aut(\Omega^+(2d,3)) \rightarrow \aut(\POmegaPlus(2d,3))$ is an isomorphism. 
\end{enumerate}
\end{theorem}

The proof of \Cref{Thm-Iso-POmegga-Omega}(ii) is similar to the proof of \cite[Proposition~3.3]{DasThakkarMPD} with $L$ being a generating set of $\Omega^{+}(2d,3)$ defined below in the proof of \Cref{construct-alpha-POmega}.

\Cref{Thm-Iso-POmegga-Omega} says that for any $ \lambda \in \aut(\POmegaPlus(2d,3))$ there is $\alpha \in \aut(\Omega^+(2d,3))$ such that $\lambda=\bar{\alpha}$. We now describe how to compute such elements $\alpha$ from a given $\lambda$.


\begin{lemma}\label{construct-alpha-POmega}
Given $\lambda \in \aut(\POmegaPlus(2d,3))$ by its action on a generating set of $\POmegaPlus(2d,3)$, we can find $\alpha\in \aut(\Omega^+(2d,3))$ such that $\lambda=\bar{\alpha}$. Moreover, $\alpha$ is specified by its action on a generating set of size $O(d^2)$.

If $\POmegaPlus(2d,3)$ is given as a quotient $G/K$ of permutation groups, where $K \trianglelefteq G \leq \Sym(n)$, then our procedure is polynomial-time computable. Furthermore, if $K = 1$, then our procedure is $\textsf{NC}$-computable.
\end{lemma}

\begin{proof}
 For a matrix $U \in \mathrm{\Omega^{+}}(2d,3)$, numbering the row and columns by $1,\ldots, d, -1, \ldots, -d$. For $i, j \in [d] \cup \{-1, \ldots, -d\}$, let $e_{i,j}$ be the $2d \times 2d$ matrix with $1$ in the $(i,j)$ entry and $0$ otherwise. Furthermore, in $\textsf{NC}$, we may write down the following set:
\begin{align*}
L=\{&I+\beta(e_{i,j}-e_{-j,-i}),\\
&I-\beta(e_{-i,-j}-e_{j,i}),\\ 
&I+\beta(e_{i,-j}-e_{j,-i}),\\ 
&I-\beta(e_{-i,j}-e_{-j,i})  \mid 0 < i < j, \beta \in \mathbb{F}_3\}.
\end{align*}

Note that $\mathrm{\Omega^{+}}(2d,3)=\langle L \rangle$ (see e.g., \cite[Page~185]{carter-book}). We now do the following: for each $T \in L$, construct a permutation $g_{T} \in \Sym(n)$ such that the map $T \mapsto g_{T}$ extends to an isomorphism. By Theorem~\ref{thm:ConstructiveRecognition}, this step is polynomial-time computable in the setting of quotients of permutation groups, and $\textsf{NC}$-computable for permutation groups ($K = 1$).

For each $U \in L$, $\text{ord}(U) = 3$, which is coprime to the order of $Z=Z( \mathrm{\Omega^{+}}(2d,3))=2$. Let $m_2: \Omega^+(2d,3) \rightarrow \POmegaPlus(2d,3)$ be the canonical map with kernel $Z$. We have the following commutative diagram.

$$ \begin{tikzcd}
\Omega^+(2d,3) \arrow{r}{\alpha} \arrow[swap]{d}{m_2} & \Omega^+(2d,3) \arrow{d}{m_2} \\
\POmegaPlus(2d,3) \arrow{r}{\lambda}& \POmegaPlus(2d,3)
\end{tikzcd}.$$ 

From the above diagram we have $m_2 \circ {\alpha} = \lambda \circ m_2$. Let $U \in L$ then $\ord(\alpha(U))=\ord(U)=3$. Notice that $\lambda(m_2 (U))= VZ$ for some $V \in \Omega^+(2d,3)$ \cite{KantorSeress}. 

We now need to define the image $\alpha(U)$ for each $U \in L$. Since $\ord(U)=3$ and $\alpha \in \aut(\Omega^+(2d,3))$ we have $\ord(\alpha(U))=3$. Since the diagram is commutative we have $\alpha(U)$ is an element in the coset $VZ$. In other words, $\alpha(U) \in VZ$ and $(m_2 \circ \alpha)(U)=VZ$. But ${\alpha}(U)$ is of order $3$ and there is just one element in $VZ$ with order $3$ (cf. \Cref{prop-UniEle-POmega}). Since $|Z|=2$ we can easily find such an element of order $3$ in the coset $VZ$. Thus we can in \textsf{NC} find $\alpha(U)$.  

Now for each $U \in L$, we can in $\textsf{NC}$, construct a word over the specified generating set of $\POmegaPlus(2d,3)$ (see Lemma~\ref{QuotientsNC} for quotients of permutation groups, and Lemma~\ref{PermutationGroupsNC} for permutation groups). Thus, we can in $\textsf{NC}$, evaluate $\lambda(m_{2}(U))$. The corresponding word, in particular, yields a coset representative of $VZ$. As we have written down $Z$, we can identify $V$ in $\textsf{NC}$. The result now follows.
\end{proof}


Now we are interested in identifying the type of the automorphism $\alpha$ of $\Omega^+(2d,3)$. Again, we follow the strategy of Das and Thakkar \cite{DasThakkarMPD}. Let $G=\Omega^+(2d,3)$, $V=\mathbb{F}_{3}^{2d}$. Consider a representations $\vartheta: \Omega^+(2d,3) \rightarrow {\rm{GL}}(2d,3)$ which takes ${U} \in \Omega^+(2d,3)$ to $\vartheta_{U}$, where ${\vartheta}_{U}: V \rightarrow V$ defined as ${\vartheta}_U(v)=U\cdot v$. Also, take $\alpha \in \aut(\Omega^+(2d,3))$. Consider $\psi^{(\alpha)}: \Omega^+(2d,3) \rightarrow {\rm{GL}}(2d,3)$ which takes $U \in \Omega^+(2d,3)$ to ${\psi}_U^{(\alpha)}$, where ${\psi}_{U}^{(\alpha)}: V \rightarrow V$ defined as ${\psi}_U^{(\alpha)}(v)=\alpha(U)\cdot v$. By Lemma~\ref{lem:OmegaIrreducible}, both $\vartheta$ and $\psi^{(\alpha)}$ are irreducible representations.


\begin{remark}\label{rem module-equ-cond-POmega}
Let $\vartheta,\psi^{(\alpha)}$ be as defined above. Then $\vartheta \sim \psi^{(\alpha)}$ if and only if there is $F \in \mathrm{GL}(2d,3)$ such that ${FUF^{-1}}=\alpha(U)$ for all $U \in G$. 
\end{remark}


\begin{lemma}\label{lemma-module-equ-cond-POmega}
Let $\vartheta,\psi^{(\alpha)}$ be as defined above. Then $\vartheta \sim \psi^{(\alpha)}$, i.e., there is $F \in \mathrm{GL}(2d,3)$ such that $FU=\alpha(U)F$ for all $U \in G$. Furthermore, we can in $\textsf{NC}^{2}$, decide if $\vartheta \sim \psi^{(\alpha)}$.
\end{lemma}
\begin{proof}    
Suppose $\alpha \in \aut(G)$. As $q = 3$, there are no non-trivial field automorphisms. Furthermore, the graph automorphism is not present. \cite{carter-book,KleidmanLiebeck,WLS}. Thus, $\alpha$ is an inner or diagonal automorphism. Therefore, for every $\alpha \in \aut(G)$ there is $F \in \mathrm{GL}(2d,3)$ such that $\alpha(U)=F^{-1}UF$. This with \Cref{rem module-equ-cond-POmega} implies that $\vartheta \sim \psi^{(\alpha)}$. 

Next, our goal is to find an $F \in \text{GL}(2d,3)$ such that for all $U \in \Omega^+(2d,3)$, we have $FUF^{-1} = \alpha(U)$. Let $B = \{ U_1, \ldots, U_b\}$ be a generating set for $\Omega^+(2d,3)$. Consider the following system of linear equations:
\[
FU_{j} = \alpha(U_{j})F, \text{ for all } j \in [b],
\]

\noindent where the entries of $F$ are the unknowns. This is a homogeneous system of $bd^{2}$ equations with $d^{2}$ unknowns. We can solve this system of equations in $\textsf{NC}^{2}$ using Gaussian elimination \cite{MulmuleyRank}. Let $F$ be a non-zero solution obtained from the Gaussian elimination algorithm. By \Cref{thm-schur} we know that $F$ is invertible. Thus, the result now follows. 
\end{proof}


\begin{observation}[cf. {\cite[Observation~7.6]{DasThakkarMPD}}]\label{Observation-typechecking-POmega}
Let $\alpha \in \aut(\Omega^+(2d,3))$. The following are equivalent: 
\begin{enumerate}[label=(\alph*)]
\item $\vartheta \sim \psi^{(\alpha)}$,
\item there exists $F \in \mathrm{GL}(2d,3)$ such that $\alpha(U)=F^{-1}UF$ for all $U \in \Omega^+(2d,3)$, and
\item $\alpha$ is a diagonal automorphism (\Cref{def:automorphisms}) of $\Omega^+(2d,3)$.
\end{enumerate}
\end{observation}


