\section{Constructions}\label{sec:exist}
%-----------------------------------------------------------------

Throughout this section, we use the identities for parameters $\lrc$, $\lrr$, $\lcc$ from Lemma~\ref{lm:avg} without referring to them explicitly.

%-----------------------------------------------------------------
\subsection{Constructions with at most one common symbol between two columns}\label{ssec:ex_lcc}
%-----------------------------------------------------------------

We start with a lemma relating large $v$ to small $\lrc$ and $\lcc$.

\begin{lemma}\label{lm:smalllambda}
    Let $e, \lrc, \lrr, \lcc$ be the parameters of an $(r \times c, v)$-near triple array.
    Then the following are equivalent:
\begin{enumerate}[(a)]
    \item\label{sml:param} $e \leq 2$, $\lrc \leq 2$ and $\lcc \leq 1$;
    \item\label{sml:v} $v \geq rc - c \cdot \min(r, c - 1) / 2$.
\end{enumerate}
\end{lemma}

\begin{proof}
If $c > r$, then \ref{sml:v} turns into $v \geq rc / 2$, which is equivalent to $e\leq 2$.
This in turn implies the other inequalities of \ref{sml:param}: if $e \leq 2$, then $\lrc \leq 2$ and $\lcc = r(\lrc - 1) / (c - 1) \leq r / (c - 1) \leq 1$.

If $c \leq r$, then $\lcc = r(\lrc - 1) / (c - 1) \leq 1$ implies $\lrc \leq 1 + (c - 1) / r < 2$ and thus also $e < 2$.
Both items of the lemma hold trivially when $e = 1$, so we may assume $e^- = 1$ and $e^+ = 2$.
Then
\[
\lrc = e^- + e^+ - \frac{e^-e^+}{e} = 3 - \frac{2v}{rc}, \text{ so } \lcc = \frac{r(\lrc - 1)}{c - 1} = \frac{r}{c - 1} \left( 2 - \frac{2v}{rc} \right) =  \frac{2(rc - v)}{c(c - 1)}.
\]
Then $\lcc \leq 1$ is equivalent to $v \geq rc - c(c - 1) / 2$, i.e. to \ref{sml:v}.
\end{proof}

Given a near triple array satisfying the conditions of Lemma~\ref{lm:smalllambda}, we can construct new near triple arrays from it by either replacing some of the repeating symbols with new ones, or by adding a new column.

\begin{lemma}\label{lm:incv}
Let $T$ be an $(r \times c, v)$-near triple array with $v \geq rc - c \cdot \min(r, c - 1) / 2$.
For each $0 < i \leq rc - v$, there exists an $(r \times c, v + i)$-near triple array.
\end{lemma}
\begin{proof}
Let $e, \lrc, \lrr, \lcc$ be the parameters of $T$.
By Lemma~\ref{lm:smalllambda}, we have $e, \lrc \leq 2$ and $\lcc \leq 1$.
Choose two rows of $T$ that have $\lrr^+$ symbols in common, and let $a$ be one of their common symbols.
Since $e \leq 2$, $a$ doesn't appear in other rows of $T$.
Let $T'$ be an $r \times c$ array on $v + 1$ symbols obtained from $T$ by replacing one of the occurrences of $a$ with a new unique symbol.
Applying Proposition~\ref{prop:altdefNTA} with $x, x_{rc} = 1$, $x_{rr} = \lrr^+ - 1$ and $x_{cc} = 0$, we see that $T'$ is an $(r \times c, v + 1)$-near triple array.
Repeating this operation $i$ times, we get an $(r \times c, v + i)$-near triple array.
\end{proof}

\begin{lemma}\label{lm:addclm}
Let $T$ be an $(r \times c, v)$-near triple array with $v \geq rc - c \cdot \min(r, c - 1) / 2$.
Let $T'$ be an $r \times (c + 1)$ array on $v + r$ symbols obtained from $T$ by adding a new column with $r$ new symbols in it.
Then $T'$ is an $(r \times (c + 1), v + r)$-near triple array.
\end{lemma}
\begin{proof}
Let $e, \lrc, \lrr, \lcc$ be the parameters of $T$.
Due to Lemma~\ref{lm:smalllambda}, we have $e, \lrc \leq 2$ and $\lcc \leq 1$.
Applying Proposition~\ref{prop:altdefNTA} with $x, x_{rc} = 1$, $x_{rr} = \lrr^-$ and $x_{cc} = 0$, we see that $T'$ is a $(r \times (c + 1), v + r)$-near triple array.
\end{proof}

In the tables of Appendix~\ref{ap:nta_tables}, columns share more and more values at the bottom, the further to the right one looks.
For example, the last 8 numbers in the columns corresponding to $3 \times 14$ and $3 \times 15$ near triple arrays in Table~\ref{tbl:nta3} coincide.
In the next corollary we provide an explanation for this phenomenon.

\begin{corollary}
Let $\mathcal{N}(r \times c, v)$ be the number of isotopism classes of $(r \times c, v)$-near triple arrays.
\begin{enumerate}[(a)]
\item\label{tail:ineq} If $v \geq rc - c \cdot \min(r, c - 1) / 2$, then $\mathcal{N}(r \times c, v) \leq \mathcal{N}(r \times (c + 1), v + r)$.
\item\label{tail:eq} If $v \geq rc - c / 2$, then $\mathcal{N}(r \times c, v) = \mathcal{N}(r \times (c + 1), v + r)$.
\end{enumerate}
\end{corollary}

\begin{proof}
The operation of adding a column from Lemma~\ref{lm:addclm} preserves isotopism classes, so \ref{tail:ineq} holds.

If $v \geq rc - c / 2$, then any $(r \times (c + 1), v + r)$-near triple array $T'$ has at most
\[
    2 \cdot ( r(c + 1) - (v + r) ) \leq c < c + 1
\]
cells filled with symbols appearing more than once in the array, so, by the pigeonhole principle, $T'$ contains a column filled with unique symbols.
By deleting this column, we get an $(r \times c, v)$-near triple array, and since this operation also preserves isotopism classes, \ref{tail:eq} follows.
\end{proof}

For $v \geq rc-c/2$, we can show existence of near triple arrays by
an explicit construction, given in the proof of the following lemma.
The basic idea is that there are so few repeated symbols that the only complication is to distribute them in such a way that row-row intersections are balanced.

\begin{lemma}\label{lm:ex_tail}
There exists an $(r \times c, v)$-near triple array whenever $v \geq rc - c / 2$.
\end{lemma}

\begin{proof}
An $(r \times c, v)$-near triple array $T$ must have $t := rc - v \leq c / 2$ symbols occurring two times, and all other symbols occurring just once.
Let
\[
\left\{ P_1, \dots, P_{\binom{r}{2}} \right\} = \binom{[r]}{2} = \{ (i, j)\ :\ 1 \leq i < j \leq r\};\quad P_i := P_{i - \binom{r}{2}} \text{ for } i > \binom{r}{2}.
\]
For $1 \leq i \leq t$ put symbol $i$ into the two cells $(j_1, 2i - 1)$ and 
$(j_2, 2i)$ of $T$, where $(j_1, j_2) = P_i$, and put the remaining unique symbols into the remaining cells in an arbitrary way.
The resulting array is clearly binary, so by Proposition~\ref{prop:altdefNTA} applied with $x, x_{rc} = 1$, $x_{rr} = \left\lfloor\frac{2t}{r(r - 1)}\right\rfloor$ and $x_{cc} = 0$, $T$ is a near triple array.
\end{proof}

Another type of construction of near triple arrays is juxtaposing
two near triple arrays with suitable parameters, as in the following lemma.

\begin{lemma}\label{lm:concat}
    Let $T_1$ and $T_2$ be an $(r \times c_1, v_1)$ and an $(r \times c_2, v_2)$-near triple arrays on disjoint sets of symbols with parameters $e_1, \lrr^1, \lcc^1, \lrc^1$ and $e_2, \lrr^2, \lcc^2, \lrc^2$, respectively.
    Let
    \begin{enumerate}
        \item $\max(e_1^+, e_2^+) - \min(e_1^-, e_2^-) \leq 1$,
        \item $\lrr^1 \in \Z$ or $\lrr^2 \in \Z$,
        \item $\lcc^1, \lcc^2 \leq 1$,
    \end{enumerate}
    and let $T$ be a concatenation of $T_1$ and $T_2$ (each row of $T$ is a concatenation of two corresponding rows of $T_1$ and $T_2$).
    Then $T$ is an $(r \times (c_1 + c_2), v_1 + v_2)$-near triple array.
\end{lemma}
\begin{proof}
Without loss of generality, we may assume that $\lrr^1 \in \Z$.
Each symbol appears in $T$ either $\min(e_1^-, e_2^-)$ or $\max(e_1^+, e_2^+)$ times, and, due to Lemma~\ref{lm:avg}~\ref{avg:lrc+-}, any row and column of $T$ have $\min(e_1^-, e_2^-)$ or $\max(e_1^+, e_2^+)$ symbols in common.
Each pair of rows of $T$ has $\lrr^1 + (\lrr^2)^-$ or $\lrr^1 + (\lrr^2)^+$ symbols in common, and each pair of columns of $T$ has $0$ or $1$ symbols in common.
Then, by Proposition~\ref{prop:altdefNTA}, $T$ is an $(r \times (c_1 + c_2), v_1 + v_2)$-near triple array.
\end{proof}

%-----------------------------------------------------------------
\subsection{Connections with (near) Youden rectangles and Latin squares}\label{ssec:ex_nyr_latin}
%-----------------------------------------------------------------

In all cases we considered for enumeration (see tables in Appendix~\ref{ap:nta_tables}), we were always able to find examples of $(r \times n, n)$ and $(r \times (n - 1), n)$-near triple arrays with $r \leq n$.
This is not true in general: $(r \times n, n)$-near triple arrays are $r \times n$ (near) Youden rectangles, and it follows from results by Brown~\cite{brown} that there are no $6 \times 17$ near Youden rectangles.
Nevertheless, in the next lemma we prove that the existence of $(r \times n, n)$-near triple arrays implies the existence of $(r \times (n - 1), n)$-near triple arrays.
As can be seen in Table~\ref{tbl:nonta}, there are no $(r \times (n - 2), n)$-near triple arrays for quite a few values of $n$ and $r$, so there is no hope of extending this construction one step further.

\begin{lemma}\label{lm:from_Youden}
    For $r \leq n$, let $T$ be an $(r \times n, n)$-near triple array, that is, a (near) Youden rectangle, and let $T'$ be a row-column design obtained from $T$ by deleting any column.
    Then $T'$ is an $(r \times (n - 1), n)$-near triple array.
\end{lemma}
\begin{proof}
Every symbol appears in $T'$ either $r$ or $r - 1$ times.
Each row of $T'$ contains all symbols except one, so it has either $r - 1$ or $r$ common symbols with any remaining column.
Moreover, since the deleted column contained $r$ different symbols, the missing symbol is different for each row, thus any pair of rows has $n - 2$ symbols in common.
The number of common symbols between any pair of columns of $T'$ is one of two consecutive integers because this holds in $T$.
By Proposition~\ref{prop:altdefNTA}, $T'$ is an $(r \times (n - 1), n)$-near triple array.
\end{proof}

It is well known that removing a single row from an $n \times n$ Latin square will produce an $(n - 1) \times n$ Youden rectangle.
We will now show that starting from a suitably chosen Latin square, it is always possible to remove two rows to get an $(n - 2) \times n$ near Youden rectangle.
Combining this with Lemma~\ref{lm:from_Youden}, we get a few more explicit constructions of near triple arrays.

\begin{lemma}\label{lm:from_latin}
    For any $n \geq 4$ and $k \leq 2$ there exist $((n - k) \times n, n)$ and $((n - k) \times (n - 1), n)$-near triple arrays.
\end{lemma}

\begin{proof}
Let $T = T_0$ be the Latin square corresponding to the addition table in $\Z_n$, and let $T_1$ and $T_2$ be the Latin rectangles obtained from $T$ by deleting the last row and the last two rows, respectively.
For $k = 0, 1, 2$, $T_k$ is an $((n - k) \times n, n)$-near triple array: it is clear for $k = 0, 1$, and for $k = 2$ it is true because the addition table in $\Z_n$ has no intercalates, so no two columns lost the same two symbols after the deletion, and consequently column intersection sizes are either $n-3$ or $n-4$.
The existence of $((n - k) \times (n - 1), n)$-near triple arrays follows from Lemma~\ref{lm:from_Youden}.
\end{proof}

Note that a $2\times n$ array on $n$ symbols without intercalates is in fact a near triple array. 
Therefore, a wider perspective on Lemma~\ref{lm:from_latin} is that starting with a suitable Latin square, and removing a set of rows forming a $(k \times n, n)$-near triple array, the remaining array (the complement) is an $((n-k) \times n, n)$-near triple array. We formulate this as a lemma.

\begin{lemma}\label{lm:complement}
    Suppose there exists a $(k \times n, n)$-near triple array. Then there exists an $((n - k) \times n, n)$-near triple array and an $((n - k) \times (n-1), n)$-near triple array.
\end{lemma}

\begin{proof}
    Let $T$ be a $(k \times n, n)$-near triple array. Viewing it as a Latin rectangle, it is well-known that $T$ may be completed to a Latin square $L$. We claim that the complement $T'$ of $T$ in $L$, that is, $L$ with the rows from $T$ removed, is an $((n - k) \times n, n)$-near triple array.

    The only near triple array property of $T'$ that is not immediate is the column intersection property.
    Suppose that columns $j_1$ and $j_2$ of $T$ share $a$ common symbols, then they contain in total $2k - a$ different symbols.
    The columns $j_1$ and $j_2$ of $T'$ then share precisely $n - 2k + a$ symbols which do not appear in columns $j_1$ and $j_2$ of $T$.
    Since column intersection sizes in $T$ take at most two values, the same holds for $T'$, so $T'$ is a near triple array.
    The existence of an $((n - k) \times (n-1), n)$-near triple array then follows from Lemma~\ref{lm:from_Youden}.
\end{proof}

