It should be mentioned though that for all but 418 of the latter 19689 parameter sets, both sides of~\eqref{eq:dual_bd} are equal to zero, that is, both $\lcc \leq 1$ and $\mu_c \leq 1$ hold.

In the following corollary, we present a collection of examples of families of parameter sets where Theorem~\ref{thm:dual_bd} implies non-existence of near triple arrays.
This collection of examples is by no means exhaustive.

\begin{corollary}\label{cor:nonta_bd}
There are no near triple arrays for the following parameter sets:
\begin{enumerate}[(a)]
    \item\label{nonta_bd_2k-1} $((2k - 1) \times (4k - 3), 4k - 1)$ for $k \geq 3$,
    \item\label{nonta_bd_2k} $(2k \times (4k - 3), 4k - 1)$ for $k \geq 3$,
    \item\label{nonta_bd_s} $(k \times (\binom{k}{2} - s), \binom{k}{2} + 1)$ for positive integers $k, s$ with $1 \leq s \leq \frac{(k - 1)(k - 2)}{2k}$.
\end{enumerate}
\end{corollary}
\begin{proof}[Proof sketch]
In each case we use Lemma~\ref{lm:avg} to calculate the parameters, and then apply Theorem~\ref{thm:dual_bd}.
Since the calculations are rather tedious, we omit the details and for each identity show only the end result.
All identities were obtained via symbolic computation in SageMath~\cite{sagemath}.
\begin{enumerate}[(a)]
\item We calculate $e = 2k - 2 + \frac{1}{4k - 1}$, thus $e^- = 2k - 2$, $e^+ = 2k - 1$ and $\lrc = 2k - 2 + \frac{1}{4k - 3}$.
Then $\lcc = k - 1 - \frac{1}{2(4k - 3)}$, so $\lcc^- = k - 2$, $\lcc^+ = k - 1$.
Also, $\mu_c = k - 2 + \frac{2k + 1}{4k - 1}$, so $\mu_c^- = k - 2$, $\mu_c^+ = k - 1$.
Finally, $S( \binom{c}{2}, \lcc ) - S( \binom{v}{2}, \mu_c ) = -\binom{k - 1}{2} < 0$.
\item We calculate $e = 2k - 1 - \frac{1}{4k - 1}$, thus $e^- = 2k - 2$, $e^+ = 2k - 1$ and $\lrc = 2k - 1 - \frac{k - 1}{(4k - 3)k}$.
Then $\lcc = k - \frac{1}{2(4k - 3)}$, so $\lcc^- = k - 1$, $\lcc^+ = k$.
Also, $\mu_c = k - 1 + \frac{2k + 1}{4k - 1}$, so $\mu_c^- = k - 1$, $\mu_c^+ = k$.
Finally, $S( \binom{c}{2}, \lcc ) - S( \binom{v}{2}, \mu_c ) = -\binom{k - 1}{2} < 0$.
\item We calculate $e = k - \frac{2k(s + 1)}{k^2 - k + 2} \geq k - 1$, with equality precisely when $s = \frac{(k - 1)(k - 2)}{2k}$.
If the equality holds, then $e = \lrc = k - 1$, and otherwise $e^- = k - 1$, $e^+ = k$ and $\lrc = k - \frac{2(k - 1)(s + 1)}{k^2 - k - 2s}$.
In both cases, $\lcc = 2 - \frac{8s(s + 1)}{(k^2 - 2k - 2s)(k^2 - 2k - 2s - 2)}$.
Also, $\mu_c = 2 - \frac{4(s + 1)}{k^2 - k + 2}$.
These expressions for $\lcc$ and $\mu_c$ are monotone in $s$ and are equal to, respectively, $2 - \frac{2}{k^2 + 1} > 1$ and $2 - \frac{2}{k} > 1$, when $s = \frac{(k - 1)(k - 2)}{2k}$, thus $\lcc^- = 1$, $\lcc^+ = 2$, $\mu_c^- = 1$, $\mu_c^+ = 2$.
Finally, $S( \binom{c}{2}, \lcc ) - S( \binom{v}{2}, \mu_c ) = -\binom{s + 1}{2} < 0$.\qedhere
\end{enumerate}
\end{proof}

