\section{Full description of the completability checking procedure}\label{ap:compl}
%-----------------------------------------------------------------

Let $T$ be a partially filled array, and let $(i_0, j_0)$ be the empty cell of $T$ to be filled in the next step of the search.
Our goal is to either deduce that $T$ cannot be completed to an $(r \times c, v)$-near triple array, or, otherwise, to find a set of symbols which may be put into the cell $(i_0, j_0)$ without directly violating any of the near triple array conditions.

Denote the set of all symbols by $V := \{0, 1, \dots, v - 1\}$.
For $i \geq 0$, let $V_i$ be the set of symbols used $i$ times in $T$.
Let $V_{may}$ be the set of symbols which may be used to fill empty cells of $T$: more precisely, $V_{may} = \bigcup_{i = 0}^{e - 1} V_i$ in the equireplicate case.
In the near-equireplicate case, using notation from Lemma~\ref{lm:k-k+}, if $|V_{e^+}| < v_+$, then $V_{may} = \bigcup_{i = 0}^{e^-} V_i$, otherwise, $V_{may} = \bigcup_{i = 0}^{e^- - 1}V_i$.

Let $v_{max}$ be the maximum symbol used so far in $T$, that is, $v_{max} \geq w$ for any symbol $w$ used in $T$, and set $V_{next} := V_{may} \cap \{0, \dots, v_{max} + 1\}$.
In order for the array obtained from $T$ by filling the cell $(i_0, j_0)$ to be canonical, the symbol put into the cell $(i_0, j_0)$ clearly has to come from $V_{next}$.

Denote by $R_i$ and $C_j$ the sets of symbols used so far in row $i$ and column $j$ of $T$, respectively.
At the start of the completability checking procedure, we define a collection of auxiliary sets as follows. For $1 \leq i \leq r$, we define 
\[
A_{R_i} := R_i,\quad B_{R_i} := \begin{cases}
R_i \cup V_{may} &\text{if row } i \text{ of } T \text{ has empty cells,}\\
R_i &\text{otherwise.}
\end{cases}
\]
Similarly, for $1 \leq j \leq c$ we define
\[
A_{C_j} := C_j,\quad B_{C_j} := \begin{cases}
C_j \cup V_{may} &\text{if column } j \text{ of } T \text{ has empty cells,}\\
C_j &\text{otherwise.}
\end{cases}
\]
Finally, for $1 \leq i \leq r$ and $1 \leq j \leq c$ we define
\[
B_{i, j} := \begin{cases}
V_{next} \setminus R_i \setminus C_j &\text{if } (i, j) = (i_0, j_0),\\
V_{may} \setminus R_i \setminus C_j &\text{if cell } (i, j) \text{ of } T \text{ is empty, but } (i, j) \neq (i_0, j_0),\\
\{T_{i, j}\} &\text{if cell } (i, j) \text{ of } T \text{ is not empty}.
\end{cases}
\]

The sets $A_{R_i}, B_{R_i}, A_{C_j}, B_{C_j}, B_{i, j}$ are the \textit{estimate sets}.
Throughout the completability checking procedure, the estimate sets may be changed, but the point of them is that we maintain the following properties throughout: if $T'$ is a near triple array completed from $T$, $R'_i$ and $C'_j$ are contents of row $i$ and column $j$ of $T'$, then
\begin{equation}\label{eq:estprop}
A_{R_i} \subseteq R'_i \subseteq B_{R_i},\quad A_{C_j} \subseteq C'_j \subseteq B_{C_j},\quad T'_{i, j} \in B_{i, j}.    
\end{equation}

In other words, $A_{R_i}$ is a set of symbols that will all appear in row $R_i$ of any completion $T'$ of $T$, and conversely, $B_{R_i}$ is a set of symbols that we cannot yet rule out as possible candidates for use in row $R_i$ of some completion $T'$ of $T$. The sets $A_{C_j}$ and $B_{C_j}$ are the analogues for columns. Finally, the set $B_{i,j}$ is a set of symbols that cannot yet be ruled out as possible candidates for use in cell $(i,j)$ in some completion $T'$ of $T$.

As long as at least one of the rules listed below can be used to either deduce the non-completability of $T$ or to update the contents of some of the estimate sets, one such rule is chosen and applied.
If the chosen rule implies that $T$ is non-completable, we stop the procedure and remove $T$ from further consideration in the search.
When none of the rules can be applied, we stop the procedure and return the estimate set $B_{i_0, j_0}$ corresponding to the empty cell $(i_0,j_0)$ of $T$ as the list of options to put into this cell in the next step of the search.


\begin{enumerate}
\item\textbf{Full content of row $i$/column $j$ determined by $A_{R_i}$/$A_{C_j}$}

\begin{enumerate}
\item If $|A_{R_i}| > c$ for some $1 \leq i \leq r$, then $T$ is non-completable.
If $|A_{R_i}| = c$, then~\eqref{eq:estprop} implies that $R'_i = A_{R_i}$ for any near triple array $T'$ completed from $T$, so we may update $B_{R_i}$ to be equal to $A_{R_i}$.
\item If $|A_{C_j}| > r$ for some $1 \leq j \leq c$, then $T$ is non-completable. 
If $|A_{C_j}| = r$, then, similarly to the previous case, we may update $B_{C_j}$ to be equal to $A_{C_j}$.
\end{enumerate}
\item\textbf{Full content of row $i$/column $j$ determined by $B_{R_i}$/$B_{C_j}$}

\begin{enumerate}
\item If $|B_{R_i}| < c$ for some $1 \leq i \leq r$, then $T$ is non-completable.
If $|B_{R_i}| = c$, then, due to~\eqref{eq:estprop}, we have $R'_i = B_{R_i}$ for any near triple array $T'$ completed from $T$.
Thus we may update $A_{R_i}$ to be equal to $B_{R_i}$.
\item If $|B_{C_j}| < r$ for some $1 \leq j \leq c$, then $T$ is non-completable.
If $|B_{C_j}| = r$, then, similarly to the previous case, we may update $A_{C_j}$ to be equal to $B_{C_j}$.
\end{enumerate}
\item\textbf{Sets $B_{R_i}$ and $B_{C_j}$ restrict set $B_{i, j}$}

For any empty cell $(i, j)$ of $T$, we may replace $B_{i, j}$ with $B_{i, j} \cap (B_{R_i} \setminus R_i) \cap (B_{C_j} \setminus C_j)$.
\item\textbf{Sets $B_{i,j}$ restrict sets $B_{R_i}$ and $B_{C_j}$}

For $1 \leq i \leq r$, we may replace $B_{R_i}$ with $B_{R_i} \cap \bigcup_{j = 1}^c B_{i, j}$.
For $1 \leq j \leq c$, we may replace $B_{C_j}$ with $B_{C_j} \cap \bigcup_{i = 1}^r B_{i, j}$.

\item\textbf{Row-column intersection and empty cells}

Let $(i, j)$ be an empty cell of $T$. 

\begin{enumerate}
\item
If $|R_i \cap C_j| + 1 > \lrc^+$, then $T$ is non-completable, since filling $(i,j)$ contributes $+1$ to the intersection between row $i$ and 
column $j$. 
If $|R_i \cap C_j| + 1 = \lrc^+$, then the symbol used in cell $(i, j)$ is the only further common symbol between row $i$ and column $j$ in any completion of $T$.
Then for any empty cell $(i, j') \neq (i, j)$ of $T$ we may replace $B_{i, j'}$ with $B_{i, j'} \setminus A_{C_j}$, and for any empty cell $(i', j) \neq (i, j)$ of $T$ we may replace $B_{i', j}$ with $B_{i', j} \setminus A_{R_i}$.

\item 
Setting
\[
l_{max} := |R_i \cap C_j| + (c - |R_i|) + (r - |C_j|) - 1,
\]
we also see that if $l_{max} < \lrc^-$, then $T$ is non-completable, since there is not enough room in the empty cells of row $R_i$ and $C_j$ to reach the required intersection size.
If $l_{max} = \lrc^-$, then each empty cell $(i, j') \neq (i, j)$ in any completion of $T$ must be filled with a symbol from $C_j$.
In other words, we may replace $B_{i, j'}$ with $B_{i, j'} \cap C_j$.
Similarly, for any empty cell $(i', j) \neq (i, j)$ of $T$ we may replace $B_{i', j}$ with $B_{i', j} \cap R_i$.
\end{enumerate}


\item\textbf{Lower bound on row-row intersection size}

Consider two rows $i$ and $j$ of $T$.
The sets
\[
X_{R_i} := (B_{R_i} \setminus A_{R_i}) \cap A_{R_j},\quad Y_{R_i} := (B_{R_i} \setminus A_{R_i} \setminus A_{R_j}) \cap B_{R_j},\quad Z_{R_i} := B_{R_i} \setminus A_{R_i} \setminus A_{R_j} \setminus B_{R_j}
\]
together with $A_{R_i}$ are pairwise disjoint and form a partition of $B_{R_i}$ as follows:
\begin{equation}\label{eq:BRipart}
B_{R_i} = A_{R_i} \sqcup X_{R_i} \sqcup Y_{R_i} \sqcup Z_{R_i}.
\end{equation}
Note that the sets $X_{R_i}$, $Y_{R_i}$, $Z_{R_i}$ depend on $A_{R_j}$ and $B_{R_j}$.
Similarly, the sets
\[
X_{R_j} := (B_{R_j} \setminus A_{R_j}) \cap A_{R_i},\quad Y_{R_j} := (B_{R_j} \setminus A_{R_j} \setminus A_{R_i}) \cap B_{R_i},\quad Z_{R_j} := B_{R_j} \setminus A_{R_j} \setminus A_{R_i} \setminus B_{R_i}
\]
together with $A_{R_j}$ are pairwise disjoint and form a partition of $B_{R_j}$:
\begin{equation}\label{eq:BRjpart}
B_{R_j} = A_{R_j} \sqcup X_{R_j} \sqcup Y_{R_j} \sqcup Z_{R_j}.    
\end{equation}
By symmetry $Y_{R_i} = Y_{R_j}$, so from now on we denote both these sets by $Y$.

Suppose $T$ is completable, and let $T'$ be a near triple array completed from $T$.
Let $R'_i$ and $R'_j$ be contents of rows $i$ and $j$ of $T'$.
Using conditions~\eqref{eq:estprop}, partitions~\eqref{eq:BRipart} and~\eqref{eq:BRjpart} give partitions of $R'_i$ and $R'_j$:
\[
R'_i = A_{R_i} \sqcup X'_i \sqcup Y'_i \sqcup Z'_i,\quad R'_j = A_{R_j} \sqcup X'_j \sqcup Y'_j \sqcup Z'_j,
\]
where
\begin{align*}
X'_i &:= R'_i \cap X_{R_i},&&Y'_i := R'_i \cap Y, &&Z'_i := R'_i \cap Z_{R_i},\\
X'_j &:= R'_j \cap X_{R_j},&&Y'_j := R'_j \cap Y, &&Z'_j := R'_j \cap Z_{R_j}.
\end{align*}
These partitions in turn give the following partition of the common intersection of $R'_i$ and $R'_j$:
\begin{equation}\label{eq:RRpart}
R'_i \cap R'_j = (A_{R_i} \cap A_{R_j}) \sqcup X'_i \sqcup X'_j \sqcup (Y'_i \cap Y'_j).    
\end{equation}
Moreover, since each row of $T'$ contains $c$ symbols,
\[
|X'_i \cup Y'_i| \geq f_i := \max(0, c - |A_{R_i}| - |Z_{R_i}|), \quad |X'_j \cup Y'_j| \geq f_j := \max(0, c - |A_{R_j}| - |Z_{R_j}|),
\]
so
\begin{equation}\label{eq:lmin}
|R'_i \cap R'_j| \geq l_{min} := |A_{R_i} \cap A_{R_j}| + \max(0, f_i + f_j - |Y|).
\end{equation}
The quantity $l_{min}$ does not depend on the choice of $T'$, and can be calculated using the estimate sets.
If $l_{min} > \lrr^+$, $T'$ cannot be a near triple array, so our assumption is wrong and $T$ is non-completable.
If $l_{min} = \lrr^+$, then the inequality~\eqref{eq:lmin} must be tight, in which case we can update the estimate sets as follows:
\begin{enumerate}[(a)]
\item If $|Y| > f_i + f_j$ or if $f_i, f_j = 0$, then we must have $|R'_i \cap R'_j| = |A_{R_i} \cap A_{R_j}|$, which together with~\eqref{eq:RRpart} implies
\[
R'_i \subseteq B_{R_i} \setminus X_{R_i},\quad R'_j \subseteq B_{R_j} \setminus X_{R_j}.
\]
Thus we may replace $B_{R_i}$ and $B_{R_j}$ with $B_{R_i} \setminus X_{R_i}$ and $B_{R_j} \setminus X_{R_j}$, respectively.
In all remaining cases we may assume that at least one of $f_i$, $f_j$ is positive and that
\begin{equation}\label{eq:ppff}
|Y| \leq f_i + f_j.
\end{equation}
\item If $f_i > 0$ and $f_j = 0$, then~\eqref{eq:ppff} turns into $|Y| \leq f_i$, and~\eqref{eq:lmin} is tight only when
\[
|R'_i \cap R'_j| = |A_{R_i} \cap A_{R_j}| + f_i - |Y|.
\]
Looking at~\eqref{eq:RRpart}, this is only possible when $X'_j, Y'_j = \emptyset$, $Y'_i = Y$ and $Z'_i = Z_{R_i}$, i.e.
\[
A_{R_i} \cup Y \cup Z_{R_i} \subseteq R'_i,\quad R'_j \subseteq B_{R_j} \setminus X_{R_j} \setminus Y,
\]
so we may replace $A_{R_i}$ and $B_{R_j}$ with $A_{R_i} \cup Y \cup Z_{R_i}$ and $B_{R_j} \setminus X_{R_j} \setminus Y$, respectively.
The case $f_i = 0$ and $f_j > 0$ is similar.
\item If $f_i, f_j > 0$, then~\eqref{eq:lmin} being tight means that
\[
|R'_i \cap R'_j| = |A_{R_i} \cap A_{R_j}| + f_i + f_j - |Y|.
\]
This is only possible when $Z'_i = Z_{R_i}$ and $Z'_j = Z_{R_j}$, i.e.
\[
A_{R_i} \cup Z_{R_i} \subseteq R'_i,\quad A_{R_j} \cup Z_{R_j} \subseteq R'_j,
\]
so we may replace the estimate sets $A_{R_i}$ and $A_{R_j}$ with $A_{R_i} \cup Z_{R_i}$ and $A_{R_j} \cup Z_{R_j}$, respectively.

Additionally, if in this case we have $|Y| = f_i + f_j$, then $|R'_i \cap R'_j| = |A_{R_i} \cap A_{R_j}|$, so $X'_i, X'_j = \emptyset$, that is
\[
R'_i \subseteq B_{R_i} \setminus X_{R_i},\quad R'_j \subseteq B_{R_j} \setminus X_{R_j},
\]
so we may also replace $B_{R_i}$ and $B_{R_j}$ with $B_{R_i} \setminus X_{R_i}$ and $B_{R_j} \setminus X_{R_j}$, respectively.
\end{enumerate}

\item\textbf{Upper bound on row-row intersection size}

We use the same notation as in the previous rule.
In particular, assuming that $T$ is completable to a near triple array $T'$ with $R'_i$ and $R'_j$ contents of rows $i$ and $j$ of $T'$, we again have a partition~\eqref{eq:RRpart} of the common intersection of $R'_i$ and $R'_j$.
Since each row of $T'$ contains $c$ symbols,
\[
|Y'_i \cup Z'_i| \geq s_i := \max(0, c - |A_{R_i}| - |X_{R_i}|), \quad |Y'_j \cup Z'_j| \geq s_j := \max(0, c - |A_{R_j}| - |X_{R_j}|),
\]
so
\begin{align}
\begin{split}\label{eq:lmax}
|R'_i \cap R'_j| \leq l_{max} :=&\ |A_{R_i} \cap A_{R_j}|\\
+& \min(c - |A_{R_i}|, |X_{R_i}|) + \min(c - |A_{R_j}|, |X_{R_j}|)\\
+& \min(|Y|, s_i, s_j).    
\end{split}
\end{align}
The quantity $l_{max}$ does not depend on the choice of $T'$ and can be calculated using the estimate sets.
If $l_{max} < \lrr^-$, then $T'$ cannot be a near triple array, so our assumption is wrong and $T$ is non-completable.
If $l_{max} = \lrr^-$, then the inequality~\eqref{eq:lmax} must be tight, in which case we can update the sets as follows:
\begin{enumerate}[(a)]
\item If $s_i, s_j = 0$, for~\eqref{eq:lmax} to be tight we must have $Y'_i, Z'_i, Y'_j, Z'_j = \emptyset$, so
\[
R'_i \subseteq B_{R_i} \setminus Y \setminus Z_{R_i},\quad R'_j \subseteq B_{R_j} \setminus Y \setminus Z_{R_j}.
\]
Then we can replace estimate sets $B_{R_i}$ and $B_{R_j}$ with $B_{R_i} \setminus Y \setminus Z_{R_i}$ and $B_{R_j} \setminus Y \setminus Z_{R_j}$, respectively.
In the remaining cases we may assume that at least one of $s_i$, $s_j$ is positive.
\item If $s_i, s_j \geq |Y|$, then~\eqref{eq:lmax} is tight only if $X'_i = X_{R_i}$, $X'_j = X_{R_j}$ and $Y'_i, Y'_j = Y$, so
\[
A_{R_i} \cup X_{R_i} \cup Y \subseteq R'_i,\quad A_{R_j} \cup X_{R_j} \cup Y \subseteq R'_j.
\]
Thus we can replace $A_{R_i}$ and $A_{R_j}$ with $A_{R_i} \cup X_{R_i} \cup Y$ and $A_{R_j} \cup X_{R_j} \cup Y$, respectively.
In the remaining cases we may assume that at least one of $s_i$, $s_j$ is less than $|Y|$.
\item If $s_i > s_j$, then~\eqref{eq:lmax} being tight implies that $X'_i = X_{R_i}$ and $Z'_j = \emptyset$, so
\[
A_{R_i} \cup X_{R_i} \subseteq R'_i,\quad R'_j \subseteq B_{R_j} \setminus Z_{R_j}.
\]
Thus we can replace estimate sets $A_{R_i}$ and $B_{R_j}$ with $A_{R_i} \cup X_{R_i}$ and $B_{R_j} \setminus Z_{R_j}$, respectively.
The case $s_j > s_i$ is similar.
\item Finally, if $s_i = s_j$, then
\[
|Y| > s_i = s_j > 0.
\]
In this case,~\eqref{eq:lmax} is tight only when $X'_i = X_{R_i}$, $X'_j = X_{R_j}$ and $Z'_i, Z'_j = \emptyset$, thus
\[
A_{R_i} \cup X_{R_i} \subseteq R'_i \subseteq B_{R_i} \setminus Z_{R_i},\quad A_{R_j} \cup X_{R_j} \subseteq R'_j \subseteq B_{R_j} \setminus Z_{R_j}.
\]
It means we can replace estimate sets $A_{R_i}$, $B_{R_i}$, $A_{R_j}$, $B_{R_j}$ with, respectively, $A_{R_i} \cup X_{R_i}$, $B_{R_i} \setminus Z_{R_i}$, $A_{R_j} \cup X_{R_j}$, $B_{R_j} \setminus Z_{R_j}$.
\end{enumerate}
\item\textbf{Lower and upper bounds on column-column and row-column intersection sizes}

By performing a similar analysis, we get rules analogous to the previous two for the intersection of two columns, and for the intersection of a row and a column.
\end{enumerate}

