\section{Measures of Similarity Between Linear Subspaces} \label{sec:subspace-similarity}

Consider two linear subspaces $\mathcal{X}$ and $\mathcal{Y}$ of $\mathbb{R}^n$ with their respective orthonormal bases given by the columns of matrices $X \in \mathbb{R}^{n \times p}$ and $Y \in \mathbb{R}^{n \times q}$. Consider the SVD of the matrix with inner products between the two sets of orthonormal bases, i.e., $X^\top Y = W_l \Sigma_{XY} W_r^\top$. Here, $W_l$ and $W_r$ are orthogonal matrices and $\Sigma_{XY}$ is a $p \times q$ diagonal matrix with singular values $\sigma^{XY}_1, \dots, \sigma^{XY}_s$ in decreasing order and $s = \min(p,q)$. The cosines of the principal angles between the subspaces are given by \cite{BjoG1973,ZhuK13},
\begin{equation} \label{eqn:relate-cosine-sing-val}
	\cos\boldsymbol{\Theta}(\mathcal{X},\mathcal{Y}) = \boldsymbol{\sigma}(X^\top Y) = [\sigma^{XY}_1, \dots, \sigma^{XY}_s],
\end{equation}
where $\boldsymbol{\Theta}(\mathcal{X},\mathcal{Y})$ denotes the vector of principal angles $\{\theta_k\}_{k=1}^{k=s}$ between $\mathcal{X}$ and $\mathcal{Y}$ arranged in increasing order, and $\boldsymbol{\sigma}(X^\top Y)$ denotes the vector of singular values of $X^\top Y$. We can use the $2$-norm of the vector of principal angles as a measure of similarity between two subspaces,  
\begin{equation} \label{eqn:distance-1}
	\mathcal{D}_1(\mathcal{X},\mathcal{Y}) := \| \boldsymbol{\Theta}(\mathcal{X},\mathcal{Y}) \|_2 = \| \arccos \boldsymbol{\sigma}(X^\top Y) \|_2,
\end{equation}
where $\mathcal{D}_1(\mathcal{X},\mathcal{Y})$ can be understood as a distance measure between the subspaces $\mathcal{X}$ and $\mathcal{Y}$.

To ease further discussions and assist the reader, we formally define what we mean by a metric, premetric, vector norm, and matrix norm. For more details, refer to the exposition in \cite{Rol87,HorJ85,SteS90}. 

\begin{definition}[Metric] \label{def:metric}
	Let $S$ be a set. A \emph{metric} on $S$ is a function $\rho$ of two arguments, defined on $S$, where $s_1, s_2, s_3 \in S$, which satisfies the following conditions:
	\begin{enumerate}
		\item $\rho(s_1,s_2) \ge 0$ (non-negativity),
		\item $\rho(s_1,s_2) = 0$ if and only if $s_1 = s_2$ (identity of indiscernibles),
		\item $\rho(s_1,s_2) = \rho(s_2,s_1)$ (symmetry),
		\item $\rho(s_1,s_2) \le \rho(s_1,s_3) + \rho(s_3,s_2)$ (triangle inequality).
	\end{enumerate}
\end{definition}

\begin{definition}[Premetric] \label{def:premetric}
	Let $S$ be a set. A \emph{premetric} on $S$ is a function $\rho$ of two arguments $s_1, s_2 \in S$, which satisfies the following conditions:
	\begin{enumerate}
		\item $\rho(s_1,s_2) \ge 0$ (non-negativity),
		\item $\rho(s_1,s_1) = 0$ for all $s_1 \in S$.
	\end{enumerate}
\end{definition}

\begin{definition}[Vector norm] \label{def:vector-norm}
	Let $V$ be a vector space over $\mathbb{R}$. A function $\| \cdot \|: V \rightarrow \mathbb{R}$ is a \emph{vector norm} if for all $v_1, v_2 \in V$, the following axioms are satisfied:
	\begin{enumerate}
		\item $\|v_1\| \ge 0$ (non-negative),
		\item $\|v_1\| = 0$ if and only if $v_1 = 0$ (positive),
		\item $\|c v_1\| = |c| \|v_1\|$ for all scalars $c \in \mathbb{R}$ (homogeneous),
		\item $\|v_1 + v_2\| \le \|v_1\| + \|v_2\|$ (triangle inequality).
	\end{enumerate}
\end{definition}

\begin{definition}[Matrix norm] \label{def:matrix-norm}
	Let $M$ be a space of matrices over $\mathbb{R}^{m \times n}$. A function $\| \cdot \|: M \rightarrow \mathbb{R}$ is a \emph{matrix norm} if for all $A, B \in M$ the following axioms are satisfied:
	\begin{enumerate}
		\item $\|A\| \ge 0$ (non-negative),
		\item $\|A\| = 0$ if and only if $A = 0$ (positive),
		\item $\|c A\| = |c| \|A\|$ for all scalars $c \in \mathbb{R}$ (homogeneous),
		\item $\|A + B\| \le \|A\| + \|B\|$ (triangle inequality),
		\item $\|A B\| \le \|A\| \|B\|$ (submultiplicative).
	\end{enumerate}
\end{definition}

\begin{prop} \label{prop:premetric-not-metric}
	If $\mathcal{X}$ and $\mathcal{Y}$ are linear subspaces with their respective orthonormal bases given by the columns of matrices $X \in \mathbb{R}^{n \times p}$ and $Y \in \mathbb{R}^{n \times q}$, then the distance measure $\mathcal{D}_1(\mathcal{X},\mathcal{Y})$ from \cref{eqn:distance-1} is a premetric for $p \ne q$, but in general not a metric.
\end{prop}

\begin{proof}
	Let us start by noting that we are concerned with the situation when $p \ne q$. As $\mathcal{D}_1(\cdot,\cdot)$ is computed by a vector norm, non-negativity is trivially ensured. Also, since the distance measure is defined using the principal angles between subspaces, the following holds:
	\begin{equation*}
		\mathcal{D}_1(\mathcal{X},\mathcal{Y}) = 0 \iff \mathcal{X} \subseteq \mathcal{Y} \text{ or } \mathcal{Y} \subseteq \mathcal{X}. 
	\end{equation*}
	This is a stronger statement that clearly includes the situation $\mathcal{X}=\mathcal{Y}$, which results in $\mathcal{D}_1(\mathcal{X},\mathcal{Y}) = 0$. Hence, the distance measure $\mathcal{D}_1(\cdot,\cdot)$ satisfies both the properties enlisted in \Cref{def:premetric}, and is a premetric for $p \ne q$. 

	Consider $\mathcal{X}_1, \mathcal{X}_2$ to be two distinct linear subspaces with respective orthonormal bases $X_1, X_2 \in \mathbb{R}^{n \times 1}$. Let $\mathcal{Y}_1$ be a linear subspace with bases $Y_1 \in \mathbb{R}^{n \times 2}$ such that $\mathcal{X}_1, \mathcal{X}_2 \subset \mathcal{Y}_1$. Assuming that the triangle inequality, property 4 in \Cref{def:metric}, is satisfied, we can write the following:
	\begin{equation*}
		\mathcal{D}_1(\mathcal{X}_1,\mathcal{X}_2) \le \mathcal{D}_1(\mathcal{X}_1,\mathcal{Y}_1) + \mathcal{D}_1(\mathcal{X}_2,\mathcal{Y}_1).
	\end{equation*} 
	Due to $\mathcal{X}_1, \mathcal{X}_2 \subset \mathcal{Y}_1$, we know that $\mathcal{D}_1(\mathcal{X}_1,\mathcal{Y}_1) = \mathcal{D}_1(\mathcal{X}_2,\mathcal{Y}_1) = 0$. Following the triangle inequality, this renders $\mathcal{D}_1(\mathcal{X}_1,\mathcal{X}_2) = 0$, which is a contradiction. This proves that $\mathcal{D}_1(\cdot,\cdot)$ does not satisfy the triangle inequality for $p \ne q$, and hence it is not a metric, but only a premetric as shown before.
\end{proof}

Note that for the example in the proof above, we considered linear subspaces of dimensions $1$ and $2$, resulting in distance evaluations between subspaces with $p=1$, $q=2$, as well as with $p=q=1$. Please refer \Cref{remark:geodesic-distance} for the scenario where all distance evaluations between linear subspaces are restricted to subspaces with $p=q$.

\begin{remark}[Geodesic distance]
	\label{remark:geodesic-distance}
	The distance measure $\mathcal{D}_1(\mathcal{X},\mathcal{Y})$ is a metric when $p=q$, and is commonly referred to as the geodesic distance~\cite{Wong1967} between linear subspaces in the Grassmannian Gr(p,n), i.e., the set of all $p$-dimensional linear subspaces in $\mathbb{R}^n$.
\end{remark}

Consider the Frobenius norm of $X^\top Y$ \cite{HorJ85,SteS90},
\begin{equation*}
	\| X^\top Y \|_F = \sqrt{\sum_{i=1}^{p}\sum_{j=1}^{q} |\mathbf{x}_i^\top \mathbf{y}_j|^2} = \sqrt{\tr((X^\top Y)^\top (X^\top Y))}.
\end{equation*}
Upon performing the SVD of $X^\top Y$, we obtain,
\begin{align*}
	\| X^\top Y \|_F &= \sqrt{\tr(W_l \Sigma_{XY} W_r^\top)^\top (W_l \Sigma_{XY} W_r^\top))}
	= \sqrt{\tr(W_r \Sigma_{XY}^\top \Sigma_{XY} W_r^\top)}	
	= \sqrt{\sum_{k=1}^{s} (\sigma^{XY}_k)^2}.
\end{align*}
Using \cref{eqn:relate-cosine-sing-val} it can be shown that $\| X^\top Y \|_F$ is related to the principal angles between the subspaces $\mathcal{X}$ and $\mathcal{Y}$,
\begin{equation} \label{eqn:frobenius-norm-angle-relation}
	\| X^\top Y \|_F = \sqrt{\sum_{k=1}^{s} (\cos \theta_k)^2}.
\end{equation}
Based on \cref{eqn:frobenius-norm-angle-relation} we are motivated to employ the following criterion to measure the similarity between subspaces,
\begin{equation} \label{eqn:distance-fro-norm}
	\tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y}) := \| X^\top Y \|_F.
\end{equation}
Here, we do not need to perform the SVD of $X^\top Y$, unlike in \cref{eqn:distance-1}. 

\begin{lemma} \label{lemma:1}
	If $\mathcal{X}$ and $\mathcal{Y}$ are linear subspaces with their respective orthonormal bases given by the columns of matrices $X \in \mathbb{R}^{n \times p}$ and $Y \in \mathbb{R}^{n \times q}$, then the similarity measure $\tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y})$ from \cref{eqn:distance-fro-norm} is related to the orthogonal projectors $P_\mathcal{X}$ and $P_\mathcal{Y}$ onto $\mathcal{X}$ and $\mathcal{Y}$ in the following way:
	\begin{equation} \label{eqn:lemma1-result}
		\tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y}) = \sqrt{\frac{1}{2} \big( p + q - \tr[(P_\mathcal{X} - P_\mathcal{Y})^2] \big)},
	\end{equation}
	where the orthogonal projectors are defined as $P_\mathcal{X} := X X^\top$ and $P_\mathcal{Y} := Y Y^\top$.
\end{lemma}

\begin{proof} Let us start by looking at the trace operation in the right hand side of \cref{eqn:lemma1-result},
	\begin{align*}
		\tr[(P_\mathcal{X} - P_\mathcal{Y})^2] &= \tr[(X X^\top - Y Y^\top)^2] 
		\\
		&= \tr(X X^\top + Y Y^\top - X X^\top Y Y^\top - Y Y^\top X X^\top)
		\\
		&= \tr(X X^\top) + \tr(Y Y^\top) - 2 \tr(X X^\top Y Y^\top)
		\\
		&= p + q - 2 \tr(Y^\top X X^\top Y)
		\\
		&= p + q - 2 \| X^\top Y \|_F^2
		\\
		&= p + q - 2 \tilde{\mathcal{D}}^2(\mathcal{X},\mathcal{Y}).
		\\
		\implies \tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y}) &= \sqrt{\frac{1}{2} \Big( p + q - \tr[(P_\mathcal{X} - P_\mathcal{Y})^2] \Big)}.
	\end{align*}
\end{proof}

Using $\tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y})$, we formulate an alternate distance measure $\mathcal{D}_2(\mathcal{X},\mathcal{Y})$:
\begin{equation} \label{eqn:distance-2}
	\mathcal{D}_2(\mathcal{X},\mathcal{Y}) := \sqrt{\max(p,q) - \tilde{\mathcal{D}}^2(\mathcal{X},\mathcal{Y})}.
\end{equation}

\begin{theorem}
	If $\mathcal{X}$ and $\mathcal{Y}$ are linear subspaces with their respective orthonormal bases given by the columns of matrices $X \in \mathbb{R}^{n \times p}$ and $Y \in \mathbb{R}^{n \times q}$, then the distance measure $\mathcal{D}_2(\mathcal{X},\mathcal{Y})$ from \cref{eqn:distance-2} is a metric for all $p, q \in \mathbb{N} \backslash \{0\}$.
\end{theorem}

\begin{proof}
	Let us systematically ensure all the properties of a metric. Consider a scenario when the subspaces are identical, i.e., $\mathcal{X} = \mathcal{Y}$. This means that $p=q$ and $\range(X) = \range(Y)$. Due to the orthonormalized bases, $\tilde{\mathcal{D}}(\mathcal{X},\mathcal{X})=\sqrt{p}=\sqrt{q}$, which means $\mathcal{D}_2(\mathcal{X},\mathcal{Y})=0$. Hence, this would ensure the identity of indiscernibles, if we can also prove that $\mathcal{D}_2(\mathcal{X},\mathcal{Y})=0$ holds only when the subspaces are identical. We defer this part for later. Next, it is easy to see that the distance measure is symmetric,
	\begin{equation*}
		\mathcal{D}_2(\mathcal{X},\mathcal{Y}) = \sqrt{\max(p,q) - \| X^\top Y \|^2_F} = \sqrt{\max(q,p) - \| Y^\top X \|^2_F} = \mathcal{D}_2(\mathcal{Y},\mathcal{X}).
	\end{equation*}
	Moreover, $\mathcal{D}_2$ is non-negative by construction, i.e., $\mathcal{D}_2(\mathcal{X},\mathcal{Y}) \ge 0$.

	By taking the square of the distance measure $\mathcal{D}_2(\mathcal{X},\mathcal{Y})$ in \cref{eqn:distance-2} we can write,
	\begin{equation*}
		\mathcal{D}_2^2(\mathcal{X},\mathcal{Y}) = \max(p,q) - \tilde{\mathcal{D}}^2(\mathcal{X},\mathcal{Y}).
	\end{equation*}
	Substituting the form of $\tilde{\mathcal{D}}(\mathcal{X},\mathcal{Y})$ shown in \cref{eqn:lemma1-result}, leads to
	\begin{align}
		\mathcal{D}_2^2(\mathcal{X},\mathcal{Y}) &= \max(p,q) - \frac{1}{2} \Big( p + q - \tr[(P_\mathcal{X} - P_\mathcal{Y})^2] \Big). \nonumber
		\\
		\implies 2 \mathcal{D}_2^2(\mathcal{X},\mathcal{Y}) &= | p - q | + \tr[(P_\mathcal{X} - P_\mathcal{Y})^2]. \label{eqn:new-distance-square}
	\end{align}
	It is clear from \cref{eqn:new-distance-square} that $\mathcal{D}_2(\mathcal{X},\mathcal{Y}) = 0$, only when $p = q$ and the projectors $P_\mathcal{X} = P_\mathcal{Y}$, which is only possible when $\mathcal{X} = \mathcal{Y}$. 
	So far, we have successfully shown that properties $1-3$ from \Cref{def:metric} hold.

	Let $\mathbf{v}_p, \mathbf{v}_q \in \mathbb{R}^n$ be such that the first $p$ and $q$ elements for $\mathbf{v}_p$ and $\mathbf{v}_q$ respectively are ones and all others are zeros. This allows us to write the following,
	\begin{equation*}
		\| \mathbf{v}_p - \mathbf{v}_q \|_1 = | p - q |.\,
	\end{equation*}
	where $\|\cdot\|_1$ is the vector $1$-norm. Using the triangle inequality, we can obtain
	\begin{equation} \label{eqn:part1-triangle-inequality}
		| p - q | \le | p - r | + | r - q |, \ \forall r \ge 0.
	\end{equation}

	The second term in the right hand side of \cref{eqn:new-distance-square} can be rewritten as below,
	\begin{align} 
		\tr[(P_\mathcal{X} - P_\mathcal{Y})^2] &= \tr[(X X^\top - Y Y^\top)^2] \nonumber
		\\
		&= \tr[(X X^\top - Y Y^\top) (X X^\top - Y Y^\top)] \nonumber
		\\
		&= \tr[(X X^\top - Y Y^\top)^\top (X X^\top - Y Y^\top)] \nonumber
		\\
		&= \|X X^\top - Y Y^\top\|_F. \nonumber
		\\
		\implies \tr[(P_\mathcal{X} - P_\mathcal{Y})^2] &= \| P_\mathcal{X} - P_\mathcal{Y} \|_F. \label{eqn:trace-to-frobenius}
	\end{align}
	Using the triangle inequality for matrix norm, we can write
	\begin{align}
		\| P_\mathcal{X} - P_\mathcal{Y} \|_F &= \|X X^\top - Y Y^\top\|_F \nonumber
		\\
		&= \|X X^\top - Z Z^\top + Z Z^\top - Y Y^\top\|_F \nonumber
		\\
		&\le \|X X^\top - Z Z^\top\|_F + \|Z Z^\top - Y Y^\top\|_F, \nonumber
		\\
		\implies \| P_\mathcal{X} - P_\mathcal{Y} \|_F &\le \|P_\mathcal{X} - P_\mathcal{Z}\|_F + \|P_\mathcal{Z} - P_\mathcal{Y}\|_F, \label{eqn:part2-triangle-inequality}
	\end{align}
	where the columns of matrix $Z \in \mathbb{R}^{n \times r}$ correspond to the orthonormal basis spanning a linear subspace $\mathcal{Z}$.

	Following \cref{eqn:new-distance-square,eqn:trace-to-frobenius}, the squared distance between the subspaces $\mathcal{X}, \mathcal{Y}, \mathcal{Z}$ can be written as,
	\begin{align}
		2 \mathcal{D}_2^2(\mathcal{X},\mathcal{Y}) &= | p - q | + \| P_\mathcal{X} - P_\mathcal{Y} \|_F, \label{eqn:dist-cap-1}
		\\
		2 \mathcal{D}_2^2(\mathcal{X},\mathcal{Z}) &= | p - r | + \| P_\mathcal{X} - P_\mathcal{Z} \|_F, \label{eqn:dist-cap-2}
		\\
		2 \mathcal{D}_2^2(\mathcal{Z},\mathcal{Y}) &= | r - q | + \| P_\mathcal{Z} - P_\mathcal{Y} \|_F. \label{eqn:dist-cap-3}
	\end{align}
	where $\mathcal{D}_2(\mathcal{X},\mathcal{Z})$ and $\mathcal{D}_2(\mathcal{Z},\mathcal{Y})$ give the distance between subspaces $\mathcal{X},\mathcal{Z}$ and $\mathcal{Z},\mathcal{Y}$ respectively. By adding \cref{eqn:part1-triangle-inequality,eqn:part2-triangle-inequality}, we obtain
	\begin{equation*} 
		| p - q | + \|P_\mathcal{X} - P_\mathcal{Y}\|_F \le | p - r | + \|P_\mathcal{X} - P_\mathcal{Z}\|_F + | r - q | + \|P_\mathcal{Z} - P_\mathcal{Y}\|_F.
	\end{equation*}
	Using \cref{eqn:dist-cap-1,eqn:dist-cap-2,eqn:dist-cap-3}, this takes the following form,
	\begin{align*} 
		2 \mathcal{D}_2^2(\mathcal{X},\mathcal{Y}) &\le 2 \mathcal{D}_2^2(\mathcal{X},\mathcal{Z}) + 2 \mathcal{D}_2^2(\mathcal{Z},\mathcal{Y}).
		\\
		\implies \mathcal{D}_2(\mathcal{X},\mathcal{Y}) &\le \sqrt{\mathcal{D}_2^2(\mathcal{X},\mathcal{Z}) + \mathcal{D}_2^2(\mathcal{Z},\mathcal{Y})}.
		\\
		\implies \mathcal{D}_2(\mathcal{X},\mathcal{Y}) &\le \mathcal{D}_2(\mathcal{X},\mathcal{Z}) + \mathcal{D}_2(\mathcal{Z},\mathcal{Y}).
	\end{align*}
	This shows that the newly proposed distance measure \cref{eqn:distance-2} satisfies the triangle inequality, i.e., property $4$ in \Cref{def:metric}. 
\end{proof}

The maximal distance value $\mathcal{D}_2(\mathcal{X},\mathcal{Y})$ can render is $\sqrt{\max(p,q)}$. This corresponds to a scenario when the subspaces $\mathcal{X}$ and $\mathcal{Y}$ are orthogonal to each other, resulting in $\tilde{D} = 0$. We normalize the distance measure by its maximal value and introduce the following:
\begin{equation} \label{eqn:distance-2-normalized}
	\hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y}) = \frac{\mathcal{D}_2(\mathcal{X},\mathcal{Y})}{\sqrt{\max(p,q)}} = \sqrt{1 - \frac{\tilde{\mathcal{D}}^2(\mathcal{X},\mathcal{Y})}{\max(p,q)}},
\end{equation}
where $0 \leq \hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y}) \leq 1$. Moreover, it is important to highlight that this form of distance computation is free from the requirement to perform an SVD of the matrix with inner products between the two sets of orthonormal bases corresponding to the subspace pair, unlike in $\mathcal{D}_1(\mathcal{X},\mathcal{Y})$. This ascertains computational efficiency when repeated distance evaluations need to be made between numerous subspace pairs, as is the situation with the new active learning framework presented in this work. 


\begin{remark}[Connection of $\hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y})$ with the chordal distance metric on the Grassmannian $Gr(p,n)$] 
	\label{remark:connection-with-geodesic-distance}
	When the linear subspaces $\mathcal{X}$ and $\mathcal{Y}$ have the same dimension, i.e., $p=q$, they lie on the Grassmannian $Gr(p,n)$. In this setting, recalling \cref{eqn:distance-fro-norm}, $\hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y})$ from \cref{eqn:distance-2-normalized} takes the following form:
	\begin{equation*}
		\hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y}) = \sqrt{1 - \frac{\| X^\top Y \|_F^2}{p}}. 
	\end{equation*}
	Using \cref{eqn:frobenius-norm-angle-relation}, we can write
	\begin{align}
		\hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y}) &= \sqrt{1 - \frac{\sum_{k=1}^{p} (\cos \theta_k)^2}{p}} = \frac{1}{\sqrt{p}} \sqrt{\sum_{k=1}^{p} \left( 1 - (\cos \theta_k)^2 \right)}, \nonumber
		\\
		\implies \hat{\mathcal{D}}_2(\mathcal{X},\mathcal{Y}) &= \frac{1}{\sqrt{p}} \sqrt{\sum_{k=1}^{p} (\sin \theta_k)^2} = \frac{1}{\sqrt{p}} \| \sin \boldsymbol{\Theta}(\mathcal{X},\mathcal{Y}) \|_2 = \frac{1}{\sqrt{p}} \mathcal{D}_{\mathcal{C}}(\mathcal{X},\mathcal{Y}), 
		\label{eqn:relation-with-chordal-metric}
	\end{align}
	where $\mathcal{D}_{\mathcal{C}}(\mathcal{X},\mathcal{Y}) := \| \sin \boldsymbol{\Theta}(\mathcal{X},\mathcal{Y}) \|_2$ is the chordal distance metric~\cite{ConHS1996,BarN02} on $Gr(p,n)$. We can see from \cref{eqn:relation-with-chordal-metric} that upon restricting the linear subspaces to have the same dimension, $\hat{\mathcal{D}}_2$ translates to the normalized chordal metric on $Gr(p,n)$.
\end{remark}



