\subsection{POD-NN ROM}

The POD-NN method outlined in this subsection is as presented in \cite{morWanHR19} for parametrized dynamical systems. The original variant of the method first appeared in \cite{morHesU18}, which is only applicable to parametrized steady-state systems. To make the method applicable for time-dependent problems, authors in \cite{morWanHR19} resort to a two-step POD procedure. A temporal compression of the snapshots is done by performing a parameter-specific POD, which is then followed by a compression in the parameter space by applying POD to the collection of parameter-specific POD bases. The final set of dominant POD modes is then used to represent the parametric FOM snapshots in the reduced coordinates. A regression model is constructed for the reduced coordinates using a feedforward neural network, which can be queried at out-of-training time and parameter values. The high-dimensional solution at the new time and parameter value is obtained by using the predicted reduced coordinates and the final set of dominant POD modes. 

Consider that a sampling of the parameter domain is available as a set of parameters $\hat{P} = \{\boldsymbol{\mu}_i\}_{i=1}^{m}$. The solution snapshots for these parameters can be obtained from a FOM solver and can be written in the following fashion, as in \cref{eqn:sol-snap}:
\begin{equation*}
	U(\boldsymbol{\mu}_i) = [ \ \mathbf{u}(t_0,\boldsymbol{\mu}_i) \ | \ \mathbf{u}(t_1,\boldsymbol{\mu}_i) \ | \ \dots \ | \ \mathbf{u}(t_{N_t},\boldsymbol{\mu}_i) \ ],
\end{equation*}
where $i = \{1, 2, \dots, m\}$. An SVD is carried out for each parameter-specific snapshot matrix, like done in \cref{eqn:svd},
\begin{equation*}
	U(\boldsymbol{\mu}_i) = L(\boldsymbol{\mu_i}) \Sigma(\boldsymbol{\mu_i}) K^\top(\boldsymbol{\mu_i}).
\end{equation*}

We form the matrix $\Phi(\boldsymbol{\mu}_i)$ of dominant POD modes, for each parameter $\boldsymbol{\mu}_i$, by collecting the truncated left singular vectors,
\begin{equation} \label{eqn:pod-nn-bases-1}
	\Phi(\boldsymbol{\mu}_i) = [ \ \mathbf{l}_1(\boldsymbol{\mu}_i) \ | \ \mathbf{l}_2(\boldsymbol{\mu}_i) \ | \ \dots \ | \ \mathbf{l}_{r_i}(\boldsymbol{\mu}_i) \ ].
\end{equation}
Here, the truncation level $r_i$ is the lowest value such that the user-defined energy criterion $\hat{\eta}$ is satisfied:
\begin{equation} \label{eqn:pod-nn-energy-criterion-1}
	\hat{\eta} = 1 - \frac{\sum_{k=1}^{k=r_i} (\sigma^{(i)}_k)^2}{\sum_{k=1}^{k=s_i} (\sigma^{(i)}_k)^2},
\end{equation}
where $s_i$ is the total number of nonzero singular values sitting on the main diagonal of $\Sigma(\boldsymbol{\mu}_i)$.

All the parameter-specific POD modes are collected and an additional SVD is carried out as
\begin{equation} \label{eqn:pod-nn-svd-2}
	[ \ \Phi(\boldsymbol{\mu}_1) \ | \ \Phi(\boldsymbol{\mu}_2) \ | \ \dots \ | \ \Phi(\boldsymbol{\mu}_m) \ ] = \tilde{L} \tilde{\Sigma} \tilde{K}^\top,
\end{equation}
where $\tilde{L} = [ \tilde{\mathbf{l}}_1 | \tilde{\mathbf{l}}_2 | \dots | \tilde{\mathbf{l}}_N ] \in \mathbb{R}^{N \times N}$, $\tilde{K} \in \mathbb{R}^{(\sum_{i=1}^{m} r_i) \times (N_t+1)}$ are orthogonal matrices with their columns as the left and right singular vectors, respectively. The non-zero singular values in \cref{eqn:pod-nn-svd-2} are denoted by $\tilde{\sigma}_k$, $k = 1, \dots, s_{global}$. The matrix $\mathbb{V}$ representing the reduced basis is formed by selecting the first $r_{global} \le s_{global}$ dominant POD modes,
\begin{equation} \label{eqn:pod-nn-bases-2}
	\mathbb{V} = [ \ \tilde{\mathbf{l}}_1 \ | \ \tilde{\mathbf{l}}_2 \ | \ \dots \ | \ \tilde{\mathbf{l}}_{r_{global}} \ ].
\end{equation}
Here, the level of truncation $r_{global}$ is taken as the lowest value such that a user-defined energy criterion $\hat{\eta}_{global}$ is met:
\begin{equation} \label{eqn:pod-nn-energy-criterion-2}
	\hat{\eta}_{global} = 1 - \frac{\sum_{k=1}^{k=r_{global}} (\tilde{\sigma}_k)^2}{\sum_{k=1}^{k=s_{global}} (\tilde{\sigma}_k)^2}.
\end{equation}

The solution snapshots corresponding to each $\boldsymbol{\mu}_i \in \hat{P}$ are projected onto the subspace spanned by the reduced bases, so that their reduced representation is obtained,
\begin{equation*}
	B(\boldsymbol{\mu}_i) = \mathbb{V}^\top U(\boldsymbol{\mu}_i) = [ \ \beta^0(\boldsymbol{\mu}_i) \ | \ \beta^1(\boldsymbol{\mu}_i) \ | \ \dots \ | \ \beta^{N_t}(\boldsymbol{\mu}_i) \ ], 
\end{equation*}
where $\beta^j \in \mathbb{R}^{r_{global}}$ is the reduced solution at time $t_j$. To obtain the reduced solution at any arbitrary time and parameter instance, a deep feed-forward neural network surrogate is trained using the data $\{\beta^j(\boldsymbol{\mu}_i)\}_{j=0}^{N_t}$ for all $\boldsymbol{\mu}_i \in \hat{P}$, providing an NN-approximation for the reduced solution. The deep neural network surrogate generates a map $\hat{\beta}$,
\begin{align*}
	\hat{\beta}: [0, T] \times \mathcal{P} \subset \mathbb{R}^{N_\mu+1} &\rightarrow \mathbb{R}^{r_{global}},
	\\
	(t, \boldsymbol{\mu}) &\rightarrow \mathbb{V}^\top \mathbf{u}(t,\boldsymbol{\mu}).
\end{align*}
The POD-NN approximate solution $u_s$ at a new time $t^*$ and parameter $\boldsymbol{\mu}^*$ instance is obtained by,
\begin{equation*}
	u_s(t^*, \boldsymbol{\mu}^*) = \mathbb{V} \hat{\beta}(t^*, \boldsymbol{\mu}^*).
\end{equation*}
We summarize the offline and online phase of POD-NN ROM in \Cref{alg:POD-NN-offline,alg:POD-NN-online}.

\begin{algorithm}[!h]
	\caption{\texttt{Offline phase of POD-NN ROM}} 
	\label{alg:POD-NN-offline}  
	\begin{algorithmic}[1]
		\REQUIRE{Parameter set $\hat{P}$, snapshots $U(\boldsymbol{\mu}_i) \ \forall \boldsymbol{\mu}_i \in \hat{P}$, energy criteria $\hat{\eta}$ and $\hat{\eta}_{global}$.}
		\ENSURE{Reduced basis $\mathbb{V}$, NN surrogate $\hat{\beta}$.}
		\STATE Perform parameter-specific SVDs: $L(\boldsymbol{\mu_i}) \Sigma(\boldsymbol{\mu_i}) K^\top(\boldsymbol{\mu_i}) = U(\boldsymbol{\mu}_i)$.
		\STATE Determine truncation orders $r_i \ \forall \boldsymbol{\mu}_i \in \hat{P}$ using $\hat{\eta}$ via \cref{eqn:pod-nn-energy-criterion-1}.
		\STATE Create parameter-specific bases sets $\Phi(\boldsymbol{\mu}_i)$ by following \cref{eqn:pod-nn-bases-1}.
		\STATE Perform SVD by following \cref{eqn:pod-nn-svd-2}: $\tilde{L} \tilde{\Sigma} \tilde{K}^\top = [ \ \Phi(\boldsymbol{\mu}_1) \ | \ \Phi(\boldsymbol{\mu}_2) \ | \ \dots \ | \ \Phi(\boldsymbol{\mu}_m) \ ]$.
		\STATE Determine truncation order $r_{global}$ using $\hat{\eta}_{global}$ via \cref{eqn:pod-nn-energy-criterion-2}.
		\STATE Obtain the matrix $\mathbb{V}$ of reduced basis from \cref{eqn:pod-nn-bases-2}.
		\STATE Extract the reduced representation of training snapshots: $B(\boldsymbol{\mu}_i) = \mathbb{V}^\top U(\boldsymbol{\mu}_i) \ \forall \boldsymbol{\mu}_i \in \hat{P}$.
		\STATE Train a NN to obtain a regression model $\hat{\beta}$.
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!h]
	\caption{\texttt{Online phase of POD-NN ROM}} 
	\label{alg:POD-NN-online}
	\begin{algorithmic}[1]
		\REQUIRE{New parameter $\boldsymbol{\mu}^*$, new time $t^*$, $\mathbb{V}$, NN surrogate $\hat{\beta}$.}
		\ENSURE{POD-NN solution at ($t^*$, $\boldsymbol{\mu}^*$).}
		\STATE Evaluate the output of the NN surrogate at input $(t^*, \boldsymbol{\mu}^*)$, i.e., $\hat{\beta}(t^*, \boldsymbol{\mu}^*)$.
		\STATE Compute the POD-NN solution: $u_s(t^*, \boldsymbol{\mu}^*) = \mathbb{V} \hat{\beta}(t^*, \boldsymbol{\mu}^*)$.
	\end{algorithmic}
\end{algorithm}


