\title{End-Edge Model Collaboration: Bandwidth Allocation for Data Upload and Model Transmission}


\author{
Dailin Yang\IEEEauthorrefmark{1},
Shuhang Zhang\IEEEauthorrefmark{2},
Hongliang Zhang\IEEEauthorrefmark{2}, and
Lingyang Song\IEEEauthorrefmark{2}\IEEEauthorrefmark{3}\IEEEauthorrefmark{4}
