\section{Relationship to WL hierarchy and GNNs}
\label{sec: relationship to wl and gnn}
Understanding the expressive power of Graph Neural Networks has become a central theme in graph learning research.
A key result in this area establishes that message-passing neural networks - a broad class of GNNs - are at most as expressive as the 1-dimensional Weisfeiler-Lehman (1-WL) graph isomorphism test~\cite{xu2018powerful, morris2019weisfeiler}. 
Recent work has extended this line of analysis to alternative architectures, including those based on relational pooling and spectral features, relating them to the broader Weisfeiler-Lehman hierarchy~\cite{zhou2023relational, zhang2024expressive}.

Within this landscape, exploring the relationship between our proposed $k$-Spectra (or equivalently, $k$-correlations) framework and the WL hierarchy offers a promising avenue for both theoretical insight and practical application. 
Understanding this connection can shed light on the representational capabilities of $k$-Spectra and suggests ways it may enhance the expressivity of graph learning models such as GNNs.

Theoretically, $k$-WL and $k$-correlation spectra capture distinct structural properties: while $k$-WL iteratively refines node representations based on patterns over $k$-tuples of node neighborhoods, $k$-correlations count edge-level substructures (see Intuition in the previous section). 
This distinction positions $k$-Spectra as a complementary framework for evaluating and augmenting expressivity in graph representations.

As an illustrative example, \citet[Corollary 3.14]{gaihomomorphism} show that spectral-invariant GNNs can count paths and cycles of up to 7 vertices.
In contrast, non-reduced $k$-Spectra - with sufficiently large $k$ - can capture longer paths and larger cycles, suggesting a path for practical advantage. 

\begin{algorithm}[t]
   \caption{Doubly-Reduced k-Spectrum}
   \label{alg:main kspect}
\begin{algorithmic}
    \STATE {\bfseries Input:} Functions $f_i:\mathbb{S}_n/\mathbb{S}_{n-2} \rightarrow \mathbb{C}$, for $i \in [d]$

    \STATE Precompute $s^{(k)}$

    \FOR{$\rho \in \{(n), (n-1, 1), (n-2, 2), (n-2, 1, 1)\}$}
        \FOR{$i \in [d]$}
            \STATE Compute $\hat{f}_{i_k}(\rho)$
        \ENDFOR
        \FOR{$G_{k-2} \in \mathrm{comb}( \mathbb{S}_{n-2} \backslash \mathbb{S}_n / \mathbb{S}_{n-2}, k-2)$}
            \FOR{$I_{k-1} \in [d]^{k-1}$}
                \STATE Compute $\hat{s}^{(k)}_{I_{k-1}}(G_{k-2}, \rho)$
            \ENDFOR
            \STATE $\hat{\mathcal{S}}^{(k)}_{f}(G_{k-2}, \rho) = \bigoplus_{I_k \in [d]^k} \hat{s}^{(k)}_{I_{k-1}}(G_{k-2}, \rho)^\dagger\hat{f}_{i_k}(\rho)$
        \ENDFOR
    \ENDFOR
    \STATE Output $\hat{\mathcal{S}}^{(k)}_f$
\end{algorithmic}
\end{algorithm}

To empirically examine the relationship with WL tests, in Section~\ref{sec: exp higher correlations} we demonstrate that features derived from the doubly-reduced $k$-Spectra are neither strictly less expressive nor strictly more expressive than those derived from 1-WL. 
This supports the intuition that $k$-Spectra offer orthogonal structural insights not captured by WL-based approaches.

Beyond theoretical comparisons with WL tests, we highlight three potential integration approaches into GNN pipelines:
\begin{itemize}
\item \textbf{Post concatenation:} Precompute a $k$-Spectra whole-graph embedding and concatenate it with the output of the GNN embedding, just before the prediction layers.
\item \textbf{k-Spectra aggregation:} Incorporate $k$-Spectra subgraph invariants during the node aggregation step.
\item \textbf{k-Spectra pooling:} Replace standard pooling functions (e.g., summation, max) with $k$-Spectra-based invariants to aggregate node features.
\end{itemize}
Each of these strategies supports the incorporation of learnable parameters, such as orbit-specific weights in the individual terms of Eq.~\ref{eq: Multi-Orbit k-spectrum}, allowing the model to adaptively emphasize the most relevant graph information. We see these directions as promising opportunities for future work at the intersection of spectral methods and GNN design.

\begin{algorithm}[!t]
   \caption{Precomputing $s^{(k)}$}
   \label{alg: precomputation}
\begin{algorithmic}
    \STATE {\bfseries Input:} Functions $f_i:\mathbb{S}_n/\mathbb{S}_{n-2} \rightarrow \mathbb{C}$, for $i \in [d]$

    \FOR{$i \in [d]$}
        \FOR{$j \in [n-2]$}
            \STATE $F_i(j) = \sum_{l \in [n] \setminus \{j\}} f_i((n-1, j, n, l))$
            \FOR{$\sigma \in \mathbb{S}_n/\mathbb{S}_{n-2}$}
                \STATE $P_i(g_1, \sigma, j) = f_i(\sigma)$
                \STATE $P_i(g_2, \sigma, j) = f_i(\sigma\cdot(n-1, n))$
                \STATE $P_i(g_3, \sigma, j) = f_i(\sigma \cdot (n-1, j))$
                \STATE $P_i(g_4, \sigma, j) = f_i(\sigma\cdot(n, j))$
                \STATE $P_i(g_5, \sigma, j) = f_i(\sigma\cdot(j, n-1, n))$
                \STATE $P_i(g_6, \sigma, j) = f_i(\sigma \cdot (j, n, n-1))$
                \STATE $P_i(g_7, \sigma, j) = \dfrac{F_i(\sigma(j)) - \sum_{l \in \{3,6\}}P_i(g_l, \sigma, j)}{n-3}$
            \ENDFOR    
        \ENDFOR
    \ENDFOR
    \FOR{$I_{k-2} \in [d]^{k-2}$}
        \FOR{$G_{k-2} \in \mathrm{comb}( \mathbb{S}_{n-2} \backslash \mathbb{S}_n / \mathbb{S}_{n-2}, k-2)$}
            \FOR{$\sigma \in \mathbb{S}_n/\mathbb{S}_{n-2}$}
                \STATE $Q_{I_{k-2}}(G_{k-2}, \sigma) = \sum_{j = 1}^{n-2} \prod_{l=1}^{k-2} P_{i_l}(g_l, \sigma, j)$
                \FOR{$i \in [d]$}
                    \STATE $I_{k-1} = \mathrm{append}(I_{k-2}, i)$
                    \STATE $s^{(k)}_{I_{k-1}}(G_{k-2}, \sigma) = \frac{f_{i_{k-1}}(\sigma)}{n-2}Q_{I_{k-2}}(G_{k-2}, \sigma)$
                \ENDFOR
            \ENDFOR
        \ENDFOR
    \ENDFOR  
    \STATE Output $s^{(k)}$
\end{algorithmic}
\end{algorithm}

\section{Computation and complexity}
\label{sec: computation and complexity}
We proceed to detail the computation of the Doubly-Reduced $k$-Spectrum (\ref{eq: reduced k-spectrum}), which is the generalization of the Skew Spectrum with the lowest computational complexity. 

The main idea is summarized in Algorithm~\ref{alg:main kspect}. 
We can treat $\hat{s}^{(k)}$ as the Fourier transform of a function $s^{(k)} \in \mathbb{S}_n/\mathbb{S}_{n-2}$. 
\begin{align}
    s^{(k)}_{I_{k-1}}(G_{k-2}, \sigma) = \frac{f_{i_{k-1}}(\sigma)}{|\mathbb{S}_{n-2}|} \sum_{h \in \mathbb{S}_{n-2}} \prod_{l=1}^{k-2} f_{i_l}(\sigma h g_l)
\end{align}
After precomputing $s^{(k)}$, we can compute its transform and that of one single orbit function, for all the input. 
Then, multiplying them produces one entry of the Spectrum. 

Precomputing $s^{(k)}$ efficiently requires some creativity.
Algorithm~\ref{alg: precomputation} does so, using a divide-and-conquer strategy, coupled with dynamic programming.
The procedure breaks the computation of $s^{(k)}$ into the computation of partial sums that can be efficiently recombined when fixing the input parameters.
We summarize this intermediate result in the following Lemma, discussing its correctness in Appendix~\ref{apx: data structure}.
\begin{lemma}[Precomputing $s^{(k)}$]
\label{lemma: precomputing s}
    Algorithm~\ref{alg: precomputation} precomputes $s^{(k)}_{I_{k-1}}(G_{k-2}, \sigma)$ for all the choices of the input parameters $I_{k-1} \in [d]^{k-1}$, $G_{k-2} \in (\mathbb{S}_{n-2}\backslash \mathbb{S}_n / \mathbb{S}_{n-2})^{k-2}$, $\sigma \in \mathbb{S}_n/\mathbb{S}_{n-2}$.
    It requires $O(d^{k-2}n^3 + d^{k-1}n^2)$ operations and $O(dn^3+d^{k-1}n^2)$ space.
\end{lemma}

Combining this lemma with the efficient computation of Fourier transforms on $\mathbb{S}_n/\mathbb{S}_{n-2}$, we arrive to the following.
\begin{theorem}[Doubly-reduced $k$-Spectrum]
\label{theorem: doubly-reduced spectrum}
    Let $f: \mathbb{S}_n/\mathbb{S}_{n-2} \rightarrow \C^d$. We can compute its doubly-reduced $k$-spectrum in $O(d^{k-1}n^3 + d^kn^2)$ operations. The doubly-reduced $k$-spectrum has up to $\binom{7}{k-2}7d^k$ non-zero entries.
\end{theorem}

This result recovers the complexity of the reduced Multi-Orbit Skew Spectrum (Theorem~\ref{theorem: Multi-Orbit Skew Spectrum}) for $k=3$ and that of the reduced Skew Spectrum (Theorem~\ref{theorem: reduced skew spec}) for $d=1$.
The double reduction limits the scaling with $n$.
On a single orbit, this enables the computation of more expressive invariants at the same computational cost of the Skew Spectrum.

\subsection{Complexity analysis}
We briefly prove Theorem~\ref{theorem: doubly-reduced spectrum}, discussing the complexity of the algorithm and the number of non-zero entries.

\paragraph{Main algorithm.} Algorithm~\ref{alg:main kspect} precomputes $s^{(k)}$ (Lemma~\ref{lemma: precomputing s}) and then proceeds to compute the entries of $\hat{\mathcal{S}}^{(k)}_f$. 
The for loops compute $d^{k-1}$ Fourier transforms on $s^{(k)}$ and $d$ on $f_i$, each of which takes $O(n^3)$ operations, since both are functions on $\mathbb{S}_n/\mathbb{S}_{n-2}$.
Finally, the direct sum performs $d^k$ matrix multiplication that cost $O(n^2)$ each (see the sparsity patterns of Lemma~\ref{lemma: fourier sparsity}).
The overall complexity is indeed $O(d^{k-1}n^3 + d^kn^2)$.

\paragraph{Non-zero entries.} 
For each of the $4$ irreps, there are $\binom{7}{k-2}$ lists $G_{k-2}$ on which evaluate the spectrum. Each spectrum entry has $d^k$ terms in the direct sum,  with non-zero entries determined by the irrep.
Using (\ref{eq: reduced k-spectrum}) and the column sparsity of the Fourier transform (Lemma~\ref{lemma: fourier sparsity}), we observe that each $\rho \in \{(n), (n-1, 1), (n-2, 1, 1)\}$ produces $1$ non-zero entry, while $\rho = (n-2, 2)$ produces $4$: $(7=1 \cdot 3 + 4)$.

