Finally, a useful result in representation theory, sometimes referred to as the Great Orthogonality Theorem (\citet[Section II.3]{Zee-groupTheory}), states that for any two irreps $\rho_1, \rho_2,$
\begin{align}
\label{eq: GOT}
    \sum_{g \in \mathbb{S}_n} \rho_1(g)^\dagger_{i,j}\rho(g)_{k,l} = \frac{|\mathbb{S}_n|}{\mathrm{dim}(\rho)} \delta_{\rho_1, \rho_2} \delta_{i,l} \delta_{j,k}.
\end{align}
Here, $\delta_{\rho_1, \rho_2}$ is the Kronecker delta, which is $1$ if $\rho_1$ and $\rho_2$ are equivalent (i.e., represent the same irrep) and $0$ otherwise.
A direct consequence of (\ref{eq: GOT}) is that summing over all elements of $\mathbb{S}_n$ in a given irrep of $\rho \vdash n$ yields:
\begin{align}
\label{eq: irrep ortho}
    \sum_{\sigma \in \mathbb{S}_n} \rho(\sigma) = \begin{cases}
        |\mathbb{S}_n| & \rho = (n)\\
        0 & \text{otherwise}.
    \end{cases}
\end{align}
This follows from the fact that the trivial representation $(n)$ has dimension $1$ and consists entirely of ones.

\section{Fourier sparsity and projecting on the trivial irrep}
\label{apx: projection on trivial}

In this appendix, we examine the role of $\tau_{\mathbb{S}_{n-2}}(\rho)$, which represents the projection of an irrep $\rho \in \mathrm{Irr}(\mathbb{S}_n)$ onto the trivial representation of $\mathbb{S}_{n-2}$:
\begin{align}
    \tau_{\mathbb{S}_{n-2}}(\rho) = \frac{1}{|\mathbb{S}_{n-2}|}\sum_{h \in \mathbb{S}_{n-2}} \rho(h)
\end{align}
This projection naturally arises in the Fourier transform of functions $\mathbb{S}_n/\mathbb{S}_{n-2} \rightarrow \C$~\cite{kondor2007homogeneus}:
\begin{align}
    \hat{f}(\rho) = \frac{1}{|\mathbb{S}_n|} \sum_{\sigma \in \mathbb{S}_n} f(\sigma)\rho(\sigma) &= \frac{1}{|\mathbb{S}_n|} \sum_{y \in \mathbb{S}_n/\mathbb{S}_{n-2}}\sum_{h \in \mathbb{S}_{n-2}} f(yh)\rho(yh) \\
    &= \frac{|\mathbb{S}_{n-2}|}{|\mathbb{S}_n|} \sum_{y \in \mathbb{S}_n/\mathbb{S}_{n-2}} f(y)\rho(y) \frac{1}{|\mathbb{S}_{n-2}|}\sum_{h \in \mathbb{S}_{n-2}}\rho(h) \\
    &= \frac{|\mathbb{S}_{n-2}|}{|\mathbb{S}_n|} \sum_{y \in \mathbb{S}_n/\mathbb{S}_{n-2}} f(y) \rho(y) \tau_{\mathbb{S}_{n-2}}(\rho).
\end{align}
Moreover, $\tau_{\mathbb{S}_{n-2}}(\rho)$ is responsible for the sparsity patterns described in Lemma~\ref{lemma: fourier sparsity}.

