%                                          \begin{array}{c}
%                                            g_{1,j}(t,x,x_{\tau_1},\ldots,x_{\tau_K}) \\
%                                            \vdots \\
%                                            g_{d,j}(t,x,x_{\tau_1},\ldots,x_{\tau_K}) \\
%                                          \end{array}
%                                        \right)\in\mathbb{R}^d.\]

