\subfloat[Heat map of a sample $Q$-Wiener process for correlated noise, with $Q$ defined by \cref{QFunction}.]{\includegraphics[width=0.3\linewidth,trim=2 0 0 0,clip]{ZExample4CorrelatedQWiener.png}}
