\tim{The widely used aggregation strategy for FL-based ASR is FedAvg~\cite{pmlr-v54-mcmahan17a}, which computes global parameters as a weighted sum of client parameters, with weights proportional to each client’s data fraction. Given the communication overhead~\cite{du2024communication}, synchronization is performed at carefully chosen frequency\footnote{\tim{The impact of communication frequency is analyzed in Section~\ref{sec:exp}.}}.}


\section{\tim{Regularized Federated Learning}}
\label{sec:reg}
% \tim{The nature of federated learning leads to data heterogeneity among clients, which is further exaggerated by the challenges of data scarcity, data imbalance and speaker heterogeneity among dysarthric and elderly population. To this end, three regularization techniques are investigated, including parameter-based, embedding-based and loss-based regularization.}
\tim{Federated learning inherently introduces data heterogeneity among clients, which is further compounded by the challenges of data scarcity, data imbalance, and speaker diversity widely observed in dysarthric and elderly speech. To mitigate this, three regularization techniques at different levels are investigated, including parameter-based, embedding-based, and loss-based regularization. For model aggregation, we adopt FedAvg~\cite{pmlr-v54-mcmahan17a} as the default strategy.}


\vspace{-15pt}
\tim{\subsection{Parameter-based regularization}}
\label{sec:para_reg}

% \$tim{Following FedProx~\cite{MLSYS2020_1f5fe839}, the parameters of the global model of the previous round are taken as the reference to regularize the local training process of the clients. The square of the L2 norm measures the Euclidean distance between the reference global model and the local model is added to the standard CTC training loss on the client side, give as:}

\tim{Following FedProx~\cite{MLSYS2020_1f5fe839}, the global model parameters from the previous communication round are taken as a reference to regularize the local training process of the clients. As shown in the upper right of Fig.~\ref{fig:FL_reg_para_emb}, the squared L2 norm $\mathcal{R}_{para}$, which measures the Euclidean distance between the reference global model and the local model, is incorporated into the local training loss as a regularization term, given as:}

\vspace{-3mm}
\begin{equation}
    \label{eq:reg_para}
    \mathcal{R}_{para} = || \bm{W}_{i} - \overline{\bm{W}} ||_{2}^{2} 
\end{equation}

% \noindent \tim{where $\mathbf{W}_i$ and $\overline{\mathbf{W}}$ respectively denotes the local model parameters of the $i^{th}$ client and the global model parameters of the previous round.}

\noindent \tim{where $\mathbf{W}_i$ represents the local model parameters of the $i^{th}$ client at the current round, while $\overline{\mathbf{W}}$ denotes the global model parameters from the previous round.}

% The loss of this client is the combination of CTC loss $\mathcal{L}_{ctc}$ and parameter-based regularization $\mathcal{L}_{param\_reg}$:
%% \vspace{-0.2cm}
% \begin{equation}\label{eqn:embedding_loss}
%% \mathcal{L}_{reg}=\sum_m^M \| \bm{E}_{is, m}^l - \bar{\bm{c}}^l \|
% \mathcal{L}_{param\_reg}= {\lVert \bm{w}_{i} - \bar{\bm{w}}\rVert}_2^2
% \end{equation}
% where $\bm{w_i}$ is the trainable parameter of the local model in the $i$-th client.  $\bar{\bm{w}}$ is the parameter of the global model in the server received in the last communication round. ${\lVert \cdot \rVert}_2^2$ is the square of L2 norm.


