\vspace{-0.8cm}
\tim{\subsection{Embedding-based regularization}}
\label{sec:emb_reg}
% \tim{Inspired by~\cite{Tun2023,GreidiCohen2024}, during each communication round, we take the latent embeddings from the local models, using a weighted sum\footnote{\tim{The weights are proportional to each client’s data fraction relative to the total training samples, similar to FedAvg~\cite{pmlr-v54-mcmahan17a}}} to aggregate them on the central server, then use it as a reference to compare with the latent embedding of the local models in the following round.}
\tim{Building on~\cite{Tun2023,GreidiCohen2024}, during each communication round, we extract latent embeddings from the local models, compute the average embedding over all utterances for each client, and then aggregate these averaged embeddings from all clients on the central server using a weighted sum\footnote{\tim{The weight is the client’s proportion of the total training data.}}. As demonstrated in the lower right of Fig.~\ref{fig:FL_reg_para_emb}, the aggregated embedding serves as a reference to constrain the local models' latent embeddings in the next round, where the local training loss integrates the squared L2 norm between these embeddings. This regularization term $\mathcal{R}_{embed}$ is given as:}

\begin{equation}
    \label{eq:reg_embed}
    \mathcal{R}_{embed} = || \bm{e}_{i}^{l} - \overline{\bm{e}_{i}^{l}} ||_{2}^{2} 
\end{equation}

\noindent \tim{where $\bm{e}_i^{l}$ represents the embedding of the $i^{th}$ client after the $l^{th}$ Transformer block, and $\overline{\bm{e}_i^{l}}$ denotes the aggregated embedding.}

\tim{\subsection{Loss-based regularization}}
\label{sec:loss_reg}
% $D_{\mathrm{KL}}(y || \hat{y}) = \sum_i y_i \log \frac{y_i}{\hat{y}_i}$
% $D_{KL}(y \parallel \hat{y})$

% \tim{To further investigate regularization at various levels of the training process, we propose a novel loss-based regularization approach. As depicted in Fig.~\ref{fig:FL_reg_loss}, instead of directly constraining the latent embedding, we pass the local embedding of $client~i$ into the global model, and conduct a feedforward pass to get the output probability distribution. In the next communication round, this distribution is used to regularize the output distribution of $client~i$, where the Kullback-Leibler (KL) divergence $\mathcal{R}_{embed}$ is included in the local training loss. $\mathcal{R}_{embed}$ is given as:}

\tim{To further investigate regularization across different aspects of the training process, we propose a novel loss-based regularization approach. As illustrated in Fig.~\ref{fig:FL_reg_loss}, rather than directly constraining the latent embedding, we feed the local embedding of the $i^{th}$ client into the global model from the previous communication round and execute a feedforward pass to derive the output probability distribution (Fig.~\ref{fig:FL_reg_loss}, red bold line). This distribution is then leveraged to regularize the output distribution of the $i^{th}$ client by incorporating the Kullback-Leibler (KL) divergence~\cite{kullback1951information} between these two distributions into the local training loss. The regularization term $\mathcal{R}_{loss}$ is defined as:}

\begin{equation}
    \label{eq:reg_loss}
    \mathcal{R}_{loss} = D_{KL}(\hat{\bm{y}}_{i} \parallel \tilde{\bm{y}}_{i}^{l}) 
\end{equation}

% \noindent \tim{where $D_{KL}(\cdot)$ denotes the KL divergence. $\hat{\bm{y}}_{i}$ is the output distribution by $client~i$, and $\tilde{\bm{y}}_{i}^{l}$ refers to the output distribution obtained by feeding the embedding of the $i^{th}$ client after the $l^{th}$ layer to the global model.}

% loss-based global side不能取平均
\noindent \tim{where $D_{KL}(\cdot)$ denotes the KL divergence. $\hat{\bm{y}}_{i}$ represents the output distribution of the $i^{th}$ client, and $\tilde{\bm{y}}_{i}^{l}$ denotes the output distribution obtained by passing the $i^{th}$ client's embedding after the $l^{th}$ Transformer block through the global model.}

