ClusterGraph is intended to serve as a tool for data visualization and compression. Compression is achieved by collapsing points within the same cluster into a vertex of the ClusterGraph. This step is motivated by an assumption that points within the same cluster are in close proximity, hence share mulipe characteristics and can be prepresent by a single vertex. We expect ClusterGraph to have much fewer vertices compared to the original number of points. The visualization aspect is accomplished when the layout of the ClusterGraph resembles, to some extent, the layout of the input point cloud. However, this is unlikely to be the case for a fully connected graph. Therefore, in Section~\ref{sec:metric_distortion_quality_measure}, we propose a \emph{metric distortion}-based criterion and techniques for removing certain edges of the ClusterGraph so that the metrics on the graph and on the initial point cloud become comparable. Different strategies for edge removal from the ClusterGraph are discussed in Section~\ref{sec:pruning}. This process yields a \emph{pruned} ClusterGraph, which we use for visualization purposes.


\subsubsection{Distances between clusters}
\label{sec:distances_clusters}
In this section, for a dataset $X$ equipped with similarity measure $d_X$ and a partition $\mathcal{C}(X)$, a number of similarity measures $d_\mathcal{C} : \mathcal{C}(X) \times \mathcal{C}(X) \rightarrow \mathbb{R}_{\geq 0}$ are presented.
The choice of the optimal one is application dependent, very much like the clustering algorithm $\mathcal{C}$, and should therefore be selected and optimized by the user. Given two clusters $C_i$ and $C_j$, possible options include:

%Given two elements $C_i, C_j \in \mathcal{C}(X)$ we have implemented the following options for $d_\mathcal{C}(C_i,C_j)$;


\begin{enumerate}
    \item Maximum, minimum or an average distance between points
          \begin{align*}
              \min(C_i, C_j)                & = \min\limits_{x \in C_i , y \in C_j  } d_X(x,y)                                   \\
              \max(C_i, C_j)                & = \max\limits_{x \in C_i , y \in C_j  } d_X(x,y)                                   \\
              %\text{\DG{this makes no sense ,the distance between a cluster and itself it non zero!}} \\
              \operatorname{avg}(C_i , C_j) & = {\sum\limits_{x \in C_i} \sum\limits_{y \in C_j}  d_X(x, y)} / {(|C_i| |C_j|)} .
          \end{align*}

    \item Hausdorff distance
          \[
              d_{H}(C_i,C_j)=\max \left\{\,\sup _{x\in C_i}d(x,C_j),\,\sup _{y\in C_j}d(C_i,y)\,\right\}, \]
          where $d(a, B) = \inf\limits_{b \in B} d(a,b)$.
          %
          %\item Wasserstein distance,
          %
    \item Earth mover (a.k.a. Wasserstein) distance~\cite{emd, Wasserstein1969} which utilizes ideas from probability theory and optimal transport
          \[
              W_p(C_i, C_j) =  \inf_{\eta:C_i \rightarrow C_j} \left (\sum_{x \in C_i} d_X(x, \eta(x))^p \right)^\frac{1}{p},
          \]
          where $\eta$ is a matching between points of $C_i$ and $C_j$ and $1 \leq p < \infty$. If the two clusters have different size, the matching is computed in a weighted way, i.e. each point in $C_i$ is assigned a weight of $1/|C_i|$ such that each cluster has a total mass of 1.

\end{enumerate}

\subsubsection{Stability}

Let us consider a dataset $X$ , and two partitions of it $\mathcal{C}(X)$, $\mathcal{D}(X)$ obtained via some clustering algorithms. We are interest in quantifying how different these two partitions can be. In order to do so we introduce the following concept.

\begin{definition}[Image of a cluster]
    Let $X$ be a dataset and $\mathcal{C}(X)$, $\mathcal{D}(X)$ two partitions of it. The \emph{image} of a cluster $C_i \in \mathcal{C}(X)$ in $\mathcal{D}(X)$ is the union of all clusters of $\mathcal{D}(X)$ that contain some points of $C_i$, namely  $ \operatorname{im}_{\mathcal{D}(X)} (C_i) = \{ \bigcup D_j \in \mathcal{D}(X) \; | \; C_i \cap D_j \neq \emptyset \}$.
\end{definition}
This idea of mapping the points covered by one cluster in a given partition to the clusters in a second partition is inspired by an analogous technique for mapper graphs, \emph{MappingMappers}, described in~\cite{mappertype}.

Let us define the \emph{diameter} of a collection of points as the greatest distance between any pair of points. We can then state the following bound.

\begin{proposition}[Clustering stability]
    \label{prop:1}
    Let $X$ be a dataset and $\mathcal{C}(X)$, $\mathcal{D}(X)$ be two partitions of it such that the diameter of each set in  $\mathcal{C}(X)$ and $\mathcal{D}(X)$ is at most $\delta$. Then, for any cluster $C_i \in \mathcal{C}(X)$, its image in $\mathcal{D}(X)$ has diameter at most $3\delta$.
\end{proposition}
\begin{proof}
    Let $d_1, d_2 \in  X$ be the two points whose distance realizes the diameter of $\operatorname{im}(C_i)$. By definition of image there is at least one point $c_1 \in C_i$ which lies in the same cluster of $\mathcal{D}(X)$ as $d_1$, and similarly there exist at least one $c_2$ for $d_2$. Therefore we have
    \[
        d_X(d_1, d_2) \leq d_X(d_1, c_1) + d_X(c_1, c_2) + d_X(c_2, d_2) \leq 3\delta \; .
    \]
\end{proof}

Using a summary statistic of the distance between points as distance between clusters (option 1 in \ref{sec:distances_clusters}) allows us to derive a similar bound for ClusterGraphs built on top of $\mathcal{C}(X)$ and $\mathcal{D}(X)$.

\begin{definition}[Image of a ClusterGraph vertex]
    Let $X$ be a dataset, $\mathcal{C}(X)$, $\mathcal{D}(X)$ two partitions of it and $G_{\mathcal{C}(X)}$, $G_{\mathcal{D}(X)}$ the ClusterGraphs obtained from $\mathcal{C}(X)$ and $\mathcal{D}(X)$.
    The \emph{image} of a vertex $i \in G_{\mathcal{C}(X)}$ (corresponding to cluster $C_i \in G_{\mathcal{C}(X)}$) in $G_{\mathcal{D}(X)}$ is the collection of all vertices of $G_{\mathcal{D}(X)}$ that corresponds to clusters in $G_{\mathcal{D}(X)}$ containing some points of $C_i$.
\end{definition}

We define the \emph{diameter} of a weighted graph as the greatest distance between any pair of vertices.

\begin{proposition}[ClusterGraph stability]
    Let $X$ be a dataset, $\mathcal{C}(X)$, $\mathcal{D}(X)$ two partitions of it and $G_{\mathcal{C}(X)}$, $G_{\mathcal{D}(X)}$ the ClusterGraphs obtained from them.
    Assume that the diameter of each set in  $\mathcal{C}(X)$ and $\mathcal{D}(X)$ is at most $\delta$.
    Then the image of each vertex  $u \in G_{\mathcal{C}(X)}$ in $G_{\mathcal{D}(X)}$ is a clique of diameter at most $3\delta$ for the maximum and average distance, and $\delta$ for the minimum.
\end{proposition}
\begin{proof}
    Let $u$ be a vertex in $G_{\mathcal{C}(X)}$ and $\operatorname{im}(u)$ its image in $G_{\mathcal{D}(X)}$.
    % Let $v_i$ and $v_j$ be the vertices in $G_{\mathcal{D}(X)}$ corresponding to clusters $D_i$ and $D_j$ in $\mathcal{D}(X)$ whose distance is the diameter of $\operatorname{im}(u)$. 
    Recall that $\operatorname{im}(u)$ is a subset of the complete graph $G_{\mathcal{D}(X)}$, therefore it is a clique.
    Let $D_i$ and $D_j$ be the clusters in $\operatorname{im}(u)$ whose distance realizes the diameter of $\operatorname{im}(u)$, i.e. they correspond to the two vertices in the clique that are the furthest apart.

    Let us start with the maximum distance case.
    In particular, let $d_1 \in D_i$ and $d_2 \in D_j$ be the two data points realizing the maximum distance between $D_i$ and $D_j$, and therefore $d(d_1, d_2) = \operatorname{im}(u)$. Let $C_u$ be the cluster in $\mathcal{C}(X)$ corresponding to vertex $u \in G_{\mathcal{G}(X)}$. By definition of image of $u$ there are at least two points $c_1, c_2 \in C_u$ which lie in the same clusters of $\mathcal{D}(X)$ as $d_1$ and $d_2$, respectively.
    We can then proceed in a similar fashion to the proof of Proposition~\ref{prop:1}, namely we have
    \[
        \operatorname{diam}(\operatorname{im}(u)) = \max(D_i, D_j) = d_X(d_1, d_2) \leq d_X(d_1, c_1) + d_X(c_1, c_2) + d_X(c_2, d_2) \leq 3\delta \; .
    \]
    %
    The same bound holds for the average distance since $\operatorname{avg}(D_i , D_j) \leq \max(D_i, D_j)$.

    For the minimum distance case it is sufficient to notice that $d_X(c_1, c_2) \leq \delta$ because they both belong to the same cluster $C_i$ whose diameter is bounded by $\delta$. Hence we have
    \[
        \operatorname{diam}(\operatorname{im}(u)) = \min(D_i, D_j) \leq d_X(c_1, c_2) \leq \delta .
    \]
\end{proof}

