\begin{definition}[Node instantiation -- from~\cite{pascual_inferring_2022}]
    \label{def:nodeinstantiation}
 If \(\mu\) is a node of \(\jerboagraphscheme{G}\), its instantiation with \(O\) is the graph obtained by applying \(\orb{o} \mapsto \orb{o^\mu}\) to \(O\):
    \[
        \iota^{\orb{o}}(\mu, O) = [\orb{o} \mapsto \orb{o^\mu}](O).
    \]

 The construction extends to the set of nodes \(N_{\jerboagraphscheme{G}}\) of \(\jerboagraphscheme{G}\), whose instantiation is the union of the instantiations of each node:
    \[
        \iota^{\orb{o}}(N_{\jerboagraphscheme{G}}, O) = \bigcup_{\mu \in N_{\jerboagraphscheme{G}}} \iota^{\orb{o}}(\mu, O).
    \]
\end{definition}

