\title{From Ground to Sky: Architectures, Applications, and Challenges Shaping Low-Altitude Wireless Networks}

\author{Weijie Yuan,~\IEEEmembership{Senior Member,~IEEE,} Yuanhao Cui,~\IEEEmembership{Member,~IEEE,} Jiacheng Wang,~\IEEEmembership{Member,~IEEE,} \\Fan Liu,~\IEEEmembership{Senior Member,~IEEE,} Geng Sun,~\IEEEmembership{Senior Member,~IEEE,} Tao Xiang,~\IEEEmembership{Senior Member,~IEEE,} \\Jie Xu,~\IEEEmembership{Fellow,~IEEE,} Shi Jin,~\IEEEmembership{Fellow,~IEEE,} Dusit Niyato,~\IEEEmembership{Fellow,~IEEE,} Sinem Coleri,~\IEEEmembership{Fellow,~IEEE,} \\ Sumei Sun,~\IEEEmembership{Fellow,~IEEE,} Shiwen Mao,~\IEEEmembership{Fellow,~IEEE,} Abbas Jamalipour,~\IEEEmembership{Fellow,~IEEE,}\\ Dong In Kim,~\IEEEmembership{Life Fellow,~IEEE,} Mohamed-Slim Alouini,~\IEEEmembership{Fellow,~IEEE,} and Xuemin Shen,~\IEEEmembership{Fellow,~IEEE}
