\title[Article Title]{An extension of Dembo-Hammer's reduction algorithm for the 0-1 knapsack problem}

\author{Yang Yang}\email{zhugemutian@outlook.com}

\affil{\orgdiv{School of Mathematical Sciences}, \orgname{Xiamen University}, \orgaddress{\street{Siming South Road 422\#}, \city{Xiamen}, \postcode{361005}, \state{Fujian}, \country{PR China}}}


\abstract{Dembo-Hammer's Reduction Algorithm (DHR) is one of the classical algorithms for the 0-1 Knapsack Problem (0-1 KP) and its variants, which reduces an instance of the 0-1 KP to a sub-instance of smaller size with reduction time complexity $O(n)$. We present an extension of DHR (abbreviated as EDHR), which reduces an instance of 0-1 KP to at most $n^i$ sub-instances for any positive integer $i$. In practice, $i$ can be set as needed. In particular, if we choose $i=1$ then EDHR is exactly DHR. Finally, computational experiments on randomly generated data instances demonstrate that EDHR substantially reduces the search tree size compared to CPLEX.}

\keywords{0-1 knapsack problem(0-1 KP), exact solution, time complexity, polynomial-time, reduction, CPLEX}

