\caption{Deployment time in seconds of one OSD per node with a storage pool}
\label{tab:deployment-time}
\begin{tabular}{llll}
NODES & Deploy           & Remove           & Total             \\
\hline
1     & $20.766\pm0.059$ & $93.723\pm0.133$ & $114.488\pm0.146$ \\
2     & $22.011\pm1.384$ & $95.754\pm2.432$ & $117.765\pm3.169$ \\
3     & $22.779\pm0.885$ & $96.598\pm2.244$ & $119.377\pm2.482$ \\
