\section{Introduction}\label{sec:intro}
{%\color{pass}
Fractional-in-time semilinear and quasilinear parabolic equations will be considered.
The  semilinear problem is of the form
\beq\label{problem}
\begin{array}{l}
\pt_t^{\alpha}u+\LL u+f(u)=0\quad\mbox{for}\;\;(x,t)\in\Omega\times(0,T],\\[0.2cm]
u(x,t)=0\quad\mbox{for}\;\;(x,t)\in\pt\Omega\times(0,T],\qquad
u(x,0)=u_0(x)\quad\mbox{for}\;\;x\in\Omega.
\end{array}
\eeq
It is posed
posed in a bounded Lipschitz domain  $\Omega\subset\R^d$ (where $d\in\{1,2,3\}$), and involves
a linear second-order elliptic  spatial operator $\LL$ defined on temporal mesh $\{t_j\}_{j\ge0}$ by
\beq\label{LL_def}
\LL u := \sum_{k=1}^d \Bigl\{-\pt_{x_k}\!(a_k(x,t)\,\pt_{x_k}\!u) + b_k(x,t)\, \pt_{x_k}\!u \Bigr\}+c(x,t)\, u,
\eeq
with sufficiently smooth coefficients $\{a_k\}$, $\{b_k\}$ and $c$ in $\bar\Omega$, for which we assume that $a_k>0$ in $\bar\Omega$,
and also both $c\ge 0$ and $c-\frac12\sum_{k=1}^d\pt_{x_k}\!b_k\ge 0$.
%
We shall also consider a quasilinear equation of the form $\pt_t^{\alpha}u+\QQ u+f(x,t,u)=0$,
where
$\QQ u := -\sum_{k=1}^d \pt_{x_k}\!\bigl\{a_k(x,t,u)\,\pt_{x_k}\!u + b_k(x,t,u) \bigr\}$ (see \S\ref{sec_quasi} for details).
%
The operator $\pt_t^\alpha$, for some $\alpha\in(0,1)$, is
the Caputo fractional derivative in time defined \cite{Diet10} by
\begin{equation}\label{CaputoEquiv}%\color{pass}
\pt_t^{\alpha} u(\cdot,t) :=  \frac1{\Gamma(1-\alpha)} \int_{0}^t(t-s)^{-\alpha}\, \pt_s u(\cdot, s)\, ds
    \qquad\text{for }\ 0<t \le T,
\end{equation}
where $\Gamma(\cdot)$ is the Gamma function, and $\pt_s$ denotes the partial derivative in $s$.


  It will be assumed throughout the paper that the exact solution satisfies
\beq\label{ass_u_pde}
\|\partial_t^l u (\cdot, t)\|_{L_p(\Omega)}\lesssim 1+t^{\sigma-l}\qquad \mbox{for}\;\; l=0,1,2,\;\;t\in(0,T],
\eeq
with some $\sigma \in (0,1) \cup (1,2)$, for $p=2$ or $p=\infty$.
%
While a more typical assumption corresponds to the particular case $\sigma:=\alpha$, other values of $\sigma$
have been considered, including $\sigma=2\alpha$ for $p=\infty$ \cite{Gracia_2alpha}, and  $\sigma<\alpha$ for $p=2$ due to non-smooth inital data \cite{JLZ19}.
%
The singularities with $\sigma>\alpha$ are also related to delay equations, such as
a linear version of \eqref{problem} with an additional delay term $u(\cdot, t-\theta)$ ($\theta>0$)
considered in  \cite{delay_cmam},
with a typical solution satisfying
$|\partial_t^l u (\cdot, t)|\lesssim 1+(t-\theta j)^{\sigma_j-l}$ on each interval $\theta(j,j+1]$ ($j\ge0$), where $\sigma_j:=\alpha(j+1)$.


The above problems will be discretized in time using the L1 discrete fractional-derivative operator, defined by
\beq\label{delta_def}
\delta_t^{\alpha} U^m :=  \frac1{\Gamma(1-\alpha)} \sum_{j=1}^m \delta_t U^j\!\int_{t_{j-1}}^{t_j}\!\!(t_m-s)^{-\alpha}\, ds,
\qquad
\delta_t U^j:=\frac{U^j-U^{j-1}}{t_j-t_{j-1}}.\vspace{-0.1cm}%
\eeq

A wide class of discretizations in time for the semilinear term will be considered, which, in the context of
 the semilinear problem~\eqref{problem}, leads
to an L1-type semidiscretization of in time, $\forall\,m=1,\ldots,M$:
%$\delta_t^\alpha$ from \eqref{delta_t_def}:
\beq\label{semi_semidiscr_method}
\delta_t^\alpha U^m +\LL U^m+ F(U^m,U^{m-1})=0\;\;\mbox{in}\;\Omega,\;U^m=0\;\;\mbox{on}\;\pt\Omega,\;\; \;U^0=u_0.
\eeq
%
Here $f(u)$ %at $t=t_m$
is discretized using $F(\cdot,\cdot)$, which satisfies general conditions A1 and A2 below,
formulated under the assumption that the exact solution $u$ of \eqref{problem} is bounded for $0\le t\le T$, with its range denoted by $\RR_u\subseteq \R$.
\smallskip

\begin{itemize}[leftmargin=0.7cm]
\item[{\bf A1}] (Consistency)
For some fixed positive constant $L$ and fixed $q\ge 1$, let
%
%
%{\color{pass}\cite[first part of the proof in Lemma 1]{DK16}: + \cite[Lemma 16]{BS73}
%==> given $u_0\in L_\infty$, we get $U^j\in H_0^1(\Omega)\cap L_\infty(\Omega)$}
$$%\beq\label{F_ass_a}
%F(v,v)=f(v)\quad\Leftarrow \quad |F(v,w)-f(v)|\le L |v-w|,\qquad
|F(v,w)-f(v)|\le L |v-w|^q\qquad \forall\,v,\,w\in\RR_u\subseteq \R.
$$%\eeq


\item[{\bf A2}] (One-sided Lipschitz condition)
Let $F(\cdot,\cdot)$ be continuous in $\R^2$ and,
for some constant $\lambda_0\ge0$, let the function
$F(v,w)+\lambda_0 v$ be non-decreasing in $v$ for any fixed $w\in\R$, or, equivalently,
\begin{align*}%\label{}
%$$%\beq\label{F_ass_b_new}\color{magenta}
F(v+\nu,w)-F(v, w)&\ge -\lambda_0\, \nu \qquad \forall\,v,\,w\in \R,\;\nu\ge 0.
\\[-3pt]
\intertext{Furthermore, let $F(\cdot,\cdot)$ satisfy the Lipschitz condition in the second argument with some constant $\lambda_1\ge 0$:\vspace{-3pt}}
%$$%\beq\label{F_ass_b_new}\color{magenta}
\bigl|F(v, w+\omega)-F(v, w)\bigr|&\le \lambda_1|\omega| \qquad \forall\,v,\,w\in \RR_u\,,\;\omega\in \R.
\end{align*}
(%If $F$ is differentiable, then
Note that
$\pt_v F(v,w)\ge-\lambda_0$ and $|\pt_w F(v,w)|\le \lambda_1$ are sufficient for A2.)
\end{itemize}
\medskip

Example 1 (Implicit scheme). One standard choice is $F(U^m,U^{m-1})=f(U^m)$, which corresponds to
$F(v,w)=f(v)$ satisfying A1 and A2 with
$L=\lambda_1=0$ and $\lambda_0=\max\{0,\,\sup_{\R}(- f')\}$.
(For  $\sigma=\alpha$, this scheme was considered in \cite{kopteva_semilin}.)
\smallskip


Example 2 (Convex splitting \cite{Du2020}).
For an Allen-Cahn model with $f(u)=u^3-u$, one choice  is
$F(U^m,U^{m-1})=(U^m)^3-U^{m-1}$, which corresponds to $F(v,w):=v^3-w$ satisfying A1 and A2 with
 $L=1$, $q=1$, $\lambda_0=0$, and $\lambda_1=1$.
\smallskip

Example 3 (First-order IMEX \cite{jin18, maskari19, Rasheed24}). A first-order IMEX scheme is given by \eqref{simplest_b} with $F(U^m,U^{m-1})=f(U^{m-1})$, which corresponds to
$F(v,w):=f(w)$ satisfying A1 and A2 with
$q=1$, $L=\lambda_1=\sup_{\R} |f'|$,
  and $\lambda_0=0$ .
\smallskip

Example 4 (Newton-iteration-type second-order IMEX \cite{HLiao1, DLi1}).
A higher-order IMEX scheme  is given by \eqref{simplest_b}
with  $F(v,w):=f(w)+[v-w]\,f'(w)$, which satisfies A1 and A2 with
 $q=2$, $L=\frac12\sup_{\R} |f''|$,
  and $\lambda_0=\max\{0,\,\sup_{\R}(- f')\}$,
  while %for $F(v, w+\omega)-F(v, w)$ one has
  $$
  F(v, w+\omega)-F(v, w)=\bigl\{f(w+\omega)- f(w)\bigr\}-\omega\,f'(w+\omega)+[v-w]\,\bigl\{f'(w+\omega)-f'(w)\bigr\}
  $$
  yields
  $\lambda_1=2\sup_{\R}|f'|+2L\,{\rm diam}(\RR_u)$.
\smallskip

Other examples include a first-order stabilized IMEX scheme \cite{Ji20}, which
%
