\section{Stability in time}\label{sec_stab}

Throughout the paper, we shall assume that the temporal mesh is quasi-graded, with a grading parameter $r\ge 1$,
in the sense that
\beq\label{t_grid_gen}%\color{pass}
\tau := t_1\simeq M^{-r},\qquad
%t_j \sim \tau j^r,\quad %t_j = \tau j^r,\quad
\tau_j:=t_j-t_{j-1}%\simeq M^{-1}\,t_j^{1-1/r}
\lesssim\tau^{1/r}t_j^{1-1/r}%{\color{red}\simeq t_j/j}
\qquad %t_{j+1}\lesssim  t_{j}
\forall\,j=1,\ldots,M.
\eeq
One notable example of \eqref{t_grid_gen} is a standard graded grid $\{t_j=T(j/M)^r\}_{j=0}^M$.


\begin{remark}\label{rem_tau_j_1}
It is useful to note that
\eqref{t_grid_gen} immediately implies that, with a sufficiently small constant $c=c(r)\in(0,\frac12)$, one has
 $t_{j-1}\ge c t_j$ $\forall\,j\ge2$ .
Indeed, choosing $c$ sufficiently small, if $\tau/t_j\le c$, from \eqref{t_grid_gen} one gets $\tau_j/t_j\lesssim c^{1/r}\le \frac12$
or $t_{j-1}\ge\frac 12 t_j\ge c t_j$. Otherwise, i.e. if $\tau/t_j> c$, from $t_{j-1}\ge\tau$ one again gets $t_{j-1}\ge  c t_j$.
\end{remark}

The main result of this section, which will be crucial for all error bounds that we obtain below, is the following stability property of the discrete fractional operator.

\begin{theorem}[stability in time]\label{theo_main_stab_semi}
Given $\gamma\in\R$ and $\lambda_0,\,\lambda_1\ge0$,
%if $\gamma>\alpha-1$,
let  the temporal mesh %, for some $1\le r\le (3-\alpha)/\alpha$,
satisfy $\lambda_0\tau_j^{\alpha}< \{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$. Additionally, suppose that either one has
\eqref{t_grid_gen} with some
$r\ge 1$, %$1\le r\le \color{red}\frac{2-\alpha}{\alpha}$,
or $\gamma\le \alpha-1$, and $\max\{\tau_j\}$ is sufficiently small.
%
Then %, given $\color{red}\gamma\ge\alpha -1$,
%for $\{U^j\}_{j=0}^M$
%with $U^0=0$
% one has
 %$\forall\, j\ge 1$%and $|\delta_t^\alpha V^j|\lesssim \tau^\gamma t_j^{-\gamma-1}$ for $j=1,\ldots,M$,
%then $|V^j|\lesssim t_j^{\alpha-1}$ for $j=1,\ldots, M$.
\beq\label{main_stab_new}
\left.\!\!\!\!\begin{array}{c}
(\delta_t^\alpha-\lambda_0) U^j-\lambda_1 U^{j-1}\lesssim (\tau/ t_j)^{\gamma+1}
\\[0.0cm]
\forall j\ge1,\;\;\; U^0=0
\end{array}\hspace{-0.2cm}\right\}
 \Rightarrow%\left.\!\!\!\!
 \begin{array}{l}
U^j\lesssim
\U^j(\tau;\gamma)\\
\quad{}:=
\ell_\gamma\tau t_j^{\alpha-1}(\tau/t_j)^{\min\{0,\,\gamma\}},%\\[0.2cm]%\;\;
%\forall j\ge 1,
\end{array}
%\hspace{-0.3cm}
\eeq
where $\ell_\gamma=\ell_\gamma(t_j):=1+\ln(t_j/\tau)$ for $\gamma=0$ and $\ell_\gamma:=1$ otherwise.
\end{theorem}

The above theorem is established (albeit under a certain restriction on $r$, as explained in Remark~\ref{rem_extension}) in \cite[Theorem~2.1]{Kopteva_Meng} for a significantly simpler case $\lambda_0=\lambda_1=0$,
and subsequently extended to the case $\lambda_0> 0=\lambda_1$ and $\gamma\neq 0$ in \cite[Theorem~3.1]{kopteva_semilin}.
In our proof below, for an extension  to the case $\gamma= 0$, we shall use an idea from \cite[Theorem~2.3]{NK_AML_L2nonl}.

\begin{remark}[dropping the restriction $r\le\frac{2-\alpha}{\alpha}$]\label{rem_extension}
Both \cite{Kopteva_Meng} and \cite{kopteva_semilin}
addressed the case $\sigma=\alpha$, for which it was sufficient to assume in \cite[Theorem~2.1]{Kopteva_Meng} and \cite[Theorem~3.1]{kopteva_semilin}
that either $1\le r\le \frac{2-\alpha}{\alpha}$ or $\gamma\le \alpha-1$.
However, an inspection of our error analysis in section~\ref{sec_error_ode} below shows that for the case $\sigma<\alpha$, we need to extend \cite[Theorem~2.1]{Kopteva_Meng}
to arbitrarily large values of $r\ge 1$. This requires non-trivial modifications in the proof of \cite[Theorem~2.1]{Kopteva_Meng}, so we devote an entire section~\ref{ssec_extension}
to this generalization.
Hence, in the proof of Theorem~\ref{theo_main_stab_semi}, we shall be able to assume that \eqref{main_stab_new} is valid for $\lambda_0=\lambda_1=0$.
\end{remark}

The proof of Theorem~\ref{theo_main_stab_semi} hinges on the following comparison principle.


\begin{lemma}[comparison principle for the operator in \eqref{main_stab_new}]\label{lem_comparison}
Given $\lambda_0,\,\lambda_1\ge0$, let the temporal mesh satisfy $\lambda_0\tau_j^{\alpha}<\{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$.
Then $V^0\le 0$ and  $(\delta_t^\alpha-\lambda_0)V^m-\lambda_1 V^{m-1}\le 0$ $\forall\,m\ge1$
imply $V^m\le 0$ $\forall\,m\ge0$.
\end{lemma}


\begin{proof}
The proof is by induction.
First,
a straightforward calculation (see, e.g., \cite{NK_MC_L1}) shows that
%$\delta_t^\alpha$ in
\eqref{delta_def} on an arbitrary temporal mesh $\{t_j\}$ can be represented as
\beq\label{delta_def_kappa}
\delta^\alpha_t V^m=\kappa_{m,m} V^m-\sum_{j=0}^{m-1}\kappa_{m,j}V^j,
\quad%\mbox{where}\;\;
\kappa_{m,m}=\frac{\tau_m^{-\alpha}}{\Gamma(2-\alpha)}, \;\; \kappa_{m,j}>0\;\;\forall\,m\ge j.
\eeq
Now, assuming that $V^j\le 0$ $\forall\,j<m$, one can rewrite $(\delta_t^\alpha-\lambda_0)V^m-\lambda_1 V^{m-1}\le 0$
as
$$
(\kappa_{m,m}-\lambda_0)V^m\le \lambda_1 V^{m-1}+\sum_{j<m}\kappa_{m,j}V^j,
$$
which immediately yields the desired $V^m\ge 0$.
\end{proof}
%\hfill$\square$

\begin{lemma}[{\cite[Lemma~3.2]{kopteva_semilin}}]\label{lem_axu_barrier}
Given any $\lambda\ge 0$, any fixed constant $0<c_0<\frac12\{\lambda \Gamma(2-\alpha)\}^{-1/\alpha}$,
and any fixed mesh point $0\le t_m\le T$, if  $\tau_j\le\frac12 c_0$ $\forall\,j\ge 1$, then
there exists a non-decreasing discrete function
$\{B^j\}_{j=0}^M$ such that $0\le B^j\lesssim 1$ $\forall\,j\ge1$ and
%$V^0=0$
\beq\label{aux_B}
B^j=0\;\;\forall\,j\le m,\quad\;\;
%0\le B^j\lesssim 1\;\mbox{and}\;
(\delta_t^\alpha- \lambda)\, B^j \ge Q^j:=\!\left\{\begin{array}{ll}
0\,&\mbox{for~}t_j< t_m+c_0\\
1\,&\mbox{for~}t_j\ge t_m+c_0
\end{array}\right.
\;\forall\,j\ge1.
\eeq
\end{lemma}

\begin{proof}[Proof of Theorem~\ref{theo_main_stab_semi}]
%
%
%\begin{proof}
For the particular case
$\lambda_0=\lambda_1=0$
(whether one has \eqref{t_grid_gen} with $r\ge 1$, %$1\le r\le \frac{2-\alpha}{\alpha}$,
or $\gamma\le \alpha-1$), the desired stability result \eqref{main_stab_new} is proved in
Lemma~\ref{lem_stability1}
(which is a generalization of \cite[Theorem~2.1]{Kopteva_Meng}), and implies that
\beq\label{main_stab_B}
\left.\begin{array}{c}
\delta_t^\alpha {\B}_\gamma^j= (\tau/ t_j)^{1+\gamma}
\\[0.2cm]
\forall j\ge1,\;\;\; {\B}_\gamma^0=0
\end{array}\right\}
\Rightarrow
0\le{\B}_\gamma^j\lesssim {\mathcal U}_\gamma^j=
%\tau t_j^{\alpha-1}(\tau/t_j)^{\min\{0,\,\gamma\}}
\ell_\gamma(t_j)\,\tau^\alpha
(\tau/t_j)^{1+\min\{0,\,\gamma\}-\alpha}
\;\;\;\forall j\ge 1,
\eeq
where we use a slightly more compact notation ${\mathcal U}_\gamma^j$ for ${\mathcal U}^j(\tau\,;\gamma)$ from \eqref{main_stab_new}, and also rewrite this quantity in
an different equivalent form.
To extend \eqref{main_stab_B} to our more general case, set
$$
\lambda:=\lambda_0+\lambda_1\ge 0,\qquad
\gamma^*:=\min\{0,\,\gamma\}-\alpha<0,\qquad
\bar\ell_\gamma:=\max_{j\le M}\ell_\gamma(t_j)=\ell_\gamma(T).
$$
Recall Remark~\ref{rem_tau_j_1} for $j\ge2$ and $\B_\gamma^0=0$ for $j=1$,
which yield ${\B}_\gamma^{j-1}\lesssim {\B}_\gamma^{j}$, and hence, with some constant $C_\gamma>0$,
$$
\lambda_0 {\B}_\gamma^j+\lambda_1 {\B}_\gamma^{j-1}\le \lambda C_\gamma\, {\mathcal U}_\gamma^j=\lambda C_\gamma\, \bar\ell_\gamma\,\tau^\alpha
(\tau/t_j)^{1+\gamma^*}.
$$
Hence,
\begin{align}\label{B_gamma}
(\delta_t^\alpha-\lambda_0){\B}_\gamma^j-\lambda_1 {\B}_\gamma^{j-1}&\ge (\tau/ t_j)^{1+\gamma}-\lambda C_\gamma\, \bar\ell_\gamma \tau^\alpha (\tau/t_j)^{1+\gamma^*},
\\
\intertext{and, similarly, only noting that $\bar\ell_{\gamma^*}=1$ (as $\gamma^*\neq 0$)
and
$\min\{0,\,\gamma^*\}-\alpha=\gamma^*-\alpha$, one gets}
(\delta_t^\alpha-\lambda_0){\B}_{\gamma^*}^j-\lambda_1 {\B}_{\gamma^*}^{j-1}&\ge (\tau/ t_j)^{1+\gamma^*}-\lambda C_{\gamma^*} \tau^\alpha (\tau/t_j)^{1+\gamma^*-\alpha}
\label{B_star}\\{}\notag
&=\textstyle
\frac12 (\tau/ t_j)^{1+\gamma^*}+\frac12 (\tau/ t_j)^{1+\gamma^*}\bigl[1-2 \lambda C_{\gamma^*} t_j^\alpha \bigr].
\end{align}


Next, using the above ${\B}_{\gamma}^j$ and ${\B}_{\gamma^*}^j$, as well as $B^j$ from Lemma~\ref{lem_axu_barrier} (assuming that the conditions of the latter lemma are satisfied), set
\beq\label{W_def}
{\mathcal W}^j:={\B}_\gamma^j+2\lambda C_\gamma\, \bar\ell_\gamma \tau^\alpha \Bigl\{ {\B}_{\gamma^*}^j+C_*\tau^{1+\gamma^*} B^j\Bigr\}
\eeq
with a sufficiently large constant $C_*$.
Now, combining the above observations \eqref{B_gamma} and \eqref{B_star} with \eqref{aux_B}, one gets
\begin{align}\label{delta_W_aux}
(\delta_t^\alpha-\lambda_0){\mathcal W}^j&-\lambda_1{\mathcal W}^{j-1}\ge  (\tau/ t_j)^{1+\gamma}
\\{}\notag
&+
\lambda C_\gamma\, \bar\ell_\gamma \tau^\alpha \Bigl\{(\tau/ t_j)^{1+\gamma^*}
\bigl[1-2 \lambda C_{\gamma^*} t_j^\alpha\bigr] + 2 C_*\tau^{1+\gamma^*} Q^j\Bigr\}.
\end{align}
Importantly, in the statement of Lemma~\ref{lem_axu_barrier}, the discrete function $B^j$ is non-decreasing in $j$, so
 $\lambda_0 B^j+\lambda_1 B^{j-1}\ge \lambda\, B^j$.
 Hence, the term $(\delta_t^\alpha- \lambda)\, B^j$ in \eqref{aux_B} can be replaced by $(\delta_t^\alpha- \lambda_0)\, B^j-\lambda_1 B^{j-1}$, which we used in the above
 evaluation.


Note that \eqref{delta_W_aux} immediately yields
\beq\label{delta_W}
(\delta_t^\alpha-\lambda_0){\mathcal W}^j-\lambda_1{\mathcal W}^{j-1}\ge
(\tau/ t_j)^{1+\gamma}
\eeq
whenever $[1-2 \lambda C_{\gamma^*} t_j^\alpha]\ge 0$.
Otherwise, i.e. if $[1-2 \lambda C_{\gamma^*} t_j^\alpha]< 0$, we shall
obtain \eqref{delta_W}
by ensuring that then $Q^j=1$ and choosing $C_*$ sufficiently large
(so that $2 C_*\tau^{1+\gamma^*} Q^j=2 C_*\tau^{1+\gamma^*}$ dominates
$(\tau/ t_j)^{1+\gamma^*}
\,2 \lambda C_{\gamma^*} t_j^\alpha$).
To ensure $Q^j=1$ whenever $[1-2 \lambda C_{\gamma^*} t_j^\alpha]< 0$,
in Lemma~\ref{lem_axu_barrier} choose a sufficiently small constant $c_0$ satisfying $2 \lambda C_{\gamma^*} (2c_0)^\alpha\le 1$, and the maximal $t_m\le c_0$ (so whenever $[1-2 \lambda C_{\gamma^*} t_j^\alpha]<0$, one gets $t_j\ge t_m+c_0$).
%
Note that Lemma~\ref{lem_axu_barrier} requires
$\tau_j\le \frac12 c_0$ $\forall\,j\ge 1$.
(If this is not the case for some $j$, then \eqref{t_grid_gen} implies $\tau^{1/r}\gtrsim t_j^{-(1-1/r)}\gtrsim 1$, so $M\simeq 1$ $\forall\,j\ge 1$, so the desired result
becomes straightforward.)

Thus, we have obtained \eqref{delta_W} $\forall\, j\ge1$.
%
Hence, in view of the comparison principle of Lemma~\ref{lem_comparison},
for $U^j$ satisfying the assumptions in \eqref{main_stab_new} one concludes
that $U^j\lesssim {\mathcal W}^j$.
Finally note that \eqref{W_def} implies
$$
U^j\lesssim{\mathcal W}^j\lesssim
\ell_\gamma(t_j)\,\tau^\alpha
(\tau/t_j)^{1+\gamma^*}
+
\bar\ell_\gamma \tau^\alpha \Bigl\{\tau^\alpha
(\tau/t_j)^{1+\gamma^*-\alpha}+\tau^{1+\gamma^*} B^j\Bigr\},
$$
while the desired assertion is equivalent to $U^j\lesssim \ell_\gamma(t_j)\,\tau^\alpha
(\tau/t_j)^{1+\gamma^*}$.
To show that the latter is indeed true, first, note that one has $B^j\neq 0$ for $t_j\ge t_m\gtrsim 1$, so the term $\tau^{1+\gamma^*} B^j$ enjoys the same bound as $\tau^\alpha
(\tau/t_j)^{1+\gamma^*-\alpha}$.
%
Combining this observation with
$$
\bar\ell_\gamma\,t_j^\alpha\lesssim \bigl[1+\ln(t_j/\tau)+\ln(T/t_j)\bigr]t_j^\alpha\lesssim 1+\ln(t_j/\tau)=\ell_\gamma(t_j)
$$
yields the desired bound $U^j\lesssim{\mathcal W}^j\lesssim \ell_\gamma(t_j)\,\tau^\alpha
(\tau/t_j)^{1+\gamma^*}$.
\end{proof}

