\subsection{Generalization of \cite[Theorem~2.1(i)]{Kopteva_Meng} for any $r\ge 1$ (dropping the restriction $r\le\frac{2-\alpha}{\alpha}$)}\label{ssec_extension}
Our task is to establish \eqref{main_stab_new} for the case $\lambda_0=\lambda_1=0$.
This result was proved in \cite[Theorem~2.1(i)]{Kopteva_Meng} under the assumption $1\le r\le \frac{2-\alpha}\alpha$.
However, for the purpose in this paper (see Remark~\ref{rem_extension}) we need to relax this assumption.
This is addressed by the following result \eqref{B_def}, valid for any $r\ge 1$, which, while not being identical  with  \eqref{main_stab_new} for the case $\lambda_0=\lambda_1=0$,
is equivalent to the latter (in view of $\delta_t^\alpha$ being a linear operator).


\begin{remark}\label{rem_nontrivial}
Note that the proof of \cite[Theorem~2.1(i)]{Kopteva_Meng} hinges on \cite[Lemma~2.3]{Kopteva_Meng}, while an inspection of the proof of the latter shows that
it cannot be extended to the more general $r\ge 1$.
The key issue lies in that the truncation error $|(\pt_t^\alpha-\delta_t^\alpha) B|$ for a single barrier function $B$ of type \eqref{B_L1_def}
is not dominated by $\frac12\pt_t^\alpha B$  unless $r\le \frac{2-\alpha}\alpha$.
%
To rectify this, we shall now present a new proof, which builds on the ideas used in \cite[Lemmas~2.3, 2.5, and 2.6]{Kopteva_Meng}
in a non-trivial way,
the key  being that for appropriately chosen linear combinations $W_N$ of functions of type \eqref{B_L1_def} (see~\eqref{W_N_def}),
we instead estimate the ensemble truncation error $(\pt_t^\alpha-\delta_t^\alpha) W_N$, which, as we show below, is dominated by $\frac12\pt_t^\alpha W_N$.
\end{remark}



\begin{lemma}\label{lem_stability1}
Given $\gamma\in\R$,
let the temporal mesh satisfy
 \eqref{t_grid_gen} %$\{t_j=T(j/M)^r\}_{j=0}^M$
with some $r\ge 1$.
Then\vspace{-0.2cm}
\beq\label{B_def}
\left.\!\!\!\!\begin{array}{c}
\delta_t^\alpha V^m\le t_m^{-1}(\tau/ t_m)^{\gamma}
\\[0.2cm]
\forall m\ge1,\;\;\; V^0=0
\end{array}\hspace{-0cm}\right\}
\; \Rightarrow\;%\left.\!\!\!\!\begin{array}{c}
V^m\lesssim
\tau^{-1}\U^m(\tau;\gamma)
=
\ell_\gamma t_m^{\alpha-1}(\tau/t_m)^{\min\{0,\,\gamma\}},%\\[0.2cm]%\;\;
%\forall j\ge 1,
%\end{array}\right.
%\hspace{-0.3cm}
\eeq
where $\ell_\gamma=\ell_\gamma(t_m)=1+\ln(t_m/\tau)$ for $\gamma=0$ and $\ell_\gamma:=1$ otherwise
(and the constants contained in $\lesssim$ depend only on $\alpha$, $r$, and $\gamma$).
\end{lemma}\vspace{-0.3cm}



%\smallskip
\begin{proof}
To simplify the presentation, we shall give a proof for a standard graded grid $\{t_j=T(j/M)^r\}_{j=0}^M$, while one can
extend it to a more general
\eqref{t_grid_gen} along the lines of the proof of \cite[Theorem~2.1(i)]{Kopteva_Meng}.


Fix $\alpha$ and $r$,  and note that it suffices to prove the desired result \eqref{B_def} for
\beq\label{gamma_star}
\gamma\le\gamma^*:=\min\{\alpha,\,(2-\alpha)/r\}.
\eeq
Indeed, %assuming \eqref{B_def} is established for $\gamma=\gamma^*$.
for any $\gamma>\gamma^*$, the discrete maximum/comparison principle for the operator $\delta_t^\alpha$
implies that if $\delta_t^\alpha \bar V^m= t_m^{-1}(\tau/ t_m)^{\gamma^*}$ subject to $\bar V^0=0$, then
$V^m\le \bar V^m$ $\forall\, m\ge 0$.
 Assuming \eqref{B_def} is established for $\gamma=\gamma^*$, one concludes that $V^m\le \bar V^m\lesssim t_m^{\alpha-1}$, which is equivalent to the assertion in \eqref{B_def}
 for $\gamma>\gamma^*$ under consideration.
 Thus, \eqref{gamma_star} will be assumed for the remainder of the proof.



Set %or {\color{magenta}$B(s\,;m)$??}%$\beta:=1-\alpha$ and %$B(s):=\min\bigl\{(s/t_p)t_p^{-\beta}, s^{-\beta} \bigr\}$, and also $B^j:=B(t_j)$.
\beq\label{B_L1_def}
\beta:=1-\alpha,\qquad B(s\,;t_n):=\min\bigl\{(s/t_n)\,t_n^{-\beta}, s^{-\beta} \bigr\},
%\mbox{where}\quad
%\quad
%1\le p\le n\le M,
%,\qquad B^j:=B(t_j).
\eeq
where $n \ge 1$.
%
It is shown in the proof of \cite[Lemma~2.3 (see (2.4))]{Kopteva_Meng} that
\beq\label{app_B_eq}
\Gamma(\beta)\,
\pt^\alpha_t B(t\,;t_n)
%\ge t_p^{-\beta} t^{-\alpha}\Bigl\{1-(1-\hat t_p)^{1-\alpha}\Bigr\}
\ge\left\{
\begin{array}{lll}
%\{\Gamma(1-\alpha)\}^{-1}
t_n^{-\beta} t^{-\alpha}\,(\beta t_n/t)
%\color{red}=\beta t_n^{\alpha}t^{-\alpha-1}
&=%\{\Gamma(1-\alpha)\}^{-1}
\beta\, (t_n/t)^{\alpha}\,t^{-1}
&\quad\forall\,t>t_n>0,\\
\beta^{-1}\, (t/ t_n)^{\beta}\,t_n^{-1}
&\ge 0
&\quad\forall\,0<t\le t_n.
%={\color{blue}\beta p^{r\alpha}\,(\tau^\alpha t^{-\alpha-1})}.
\end{array}\right.
\eeq
%as well as $\pt^\alpha_t B(t\,;t_n)>0$ $\forall\,t>0$.
%
Next, for any fixed $0\le N\le \infty$, consider the barrier function
\beq\label{W_N_def}
W_N(s):=\sum_{n=0}^N  c_nB(s\,;t_{p_n}),\qquad\mbox{where}\quad p_n:= 2^n p\qquad
c_n:=(t_p/t_{p_n})^\gamma,
%\color{red}=2^{-\gamma r n},
%,\quad p_N\le M.
\eeq
and $1\le p\lesssim 1$ is a sufficiently large fixed integer to be chosen later in the proof
to ensure~\eqref{bar_B_new}, so the dependence on $p$ will be shown explicitly in all bounds of type $\lesssim$ leading to~\eqref{bar_B_new}.
Note that (in view of $t_j=T(j/M)^r$)
\beq\label{c_aux2}
p_n< m\le p_{n+1}\;\;\Rightarrow\;\;
t_{p_n}/  t_m \ge t_{p_n}/  t_{p_{n+1}} \ge 2^{-r}
\;\;\mbox{and}\;\;
% 2^{\min\{r\gamma,\,0\}}\le c_n (t_p/t_m)^{-\gamma}\le 2^{\max\{r\gamma,\,0\}} .
c_n \simeq (t_p/t_m)^{\gamma}.
\eeq
Furthermore, noting that the weights $c_n=(t_p/t_{p_n})^\gamma=2^{-\gamma r n}$ form a geometric sequence, for any $N\ge 0$, one gets
\beq\label{c_aux1}
\sum_{n=0}^N c_n\lesssim S_N:=\left\{\begin{array}{ll}
1&\mbox{if~~}\gamma>0,
\\
1+\ln(t_{p_N}/t_p)&\mbox{if~~}\gamma=0,
\\
%c_N=
(t_p/t_{p_N})^\gamma&\mbox{if~~}\gamma<0.
\end{array}\right.
\eeq
In particular, for $\gamma=0$, we combined  $\sum_{n=0}^N c_n=N+1$ with
$\ln(t_{p_N}/t_p)=N\ln(2^{r})$, while
for $\gamma<0$, we used $\sum_{n=0}^N c_n\lesssim c_N$.


%such that  $p_N\le M$,
We claim %, $\forall\, m\le p_{N+1}$,
that one can choose a sufficiently large $1\le p\lesssim 1$ such that, for any fixed
$N\ge 0$,
\beq\label{bar_B_new}
W_N(t_m)\lesssim t_m^{-\beta}\,S_N\quad\mbox{and}\quad\delta_t^\alpha W_N(t_m)\gtrsim t_m^{-1}\,(t_p/ t_m)^{\gamma}\qquad \forall\, m\le p_{N+1},
\eeq
where the error constant in the second bound is independent of $N$,
but depends on %$\alpha$, $\gamma$, $r$, and a sufficiently large
$p$.

Once \eqref{bar_B_new} is established,
a comparison of $\delta^\alpha_t W_N(t_m)$ with $\delta^\alpha_t V^m$ in \eqref{B_def}
 immediately implies (in view of the discrete maximum principle for the operator $\delta_t^\alpha$
on the mesh $\{t_j,j\le  p_{N+1}\}$, and the observation that
$t_p=\tau p^r$, where $1\le p\lesssim 1$) that
$V^m\lesssim W_N(t_m)\lesssim t_m^{\alpha-1}S_N$ $\forall\,m\le p_{N+1}$.
Combining this with the  bound \eqref{c_aux1} on $S_N$ yields a bound on $V^m$ $\forall\,m\le p_{N+1}$,
which involves $(t_{p_N}/t_p)$.
The latter bound immediately implies the desired bound \eqref{B_def}
for $p_N< m\le p_{N+1}$, as for this range $t_{p_N}/t_p\le t_m/t_p\le t_m/\tau$.
As this argument applies for any fixed $N\ge 0$
(since the error constant in \eqref{bar_B_new} is independent of $N$), one gets the desired bound on $V^m$ $\forall\,p<m\le M$.
For the remaining range $ m\le p$,
one has $V^m\lesssim W_0(t_m)\lesssim t_m^{\alpha-1}S_0=t_m^{\alpha-1}$ (as $S_0=1$), which, combined with $t_m/\tau\ge 1$, again yields \eqref{bar_B_new}.
Note also that
for $\gamma>0$, one gets $S_\infty=1$, so one can simplify the above argument and use $V^m\lesssim W_\infty(t_m)\lesssim t_m^{\alpha-1}S_N$ $\forall\,m\ge 1$.

Thus, it remains to establish \eqref{bar_B_new} for any fixed $\gamma\le \gamma^*$.
The first bound in \eqref{bar_B_new} is straightforward, in view of the definition of $W_N$ combined with $B(s\,;t_{p_n)}\le s^{-\beta}$ $\forall\, n$, and \eqref{c_aux1}.
For the second bound in \eqref{bar_B_new}, we shall start with a desired bound on $\pt_t^\alpha W_N(t_m)$, and then show that
the truncation error $|(\pt_t^\alpha-\delta_t^\alpha) W_N(t_m)|$ is dominated by $\frac12\pt_t^\alpha W_N(t_m)$.
To proceed with this plan,
recall that $\pt_t^\alpha  B(t\,;t_{p_n})\ge 0$ $\forall\,t>0$.
Hence, for each $0\le n\le N$
for the range $p_n<m\le p_{n+1}$, one has
\begin{align}\label{pt_W}
\pt_t^\alpha W_N(t_m)\ge c_n\,\pt_t^\alpha  B(t_m\,;t_{p_n})&\ge c_n\{\Gamma(\beta)\}^{-1}\beta\, (t_{p_{n}}/t_m)^{\alpha}\,t_m^{-1}
\gtrsim (t_p/t_m)^{\gamma}\,t_m^{-1},
%\\
%&\ge  2^{\min\{0,\,\gamma r\}-\alpha r}\,\{\Gamma(\beta)\}^{-1}\beta\,
%(t_p/t_m)^{\gamma}t_m^{-1},
\end{align}
where we first used the first line in \eqref{app_B_eq}, and then \eqref{c_aux2}.
Similarly, for $1\le m\le p$, one gets $\pt_t^\alpha W_N(t_m)\ge c_0\,\pt_t^\alpha  B(t_m\,;t_{p})$, where $c_0=1$,
so
the second line in \eqref{app_B_eq} yields
$\pt_t^\alpha W_N(t_m)\gtrsim (t_m/t_p)^{\beta}\,t_p^{-1}\ge  p^{-r\,\max\{0,\,\beta+\gamma+1\}}\,t_m^{-1}(t_p/t_m)^\gamma$, where we also used
$t_m/t_p\ge t_1/t_p=p^{-r}$.


Our next task is to bound $|(\pt_t^\alpha-\delta_t^\alpha) W_N(t_m)|$.
When evaluating the truncation errors for each $B(t_m\,;t_{p_n})$
appearing in $W_N(t_m)$, note that while this function remains linear in $t_m$ (i.e. for $m\le{p_n}$), it does not induce any truncation error.
Hence, we immediately get $(\pt_t^\alpha-\delta_t^\alpha)W_N(t_m)=0$, and so
the second bound in \eqref{bar_B_new}, for $m\le p$.


To estimate $|(\pt_t^\alpha-\delta_t^\alpha) W_N(t_m)|$
for $m>p$, note that the evaluation in the proof of \cite[Lemma~2.3]{Kopteva_Meng} (see, in particular, \cite[(2.5)]{Kopteva_Meng}) yields, for $m>p_n$,
\begin{align*}
\Gamma(\beta)\,(\pt_t^\alpha-\delta_t^\alpha)B(t_m\,;t_{p_n})&=
\int_{t_{p_n}}^{t_m}\!\!\pt_s(B-B^I)(s\,;t_{p_n})\,(t_m-s)^{-\alpha}ds\\
&=\alpha\int_{t_{p_n}}^{t_m}\!\! (B^I-B)(s\,;t_{p_n})\,(t_m-s)^{-\alpha-1} ds.
\end{align*}
Here $B^I(s\,;t_{p_n})$ is the standard piecewise-linear interpolant of $B(s\,;t_{p_n})$ on $\{t_j\}$, and, recalling the definition of the latter,
note that
$B(s\,;t_{p_n})=B(s\,;t_{p})$ for $s>t_{p_n}$,
so
$(B^I-B)(s\,;t_{p_n})=(B^I-B)(s\,;t_{p})\ge 0$ for $s>t_{p_n}$, while $(B^I-B)(s\,;t_{p_n})=0$ for $s\le t_{p_n}$.
Combining the above observations, one concludes that, $\forall\,m> p$,
\begin{align*}
\Gamma(\beta)\,(\pt_t^\alpha-\delta_t^\alpha)W_N(t_m)
&=\sum_{n\,:\, p_n<m}c_n\,\alpha\int_{t_{p_n}}^{t_m}\!\! (B^I-B)(s\,;t_{p})\,(t_m-s)^{-\alpha-1} ds\\
&\le %S_J\,
\underbrace{\Bigl\{\sum_{n\,:\, p_n<m}c_n\Bigr\}}_{{}\lesssim S_J}\,
\alpha\int_{t_{p}}^{t_m}\!\! (B^I-B)(s\,;t_{p})\,(t_m-s)^{-\alpha-1} ds.
\end{align*}
Here
$J=J(m)$ is the maximum value in the set $\{n: p_n<m\}$, i.e.
$p_J<m\le p_{J+1}$, so $\sum_{n: p_n<m} c_n\lesssim S_J$, in view of \eqref{c_aux1}.


The above integral is (up to a constant factor) the truncation error of $B(s\,;t_{p})$ on the interval $(t_p,t_m)$, which is evaluated in
\cite[(2.6) and (2.7)]{Kopteva_Meng}. In particular, the first line of \cite[(2.7)]{Kopteva_Meng} yields the following bound
(while the second line in \cite[(2.7)]{Kopteva_Meng} already relies on the restriction $r\le\frac{2-\alpha}\alpha$, which we avoid in this proof):
\beq
%\begin{align}
\label{trunc_er_B}
\left|(\pt_t^\alpha-\delta_t^\alpha)W_N(t_m)\right|
%&\lesssim S_J\, \tau^{2/r}\!\int_{t_{p}}^{t_m}\!\!\!s^{-\beta-2/r}\,(t_m-s)^{-\alpha-1}\,\min\bigl\{1,(t_m-s)/\tau_m\bigr\}\,ds.
%\\
%&\lesssim S_J\,
%t_m^{-1}(\tau/t_m)^{2/r}
%\underbrace{\int_{\hat t_{p}}^{1}\!\hat s^{-\beta-2/r}(1-\hat s)^{-\alpha-1}\min\bigl\{1,(1-\hat s)/\hat\tau_m\bigr\}\,d\hat s}_{\lesssim\, \hat t_p^{\alpha-2/r}  +\hat\tau_m^{-\alpha}}
%\\
%
%&
\lesssim S_J\,
t_m^{-1}
\Bigl[ (\tau/t_p)^{2/r}(t_p/t_m)^\alpha + (\tau/t_m)^{(2-\alpha)/r}\Bigr].
\eeq
%\\
%\notag
%\intertext
{Alternatively, this truncation error bound can be viewed as a particular case
of a more general bound obtained in the proof of Lemma~\ref{lem_r} below (as elaborated in Remark~\ref{rem_trunc}).
Next, from \eqref{trunc_er_B} one gets}
\begin{align}
\notag
\left|(\pt_t^\alpha-\delta_t^\alpha)W_N(t_m)\right|
&\lesssim
S_J\,t_m^{-1}\,(\tau/t_p)^{(2-\alpha)/r} \Bigl[ (\tau/t_p)^{\alpha/r}(t_p/t_m)^\alpha+ (t_p/t_m)^{(2-\alpha)/r}\Bigr]
\\
%\notag
%&\lesssim
%(\tau/t_p)^{(2-\alpha)/r} \Bigl[ (t_p/t_m)^{\gamma^*}\Bigr]\,S_J\,t_m^{-1}
%\\
\notag
&\lesssim
S_J\,t_m^{-1}\,p^{-(2-\alpha)} \Bigl[ (t_p/t_m)^{\gamma^*}\Bigr],
\end{align}
where we used
$(\tau/t_p)^{(2-\alpha)/r}=(p^{-r})^{(2-\alpha)/r}=p^{-(2-\alpha)}$, as well as
$(\tau/t_p)^{\alpha/r}\le 1$, and then $t_p/t_m<1$ combined with \eqref{gamma_star}.

A comparison of the above bound with \eqref{pt_W} (in both of which, importantly, the dependence on $p$
is shown explicitly) implies that it remains
 to prove that
 \beq\label{s_J}
S_J\,\Bigl[ (t_p/t_m)^{\gamma^*}\Bigr]\lesssim (t_p/t_m)^\gamma\qquad \mbox{for any}\quad \gamma\le\gamma^*.
  \eeq
 Then, indeed, %in view of $(\tau/t_p)^{(2-\alpha)/r}=(p^{-r})^{(2-\alpha)/r}=p^{-(2-\alpha)}$
 choosing a sufficiently large $p$ ensures that $|(\pt_t^\alpha-\delta_t^\alpha)W_N(t_m)|$
 is dominated by $\frac12\pt_t^\alpha W_N(t_m)$ for any $m\ge p$, which yields the second bound in \eqref{bar_B_new}.
For $0<\gamma\le \gamma^*$, recalling \eqref{c_aux1}, one gets $S_J=1$, so \eqref{s_J} is obvious.
For $\gamma\le 0$, recall also that
$J=J(m)$ is such that
$p_J<m\le p_{J+1}$, so $t_{p_J}/t_p\le t_m/t_p$, which, combined with \eqref{c_aux1} again yields \eqref{s_J}
In particular, for $\gamma=0$, we used $S_J\le 1+\ln(t_m/t_p)$ leading to
$ S_J(t_p/t_m)^{\gamma^*} \lesssim 1$,
while for any $\gamma<0$, we used $S_J\le (t_p/t_m)^{\gamma}$ combined with
$ (t_p/t_m)^{\gamma^*}\le 1$.
This completes the proof of \eqref{bar_B_new}, and, hence, of \eqref{B_def}.
\end{proof}
