\section{Error for a paradigm example without spatial derivatives}\label{sec_error_ode}
We shall first illustrate our error analysis using the   simplest semilinear example without spatial derivatives and its disretization of type~\eqref{semi_semidiscr_method}:
\begin{subequations}\label{simplest}%\color{pass}
\begin{align}
\label{simplest_a}
\pt_t^\alpha u(t)\;+\;\;f(u)\;\;&=g(t)&&\hspace{-0cm}\mbox{for}\;\;t\in(0,T],&&\hspace{-0.0cm} u(0)=u_0,
\\[3pt]
\delta_t^\alpha U^m+F(U^m,U^{m-1})&=g(t_m)&&\hspace{-0cm}\mbox{for}\;\;m=1,\ldots,M,&&\hspace{-0.0cm} U^0=u_0.
\label{simplest_b}
\end{align}
\end{subequations}
%
It will be assumed throughout this section that \eqref{simplest_a} has a unique solution that, for some $\sigma \in (0,1) \cup (1,2)$, satisfies
\beq\label{ass_u_ode}
\textstyle\bigl|\frac{d^l}{dt^l}u(t)\bigr|\lesssim 1+t^{\sigma-l}\qquad \mbox{for}\;\; l=0,1,2,\;\;t\in(0,T].
\eeq

\noindent
{\it Example.}\,
The simplest case of \eqref{simplest_a} subject to \eqref{ass_u_ode} is
with
 $f(u):=0$ and $g(t)=c_0\,t^{\sigma-\alpha}$,
 where $c_0=\Gamma(\sigma+1)/\Gamma(\sigma+1-\alpha)$,
 which yields
 $u(t)=u_0+t^\sigma$.




\subsection{Truncation error of the L1 fractional-derivative operator}

For the truncation error associated with our discrete fractional-derivative operator $\delta_t^\alpha$, we have the following bound.
%$\color{pass}r^m:=\delta_{t}^{\alpha} u(t_m)-\pt_t^\alpha u(t_m)$, $\forall\,m\ge 1$, of the L1 method.

%For the truncation error of the discrete fractional-derivative $\delta_t^\alpha$ from \eqrefl{delta_def}, we have the following result.

\begin{lemma}[truncation error for $\delta_t^\alpha$]\label{lem_r}
%When one assumes the solution of the problem (\ref{eqn:Prob}) to be of the form given above (\ref{eqn:solass}), for $\sigma \in (0,1) \cup (1,2)$ and $r^m$ as defined in (\ref{eqn:TE}), under the conditions of the $L1$ method outlined in section \ref{section:4.2} with $r \geqslant 1$, we have
Let $u$ satisfy \eqref{ass_u_ode} with some $\sigma \in (0,1) \cup (1,2)$.
Then for the truncation error $r^m:=\delta_{t}^{\alpha} u(t_m)-\pt_t^\alpha u(t_m)$
on the temporal grid~\eqref{t_grid_gen}, one has
\beq\label{r_bound_simple}
|r^m|\lesssim  \tau^{\sigma - \alpha} (\tau/t_m)^{\gamma+1}\quad\forall\,m\ge 1,
\quad\mbox{where}\;\;
\textstyle
\gamma:=\min\bigl\{\alpha,\,\,\frac{2-\alpha}{r}+\alpha-\sigma-1\bigr\}.%\vspace{-0.5cm}
\eeq
\end{lemma}


\begin{proof}
We start by representing $r^m$ via the function $\chi := u - u^I$, where $u^I(t)$ is the piecewise linear interpolant of $u(t)$ on our temporal mesh $\{t_j\}$.
Note that $\forall\,s\in(t_{j-1},t_j)$ one has $\frac{u(t_{j})-u(t_{j-1})}{\tau_j}-u'(s)=-\chi'(s)$. Hence, combining \eqref{CaputoEquiv} and \eqref{delta_def}
and then integrating by parts yields
\beq\label{trun_int}
\Gamma(1-\alpha)\,r^m%\!=\!\sum_{j=1}^m\!\int_{t_{j-1}}^{t_j}\!\!\!\!(t_m-s)^{-\alpha}\![\delta_t u(t_j)-\pt_s u(s)]ds
=\int_0^{t_m}\!\!\!(t_m-s)^{-\alpha}\,[-\chi'(s)]ds
=\alpha%\sum_{j=1}^m\!\int_{t_{j-1}}^{t_j}
\int_0^{t_m}
\!\!\!(t_m-s)^{-\alpha-1}\chi(s)\,ds.
\eeq
%where we also used an integration by parts %.(the resulting integral well-defined in view of $|\chi(s)|\lesssim C(t_m-s)$ $\forall\,s\le t_m$).

Next, note that
for $s\in(t_{j-1},t_j)$ with $2\le j\le m$ (i.e. away from the initial singularity),
 in view of~\eqref{ass_u_ode},
one gets
$|\chi(s)|\lesssim (t_j-s)(s-t_{j-1})\,t_{j-1}^{\sigma-2}$. So,
using $t_{j-1}\simeq s \simeq t_j$ (as $j\ge 2$) and
$\tau_j\lesssim\tau^{1/r}s^{1-1/r}$,
 both of which follow from \eqref{t_grid_gen} (as discussed in Remark~\ref{rem_tau_j_1}) ,
yields
\beq\label{chi1}
|\chi(s)|%\lesssim (t_j-s)(s-t_{j-1})t_{j-1}^{\sigma-2}
\lesssim
\min \bigl\{\tau_j^2,\,(t_m-s)\,\tau_j\bigr\}\, s^{\sigma-2}
\lesssim \min\bigl\{
\tau^{2/r}s^{\sigma-2/r},\,
(t_m-s)\, \tau^{1/r}s^{\sigma-1-1/r}
\bigr\}.
\eeq

For $s\in(0,t_1)$, we shall instead use
\beq\label{chi0}
|\chi(s)|\lesssim (t_1-s)\,(s^{\sigma-1}+t_1^{\sigma-1}),
\eeq
which
holds true whether $\sigma$ is in $(0,1)$ or $(1,2)$. %[should be $(t_1-s)$]}
For $\sigma\in(0,1)$, %the factor $(s^{\sigma-1}+t_1^{\sigma-1})\simeq s^{\sigma-1}$, and
this bound follows from
$|\chi(s)|\le |u(t_1)-u(s)|+|u(t_1)-u^I(s)|$
combined with
$|u'(s)|\lesssim s^{\sigma-1}$.
To be more precise, we also employed
$|u(t_1)-u(s)|\le (t_1-s)\,\sup_{(s,t_1)}|u'|$,  as well as  $|u(t_1)-u^I(s)|=(t_1-s)\,t_1^{-1}|u(t_1)-u(0)|$, where
$|u(t_1)-u(0)|\lesssim |\int_0^{t_1}s^{\sigma-1}ds|\simeq t_1^\sigma$.
%
For $\sigma\in(1,2)$, we only have
$|u'(s)|\lesssim 1+s^{\sigma-1}\simeq 1$.
So we modify the argument used for $\sigma\in(0,1)$ by replacing $u(t)$ with $\tilde u(t):=u(t)-u(0)-u'(0)\,t$, which enjoys
$|\tilde u'(t)|\le\int_0^t|u''(s)|ds\lesssim t^{\sigma-1}$ (so $\sup_{(s,t_1)}|\tilde u'|\lesssim t_1^{\sigma-1}$),
while $\chi=u-u^I=\tilde u-\tilde u^I$.

%(while for $u(t)$ we only have $|u'(s)|\lesssim 1+s^{\sigma-1}\simeq 1$).

Now, splitting the integral in \eqref{trun_int} into three parts, over $(0,t_1)$, $(t_1,t_m^*)$, and $(t_m^*,t_m)$,
and then using \eqref{chi0} on the first interval and \eqref{chi1} elsewhere,
one gets
\begin{align*}
|r^m |{}\lesssim
\mathcal{I}_1{}&+\mathcal{I}_2+\mathcal{I}_3:=
%\underbrace{
\int_{0}^{t_1}\!\!(t_m -s)^{-\alpha -1}(t_1-s)\,(s^{\sigma-1}+t_1^{\sigma-1})\,ds
%}_\text{$\mathcal{I}_1$}
\\
&{}+
%\underbrace{
\int_{t_1}^{t_m^*}\!\!
(t_m -s)^{-\alpha -1}\tau^{2/r}s^{\sigma-2/r}\,ds
%}_\text{$\mathcal{I}_2$}
+
%\underbrace{
\int^{t_{m}}_{t_m^*}\!\!(t_m -s)^{-\alpha}\,\tau^{1/r}s^{\sigma-1-1/r}\,ds
%}_\text{$\mathcal{I}_3$}
.
\end{align*}
Here %the intermediate point
$t_m^*:=\max\{t_1,\,t_m(1-\theta)\}$, where $\theta=\theta_m:=\frac12(\tau/t_m)^{1/r}\le\frac12$
(note that the second relation in \eqref{t_grid_gen} can then be rewritten as $\tau_m/t_m\lesssim \theta_m$).

To estimate $\mathcal{I}_1$,  note that $t_m/t_1\le(t_m-s)/(t_1-s)$
implies that
$(t_m -s)^{-\alpha -1}\le (\tau/t_m)^{\alpha +1}(t_1 -s)^{-\alpha -1}$.
So, with the change of variable $\hat s:=s/t_1=s/\tau$, one gets
\begin{align*}
\mathcal{I}_1&{}\le (\tau/t_m)^{\alpha +1}\!\int_{0}^{t_1}\!\!(t_1 -s)^{-\alpha}\,(s^{\sigma-1}+t_1^{\sigma-1})\,ds
\\
&{}=\tau^{\sigma-\alpha}(\tau/t_m)^{\alpha +1}
\!\int_{0}^{1}\!\!(1 -\hat s)^{-\alpha}\,(\hat s^{\sigma-1}+1)\, d\hat s
\\[2pt]
&{}\lesssim  \tau^{\sigma-\alpha}(\tau/t_m)^{\alpha +1}.
\end{align*}

For the remaining integrals,
without loss of generality, we shall assume that $t_m^*>t_1$
(as, otherwise, $\mathcal{I}_2=0$, while $\mathcal{I}_3$ is estimated with minimal changes).
Thus,
a different change of variable $\hat s:=s/t_m$  yields
\beq\label{I2_bound}
\mathcal{I}_2
{}\lesssim t_m^{\sigma-\alpha}\,(\tau/t_m)^{2/r}
\underbrace{
\int_{\tau/t_m}^{1-\theta}
(1 -\hat s)^{-\alpha -1}\,\hat s^{\sigma-2/r} d\hat s
}_{{}\lesssim\, (\tau/t_m)^{\sigma-2/r+1}+\theta^{-\alpha}}
%\\
%&{}\lesssim
% t_m^{\sigma-\alpha}\,(\tau/t_m)^{2/r}
%\bigl[
%(\tau/t_m)^{\sigma-2/r+1}+\theta^{-\alpha}
%\bigr]
\eeq
and
\beq\label{I3_bound}
\mathcal{I}_3\lesssim
t_m^{\sigma-\alpha}\,(\tau/t_m)^{1/r}
\underbrace{
\int_{1-\theta}^{1}
(1 -\hat s)^{-\alpha }\,\hat s^{\sigma-1-1/r} d\hat s
}_{{}\lesssim\, \theta^{1-\alpha}}\,,
%\lesssim t_m^{\sigma-\alpha}\,(\tau/t_m)^{1/r}\,
%\bigl[
%\theta^{1-\alpha}
%\bigr],
\eeq
where, importantly, the bounds on the integrals in variable $\hat s$ rely on $\theta\le\frac12$.
Finally, combining the above bounds on $\mathcal{I}_1$, $\mathcal{I}_2$, and $\mathcal{I}_3$
with $r^m\lesssim
\mathcal{I}_1+\mathcal{I}_2+\mathcal{I}_3$, and
recalling that
$\theta=\frac12(\tau/t_m)^{1/r}$, one arrives at
\begin{align*}
r^m&{}\lesssim
%\mathcal{I}_1+\mathcal{I}_2+\mathcal{I}_3\lesssim
\tau^{\sigma-\alpha}(\tau/t_m)^{\alpha +1}+
 t_m^{\sigma-\alpha}\,
\bigr[(\tau/t_m)^{\sigma+1}
+
(\tau/t_m)^{(2-\alpha)/r}\bigr]
\\&{}\lesssim
\tau^{\sigma-\alpha}
\bigl[
(\tau/t_m)^{\alpha +1}+
(\tau/t_m)^{(2-\alpha)/r+\alpha-\sigma}
\bigr].
\end{align*}
As $(\tau/t_m)\le 1$, the obtained bound is equivalent to the desired assertion~\eqref{r_bound_simple}.
%\hfill$\square$
%\endproof
\end{proof}

\begin{remark}[bound \eqref{trunc_er_B} in view of Lemma~\ref{lem_r}]\label{rem_trunc}
The truncation error bound \eqref{trunc_er_B} (used in the proof of Lemma~\ref{lem_stability1})
 can be viewed as a particular case
of a more general bound obtained in the proof of Lemma~\ref{lem_r}.
To be more precise, \eqref{trunc_er_B} bounds the truncation error of $B(s\,;t_p)$ multiplied by $S_J$.
In view of \eqref{B_L1_def}, the bound \eqref{trunc_er_B} reduces to $S_J\,|r^m|$, where $r^m$ is as above,
only with the integrand on $(0,t_p)$ vanishing (as $B(s\,;t_p)$ is linear on this interval).
So we proceed with the bound on $r^m$ as before,
only now $\sigma:=-\beta=\alpha-1$, so $t_m^{\sigma-\alpha}=t_m^{-1}$,
and
 $|r^m |{}\lesssim \mathcal{I}_2+\mathcal{I}_3$ (with $\mathcal{I}_1{}$ now vanishing).
For $\mathcal{I}_2{}$ one again gets \eqref{I2_bound}, only with the lower limit $\tau/t_m$ replaced by $t_p/t_m$,
while for  $\mathcal{I}_3{}$ one gets \eqref{I3_bound}.
Combining these observations yields \eqref{trunc_er_B}.
\end{remark}


\subsection{Truncation error for the semilinear term}


Next, we estimate the truncation error associated with the discretization of $f(u)$ by $F(U^{m},U^{m-1})$.


\begin{lemma}[truncation error for $f$]\label{lem_r_f}
Under the conditions of Lemma~\ref{lem_r} and condition A1 on $F(\cdot,\cdot)$, one has
\beq\label{r_f}
\bigl|r^m_f\bigr|:=\bigl|F(u(t_m),\,u(t_{m-1}))-f(u(t_m))\bigr|
\lesssim
\bigl\{t_m^{\hat\sigma}\,(\tau/t_m)^{1/r}\bigr\}^q,\quad \hat\sigma:=\min\{\sigma,\,1\}.
\eeq
If $q=2$, then $|r^m_f|$ enjoys the same bound as $|r^m|$ in \eqref{r_bound_simple}.
\end{lemma}


\begin{proof}
(i)
In view of A1, one gets $|r^m_f|\le L |u(t_m)-u(t_{m-1})|^q$, so
$|r^m_f|^{1/q}\lesssim \int_{t_{m-1}}^{t_m} |u'(s)|\,ds$.
%
If $\sigma\in(1,2)$, by~\eqref{ass_u_ode}, $|u'(s)|\lesssim 1$ so $|r^m_f|^{1/q}\lesssim \tau_m$,
while if $\sigma\in(0,1)$, a calculation yields $|r^m_f|^{1/q}\lesssim t_m^{\sigma-1}\tau_m$.
Combining these two cases yields $|r^m_f|^{1/q}\lesssim t_m^{\hat\sigma-1}\tau_m$
%
Finally, recall from~\eqref{t_grid_gen} that $\tau_m/t_m\lesssim (\tau/t_m)^{1/r}$, so
$|r^m_f|^{1/q}\lesssim t_m^{\hat\sigma}\,(\tau/t_m)^{1/r}$, which yields the desired assertion~\eqref{r_f}.

(ii)
It remains to show that for $q=2$ the bound on $|r^m|$ from \eqref{r_bound_simple} dominates the bound on $|r^m_f|$ in~\eqref{r_f}, i.e.
\beq\label{r_dominates}
\tau^{\sigma-\alpha}(\tau/t_m)^{\gamma+1}\gtrsim t_m^{2\hat\sigma}\,(\tau/t_m)^{2/r}
\eeq
As the latter can be rewritten as $\tau^{p_1}t_m^{p_2}\gtrsim 1$ with some $p_1,\,p_2\in \R$,
clearly, it suffices to check that \eqref{r_dominates} holds true for $t_m=\tau$ and $t_m=T\simeq 1$.
This, respectively, is equivalent to
$\tau^{\sigma-\alpha}\gtrsim \tau^{2\hat\sigma}$
and
$\tau^{\sigma-\alpha+\gamma+1}\gtrsim \tau^{2/r}$.
Both hold true, the first one due to $\sigma-\alpha<\sigma\le2\hat\sigma$,
while the second follows from
$\sigma-\alpha+\gamma+1<\sigma-\alpha+\frac{2-\alpha}r+\alpha-\sigma=\frac{2-\alpha}r<2/r$.
%~\hfill$\square$
\end{proof}


\begin{remark}[Case $q=1$]\label{rem_p_1}
Using an argument
similar to the one in part (ii) of the above proof, one can show that if $q=1$, then the bound on $|r^m|$ in \eqref{r_bound_simple} does not  dominate
$|r^m_f|\lesssim
t_m^{\hat\sigma}\,(\tau/t_m)^{1/r}\simeq \tau^{\hat\sigma}\,(\tau/t_m)^{1/r-\hat\sigma}$
(for which one would need $\sigma-\alpha\le \hat\sigma$
and $\sigma-\alpha+\gamma+1\le 1/r$, with the latter never satisfied).
On the other hand, \eqref{main_stab_new} readily provides a bound $\tau^{\hat\sigma}\,\U^j(\tau;\hat\gamma)$ on the possible additional error induced by $r^m_f$, with $\hat\gamma=1/r-\hat\sigma-1\le -\hat\sigma< 0$.
Hence, a calculation shows that  %$\min\{0,\,\gamma\}=0$, so
%$\U^j(\tau;\hat\gamma)=
%\ell_\gamma
%\tau t_j^{\alpha-1}$.
%Finally,
the additional error, corresponding to $r^m_f$, is bounded by
$$
%\ell_\gamma
%\tau^{\min\{\sigma,\,1\}}\,\tau t_j^{\alpha-1}
t_m^{\min\{\sigma,\,1\}+\alpha}\,(\tau/t_m)^{1/r}\simeq M^{-1}\, t_m^{\min\{\sigma,\,1\}+\alpha-1/r},
$$
where we used $\tau^{1/r}\simeq M^{-1}$
(in view of  \eqref{t_grid_gen}). Thus, in positive time one always gets only the first-order convergence
of this additional error component.
\end{remark}


\subsection{Pointwise-in-time error bound}


\begin{theorem}[pointwise-in-time error bound]\label{the_er_simplest}
Suppose that $u$ is a unique solution  of \eqref{simplest_a}, which satisfies \eqref{ass_u_ode} with some $\sigma \in (0,1) \cup (1,2)$,
while the numerical scheme \eqref{simplest_b} for \eqref{simplest_a}
satisfies
conditions A1 with $q=2$ and  A2 on $F(\cdot,\cdot)$, with some constants $\lambda_0,\lambda_1\ge 0$.
Additionally, suppose that
the temporal grid satisfies~\eqref{t_grid_gen} and
 $\lambda_0\tau_j^{\alpha}< \{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$.
Then there exists a unique solution  $\{U^m\}$ of \eqref{simplest_b}, and $\forall\,m\ge 1$
\beq\label{E_cal_m}
|u(t_m)-U^m|\lesssim {\mathcal E}^m\!:=\!
\left\{\!\!\begin{array}{ll}
M^{-\nu r}\,t_m^{\alpha-1}&\mbox{if~}1\le r<\frac{2-\alpha}{\nu},\\[0.2cm]
%M^{-r(1-\epsilon)}\,t_m^{\alpha-(1-\epsilon)}
 M^{-(2-\alpha)}\,t_m^{\alpha-1}\,\ell_0
&\mbox{if~}r=\frac{2-\alpha}{\nu},\\[0.1cm]
M^{-(2-\alpha)}\,t_m^{\sigma-\frac{2-\alpha}{r}}%{\min\{0,\alpha-(2-\alpha)/r\}}
&\mbox{if~}r>\frac{2-\alpha}{\nu},
\end{array}\right.    %\quad
\nu:=1+\sigma-\alpha,
\eeq
where $\ell_0=\ell_0(t_m)=[1+\ln(t_m/t_1)]$.
%$$
%\nu:=1+\sigma-\alpha.
%$$

Under the above assumptions, only with $q=1$ in A1,
there exists a unique solution  $\{U^m\}$ of \eqref{simplest_b}, and
$|u(t_m)-U^m|\lesssim\widetilde{\mathcal E}^m := {\mathcal E}^m+M^{-1}\, t_m^{\min\{\sigma,\,1\}+\alpha-1/r}$
$\forall\,m\ge 1$.
\end{theorem}

\begin{corollary}[convergence in positive time]
For $t_m\gtrsim 1$ the error bound in \eqref{E_cal_m} involves
${\mathcal E}^m\simeq M^{-\min\{\nu r,\,2-\alpha\}}$ if $r\neq\frac{2-\alpha}{\nu}$
and ${\mathcal E}^m\simeq M^{-(2-\alpha)}\ln M$ otherwise.
Thus, $r>\frac{2-\alpha}{\nu}$ yields the optimal convergence rate with  ${\mathcal E}^m\simeq M^{-(2-\alpha)}$ in positive time.
\end{corollary}

\begin{corollary}[global convergence]\label{cor_glob_con}
The global-in-time version of \eqref{E_cal_m} is
\beq\label{E_cal_m_global}
\max_{t_m\le T}|u(t_m)-U^m|\lesssim \max_{m\le M}{\mathcal E}^m\simeq M^{-\min\{\sigma r,\,2-\alpha\}}.
\eeq
Thus, $r\ge \frac{2-\alpha}{\sigma}$ yields the optimal global convergence rate $M^{-(2-\alpha)}$.
\end{corollary}

\begin{remark}[earlier results as particular cases of \eqref{E_cal_m}]\label{rem_earlier_sigma}
The error bound~\eqref{E_cal_m} includes the following earlier results as particular cases:
for $\sigma = \alpha$ and $r \geqslant 1$ it is obtained using similar barrier-function techniques in \cite{Kopteva_Meng,kopteva_semilin}, while for
uniform temporal meshes (i.e. for $r=1$)  it is established using discrete Gr\"{o}nwall inequalities in
\cite{DLi1}.
The global bound \eqref{E_cal_m_global} for the particular case $\sigma=2\alpha$ is found in \cite[Theorem 4]{Gracia_2alpha}
for a fitted version of the L1 method (in which the error induced by $t^\alpha$ vanishes).
\end{remark}


\begin{proof}[Proof of Theorem~\ref{the_er_simplest}]
Recall the representation \eqref{delta_def_kappa} for the operator $\delta^\alpha_t$.
Note that $\lambda_0<\kappa_{m,m}$ $\forall\,m\ge1$.
%
Hence, given $\{U^j\}_{j<m}$, equation \eqref{simplest_b} is a nonlinear equation for $U^m$ of type
\beq\label{GUm}
G(U^m):=(\kappa_{m,m}-\lambda_0)U^m +\bigl\{F(U^m,w)+\lambda_0U^m\bigr\}=S,
\eeq
where $w= U^{m-1}$ and $S=\sum_{j=0}^{m-1}\kappa_{m,j}U^j+g(t_m)$ are in $\R$.
%For $\bar v:=(\kappa_{m,m}-\lambda_0)^{-1}(|F(0,w)|+|S|)\ge 0$
%one gets $F(\bar v,w)+\lambda_0\bar v\ge F(0,w)$ (as $F(v,w)+\lambda_0v$ is non-decreasing in $v$ by A2)
%$G(\bar v)\ge(|F(0,w)|+|S|)+F(0,w)\ge S$. Similarly, $G(- \bar v)<S$. Hence, by the intermediate value theorem, there exists a unique $U^m\in[-\bar v, \bar v]$
%(the uniqueness following from $G$ increasing)...
%\\
In view of A2, the function $G$ is continuous and strictly increasing, with $\lim_{v\rightarrow\pm\infty}G(v)=\pm\infty$, so the above equation has a unique solution $U^m\in\R$.

Next, consider the error $e^m:=U^m-u^m$, where we use the notation $u^m:=u(t_m)$ for the exact solution values at grid points.
The associated truncation errors $r^m=\delta_{t}^{\alpha} u^m-\pt_t^\alpha u(t_m)$ and $r_f^m=F(u^m,u^{m-1})-f(u^m)$ are
respectively estimated in Lemmas~\ref{lem_r} and~\ref{lem_r_f}.
Combining those with \eqref{simplest_a}, one gets
$\delta_t^\alpha u^m+F(u^m,u^{m-1})=r^m+r^{m}_f$.
Subtracting the latter from \eqref{simplest_b} yields
$e^0=0$ and
\beq\label{error_eq_simple}
\delta_t^\alpha e^m+F(u^m+e^m, U^{m-1})-F(u^m,u^{m-1})=-r^m-r^m_f\quad \forall\,m\ge 1.
\eeq
Multiply this equation by $\varsigma^m:={\rm sign}(e^m)$, equal to $1$ if $e^m\ge 1$ and $-1$ otherwise,
%(with the convention that ${\rm sign}(0)=1$).
and note that $\varsigma^me^m=|e^m|$ so
\begin{subequations}\label{error_lead}
\begin{align}
\varsigma^m(\delta_t^\alpha e^m)\ge\kappa_{m,m}|e^m|-\sum_{j=0}^{m-1}\underbrace{\kappa_{m,j}}_{>0} |e^{j}|&= \delta_t^\alpha |e^m|,
\\
\varsigma^m\bigl[F(u^m+e^m, U^{m-1})-F(u^m,U^{m-1})\bigr]&\ge -\lambda_0 |e^m|,%-\lambda_1|e^{m-1}|,
\\
\intertext{while}
\bigl|F(u^m, U^{m-1})-F(u^m, u^{m-1})\bigr|&\le \lambda_1 |e^{m-1}|,
\end{align}
\end{subequations}
where we used \eqref{delta_def} and A2 (with the second relation following from the monotonicity of $F(v, U^{m-1})+\lambda_0 v$ in $v$, in view of A2).
%Condition A1 also yields  $|F(u^m, U^{m-1})-F(u^m, u^{m-1})|\le \lambda_1|e^{m-1}|$
Thus, \eqref{error_eq_simple} multiplied by $\varsigma^m$ yields
\beq\label{error_ineq}
%e^0=0,\qquad\qquad
(\delta_t^\alpha -\lambda_0)\, |e^m|-\lambda_1|e^{m-1}|\le |r^m|+|r^m_f|\qquad \forall\,m\ge 1.
\eeq

To complete the proof, it remains to recall the bounds of Lemmas~\ref{lem_r} and~\ref{lem_r_f} respectively for $r^m$ and $r^m_f$, and then apply Theorem~\ref{theo_main_stab_semi} to get  \eqref{E_cal_m}.
The cases of A1 with $q=2$ and $q=1$  will be considered separately.

First, consider A1 with $q=2$,
when $|r^m|+|r^m_f|\lesssim \tau^{\sigma - \alpha} (\tau/t_m)^{\gamma+1}$,
with
$\gamma:=\min\bigl\{\alpha,\,\,\frac{2-\alpha}{r}-\nu\bigr\}$.
So Theorem~\ref{theo_main_stab_semi} yields
$|e^j|\lesssim
\widetilde\U^j
:=\tau^{\sigma - \alpha}\,\U^j$, i.e.
$\widetilde\U^j:=
\ell_\gamma\tau^\nu t_j^{\alpha-1}(\tau/t_j)^{\min\{0,\,\gamma\}}$, and it suffices to show that $\widetilde\U^j\simeq {\mathcal E}^j$.
%
As $\alpha>0$, one has $\min\{0,\,\gamma\}=\min\{0,\,\frac{2-\alpha}{r}-\nu\}$, and
$\ell_\gamma\neq 1$ iff $r\neq\frac{2-\alpha}{\nu} $ (which is equivalent to $\gamma\neq 0$).
Now, $r<\frac{2-\alpha}{\nu}$
%is equivalent to $\gamma>0$, so
yields
$\min\{0,\,\gamma\}=0$, so $\widetilde\U^j\simeq \tau^\nu t_j^{\alpha-1}\simeq M^{-\nu r}t_j^{\alpha-1}\simeq {\mathcal E}^j$.
Similarly,  $r=\frac{2-\alpha}{\nu}$ yields $\widetilde\U^j%\simeq \ell_0\tau t_j^{\alpha-1}
\simeq \ell_0 M^{-\nu r}t_j^{\alpha-1}\simeq {\mathcal E}^j$.
%
Finally,  $r>\frac{2-\alpha}{\nu}$ yields
 $\min\{0,\,\gamma\}=\frac{2-\alpha}{r}-\nu<0$, so
 $\widetilde\U^j\simeq \tau^\nu t_j^{\alpha-1}(\tau/t_j)^{\frac{2-\alpha}{r}-\nu}\simeq \tau^{\frac{2-\alpha}{r}}t_j^{\sigma-\frac{2-\alpha}{r}}$
so again $\widetilde\U^j\simeq M^{-(2-\alpha)} t_j^{\sigma-\frac{2-\alpha}{r}}\simeq {\mathcal E}^j$.


For the case $q=1$ in A1, the error induced by  $r^m$ is estimated similarly and remains $\lesssim {\mathcal E}^m$, while  the error induced by $r^m_f$
is estimated as described in Remark~\ref{rem_p_1}.
%~\hfill$\square$
\end{proof}



\section{Error analysis for semilinear time-fractional parabolic equations}\label{sec_semi}
In this section we shall consider discretizations of type \eqref{semi_semidiscr_method} for the semilinear problem~\eqref{problem}.
It will be assumed throughout the section that the exact solution satisfies
\eqref{ass_u_pde}, i.e. that
$\|\partial_t^l u (\cdot, t)\|_{L_p(\Omega)}\lesssim 1+t^{\sigma-l}$ for $l = 0,1,2$ and $t\in(0,T]$, where $p=2$ or $p=\infty$,
with some $\sigma \in (0,1) \cup (1,2)$.
Our purpose is to establish pointwise-in-time bounds of type~\eqref{E_cal_m} in the spatial norms $L_2(\Omega)$ and $L_\infty(\Omega)$.
Both semidiscretizations in time and  full discretizations, using finite differences and finite elements, will be addressed,
with extensions  to full discretizations carried out along the lines of \cite[\S\S6-7]{kopteva_semilin}.




\subsection{Semidiscretization in time}

\begin{theorem}\label{theo_semidiscr}
Given $p\in\{2,\infty\}$, suppose that $u$ is a unique solution  of \eqref{problem},\eqref{LL_def} with the initial condition $u_0\in L_\infty(\Omega)$,
which satisfies
$u(\cdot,t)\in H^1_0(\Omega)$ for $t\in(0,T]$ and
\eqref{ass_u_pde}
with some $\sigma \in (0,1) \cup (1,2)$.
%
Let the numerical scheme \eqref{semi_semidiscr_method} for \eqref{problem}
satisfy
conditions A1 with $q=2$ and  A2 on $F(\cdot,\cdot)$, with some constants $\lambda_0,\lambda_1\ge 0$.
Also, let
the temporal grid satisfy~\eqref{t_grid_gen} and
 $\lambda_0\tau_j^{\alpha}< \{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$.
%
Then there exists a unique solution  $\{U^m\}$ of \eqref{semi_semidiscr_method},
 with $U^m\in H^1_0(\Omega)\cap L_\infty(\Omega)$ %$\forall m\ge 1$
and
\beq\label{L1_semi_error}
\|u(\cdot,t_m)-U^m\|_{L_p(\Omega)}\lesssim {\mathcal E}^m
\qquad\forall\,m=1,\ldots,M, %\qquad p\in\{2,\infty\},
\eeq
where ${\mathcal E}^m$ is from \eqref{E_cal_m}.


Under the above assumptions, only with $q=1$ in A1, the error bound \eqref{L1_semi_error} is replaced by
$\|u(\cdot,t_m)-U^m\|_{L_p(\Omega)}\lesssim\widetilde{\mathcal E}^m={\mathcal E}^m+M^{-1}\, t_m^{\min\{\sigma,\,1\}+\alpha-1/r}$
$\forall\,m\ge 1$.
\end{theorem}

\begin{proof}
We combine the proof of Theorem~\ref{the_er_simplest} with the proof of \cite[Theorem~5.1]{kopteva_semilin}.

The existence of a unique solution $U^m\in H^1_0(\Omega)\cap L_\infty(\Omega)$ can be shown by induction using \cite[Lemma~2.1(i)]{kopteva_semilin}.
Indeed, assuming that there exist desired $\{U^j\}_{j<m}$, for $U^m$ one gets an elliptic-equation version
$\LL U^m+G(U^m)=S$
of \eqref{GUm},
where the definition of $G(\cdot)$ involves $w= U^{m-1}\in L_\infty(\Omega)$, while $S=\sum_{j=0}^{m-1}\kappa_{m,j}U^j\in L_\infty(\Omega)$.
To apply \cite[Lemma~2.1(i)]{kopteva_semilin} to this equation,
note that A2 yields the continuity of  $F(v,w)$ in $v$,  as well as
$F(v,U^{m-1}(\cdot))\in L_\infty(\Omega)$ $\forall\,v\in\R$, and the one-sided Lipschitz condition on $F$ in $v$ with the constant $\lambda_0$.


It remains to establish~\eqref{L1_semi_error}, for which it suffices to get a version of \eqref{error_ineq}, in which each
term of type $|\cdot|$ is replaced by the corresponding
 $\|\cdot\|_{L_p(\Omega)}$:
\beq\label{error_ineq_semi}
%e^0=0,\qquad\qquad
(\delta_t^\alpha -\lambda_0)\, \|e^m\|_{L_p(\Omega)}-\lambda_1\|e^{m-1}\|_{L_p(\Omega)}\le \|r^m\|_{L_p(\Omega)}+\|r^m_f\|_{L_p(\Omega)}\quad \forall\,m\ge 1.
\eeq
Indeed, once \eqref{error_ineq_semi} is true, using
%{\color{magenta}$\|\partial_t^l u (\cdot, t)\|_{L_p(\Omega)}\lesssim 1+t^{\alpha-l}$ for $l = 0,1,2$ and $t\in(0,T]$}
\eqref{ass_u_pde},
one gets bounds of type \eqref{r_bound_simple} and \eqref{r_f} %[Lemmas~\ref{lem_r} and~\ref{lem_r_f}]
on $\|r^m\|_{L_p(\Omega)}$ and $\|r^m_f\|_{L_p(\Omega)}$,
and then applies Theorem~\ref{theo_main_stab_semi} to get  \eqref{L1_semi_error}
exactly as in the proof of Theorem~\ref{the_er_simplest}.


If $p=2$, one easily gets \eqref{error_ineq_semi} by taking the $L_2(\Omega)$ inner product
 (denoted $\langle\cdot,\cdot\rangle$) of $e^m$
with the following version of \eqref{error_eq_simple}:
\beq\label{err_eq_semi}
\delta_t^\alpha e^m +\LL e^m+F(u^m+e^m, U^{m-1})-F(u^m,u^{m-1})=-r^m-r^m_f\quad\;\; \forall\,m\ge 1.
\eeq
%
Then, \eqref{error_ineq_semi}, indeed, follows from
$\langle\LL e^m,e^m\rangle\ge0$ (in view of $c-\frac12\sum_{k=1}^d\pt_{x_k}\!b_k\ge 0$) combined with
 the following version of \eqref{error_lead} (in which $\|\cdot\|=\|\cdot\|_{L_2(\Omega)}$):
\begin{align*}
\bigl\langle\delta_t^\alpha e^m,\,e^m\bigr\rangle \ge\kappa_{m,m}\|e^m\|^2-\sum_{j=0}^{m-1}\underbrace{\kappa_{m,j}}_{>0} \|e^{j}\|\,\|e^m\|&=
\bigl(\delta_t^\alpha \|e^m\|\bigr)\,\|e^m\|,
\\
\bigl\langle F(u^m+e^m, U^{m-1})-F(u^m,U^{m-1}),\,e^m\bigr\rangle&\ge -\lambda_0 \|e^m\|^2,%-\lambda_1|e^{m-1}|,
\\[0.3cm]
\bigl|\bigl\langle F(u^m, U^{m-1})-F(u^m, u^{m-1}),\,e^m\bigr\rangle\bigr|&\le \lambda_1 \|e^{m-1}\|\,\|e^m\|.
\end{align*}

Finally, if $p=\infty$, one gets \eqref{error_ineq_semi}
by multiplying \eqref{err_eq_semi}
with
$\varsigma^m:={\rm sign}(e^m)\in L_\infty(\Omega)$
and then employing \eqref{error_lead}, which yields an elliptic-equation version of
\eqref{error_ineq} (in which $\|\cdot\|=\|\cdot\|_{L_\infty(\Omega)}$):
\beq\label{error_ineq}
\varsigma^m\,(\LL+\kappa_{m,m})e^m
\le \mu^m:=
\!\sum_{j=0}^{m-1}\!\kappa_{m,j} \|e^{j}\|
+\lambda_0 \|e^m\|
+\lambda_1\|e^{m-1}\|+ \|r^m\|+\|r^m_f\|.\!
%\qquad \forall\,m\ge 1.
\eeq
The above equation holds $\forall\,x\in\Omega$ (and $\forall\,m\ge 1$). If $\|e^m\|=|e^m(x^*)|=(\varsigma^m\, e^m)(x^*)$ for some $x^*\in\Omega$, and $\LL e^m(x^*)$ is defined
in the classical sense, then $(\varsigma^m\,\LL e^m)(x^*)\ge 0$, so \eqref{error_ineq} implies $\kappa_{m,m}\|e^m\|\le \mu^m$, which immediately implies
the desired \eqref{error_ineq_semi}
for $p=\infty$.
%
The same result also follows from \eqref{error_ineq}
for less smooth $e^m\in H^1_0(\Omega)\cap L_\infty(\Omega)$
(note that $\LL e^m \in L_\infty(\Omega)$),
as described in Remark~\ref{rem_weak_max}.
%\hfill$\square$
\end{proof}

\begin{remark}[weak maximum principles for functions in $H^1_0(\Omega)$]\label{rem_weak_max}
For weak maximum principles for functions in $H^1_0(\Omega)$, we refer the reader to
\cite[\S8.1]{GTru}.
For our purposes, the following result should be applied to \eqref{error_ineq}:\\
If
%the operator $\LL$ is of type~\eqref{LL_def},
$v\in H_0^1(\Omega)\cap L_\infty(\Omega)$ and  $\LL v\in L_\infty(\Omega)$, while $\varsigma:={\rm sign}(v)$,
then, with any positive constants $\kappa$ and $\mu$,
$$
%{\rm sign}(v)
\varsigma\, \bigl(\LL+\kappa\bigr)v\le \mu\quad\Rightarrow\quad \kappa\,\|v\|_{L_\infty}\le \mu.
$$
Indeed, consider $w:=( v-\mu/\kappa)^+=\max\{ v-\mu/\kappa\,,0\}$, which is in $H_0^1(\Omega)$ \cite[Lemma~7.6]{GTru}.
Assuming this function has non-empty support $\Omega^+:=\{\kappa v>\mu\}\subseteq\Omega$,
one gets $(\LL+\kappa)[w+\mu/\kappa]=(\LL+\kappa)v\le \mu$ in $\Omega^+$. Combining this with $(\LL+\kappa) [\mu/\kappa]=(\mu/\kappa)\,\LL[1]+\mu \ge \mu$ yields
$(\LL+\kappa)w\le 0$ in $\Omega^+$.
Taking the inner $L_2(\Omega^+)$ product of the latter bound with $w\ge 0$, and noting that
 $\int_{\Omega^+}\!w\,\LL w\ge 0$ (for any $w\in H^1_0(\Omega^+)$, one gets $\int_{\Omega^+}\!\kappa w^2\le 0$. This implies that $\Omega^+$ is empty, so $\kappa v\le \mu$ in $\Omega$.
Similarly,
rewriting  $\text{sign}(v)\, (\LL+\kappa)v\le \mu$ as
$\text{sign}(-v)\, (\LL+\kappa)[-v]\le \mu$ yields $\kappa(-v)\le \mu$.
The desired assertion $\kappa\|v\|_{L_\infty(\Omega)}\le \mu$ follows.
\end{remark}



\subsection{Maximum norm error for finite difference discretizations}\label{ssec_FD}

In  the spatial domain $\Omega=(0,1)^d\subset\R^d$,
%To discretize it in space,
let
 $\bar\Omega_h$ be the tensor product of $d$ uniform meshes $\{ih\}_{i=0}^N$,
 with $\Omega_h:=\bar\Omega_h\backslash\pt\Omega$ denoting the set of interior mesh nodes.
Now, consider a finite difference discretization in space of \eqref{semi_semidiscr_method}
in the form
\beq\label{FD_method}
\delta_t^\alpha U^m(z) +\LL_h U^m(z)+ F(U^m(z),U^{m-1}(z))=0\quad\mbox{for}\;\;z\in\Omega_h%,\quad U^m=0\;\;\mbox{on}\;\pt\Omega\quad\forall\,m=1,\ldots,M;\quad U^0=u_0.
\eeq
subject to $U^m=0$ in $\bar\Omega_h\cap\pt\Omega$ $\forall\,m\ge 1$ and $U^0=u_0$ in $\bar\Omega_h$.
 Here the discrete spatial operator $\LL_h$
is a standard finite difference operator defined,
using the standard orthonormal basis $\{\mathbf{i}_k\}_{k=1}^d$ in $\R^d$
(such that $z=(z_1,\ldots,z_d)=\sum_{k=1}^d z_k\, \mathbf{i}_k$ for any $z\in\R^d$), by
\begin{align*}
&\LL_hV(z):=\\[-0.1cm]
%\pt_{x_k}(a_k(x)\,\pt_{x_k}u)(z)\;\;\mapsto\;\;
&\sum_{k=1}^d h^{-2}\Bigl\{a_k(z+{\textstyle \frac12}h\mathbf{i}_k)\,\bigl[V(z)-V(z+h\mathbf{i}_k)\bigr]+a_k(z-{\textstyle \frac12}h\mathbf{i}_k)\,\bigl[V(z)-V(z-h\mathbf{i}_k)\bigr]\Bigr\}\\[-0.4cm]
&\qquad\quad{}+\sum_{k=1}^d{\textstyle \frac12}h^{-1}\, b_k(z)\,\bigl[V(z+h\mathbf{i}_k)-V(z-h\mathbf{i}_k)\bigr] +c(z)\,V(z)
\quad\qquad\mbox{for}\;\;z\in\Omega_h.
\end{align*}
(Here the terms in the first and second sums respectively discretize $-\pt_{x_k}\!(a_k\,\pt_{x_k}\!u)$ and $b_k\, \pt_{x_k}\!u$ from \eqref{LL_def}.)



Assuming that $h$ is sufficiently small, to be more precise,
\beq\label{d_max_pr}
h^{-1}\ge \max_{k=1,\ldots,d}\bigl\{{\textstyle\frac12}\|b_k\|_{L_\infty(\Omega)}\,\|a_k^{-1}\|_{L_\infty(\Omega)}\bigr\},
\eeq
and that $c\ge 0$ in $\Omega\times(0,T]$,
one can easily check that  the spatial discrete operator $\LL_h$ is associated with an M-matrix,
while $\LL_h $ satisfies the discrete maximum principle.
Then, \cite[Lemma~2.5(i)]{kopteva_semilin} yields the existence of a unique solution $\{U^j\}_{j=0}^m$ for the fully discrete problem~\eqref{FD_method}.


%The error of this method will be bounded in the nodal maximum norm, denoted
%$\|\cdot\|_{L_\infty(\Omega_h)}:=\max_{\Omega_h}|\cdot|$.

Furthermore, under the conditions of Theorem~\ref{theo_semidiscr}, additionally assuming \eqref{d_max_pr}
and
$\|\pt_{x_k}^l u(\cdot,t)\|_{L_\infty(\Omega)}\lesssim 1$ for $l=3,4$, $k=1,\ldots,d$, $t\in(0,T]$,
one gets a version of~\eqref{L1_semi_error}
for the nodal maximum norm of the error
$$
%\|u(\cdot,t_m)-U^m\|_{L_\infty(\Omega_h)}
\max_{\Omega_h}|u(\cdot,t_m)-U^m|
\lesssim {\mathcal E}^m+t_m^{\alpha}\, h^2
$$
if $q=2$, while
${\mathcal E}^m$ in the above bound is replaced by $\widetilde{\mathcal E}^m$
if $q=1$.

The proof of the above error bounds, to a large degree, imitates the proof of Theorem~\ref{theo_semidiscr} for $p=\infty$.
Additionally, one needs to take into account the truncation error $O(h^2)$ induced by the finite difference discretization $\LL_h$ of $\LL$,
which is estimated using the same stability result~\eqref{main_stab_new} only with $\gamma=-1$.



