\section{Quasilinear time-fractional subdiffusion equations}\label{sec_quasi}


Since the coefficients in \eqref{problem} are functions of $x$ and $t$,
our error analysis framework naturally extends to the quasilinear case, as we  now demonstrate.


Consider a quasilinear version of~\eqref{problem},\eqref{CaputoEquiv}:
\beq\label{problem_q}
\begin{array}{l}
\pt_t^{\alpha}u+\QQ u+f(x,t,u)=0\quad\mbox{for}\;\;(x,t)\in\Omega\times(0,T],\\[0.2cm]
u(x,t)=0\quad\mbox{for}\;\;(x,t)\in\pt\Omega\times(0,T],\qquad
u(x,0)=u_0(x)\quad\mbox{for}\;\;x\in\Omega.
\end{array}
\eeq
%{\color{red}$f(u)$ replaced by $f(x,t,u)$??}
Here the quasilinear spatial operator $\QQ$ is defined by
\beq\label{LL_quasi}
\QQ u := -\sum_{k=1}^d \pt_{x_k}\!\Bigl\{a_k(x,t,u)\,\pt_{x_k}\!u + b_k(x,t,u) \Bigr\},%+c(x,t)\, u,
\eeq
%(compared to \eqref{LL_def}, the term $c(x,t)\, u$  is absorbed by $f(x,t,u)$)
under the following conditions
\beq\label{C_a}
\begin{array}{rl}
0<c_a\le a_k(x,t,v)&\le \bar c_a,
\quad
\\[0.2cm]
|a_k(x,t,v)-a_k(x,t,w)|&\le C_a|v-w|,
\quad
\\[0.2cm]
|b_k(x,t,v)-b_k(x,t,w)|&\le C_b|v-w|,
\quad\forall x\in\Omega,\;\;t>0 ,\;\;  v,\,w\in\R,
\end{array}
\eeq
with some constants $\bar c_a\ge c_a>0$, $C_a\ge 0$, and $C_b\ge0$.


Let $f$ in \eqref{problem_q} be continuous in $s$ and  satisfy $f(\cdot,t,s)\in L_\infty(\Omega)$ for all $t>0$ and $s\in\R$,
and the one-sided Lipschitz condition
\beq\label{ass_f}
f(x,t,v)-f(x,t,w)\ge -\lambda_0[v-w]\qquad \forall v\ge w,\;\; x\in\Omega,\;\;t>0
\eeq
with some constant $\lambda\ge0$.
If $f=f(u)$, the above \eqref{ass_f} becomes equivalent to A1 and A2 for $F(v,w):=f(v)$ with constants $L=0$ and $\lambda_1=0$.
Note also that \eqref{ass_f} was assumed in \cite{kopteva_semilin} when considering semilinear subdiffusion equations.


To simplify the presentation, we shall restrict our consideration to the fully implicit semidiscretization
of \eqref{problem_q} in time of L1 type (compare with \eqref{semi_semidiscr_method}):
\beq\label{semi_semidiscr_method_quasi}%\color{pass}
\delta_t^\alpha U^m +\QQ^m U^m+ f(\cdot,t_m,U^m)=0\quad\mbox{in}\;\Omega,%\qquad U^m=0\;\;\mbox{on}\;\pt\Omega,%\quad\forall\,m=1,\ldots,M;\quad U^0=u_0.
\eeq
$\forall\,m\ge 1$, subject to  $U^m=0$\ on $\pt\Omega$ and $U^0=u_0$,
where $\QQ^m=\QQ\big|_{t=t_m}$.
%
For each $m$, equation~\eqref{semi_semidiscr_method_quasi} is a quasilinear elliptic equation.
Existence (and uniqueness) of solutions of such equations is typically established by the application of topological fixed point theorems
in appropriate function spaces
%[+Lad]
\cite{GTru,evans}, as we illustrate in \S\ref{ssec_existence}.



\begin{theorem}[error bound]\label{theo_semidiscr_quasi}
Suppose that problem \eqref{problem_q},\,\eqref{LL_quasi},
under conditions \eqref{C_a},\,\eqref{ass_f}, has a unique solution
%with the initial condition $u_0\in L_\infty(\Omega)$,
$u$, which satisfies
\eqref{ass_u_pde}
for $p=2$ and some constant $\sigma \in (0,1) \cup (1,2)$,
and  $\|\nabla u(\cdot,t)\|_{L_\infty(\Omega)}\le C_u$ $\forall\, t\in[0,T]$  for some constant $C_u$.
%with and
%$\|\partial_t^l u (\cdot, t)\|_{L_2(\Omega)}\lesssim 1+t^{\sigma-l}$ for $l = 0,1,2$ and $t\in(0,T]$,
%
Let
%the numerical scheme \eqref{semi_semidiscr_method_quasi} for \eqref{problem_q}
%satisfy
%conditions A1  and  A2 on $F(\cdot,\cdot)$, with some constants $\lambda_0\ge 0$.
%Also, let
the temporal grid satisfy~\eqref{t_grid_gen} and
 $\lambda\tau_j^{\alpha}< \{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$,
 where $\lambda:=\lambda_0 +{(C_aC_u+C_b\sqrt{d})^2}/(4c_a)$.
%
Then a solution  $U^m\in H^1_0(\Omega)$ of \eqref{semi_semidiscr_method_quasi},
 %with $U^m\in H^1_0(\Omega)\cap L_\infty(\Omega)$ %$\forall m\ge 1$
satisfies
\beq\label{L1_q_error}
\|u(\cdot,t_m)-U^m\|_{L_2(\Omega)}\lesssim {\mathcal E}^m
\qquad\forall\,m=1,\ldots,M, %\qquad p\in\{2,\infty\},
\eeq
where ${\mathcal E}^m$ is from \eqref{E_cal_m}.
%
%\color{blue}
%(ii) If $a_k=a(x,t)$ (i.e. are independent of $u$) or $a_k=a(t,u)$ (i.e. are independent of $k$ and $x$),
%then the above result remains true under the weaker assumption that $u(\cdot,t)\in H_0^1(\Omega)$ for $t\in(0,T]$
%and $C_u:=0$ used in the definition of $\lambda$.
\end{theorem}


\begin{proof}
%{\color{magenta}(i)}
Throughout the proof, let $\|\cdot\|=\|\cdot\|_{L_2(\Omega)}$.
%
For the error
$e^m=U^m-u^m$
we again get a version of \eqref{err_eq_semi} $\forall\,m\ge 1$, in which $\LL e^m$ is now replaced by $\QQ^m U^m -\QQ^m u^m$
(and also $F(v,\cdot)$ is replaced by $f(\cdot,t_m, v)$, and $r^{m}_f=0$):
\beq\label{err_eq_quasi}
\delta_t^\alpha e^m +\bigl\{\QQ^m U^m-\QQ^m u^m\bigr\}
%+F(u^m+e^m, U^{m-1})-F(u^m,u^{m-1})
+f(\cdot,t_m,u^m+e^m)-f(\cdot,t_m,u^m)
=-r^m%-r^m_f
%\quad\;\; \forall\,m\ge 1.
\eeq
To be more precise, \eqref{err_eq_quasi} is obtained by subtracting $\delta_t^\alpha u^m+\QQ^m u^m%+F(u^m,u^{m-1})
+f(\cdot,t_m,u^m)=r^m
%+r^{m}_f
$
from \eqref{semi_semidiscr_method_quasi}.
Next, taking  the $L_2(\Omega)$ inner product
 of $e^m$
with~\eqref{err_eq_quasi},
one gets (similarly to deriving \eqref{error_ineq_semi} for $p=2$  in the proof of Theorem~\ref{theo_semidiscr})
%(in which )
\beq\label{er_aux_q}
(\delta_t^\alpha -\lambda_0)\, \|e^m\|
%-\lambda_1\|e^{m-1}\|
+\frac{\langle \QQ^m U^m-\QQ^m u^m, e^m\rangle}{\|e^m\|}
\le\|r^m\|\,.
%+\|r^m_f\|.
\eeq
Here, in view of \eqref{LL_quasi},
$$
\langle \QQ^m U^m-\QQ^m u^m, e^m\rangle
=\sum_{k=1}^d  \langle -\pt_{x_k} w^m_k \,, e^m\rangle
=\sum_{k=1}^d  \langle w^m_k \,, \pt_{x_k} e^m\rangle,
$$
where
$$
w^m_k=a_k(\cdot,t_m,U^m)\,\pt_{x_k}\!U^m- a_k(\cdot,t_m,u^m)\,\pt_{x_k}\!u^m
%+\bigl[a_k(\cdot,t,U)-a_k(\cdot,t,u)\bigr]\,\pt_{x_k}\!u^m
+b_k(\cdot,t_m,U^m)-b_k(\cdot,t_m,u^m).
$$
A calculation using \eqref{C_a} shows that
$$
w^m_k\ge a_k(\cdot,t_m,U^m)\,\pt_{x_k}\!e^m-C_a\,|e^m|\,|\pt_{x_k}\!u^m|-C_b|e^m|.
$$
Hence, with  $\|\nabla u^m\|_{L_\infty(\Omega)}\le C_u$, one gets
\begin{align*}
\langle \QQ^m U^m-\QQ^m u^m, e^m\rangle&=\sum_{k=1}^d  \langle w^m_k \,, \pt_{x_k} e^m\rangle
\\[2pt]
&\ge c_a\|\nabla e^m\|^2-C_aC_u \|\nabla e^m\|\,\|e^m\|- C_b\sqrt{d}\,\|\nabla e^m\|\,\|e^m\|
\\[2pt]
&\ge -\frac{(C_aC_u+C_b\sqrt{d})^2}{4c_a}\|e^m\|^2.
\end{align*}
%where we used \eqref{C_a} and $C_u=\max_{t\in[0,T]}\|\nabla u(\cdot,t)\|_{L_\infty(\Omega)}$.
Combining this with \eqref{er_aux_q}, one arrives at
$$
(\delta_t^\alpha -\lambda)\, \|e^m\|%-\lambda_1\|e^{m-1}\|
%+\langle \QQ U^m-\QQ u^m, e^m\rangle
\le \|r^m\|,%+\|r^m_f\|,
\quad\mbox{where}\;\;
\lambda=\lambda_0 +\frac{(C_aC_u+C_b\sqrt{d})^2}{4c_a}.
$$
Now, using
\eqref{ass_u_pde}, one gets a bound of type \eqref{r_bound_simple}
on $\|r^m\|$,
and then applies Theorem~\ref{theo_main_stab_semi} to get  \eqref{L1_q_error}
exactly as in the proof of Theorem~\ref{the_er_simplest}.
\hfill%$\square$
\end{proof}

\subsection{Existence and uniqueness for \eqref{semi_semidiscr_method_quasi} with $a_k=a(u)$}\label{ssec_existence}
Here we shall assume, similarly to \cite{Jin2024,Plociniczak2023}, that
 the diffusion coefficients $a_k:=a(u)$ $\forall\,k$, while still allowing a non-self-adjoint case of $\QQ$ in \eqref{LL_quasi}.
Note also that the following existence and uniqueness result seamlessly applies to the case $a_k=a(t,u)$.

\begin{lemma}\label{lem_exist_quasi}
Under conditions \eqref{C_a},\,\eqref{ass_f},
let
the temporal grid satisfy
 $\lambda\tau_j^{\alpha}< \{\Gamma(2-\alpha)\}^{-1}$ $\forall\,j\ge1$,
 where $\lambda$ is from Theorem~\ref{theo_semidiscr_quasi},
and suppose that $U^0\in L_2(\Omega)$. Then there exists a unique solution $U^m\in H^1_0(\Omega)$ of \eqref{semi_semidiscr_method_quasi} $\forall\,m\ge 1$.
\end{lemma}

\begin{proof}
\newcommand{\TTT}{\mathbb T}
Set $A(w):=\int_0^w a(s)\,ds$; then %$A'=a$ and
$\QQ w = -\sum_{k=1}^d \pt_{x_k}\!\bigl\{\pt_{x_k}\!A(w) + b_k(x,t,w) \bigr\}$.
Now, assuming the desired assertion is proved for $\{U^j\}_{j<m}$,
and also recalling \eqref{delta_def_kappa}, one sees that
 \eqref{semi_semidiscr_method_quasi} is a quasilinear elliptic equation for $U^m$, any solution of which is
 a fixed point of the nonlinear mapping $\TTT$ in $L_2(\Omega)$, defined by $w=\TTT v$, where
\beq\label{T_def_A}
-\sum_{k=1}^d \pt_{x_k}^2\!A(w) + [\kappa_{m,m}w+f(\cdot,t_m,w)]=\sum_{k=1}^d \pt_{x_k}\! b_k(x,t,v) +S,
\eeq
subject to $w=0$ on $\pt\Omega$,
with $S=\sum_{j<m}\kappa_{m,j}U^j\in L_2(\Omega)$.
%
Taking the difference of \eqref{T_def_A} for any $w_1=\TTT v_1$ and $w_2=\TTT v_2$, and then the inner product of the latter with $A(w_1)-A(w_2)=:\omega[w_1-w_2]$,
yields
$$
\|\nabla(\omega[w_1-w_2])\|^2+(\kappa_{m,m}-\lambda_0)c_a\|w_1-w_2\|^2\le C_b\sqrt{d}\,\|v_1-v_2\|\,\|\nabla(\omega[w_1-w_2])\|.
$$
Here we used
the standard linearization of $A(w_1)-A(w_2)$ yielding $\omega=\int_0^1 a(sw_1+[1-s]w_2)\,ds\in L_\infty(\Omega)$
(as its range is within $[c_a,\bar c_a]$) and
$\omega\ge c_a>0$.
%$\langle A(w_1)-A(w_2),w_1-w_2\rangle\ge c_a\|w_1-w_2\|^2$
Hence, a calculation shows that
\beq\label{contraction}
(\kappa_{m,m}-\lambda_0)\,c_a\|w_1-w_2\|^2\le\frac{C_b^2 d}{4}\|v_1-v_2\|^2.
\eeq
The definition of $\kappa_{m,m}$ in \eqref{delta_def_kappa},
combined with the restriction on $\tau_m$,
implies that $\kappa_{m,m}<\lambda$, while  $\lambda=\lambda_0 +{(C_aC_u+C_b\sqrt{d})^2}/(4c_a)$.
Thus $\TTT$ is a strict contraction, so, by Banach's fixed point theorem \cite[\S9.2.1]{evans}, one concludes that $\TTT$ indeed has a unique fixed point
in $L_2(\Omega)$, which, in view of \eqref{T_def_A}, is also in $H^1_0(\Omega)$.
%\hfill%$\square$

Importantly, the above argument relies on the semilinear equation \eqref{T_def_A} having a unique solution in $H_0^1(\Omega)$ for any $v, S\in L_2(\Omega)$.
The uniqueness is straightforward from \eqref{contraction} with $v_1=v_2$.
The existence
of $w\in H_0^1(\Omega)$
can be shown, for example,
applying the method of  sub- and super-solutions \cite[\S9.3]{evans}
to \eqref{T_def_A} rewritten for $W:=A(w)$, with the left-hand side
$-\sum_{k=1}^d \pt_{x_k}^2 W+\hat f(\cdot, A^{-1}(W))$,
where
$\hat f(\cdot,w):=\kappa_{m,m}w +f(\cdot,t_m,w)$ is increasing in $w$,
and
$A^{-1}:\R\rightarrow \R$ denotes the inverse of $A:\R\rightarrow \R$.
\end{proof}





