		\vspace{-1em}
		\begin{tabular}{l|l|l}
			\textit{Real-world constraint} &
			\textit{Regex equivalent} &
			\textit{Notes}
			\\
			\hline
			a line with an email & $\texttt{\caret{}.\st{}@.\st\dollar{}}$ 
			& $\texttt{\caret{}}\eqdef\lb{\sanchor\alt\bslash{n}}$ and
			$\texttt{\dollar{}}\eqdef\la{\eanchor\alt\bslash{n}}$
			\\
