A \textit{theory} is the class of all interpretations (thus called $\T$-interpretations, or the models of $\T$) satisfying some set of sentences $\ax{\T}$ (which does not need to be computably enumerable), called the {\em axiomatization} of $\T$.
A formula $\varphi$ is then: 
{($\T$-)}\textit{satisfiable} if there is a 
{($\T$-)}interpretation that satisfies $\varphi$; 
{($\T$-)}\textit{equivalent} to a formula $\psi$ if every 
{($\T$-)}interpretation that satisfies one also satisfies the other; and 
{($\T$-)}\textit{valid} if every ($\T$-)interpretation satisfies $\varphi$, denoted $\vDash\varphi$ 
($\vDash_{\T}\varphi$). 

We denote, for $n\leq m$, the set $\{n, \ldots, m\}$ by $[n,m]$; if $n=0$, we simplify it to $[m]$. 
Of course, $|[n,m]|=m-n+1$, and $|[m]|=m+1$.
Furthermore, $A\cap[1,n]$ will be denoted by $\An$; we denote $\{|\dom{\A}| : \text{$\A$ is a $\T$-interpretation}\}\cap\mathbb{N}$ by $\spec{\T}$, and we define $\specn{\T}$ as $\spec{\T}\cap [1,n]$. 
Analogously, 
$\spec{\T,\phi}$
is the set of finite cardinalities of $\T$-interpretations that satisfy $\phi$.
%
We can then also define $\specn{\T,\phi}$ as $\spec{\T,\phi}\cap[1,n]$. 
%



\subsection{Number theory}\label{number theory}

The {\em natural density}~\cite{Tenenbaum} of a set $A\subseteq \mathbb{N}$  is the following real number,
if it exists (and then we say the density of $A$ is well-defined):
% $\mu(A)=\LIM |A\cap \{0, \ldots, n\}|/|\{0, \ldots , n\}|$
$\mu(A)=\LIM |A\cap [n]|/|[n]|$.

\begin{example}
    %\begin{enumerate}
        %\item 
        Consider the set $A$ of even non-negative integers: we then have that $\mu(A)$ is the limit of the sequence $a_{n}$ which equals $\fr{(n+2)}{2(n+1)}$ if $n$ is even, and $\fr{1}{2}$ if it is odd, meaning that $\mu(A)$ is well-defined and equals $\fr{1}{2}$.
\end{example}



It is easy to prove that $\mu$ satisfies, for all disjoint sets $A$ and $B$ for which it is defined: $0\leq \mu(A)$; $\mu(\mathbb{N})=1$; and $\mu(A\cup B)=\mu(A)+\mu(B)$.
The subsets of the non-negative integers we shall calculate the natural density of are sets of finite cardinalities of interpretations in a theory: since they are never zero (as we assume $\dom{\A}$ is never empty), we can change $\mu(A)$ to be the limit of the ratio of $|A\cap\{1,\ldots,n\}|$ to $|\{1,\ldots,n\}|=n$.\footnote{Of course, this does not change the value of $\mu(A)$.}
With this, we can finally define the natural density of a theory (relative to a quantifier-free formula or not) as the natural density of its spectrum: $\mu(\T)=\LIM \fr{|\specn{\T}|}{|[1,n]|}$, and $\mu(\T,\phi)=\LIM \fr{|\specn{\T,\phi}|}{|[1,n]|}$.
%






\begin{definition}\label{definition computable number}
    Let $r\in\mathbb{R}$. $r$ is computable~\cite{Turing} if there are computable sequences 
    %(computable functions from $\mathbb{N}$) 
    $\{a_{n}\}_{n\in\mathbb{N}}$ in $\mathbb{Z}$ and $\{b_{n}\}_{n\in\mathbb{N}}$ in $\No $ with $\LIM \fr{a_{n}}{b_{n}}=r$.
\end{definition}

\begin{example}\label{computable number examples}~
          Every rational number $\fr{p}{q}$ is computable: just take $a_{n}=p$ and $b_{n}=q$.
          The number $\sum_{n=1}^{\infty}2^{-\bb(n)}=0.57824...$ is not computable, for $\bb$ the busy beaver function~\cite{Rado}, which
          maps $n\in\mathbb{N}$ to the maximum number of $1$’s a Turing machine with at most $n$ states can write when it halts, assuming the tape begins with only $0$’s.
          Now, $0.57824...$.
          is the limit of $\fr{5}{10}, \fr{57}{100}, \fr{578}{1000},\ldots$.
          Consider then the theory $\T$ with models of size $1$ through $5$, $11$ through $52=57-5$, $101$ through $521=578-57$, and so on.
          Its density is the limit of the fractions $\fr{5}{10}$, $\fr{57}{100}$, $\fr{578}{1000}$ and so on, i.e. $0.57824...$, although this number is irrational.
          More generally, any $0\leq r\leq 1$ is the density of some theory.
\end{example}




\subsection{Theory combination}\label{theory combination}
In what follows, let $\Sigma$ be an arbitrary signature and $\T$ be a $\Sigma$-theory.

$\T$ is \textbf{stably infinite}~\cite{NelsonOppen} if for every satisfiable quantifier-free formula $\phi$, there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|\geq \aleph_{0}$. $\T$ is \textbf{smooth} when, for all quantifier-free formulas $\phi$, $\T$-interpretations $\A$ that satisfy $\phi$, and cardinals $\kappa>|\dom{\A}|$, there exists a $\T$-interpretation $\B$ that satisfies $\phi$ with $|\dom{\B}|=\kappa$.
Notice that being smooth implies being stably infinite.

\begin{example}
    The theory axiomatized by $\{\psi_{\geq 3}\}$ is smooth, as we can always add more elements to an interpretation.
    % the theory with axiomatization $\{\psi_{=3}\vee\psi_{\geq 5}\}$ is stably infinite but not smooth, as there is no interpretation of this theory with cardinality $4$ that satisfies $x=x$;
    % finally, the axiomatization $\{\psi_{\leq 3}\}$ gives a theory that is neither stably infinite nor smooth, having no infinite interpretations.
\end{example}

%\noindent\textbf{Witnessability}
$\T$ is \textbf{finitely witnessable}~\cite{RanRinZar} when there is a computable function $\wit$ (called a witness) from the quantifier-free formulas into themselves such that, for every quantifier-free formula $\phi$: $(\textit{I})$ $\phi$ and $\Exists{\overarrow{x}}\wit(\phi)$ are $\T$-equivalent, where $\overarrow{x}=\vars(\wit(\phi))\setminus\vars(\phi)$; and $(\textit{II})$ if $\wit(\phi)$ is $\T$-satisfiable, then there is a $\T$-interpretation $\A$ that satisfies $\wit(\phi)$ and, in addition, $\dom{\A}=\vars(\wit(\phi))^{\A}$ (that is, every element of $\dom{\A}$ is the interpretation of a variable in $\wit(\phi)$). 
%
Now, given a finite set of variables $V$ on the signature $\Sigma$, and an equivalence $E$ on $V$, the \textbf{arrangement} on $V$ induced by $E$, written $\delta_{V}^{E}$ or $\delta_{V}$ if $E$ is clear from context, is the formula $\bigwedge_{xEy}(x=y)\wedge\bigwedge_{x\overline{E}y}\neg(x=y)$, where $\overline{E}$ is the complement of $E$.
Intuitively, an arrangement codifies the relationships between a finite set of variables, that is, if they should be equal or different to one another.
$\T$ is then \textbf{strongly finitely witnessable}~\cite{JB10-LPAR} if it has a witness $\wit$ (that in this case will be called a strong witness) satisfying, in addition to $(\textit{I})$ and $(\textit{II})$, the stronger $(\textit{II}^{*})$: for every finite set of variables $V$ and arrangement $\delta_{V}$ on $V$, if $\wit(\phi)\wedge\delta_{V}$ is $\T$-satisfiable, then there exists a $\T$-interpretation $\A$ that satisfies that formula and, in addition, $\dom{\A}=\vars(\wit(\phi)\wedge\delta_{V})^{\A}$.

\begin{example}
    The theory axiomatized by $\{\psi_{\leq 3}\}$ has as strong witness $\wit(\phi)=\phi\wedge\bigwedge_{i=1}^{3}x_{i}=x_{i}$, where $x_{1}$, $x_{2}$ and $x_{3}$ are fresh variables (i.e., not in $\phi$).
    % Of course $\phi$ and $\wit(\phi)$ are equivalent, so condition $(I)$ easily follows;
    % since any interpretation in this theory has at most $3$ elements, we can just map the variables $x_{i}$ to different elements, and we see condition $(II)$ is met.
\end{example}

%\noindent\textbf{Minimal model function}
%
%\noindent\textbf{Finite model property}
$\T$ has the \textbf{finite model property (FMP)} if for every $\T$-satisfiable quantifier-free formula $\phi$, there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|<\aleph_{0}$.\footnote{A common definition for the finite model property demands this condition holds for all formulas, but in theory combination quantifier-free formulas are typically used.}
%
Consider $\N=\mathbb{N}\cup\{\aleph_{0}\}$. A \textbf{minimal model function}~\cite{TinZar05} for $\T$ is a function $\minmod_{\T}:\qf{\Sigma}\rightarrow\N$ such that, if $\phi$ is quantifier-free and $\T$-satisfiable, then $\minmod_{\T}(\phi)=n$ if, and only if: there exists a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=n$; and if $\B$ is another $\T$-interpretation that satisfies $\phi$, with $|\dom{\B}|\neq n$, then $|\dom{\B}|>n$.

\begin{example}
    The theory axiomatized by $\{\psi_{\geq 3}\}$ has a computable minimal model function.
    To calculate it on a quantifier-free formula $\phi$, take the cardinality $n$ of the smallest interpretation in equational logic that satisfies $\phi$, which can easily be found algorithmically. 
    If $n<3$, $\minmod(\phi)=3$;
    otherwise $\minmod(\phi)=n$.
\end{example}

%\noindent\textbf{Politeness and shininess}
%
$\T$ is \textbf{(strongly) polite} if it is smooth and (strongly) finitely witnessable. It is \textbf{shiny} if it is smooth, has the FMP and a computable minimal model function.
%
%\noindent\textbf{Gentleness}
$\T$ is \textbf{gentle}~\cite{gentle} if for every quantifier-free formula $\phi$, $\spec{\T,\phi}$ is \emph{fully computable}, that is: 
$(i)$ it is computable; %\footnote{Meaning that there is, for each quantifier-free formula $\phi$, an algorithm that decides whether $n\in \spec{\T,\phi}$ or not, with $n$ as input.}
$(ii)$ it is either co-finite,\footnote{\textit{I.e.}, $\mathbb{N}\setminus \spec{\T,\phi}$ is finite.} or a finite set of finite cardinalities, and there is an algorithm with $\phi$ as input that tells which one is the case;
$(iii)$ if $\spec{\T,\phi}$ is finite, $\max(\spec{\T,\phi})$ is computable, and if it is infinite $\max(\mathbb{N}\setminus \spec{\T,\phi})$ is computable, both with $\phi$ as input.\footnote{If $\spec{\T,\phi}$ or $\mathbb{N}\setminus\spec{\T,\phi}$ are empty, their respective maxima are $0$, as usual, so $\T$ must be decidable as $\max(\spec{\T,\phi})=0$ iff $\phi$ is not $\T$-satisfiable.}

\begin{example}\label{firsteven}
    Consider the $\Sigma_{1}$-theory $\Teven$ (see \cite{CADE}), with axiomatization\\ $\{\neg\psi_{=2n+1} : n\in\mathbb{N}\}$:
    it is not gentle, as $x=x$ has as spectrum the set of even positive numbers, which is neither finite nor cofinite.
\end{example}



\section{Theory combination and natural density}\label{computability and density}
In this section we establish various connections between 
model-theoretic properties of a theory, and its natural density.
We focus our investigation on the empty signature $\Sigma_1$, 
that has a single sort and no function and predicate symbols
other than equality.
Generalizations to non-empty signatures are given
 in \Cref{non empty}.

We start with the empty signature, because 
a theory on such a signature has essentially one natural density, while for the non-empty case we must consider the density with respect to both a formula and the theory (this can also be done on the empty case, but all $\T$-satisfiable formulas will give the same density).
Furthermore, some results will not hold on the non-empty case, such as the third item in \Cref{SI density} below.


\Cref{sec:sufficient} deals with sufficient conditions: if the density satisfies them, then we can deduce some 
combination properties.
\Cref{necessary section} obtains necessary conditions: 
one would use the contrapositive  and conclude that the theory does not have the properties at hand,
and then at least one knows that a different combination method
has to be used.


\subsection{Sufficient conditions}
\label{sec:sufficient}
% We start with sufficient conditions for properties of theory combination.
%
In \Cref{SI density} we identify sufficient conditions for stable infiniteness, the finite model property and finite witnessability, properties that are needed
for Nelson-Oppen combination, shiny combination, and polite combination, respectively.


\begin{restatable}{theorem}{SIdensity}\label{SI density}\label{not FW density}
    If $\T$ is a $\Sigma_{1}$-theory with a well-defined natural density, then the positivity of $\mu(\T)$ is sufficient for $\T$ to:
        1.  be stably infinite;
        2. have the finite model property; and
        3. be finitely witnessable.

\end{restatable}

\begin{proof}[sketch]\footnote{Full proofs appear in the appendix.}
% Items $1$ and $2$ simple to prove. 
%
The proof of the third item is more involved than that of the first two, which is routine. 
Szemer{\'e}di's theorem~\cite{Szemerdi}, which settled a well-know conjecture by Erd{\"o}s and Tur{\'a}n, showed that each set with positive natural density contains arbitrarily long finite subsequences in arithmetic progression (i.e., the difference between two consecutive elements is constant). 
Item $3$ is a similarly flavored result, although with a much simpler proof than that of Erd{\"o}s and Tur{\'a}n, that will guarantee that any theory $\T$ which is not finitely witnessable and  has a well-defined natural density must satisfy $\mu(\T)=0$.

\end{proof}


\begin{example}\label{one ex}
Fix some positive natural number $n$,
    and consider the theory $\Tgeqn$, with axiomatization $\{\psi_{\geq n}\}$.
    It obviously has positive density.
    By \Cref{SI density} it is stably infinite, has the finite model property, and is finitely witnessable.
\end{example}


The following example shows that 
all the reciprocals of \Cref{SI density} are false, a single counterexample being enough for all three. 

\begin{example}\label{example SI density}   
    Take the $\Sigma_{1}$-theory $\Tpt$ with axiomatization $\{\psi_{\geq 2^{n}}\vee\bigvee_{i=0}^{n}\psi_{=2^{i}}: n\in\mathbb{N}\}$, which has interpretations $\A$ with domains whose cardinality is either infinite or a power of two.
    It is stably infinite, has the finite model property and is finitely witnessable,\footnote{A witness being, if $\phi$ has $n$ variables, $\wit(\phi)=\phi\wedge\bigwedge_{i=1}^{2^{n}}x_{i}=x_{i}$, for fresh $x_{i}s$.} 
    but 
    $\mu(\Tpt)=\LIM \frac{|\specn{\Tpt}|}{n}=\LIM  \frac{\lfloor \log_{2}(n)\rfloor+1}{n}=0$.
\end{example}



The following example shows the sharpness of
\Cref{not FW density}, in the sense that its assumption is really needed to reach its conclusions.

\begin{example}\label{first appearance Tbb}
The conclusion of \Cref{not FW density} cannot hold under the assumption that $\mu(\T)=0$.
The theory
$\Tinfty$, with axiomatization $\{\psi_{\geq n} : n\in\No\}$, 
has only infinite models.
%
It has density $0$ but does not have the finite model property.
The theory $\Tone$, with axiomatization $\{\psi_{=1}\}$, has a single model up to isomorphism, with a single element. 
It has density $0$ but is not stably infinite.
For item $3$, a theory that is not finitely witnessable and has natural density $0$ is $\Tbb$, from \cite{FroCoS}, with axiomatization 
$\{\psi_{\geq \bb(n)}\vee\bigvee_{i=2}^{n}\psi_{=\bb(i)} : n\in\mathbb{N}\setminus\{0,1\}\}$
for $\bb:\mathbb{N}\rightarrow\mathbb{N}$ the busy beaver function
(see \Cref{computable number examples}).
% Rad{\'o} (\cite{Rado}) proved that for any computable function $f:\mathbb{N}\rightarrow\mathbb{N}$, there is a $k_{0}\in\mathbb{N}$ such that $\bb(k)\geq f(k)$ for all $k\geq k_{0}$: 
% this allows one to prove that $\Tbb$ is not finitely witnessable (see \cite[Lemma~53]{arxivFroCoS}). 
% At the same time, the spectrum of $\Tbb$ equals $A=\{4, 6, 13, 47\:176\:870, \ldots\}$%
% \footnote{See \cite{fifth} for the statement, not yet peer-reviewed, that the last number in this list is indeed the fifth Busy Beaver number.} 
% %
% of busy beaver numbers greater than $1$.
The cardinalities of its finite models are precisely the Busy Beaver numbers,
that is, the elements of the image of $\bb$.
We can show that $\mu(\T)=0$.
% Using Rad{\'o}'s result with $f(k)=k^{2}$, and denoting by $B$ the set $\{k^{2} : k\in\mathbb{N}\setminus\{0,1\}\}$, we have that there is $k_{0}\in\mathbb{N}$ 
% such that $\bb(k)\geq k^{2}$ for all $k\geq k_{0}$, and so $|\An|=|\{k\in A : k\leq n\}|\leq|\{k\in B : k\leq n\}|= |B_{n}|$; this way, 
% $\mu(A)=\LIM \frac{|\An|}{n}\leq \LIM \frac{|B_{n}|}{n}=\LIM\frac{\lfloor\sqrt{n}\rfloor-1}{n}=0$.
In a way, item $3$ of \Cref{not FW density} shows that every theory  not finitely witnessable must, like $\bb$, "escape" all computable functions, and thus have natural density $0$.
\end{example}


\subsection{Necessary conditions}\label{necessary section}
We now move on to the results establishing necessary conditions
for gentleness (\Cref{sec:genneccond}),
smoothness and finite model property (\Cref{smooth section}), 
strong finite witnessability (\Cref{SFW section}), 
the computability of a minimal model function (\Cref{cmmf section}), 
and  finite witnessability (\Cref{FW section}).


\subsubsection{Gentleness}
\label{sec:genneccond}
\begin{restatable}{theorem}{gentlesomething}
\label{gentle zero one}
    If $\T$ is a $\Sigma_{1}$-theory, then $\mu(\T)$  being well-defined and equal to $0$ or $1$ is a necessary condition for $\T$ to be gentle.
\end{restatable}

\begin{proof}[sketch]
By taking a tautology $\phi$ for a gentle $\Sigma_{1}$-theory $\T$, we see that $\spec{\T}=\spec{\T,\phi}$ is either finite (and then its density is $0$) or co-finite (and then its density is $1$. 
\end{proof}

\begin{example}
\label{exwithteven}
Consider the theory $\Teven$ from \Cref{firsteven}:
it's density is $\fr{1}{2}$, what implies by the theorem it is not gentle. 
% This can also be seen from the fact that the spectrum of any tautology is both infinite and co-infinite.
\end{example}

The reciprocal of \Cref{gentle zero one} is false, as shown by the next
example.
\begin{example}\label{example gentle density}
    \Cref{example SI density} presents a theory $\Tpt$ that has density $0$ but is not gentle (since both $\spec{\Tpt}$ and $\mathbb{N}\setminus\spec{\Tpt}$ are infinite).
    On the other hand, take the $\Sigma_{1}$-theory $\Tnpt$ with axiomatization $\{\neg\psi_{=2^{n}} : n\in\mathbb{N}\}$, which has interpretations $\A$ with either $|\dom{\A}|$ infinite, or $|\dom{\A}|$ finite but not a power of two. 
    It is not gentle, yet
    $\mu(\Tnpt)=\LIM \frac{|\specn{\Tnpt}|}{n}=\LIM  \frac{n-\lfloor \log_{2}(n)\rfloor-1}{n}=1$.
\end{example}

Notice also that both cases of \Cref{gentle zero one} are possible, namely: there are gentle theories with density $0$ and gentle theories with density $1$.
Before showing them, let us present two useful lemmas, that relate gentleness
to other properties:


\begin{restatable}{lemma}{gentlenessimplies}
\label{gentleness implies}
    If $\T$ is gentle, then $\T$ has a computable minimal model function and the finite model property, and therefore is finitely witnessable as well.
\end{restatable}

\begin{restatable}{lemma}{impliesgentleness}
\label{implies gentleness}
    Let $\T$ be a $\Sigma_{1}$-theory: if $\T$ is not stably infinite, or if it is strongly finitely witnessable, then $\T$ is gentle.
\end{restatable}


\begin{example}\label{line eight}~
\begin{enumerate} 
\item The trivial $\Sigma_{1}$-theory $\T_{\geq 1}$, with axiomatization $\{\psi_{\geq 1}\}$, consists of all $\Sigma_1$-interpretations.
It is strongly finitely witnessable (given its axiomatization is given by an universal formula, this is proven in \cite{Sheng2022}), and of course $\specn{\T_{\geq 1}}=[1,n]$ so $\mu(\T_{\geq 1})=1$. 
\item The $\Sigma_{1}$-theory $\Tone$ from \Cref{first appearance Tbb}  is also strongly finitely witnessable and thus gentle (\Cref{implies gentleness}), but $\specn{\Tone}=\{1\}$ so $\mu(\Tone)=0$.
\item An example of a $\Sigma_{1}$-theory that is gentle and has density $0$, but is not strongly finitely witnessable,
is denoted by $\Tmn$, for any fixed $m,n\in\No$.
It has axiomatization $\{\psi_{=m}\vee\psi_{=n}\}$, and its
models have cardinalities $m$ or $n$.
\end{enumerate}
\end{example}






\subsubsection{Smoothness and finite model property}\label{smooth section}

The next result involves both smoothness and the finite model property.

\begin{restatable}{theorem}{smoothdensitytheorem}
\label{smooth density}
    If $\T$ is a $\Sigma_{1}$-theory, $\mu(\T)$ being well-defined and equal to $1$ is necessary  for $\T$ to simultaneously admit smoothness and the finite model property.
\end{restatable}

\begin{proof}[sketch]
 The proof is dual to that of \Cref{SI density}: if a theory is smooth and has the finite model property, it has all sufficiently large numbers as cardinalities of its models, and its density is therefore $1$.
\end{proof}

The following example not only allows one to visualize the use of \Cref{smooth density}, but will also help later in providing examples for each and all possible combination of the properties under consideration.


\begin{example}\label{application of smooth density}
Consider again $\Teven$ from \Cref{exwithteven}, with density $\fr{1}{2}$.
%
It was already shown in \cite{SZRRBT-21} that $\Teven$ has the finite model property without being smooth, but notice that \Cref{smooth density} perfectly encapsulates an intuition for why that is:
%
    as the theory has the finite model property, it has a finite model;
    were it smooth, it would have models of all larger cardinalities, and thus density $1$.
\end{example}




\begin{example}\label{example smooth density}
    The reciprocal of \Cref{smooth density} is false, as we can see from the theory $\Tnpt$ defined in \Cref{example gentle density}, which is not smooth. 
\end{example}

Now, \Cref{application of smooth density} shows an example of a theory that has the finite model property but is not smooth. 
But all three other Boolean combinations of these two properties are possible, as seen below.

\begin{example}\label{SM-FMP ex}~\begin{enumerate}
        \item The theory $\T_{\geq 1}$ from \Cref{line eight} is smooth and has the finite model property.
        \item One example of a smooth theory without the finite model property is the $\Sigma_{1}$-theory $\Tinfty$  
        from \Cref{first appearance Tbb}.
        It has density $0$, as it has no finite models.
        \item To see one of a theory that is neither smooth nor has the finite model property, which by \Cref{SI density} must have density $0$, fix an $n\in\No$ and consider the $\Sigma_{1}$-theory $\Tninfty$, defined in \cite{CADE} by the axiomatization $\{\psi_{=n}\vee\psi_{\geq m} : m\in\No\}$. Its finite models must have cardinality $n$.
    \end{enumerate}
\end{example}

\subsubsection{Strong finite witnessability}\label{SFW section}

%Although a complicated property, the result involving  strong finite witnessability is rather simple.
%Although being a result about necessity, and thus more useful to test for the absence of a property (in this case, strong finite witnessability), \Cref{SFW density} is still 
The following result, which is a corollary of earlier ones, is specially useful: proving a theory is not strongly finitely witnessable is quite challenging;
it involves finding a quantifier-free formula, a set of variables, and an arrangement on that set which fail the conditions to be a strong witness, for every candidate for a strong witness.
Checking whether the theory's density is $0$ or $1$ can be fairly easier.

\begin{restatable}{theorem}{sfwdensitytheorem}
\label{SFW density}
    If $\T$ is a $\Sigma_{1}$-theory, then $\mu(\T)$  being well-defined and equal to $0$ or $1$ is a necessary condition for $\T$ to be strongly finitely witnessable.
\end{restatable}

\begin{proof}
 By \Cref{implies gentleness} and \Cref{gentle zero one}.
\end{proof}

\begin{example}
The theory $\Teven$ from \Cref{exwithteven} is not strongly finitely witnessable, as proven in \cite{SZRRBT-21}, but the proof found there is quite involved, demanding careful use of arrangements.
    Here, we only need to point to the fact that $\Teven$ has natural density $\fr{1}{2}$.
\end{example}


\begin{example}
    The reciprocal of \Cref{SFW density} is false: the theories 
    $\Tpt$ and $\Tnpt$ from
    \Cref{example SI density,example gentle density} have, respectively, densities $0$ and $1$, but neither is strongly finitely witnessable, which follows from the fact that both are stably infinite without being smooth, together with \cite[Theorem~7]{CADE}, which shows
    stably infinite, one-sorted theories that are strongly finitely witnessable are smooth.
\end{example}

\subsubsection{Computability of minimal model functions}\label{cmmf section}

We move now to the question of computability of a minimal model function. 
For this, we first establish in \Cref{cmmf and computability} a connection between this  and the computability of the spectra.

\begin{restatable}{proposition}{cmmfcomputability}\label{cmmf and computability}
    $\T$ is a $\Sigma_{1}$-theory with a computable minimal model function if, and only if, $\spec{\T}$ is computable.
\end{restatable}

This proposition plays an important role in the proof of the theorem below:


\begin{restatable}{theorem}{cmmfdensity}\label{cmmf density}
    If $\T$ is a $\Sigma_{1}$-theory with a well-defined density, the fact that $\mu(\T)$ is a computable number is a necessary condition for $\T$ to have a computable minimal model function.
%    
    Furthermore, for every computable number $0\leq r\leq 1$, there exists a $\Sigma_{1}$-theory $\T$ with $\mu(\T)=r$ that has a computable minimal model function and the finite model property, but is not smooth.
\end{restatable}

The proof of the first part takes a theory $\T$
with a computable minimal model function, and from \Cref{cmmf and computability} one sees that $\spec{\T}$ is computable; we then prove 
that this implies $\mu(\T)$
% as the natural density of the computable set $\spec{\T}$, 
is itself a computable real number, ruling out non-computable numbers. 
Indeed, if $A$ is a computable set, the sequence $\{|\An|\}_{n\in\mathbb{N}}=\{|\{k\in A : k\leq n\}|\}_{n\in\mathbb{N}}$ is computable (and so is $\{n\}_{n\in\mathbb{N}}$, but that is obvious); if $\mu(A)=r$, we have $r=\LIM\fr{|\An|}{n}$, proving $r$ is computable. 

% In addition, \Cref{cmmf density} includes a second part,
% which proves that
%  any computable number between $0$ and $1$ is the natural density of a corresponding theory with a computable minimal model function, so this is the best we can hope for. 

We prove the second part  by constructing in \Cref{definition of f} below, from two sequences $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$, a function $f$ whose image (which will also equal the spectrum of the theory to be constructed) will be a computable set and have a density associated to the mediants of the ratios $\fr{a_{n}}{b_{n}}$, where the mediant of the fractions $\fr{a}{b}$ and $\fr{c}{d}$ is the fraction $\fr{(a+c)}{(b+d)}$. Although tedious to prove, it is true that the limit of the mediants of the ratios between two sequences equals the limit of the ration, and this guarantees that the natural density of the image of $f$ will be the limit of $\fr{a_{n}}{b_{n}}$. 

\begin{definition}\label{definition of f}
    Given  sequences $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$ with $0<a_{n}<b_{n}$ and $a_{n},b_{n}\in\mathbb{N}$, for all $n\in\mathbb{N}$, we define an associated function $f:\No \rightarrow\No $ inductively as follows: $f(n)=n$ for $1\leq n\leq a_{0}$, and $f(n)=a_{0}$ for $a_{0}+1\leq n\leq b_{0}$; and, assuming $f(n)$ defined for all $1\leq n\leq M=\sum_{i=0}^{m}b_{i}$, for any $m\geq 0$, we make $f(n)=n$ for $M+1\leq n\leq M+a_{m+1}$, and $f(n)=M+a_{m+1}$ for $M+a_{m+1}+1\leq n\leq M+b_{m+1}$.
\end{definition}

The construction defined in \Cref{definition of f} is outlined  in \Cref{graphs} $(A)$.
Notice the step-shape of the function, that can be computed by induction on $n$.


