\newcommand\smeq{\scaleobj{0.85}{=}}
\begin{example}\label{not FW density counterexample}
    Consider the function $\bb^{-1}:\mathbb{N}\rightarrow\mathbb{N}$ from \cite{FroCoS}, which is a left inverse of $\bb$, 
    and the theory $\Tbbs$ on the signature with only a single unary function $s$, from the same paper.
    Both $\bb^{-1}$ and $\Tbbs$ are given in \Cref{fig-card-s}.
It is  
 smooth, has the finite model property, but is not finitely witnessable (see \cite[Lemmas~71,72,73]{arxivFroCoS}), meaning $\mu(\Tbbs,\phi)=1$ for all quantifier-free $\Tbbs$-satisfiable formulas $\phi$ by \Cref{smooth non empty}. 
Thus, the obvious generalization of item $3$ of \Cref{not FW density} is not valid.
\end{example}


\Cref{smooth non empty} is also useful to show,
for example, that
a variant of the SMT-LIB theory of bit-vectors
is not smooth.

\begin{example}
Fix $n\in\No$, and
    consider the one-sorted fragment of the SMT-LIB theory $\bv$ of bit-vectors~\cite{BarFT-RR-17} of length $n$, with the usual operations (but without concatenation and extraction). 
    The domain of its interpretations  has cardinality $2^{n}$, and so it  has the finite model property.
    By \Cref{smooth non empty} this theory is not smooth, as for any quantifier-free formula $\phi$ one has $\mu(\bv,\phi)=0$.
\end{example}


