\section{\tp{Proof of \Cref{SI density}}{Proof of result \ref{SI density}}}

\begin{lemma}\label{bigger interpretation}
    Let $\T$ be a $\Sigma_{1}$-theory.
    If $\phi$ is a quantifier-free $\Sigma_{1}$-formula, and $\A$ and $\B$ are $\T$-interpretations such that $\B$ satisfies $\phi$, and $|\dom{\A}|\geq|\vars(\phi)^{\B}|$, then there is a $\T$-interpretation $\A^{\prime}$, differing from $\A$ at most on the value assigned to $\vars(\phi)$, that satisfies $\phi$. 

    If $\A$ and $\B$ are $\T$-interpretations with $|\dom{\A}|=|\dom{\B}|$, then there is a $\T$-interpretation $\A^{\prime}$, differing from $\A$ at most on the values assigned to variables, such that $\A^{\prime}$ and $\B$ satisfy exactly the same, not necessarily quantifier-free, formulas.
\end{lemma}

\begin{proof}
    Take an injective function $f:\vars(\phi)^{\B}\rightarrow\dom{\A}$ (bijective function $f:\dom{\B}\rightarrow\dom{\A}$ if $|\dom{\A}|=|\dom{\B}|$), and define an interpretation $\A^{\prime}$ such that: $\dom{\A^{\prime}}=\dom{\A}$;  $x^{\A^{\prime}}=f(x^{\B})$ if $x^{\B}$ is in the domain of $f$; and $x^{\A^{\prime}}=x^{\A}$ otherwise. We now prove by structural induction that $\A^{\prime}$ satisfies $\phi$; in the case where $|\dom{\A}|=|\dom{\B}|$ and $f$ is bijective, we must perform the proof simultaneously over all interpretations with the same cardinality as that of $\A$ and $\B$.

    \begin{enumerate}
        \item If $\psi$ is an atomic subformula of $\phi$, since our signature is empty it must equal $x=y$, for some variables $x$ and $y$; then $\B$ satisfies $\psi$ iff $x^{\B}=y^{\B}$ and, since $x^{\A^{\prime}}=f(x^{\B})$ and $y^{\A^{\prime}}=f(y^{\B})$, that happens iff $\A^{\prime}$ satisfies $\psi$.
        \item So, suppose $\B$ satisfies the subformulas $\psi$ and $\psi_{i}$ (for $i\in\{1,2\}$) of $\phi$ iff $\A^{\prime}$ satisfies the same formulas.
        \begin{enumerate}
            \item We have that $\B$ satisfies $\neg\psi$ iff it does not satisfy $\psi$, what in turn happens iff $\A^{\prime}$ does not satisfy $\psi$, and so $\B$ satisfies $\neg\psi$ iff $\A^{\prime}$ satisfies $\neg\psi$.

            \item Analogously, $\B$ satisfies $\psi_{1}\vee\psi_{2}$ iff it satisfies $\psi_{1}$ or $\psi_{2}$, what happens iff $\A^{\prime}$ satisfies $\psi_{1}$ or $\psi_{2}$, what in turn happens iff $\A^{\prime}$ satisfies $\psi_{1}\vee\psi_{2}$.

            \item For the case where $|\dom{\A}|=|\dom{\B}|$, and $\phi$ is not necessarily quantifier-free, suppose $\B$ satisfies $\Exists{x}\psi$, and so there exists an interpretation $\B_{*}$, differing from $\B$ at most on the value assigned to $x$, that satisfies $\psi$. We then define an interpretation $\A^{\prime}_{*}$ differing from $\A^{\prime}$ at most on the value assigned to $x$, where $x^{\A_{*}^{\prime}}=f(x^{\B_{*}})$, and from the strengthened form of the induction hypothesis we have $\A_{*}^{\prime}$ satisfies $\psi$, and thus $\A^{\prime}$ satisfies $\Exists{x}\psi$. 

            Reciprocally, if $\A^{\prime}$ satisfies $\Exists{x}\psi$, there is an interpretation $\A^{\prime}_{*}$ differing from $\A^{\prime}$ at most on $x$, and we can then define an interpretation $\B_{*}$, differing of $\B$ at most on $x$ where $x^{\B_{*}}=f^{-1}(x^{\A^{\prime}_{*}})$, so that $\B_{*}$ satisfies $\psi$ and thus $\B$ satisfies $\Exists{x}\psi$.

            \item The cases of $\psi_{1}\wedge\psi_{2}$ and $\psi_{1}\rightarrow\psi_{2}$ (and $\Forall{x}\psi$) can be derived from those, and thus we are done.

        \end{enumerate}
    \end{enumerate}   
    That $\A^{\prime}$ is still a $\T$-interpretation follows from the fact that to obtain $\A^{\prime}$ we only (at most) changed the value assigned by $\A$ to some variables.
\end{proof}

\begin{lemma}\label{has infinite model}
    If $\T$ is a $\Sigma_{1}$-theory with an infinite interpretation, it is stably infinite.
\end{lemma}

\begin{proof}
    Let $\A$ be an infinite $\T$-interpretation, $\phi$ a quantifier-free formula, and $\B$ a $\T$-interpretation that satisfies $\phi$: since $|\dom{\A}|\geq|\vars(\phi)^{\B}|$ we can thus apply \Cref{bigger interpretation} to obtain an infinite $\T$-interpretation $\A^{\prime}$ that satisfies $\phi$.
\end{proof}

\begin{lemma}\label{-SI implies bound}
    If $\T$ is a $\Sigma_{1}$-theory that is not stably infinite, then there exists $M\in\mathbb{N}$ such that $|\dom{\A}|\leq M$ for all $\T$-interpretations $\A$.
\end{lemma}

\begin{proof}
    Suppose that, for every $n\in\mathbb{N}$, there exists a $\T$-interpretation $\A_{n}$ with $|\dom{\A_{n}}|\geq n$. If we define $\Gamma=\ax{\T}\cup\{\psi_{\geq m} : m\in\mathbb{N}\}$, for any finite subset $\Gamma_{0}\subseteq\Gamma$, take the maximum $n$ of $m$ such that $\psi_{\geq m}$ occurs in $\Gamma_{0}$.
    Of course, $\A_{n}$ then satisfies $\Gamma_{0}$; it satisfies $\Gamma_{0}\cap\ax{\T}$ as it is a $\T$-interpretation;
    and it satisfies any $\psi_{\geq m}$ in $\Gamma_{0}$, since it satisfies $\psi_{\geq n}$, and $\psi_{\geq n}\rightarrow\psi_{\geq m}$ is valid for all $m\leq n$. From \Cref{compactness}, it follows that $\Gamma$ is satisfiable, meaning there is an infinite $\T$-interpretation $\A$. The result then follows from \Cref{has infinite model}.
\end{proof}

\begin{lemma}\label{-FMP implies bound}
    If $\T$ is a $\Sigma_{1}$-theory that does not have the finite model property, then there exists $M\in\mathbb{N}$ such that $|\dom{\A}|\leq M$ for all finite $\T$-interpretations $\A$.
\end{lemma}

\begin{proof}
    If $\T$ has only finite interpretations it already has the finite model property, so take a quantifier-free formula $\phi$ that is satisfied by no finite $\T$-in\-ter\-pre\-ta\-tions, and an infinite $\T$-interpretation $\A$ that satisfies $\phi$. Suppose that there exists, for each $n\in\mathbb{N}$, a finite $\T$-interpretation $\A_{n}$ with $|\dom{\A_{n}}|\geq n$: then, for $n=|\vars(\phi)^{\A}|$, \Cref{bigger interpretation} guarantees that by changing the value assigned to variables in $\A_{n}$ we can make it satisfy $\phi$, contradicting our hypothesis.
\end{proof}

\SIdensity*

\begin{proof}
    The proofs for the first and second items are the same: assuming $\T$ is not stably infinite, respectively does not have the finite model property, we have from \Cref{-SI implies bound}, respectively \Cref{-FMP implies bound}, that there is an $M\in\mathbb{N}$ such that, for all finite $\T$-interpretations $\A$, $|\dom{\A}|\leq M$. This means that $\specn{\T}\subseteq [1,M]$ for all $n\geq 1$, and so $|\specn{\T}|\leq M$ in that case: therefore, $\mu(\T)=\LIM \fr{|\specn{\T}|}{n}\leq \LIM \fr{M}{n}=0$. Thus $\mu(\T)=0$, and by the contrapositive we have the desired result.

    For the third item, from the hypothesis in the theorem's statement, $\mu(\T)$ is well-defined; suppose, in addition, that $\mu(\T)>0$. 
    % Then 
    % $\T$ has the finite model property by \Cref{SI density}. 
    Let $\{a_{n}\}_{n\in\mathbb{N}}$ be the increasing sequence of the elements of $\spec{\T}$ (if this set were to be finite, it would be bounded by some $M\in\mathbb{N}$, and we would have $\mu(\T)\leq \LIM\fr{M}{n}=0$). There are then two cases to consider: $(1)$ there is a computable sequence $\{b_{n}\}_{n\in\mathbb{N}}$ such that $a_{n}\leq b_{n}$ for all $n\in\mathbb{N}$; and $(2)$ for all computable sequences $\{b_{n}\}_{n\in\mathbb{N}}$ and all $N_{0}\in\mathbb{N}$, there is an $n\geq N_{0}$ such that $a_{n}> b_{n}$. Notice that the negation of $(2)$ implies $(1)$, meaning these are indeed the only cases we need to consider: if there is a computable sequence $\{b_{n}\}_{n\in\mathbb{N}}$ and an integer $N_{0}$ such that $b_{n}\geq a_{n}$ for all $n\geq N_{0}$, we define the computable sequence $\{c_{n}\}_{n\in\mathbb{N}}$ by making $c_{n}=b_{N_{0}}$ for $n\leq N_{0}$, and $c_{n}=b_{n}$ for $n\geq N_{0}$, which satisfies the conditions in case $(1)$. We will prove that case $(1)$ implies $\T$ is finitely witnessable; and that $(2)$ implies $\mu(\T)=0$, contradicting our assumption.

    \begin{enumerate}
        \item Let $x_{i}$ be fresh variables, and define $N(\phi)$, for a quantifier-free formula $\phi$, as $b_{n}$, for $n=|\vars(\phi)|$. We define $\wit(\phi)=\phi\wedge\bigwedge_{i=1}^{N(\phi)}x_{i}=x_{i}$: this is obviously a function from quantifier-free formulas into themselves, and is computable given $b_{n}$, and thus $N(\phi)$, are computable. Furthermore, $\phi$ and $\Exists{\overarrow{x}}\wit(\phi)$ are clearly $\T$-equivalent, given $\wit(\phi)$ is the conjunction of $\phi$ and a tautology and thus already equivalent to $\phi$.

        Finally, let $\phi$ be a quantifier-free formula, and $\A$ a $\T$-interpretation that satisfies $\wit(\phi)$ (and thus $\phi$, since the two are equivalent). 
        Take again $n=|\vars(\phi)|$, a set $A$ with $a_{n}-|\vars(\phi)^{\A}|$ elements (a non-negative quantity, since $\{a_{n}\}_{n\in\mathbb{N}}$ is increasing and therefore $a_{n}\geq n=|\vars(\phi)^{\A}|$), disjoint from $\dom{\A}$, and define an interpretation $\B$ by making: 
        $\dom{\B}=\vars(\phi)^{\A}\cup A$ (so $|\dom{\B}|=a_{n}$, making $\B$ a $\T$-interpretation, as there is only one $\T$-interpretation of a given size up to isomorphism by \Cref{bigger interpretation}); $x^{\B}=x^{\A}$ for all $x\in\vars(\phi)$ (so $\B$ satisfies $\phi$); 
        \[x_{i}\in \{x_{i} : 1\leq i\leq N(\phi)\}\mapsto x_{i}^{\B}\in\dom{\B}\]
        a surjective map (what is possible, as $N(\phi)=b_{n}\geq a_{n}$); and $x^{\B}$ defined arbitrarily for all other variables. 
        Because $\{x_{i} : 1\leq i\leq N(\phi)\}$ is contained in $\vars(\wit(\phi))$, and $\{x_{i} : 1\leq i\leq N(\phi)\}^{\B}=\dom{\B}$, we have $\dom{\B}=\vars(\wit(\phi))^{\B}$ (since obviously the former set at least contains the latter): it then follows that $\wit$ is a witness.

        \item Consider the computable sequence $b_{n}=n^{2}$: take $m_{0}$ as the minimum of the positive integers $m$ such that $a_{m}> b_{m}$ and, inductively, $m_{n+1}$ as the minimum of the integers $m>m_{n}$ such that $a_{m}> b_{m}$; this way, $a_{m_{n}}>b_{m_{n}}=m_{n}^{2}$ for all $n\in\mathbb{N}$. Of course, for all $n\in\mathbb{N}$ one finds $|\Spec_{a_{m_{n}}}(\T)|=m_{n}$, and $|[1,a_{m_{n}}]|=a_{m_{n}}> m_{n}^{2}$, thus $\fr{|\Spec_{a_{m_{n}}}(\T)|}{|[1,a_{m_{n}}]|}< \fr{1}{m_{n}}$. This means that a subsequence of $\fr{|\Spec_{n}(\T)|}{|[1,n]|}$ (which converges to $\mu(\T)$, as this value was assumed in the theorem's statement to be well-defined) converges to $0$, meaning $\mu(\T)=0$.

    \end{enumerate}


\end{proof}


