\section{\tp{Proof of \Cref{gentle zero one}}{Proof of result \ref{gentle zero one}}}

\gentlesomething*
\begin{proof}
    If $\spec{\T}$ is finite, there is an $M$ such that $|\specn{\T}|\leq |\spec{\T}|\leq M$, and therefore $\mu(\T)=\LIM\fr{M}{n}=0$.
    If $\spec{\T}$ is co-finite instead, there is an $M$ such that for all $n>M$ one has $|\specn{\T}|\geq n-M$, and so $\mu(\T)\geq\LIM\fr{(n-M)}{n}=1$.
\end{proof}


\section{\tp{Proof of \Cref{gentleness implies}}{Proof of result \ref{gentleness implies}}}

\gentlenessimplies*

\begin{proof}
Suppose $\T$ is gentle.
From the definition of gentleness we get there must exist a finite number in the spectrum of each $\T$-satisfiable quantifier-free formula $\phi$;
this means there is a finite $\T$-interpretation that satisfies $\phi$, so $\T$ indeed has the finite model property.

Given a quantifier-free formula $\phi$, we can decide whether $\spec{\T,\phi}$ is finite, and then computably calculate $\max(\spec{\T,\phi})$, or co-finite, and in this case calculate $\max(\mathbb{N}\setminus\spec{\T,\phi})$.
Using that $\spec{\T,\phi}$ is computable, we can also algorithmically obtain $\min(\spec{\T,\phi})$: 
if $\spec{\T,\phi}$ is finite, we test which $n\leq \max(\spec{\T,\phi})$ are in $\spec{\T,\phi}$ and take their minimum (if $\max(\spec{\T,\phi})$ is $0$, we just set $\min(\spec{\T,\phi})$ to $0$ as well, for simplicity);
if $\spec{\T,\phi}$ is co-finite, we test which $n\leq \max(\mathbb{N}\setminus\spec{\T,\phi})+1$ are in $\spec{\T,\phi}$, and again take their minimum.    

We state that $\minmod_{\T}(\phi)=\min(\spec{\T,\phi})$ is a computable minimal model function, being certainly computable.
Assume then $\phi$ is $\T$-satisfiable, and so $\min(\spec{\T,\phi})>0$.
For the first direction, suppose there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|<\min(\spec{\T,\phi})$;
since $|\dom{\A}|$ is in $\spec{\T,\phi}$, this contradicts the fact $\min(\spec{\T,\phi})$ is the minimum element of that set.
Now, since $\min(\spec{\T,\phi})$ is in $\spec{\T,\phi}$, there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=\min(\spec{\T,\phi})$, and thus we have proved $\min(\spec{\T,\phi})$ is indeed a minimal model function.

Finite witnessability follows from \cite[Theorem~4]{LPAR-arXiv}.
\end{proof}

\section{\tp{Proof of \Cref{implies gentleness}}{Proof of result \ref{implies gentleness}}}

\begin{lemma}
\label{sigma one decidable}
    A $\Sigma_{1}$-theory is always decidable.
\end{lemma}

\begin{proof}
    Take a $\Sigma_{1}$-theory $\T$.
    We divide the proof in two cases:
    for each of them we find an algorithm to decide whether a quantifier-free formula $\phi$ is $\T$-satisfiable;
    notice, however, that there is no decision method with $\T$ as input that returns which of the described algorithms is the correct one.
    \begin{enumerate}
        \item Suppose $\T$ has a maximum model $\A$, with $|\dom{\A}|=M$;
        we state that $\phi$ is $\T$-satisfiable if and only if there is an interpretation $\B$ in equational logic that satisfies $\phi$ with $|\dom{\B}|\leq M$, meaning we are done since equational logic is decidable.
        Indeed, if $\B$ is an interpretation in equational logic that satisfies $\phi$ with $|\dom{\B}|\leq M$, we can change the values assigned to the variables in $\phi$ by $\A$ in order to obtain a $\T$-interpretation $\A^{\prime}$ that satisfies $\phi$ (see \Cref{bigger interpretation}).
        And, if $\C$ is a $\T$-interpretation that satisfies $\phi$, given the facts that $|\dom{\C}|\leq M$ and $\C$ is an interpretation in equational logic as well, we are done.

        \item If $\T$ doesn't have a maximum model, we state that all quantifier-free formulas satisfiable in equational logic are also $\T$-satisfiable.
        Indeed, if $\phi$ is satisfied by the interpretation $\B$ of equational logic, we know there is a $\T$-interpretation $\A$ with $|\dom{\A}|\geq \B$, and again by \Cref{bigger interpretation} we are done.
    \end{enumerate}
\end{proof}

\impliesgentleness*

\begin{proof}
    If $\T$ is not stably infinite, by \Cref{-SI implies bound} $\T$ has a maximum interpretation $\A$, say with $|\dom{\A}|=M$.
    $\spec{\T,\phi}$ is then always finite (see \Cref{bigger interpretation});
    $\max(\spec{\T,\phi})=M$ if $\phi$ is $\T$-satisfiable (we use \Cref{sigma one decidable}), and $0$ otherwise;
    and a cardinality is in $\spec{\T,\phi}$ if it is both in $\spec{\T}$ and larger than or equal to the minimum cardinality of an interpretation in equational logic that satisfies $\phi$ ($\spec{\T}$ is a finite list, so it can be hardcoded).
    In summary, $\T$ is gentle.

    If $\T$ is strongly finitely witnessable but not stably infinite the previous reasoning already implies $\T$ is gentle, so assume $\T$ is strongly finitely witnessable and stably infinite.
    $\T$ is then also smooth by \cite[Theorem~7]{CADE}, and so $\spec{\T}$ is co-finite:
    let $M$ be the maximum of $\mathbb{N}\setminus\spec{\T}$. 
    $\spec{\T,\phi}$ is then always co-finite, by \Cref{bigger interpretation} and the fact that strong finite witnessability implies the finite model property;     $\max(\mathbb{N}\setminus\spec{\T,\phi})=0$ if $\phi$ is not $\T$-satisfiable (what can be decided from \Cref{sigma one decidable}), and otherwise we make $N$ the cardinality of the smallest interpretation in equational logic that satisfies $\phi$, and then $\max(\mathbb{N}\setminus\spec{\T,\phi})=\max\{M,N-1\}$, both computable quantities;
    and finally, $n\in\spec{\T,\phi}$ iff $n>\max\{M,N-1\}$, meaning $\spec{\T,\phi}$ is computable.
\end{proof}



\section{\tp{Proof of \Cref{smooth density}}{Proof of result \ref{smooth density}}}

\smoothdensitytheorem*

\begin{proof}
    Let $\phi$ be any tautology, and from the fact that $\T$ has the finite model property there exists a finite $\T$-interpretation $\B$ that satisfies $\phi$: 
    from the fact $\T$ is smooth it follows that for all $n\geq M=|\dom{\B}|$ there exists a $\T$-interpretation $\A_{n}$ with $|\dom{\A_{n}}|=n$, so $|\specn{\T}|=|\Spec_{M}(\T)|+(n-M)$ for all $n\geq M$. 
    Thus we have $\mu(\T)=\LIM \fr{|\specn{\T}|}{n}\geq \lim_{m\rightarrow\infty} \fr{m}{(m+M)}=1$; 
    therefore $\mu(\T)=1$, as we wished to prove.
\end{proof}

\section{\tp{Proof of \Cref{SFW density}}{Proof of result \ref{SFW density}}}

\sfwdensitytheorem*

\begin{proof}
    From \cite[Theorem~2]{FroCoS} we know strong finite witnessability implies the final model property. From \cite[Theorem~7]{CADE}, we know that if $\T$ is stably infinite, then it is smooth, and so $\mu(\T)=1$ from \Cref{smooth density}; if $\T$ is not stably infinite, \Cref{SI density} guarantees that $\mu(\T)=0$.
\end{proof}


\section{\tp{Proof of \Cref{cmmf and computability}}{Proof of result \ref{cmmf and computability}}}

\cmmfcomputability*


\begin{proof}
    For the right-to-left direction,
    suppose the spectrum $\spec{\T}$ is computable: if $\T$ does not have the finite model property, by \Cref{-FMP implies bound} one gets 
    that there is a natural number $M$ that bounds the cardinalities of all finite models of $\T$. Thus, a minimal model function can simply be obtained by checking for all models up to $M$ whether they satisfy the input formula, and stopping at the first one (recall that since the signature is empty a model is uniquely determined by its cardinality).
    %
    If $\T$ is empty (has no models) then any computable
    function is a minimal model function, as no formula
    is $\T$-satisfiable. 

    We may then assume that $\T$ both has the finite model property and is not contradictory (so $\spec{\T}\neq\emptyset$) and take, if $\phi$ is not a contradiction (what can be determined algorithmically in equational logic): the set of variables $V$ in $\phi$; the set $\eq{V}$ of all the equivalences $E$ on $V$; $M=\sup(\spec{\T})$ (which equals $\aleph_{0}$ if $\spec{\T}$ is infinite, and is otherwise always a positive
    natural number since $\spec{\T}\neq\emptyset$),
    % \footnote{Although the set $\spec{\T}$ may be infinite, in which case $M$ may not be computed in finite time, $M$ serves as a constant on the definition of $minmod_{\T}$, and thus this function will still computable.} 
    $M(\phi)=\min\{|V/E| : \text{$\delta_{V}^{E}$ implies $\phi$}\}$ (a quantity that is computable since the problem may be reduced to one in equational logic), and we state that
    % \[\minmod_{\T}(\phi)=\begin{cases}
    %     \aleph_{0}, & \text{if $\phi$ is contradictory, or $M(\phi)>M$;}\\
    %     \min\{M(\phi)\leq k\leq M : k\in \spec{\T}\}, & \text{otherwise}
    % \end{cases}\]
    \[
  \minmod_{\T}(\phi) =
  \begin{cases}
    \aleph_{0}           & \begin{aligned}%[b]
       & \text{if $\phi$ is contradictory,} \\
       & \text{or $M(\phi)>M$;}
    \end{aligned} \\%[1ex]
    \min\{M(\phi)\leq k\leq M : k\in \spec{\T}\} & \text{otherwise}
  \end{cases}
\]
    is a computable minimal model function for $\T$. 
    Indeed, if $\phi$ is a contradiction, what the decision procedure for equational logic can tell us, $\minmod_{\T}(\phi)=\aleph_{0}$; 
    if $\phi$ is not a contradiction, but it is a $\T$-contradiction, then $M(\phi)>M$ (indeed, if $M\geq M(\phi)$ there is a $\T$-interpretation $\A$ with $|\dom{\A}|=M$, by appealing to \Cref{compactness} if necessary; and by \Cref{bigger interpretation} we get that $\phi$ is $\T$-satisfiable), and again $\minmod_{\T}(\phi)=\aleph_{0}$. Finally, in the case that $\phi$ is $\T$-satisfiable, since $\T$ has the finite model property by assumption, there is a finite $\T$-interpretation $\A$ that satisfies $\phi$ and, of course, $|\dom{\A}|\geq M(\phi)$ (because otherwise $\A$ induces an equivalence $\delta_{V}^{E}$ that implies $\phi$ with $|V/E|<M(\phi)$): therefore the set $\{M(\phi)\leq k\leq M : k\in \spec{\T}\}$ is not empty (it contains at least $|\dom{\A}|$), and finding its minimum is easy.

    So assume $\phi$ is $\T$-satisfiable, and take: an $E\in\eq{V}$ with $|V/E|=M(\phi)$ (and necessarily $M(\phi)<\aleph_{0}$); the minimum $n$ of $M(\phi)\leq k\leq M$ such that $k\in \spec{\T}$;
    % (which will equal $\aleph_{0}$ if $M>M(\phi)$); 
    and a set $X$ with $|X|=n-M(\phi)$ disjoint from $V/E$. We then create an interpretation $\B$ with: $\dom{\B}=(V/E)\cup X$; $x^{\B}=[x]$ for all $x\in V$, where $[x]$ is the equivalence class under $E$ represented by $x$; and $x^{\B}$ defined arbitrarily for variables $x$ not in $V$. Because $|\dom{\B}|=M(\phi)+(n-M(\phi))=n$, we know thanks to \Cref{bigger interpretation} that $\B$ is a $\T$-interpretation; furthermore, $\B$ satisfies $\delta_{V}^{E}$ by definition, thus satisfying $\phi$, so that we indeed have a $\T$-interpretation that satisfies $\phi$ with cardinality $n$. 

    Assume now that there is a $\T$-interpretation $\C$ that satisfies $\phi$ with $|\dom{\C}|=m<n$, and let $F$ be the equivalence induced by $\C$ on $V$, implying that $\C$ satisfies $\delta_{V}^{F}$. We then have that $M(\phi)\leq |V/F|\leq m\leq M$, and that $m\in \spec{\T}$, despite the fact that $m<n$ and $n$ should be the minimum such element. So $\T$ indeed has a computable minimal model function.

    For the reciprocal, the left-to-right direction, suppose that $\T$ has a computable minimal model function $\minmod_{\T}$, and we shall consider two cases: one where $\spec{\T}$ is finite, and one where it is infinite. 
    If $\spec{\T}$ is finite we have nothing left to do, as it is enough to simply hardcode these values into an algorithm that decides whether an element is in $\spec{\T}$. 
    If $\spec{\T}$ is instead infinite, the formulas $\NNEQ{x}$ are $\T$-satisfiable for all $n\in\mathbb{N}$: indeed, since $\spec{\T}$ is infinite, we can always find $m\in\spec{\T}$ such that $m\geq n$, and thus there exists a $\T$-interpretation $\A$ with $|\dom{\A}|=m$; 
    by changing at most the values assigned to the variables $x_{1},\ldots,x_{n}$ (assumed fresh), we get a $\T$-interpretation that satisfies $\NNEQ{x}$. 
    We then define $f(0)=\minmod_{\T}(x=x)$ and, assuming $f(m)$ defined, $f(m+1)=\minmod_{\T}(\NNNEQ{x}{f(m)+1})$;
    we state that $n\in\spec{\T}$ iff $n\in\{f(0),\ldots,f(n)\}$. 

    That this results in a decision procedure follows from the fact that $\minmod_{\T}$ is assumed to be computable and so is producing the formulas $\NNNEQ{x}{f(m)+1}$; 
    we have left to prove that it is both sound and complete. 
    If $n\in\{f(0),\ldots,f(n)\}$, there exists an $0\leq m< n$ such that $n=\minmod_{\T}(\NNNEQ{x}{f(m)+1})$, and so there is a $\T$-interpretation $\A$ that satisfies $\NNNEQ{x}{f(m)+1}$ with $|\dom{\A}|=n$; 
    of course $\A$ is a $\T$-interpretation with $|\dom{\A}|=n$, so $n\in\spec{\T}$ and indeed the algorithm is sound. 
    Reciprocally, if $n\in\spec{\T}$, suppose that $f(m)<n<f(m+1)$ for some $0\leq m<n$ (there is either such an element or $n=f(m)$ and we have nothing to prove, since $f(m+1)\geq f(m)+1$): because $n$ is in $\spec{\T}$, there is a $\T$-interpretation $\A$ with $|\dom{\A}|=n$; but since $n>f(m)$, $n\geq f(m)+1$, and so $\A$ satisfies $\NNNEQ{x}{f(m)+1}$. This, in combination with the fact that $f(m+1)>n$, contradicts that $f(m+1)=\minmod_{\T}(\NNNEQ{x}{f(m)+1})$, proving that the algorithm is also complete and finishing the proof.
\end{proof}






\section{\tp{Proof of \Cref{cmmf density}}{Proof of result \ref{cmmf density}}}

\begin{lemma}\label{mediant}
    Given a sequence $\fr{a_{n}}{b_{n}}$ converging to a $0<r<1$, the sequence of partial mediants
    \[\left\{\cdots,\frac{a_{0}+\cdots+a_{n}}{b_{0}+\cdots+b_{n}},\frac{a_{0}+\cdots+a_{n}+1}{b_{0}+\cdots+b_{n}+1},\cdots,\frac{a_{0}+\cdots+a_{n}+a_{n+1}}{b_{0}+\cdots+b_{n}+a_{n+1}}, \frac{a_{0}+\cdots+a_{n}+a_{n+1}}{b_{0}+\cdots+b_{n}+a_{n+1}+1},\cdots\right\}\]
    also converges to $r$.
\end{lemma}


\begin{proof}
    Because $0<r<1$, we can assume that $0<a_{n}<b_{n}$ for all $n\in\mathbb{N}$, what makes the definition of the partial mediants consistent. If we write $A(n)=\sum_{i=0}^{n}a_{n}$, and analogously for $B(n)$, and $A(m,n)=\sum_{i=n+1}^{m}a_{i}$ for $m>n$, and the same for $B(m,n)$, we see that the elements in our sequence of index $B(n)\leq i\leq B(n)+a_{n+1}$ lie between $\fr{A(n)}{B(n)}$ and $\fr{A(n+1)}{(B(n)+a_{n+1})}$, while those with index $B(n)+a_{n+1}\leq i\leq B(n+1)$ lie between $\fr{A(n+1)}{(B(n)+a_{n+1})}$ and $\fr{A(n+1)}{B(n+1)}$. So, it is enough to prove that both $\fr{A(n)}{B(n)}$ and $\fr{A(n+1)}{(B(n)+a_{n+1})}$ converge to $r$ in order to sandwich the whole sequence of partial mediants into converging to $r$.

    Take an $\epsilon>0$: because $\LIM a_{n}/b_{n}=r$, there exists an $n_{0}\in\mathbb{N}$ such that $|r-(\fr{a_{n}}{b_{n}})|\leq\fr{\epsilon}{2}$ (and thus $|rb_{n}-a_{n}|\leq b_{n}\fr{\epsilon}{2}$) for all $n\geq n_{0}$. Then, for $n>m_{0}=\max\{n_{0},k\}$, where $k=\lceil \fr{2|rB(n_{0})-A(n_{0})|}{\epsilon}\rceil$, we have
    \[\left|r-\frac{A(n)}{B(n)}\right|=\left|r-\frac{A(n_{0})+A(n,n_{0})}{B(n_{0})+B(n,n_{0})}\right|=\]
    \[\left|\frac{rB(n_{0})+rB(n,n_{0})-A(n_{0})-A(n,n_{0})}{B(n_{0})+B(n,n_{0})}\right|\leq\]
    \[\left|\frac{rB(n_{0})-A(n_{0})}{B(n_{0})+B(n,n_{0})}\right|+\left|\frac{rB(n,n_{0})-A(n,n_{0})}{B(n_{0})+B(n,n_{0})}\right|=\]
    \[\left|\frac{rB(n_{0})-A(n_{0})}{B(n)}\right|+\left|\frac{\sum_{i=n_{0}+1}^{n}rb_{i}-a_{i}}{B(n)}\right|\leq\]
    \[\frac{1}{n}|rB(n_{0})-A(n_{0})|+\frac{1}{B(n)}\sum_{i=n_{0}+1}^{n}|rb_{i}-a_{i}|\leq\]
    \[\frac{\epsilon}{2}+\frac{1}{B(n)}\sum_{i=n_{0}+1}^{n}\frac{b_{i}\epsilon}{2}=\frac{\epsilon}{2}+\frac{B(n,n_{0})\epsilon}{2B(n)}\leq\frac{\epsilon}{2}+\frac{\epsilon}{2}=\epsilon,\]
    thus proving $\LIM \fr{A(n)}{B(n)}=r$.\footnote{Notice we have used that $B(n)\geq n$.} The proof for the sequence $\fr{A(n+1)}{(B(n)+a_{n+1})}$ is similar, so we only highlight the differences. $\fr{\epsilon}{2}$ must be replaced by $\fr{\epsilon}{3}$ since we get an extra term $\fr{a_{n+1}(1-r)}{(B(n)+a_{n+1})}$, which again can be bounded from the fact that $B(n)+a_{n+1}\geq n+1$: we just need to choose $m_{0}=\max\{n_{0},K\}$, where $K=\lceil \fr{3\max\{|rB(n_{0})-A(n_{0})|, a_{n+1}(1-r)\}}{\epsilon}\rceil$.
\end{proof}

\begin{lemma}\label{comp. set comp. number}
    If $A$ is a computable set with a well-defined density, $\mu(A)$ is a computable number.
\end{lemma}


\begin{proof}
    Since we have an algorithm for deciding whether a non-negative integer is in $A$ or not, we also have one for the sequence $a_{n}$
    (where the input is $n$ and the output is $a_n$),
    such that $a_{0}=1$ if $1\in A$, and $a_{0}=0$ otherwise; and $a_{n}=a_{n-1}+1$ if $n+1\in A$, and $a_{n}=a_{n-1}$ otherwise. Of course, the sequence $b_{n}=n+1$ is also computable. Now, by definition of $a_{n}$, $a_{n}=|\AA{n+1}|$, and therefore $\mu(A)=\LIM \fr{|\An|}{n}=\LIM \fr{a_{n-1}}{b_{n-1}}$, so $\mu(A)$ is indeed computable.
\end{proof}

\cmmfdensity*

\begin{proof}
    The first part of the theorem follows from \Cref{cmmf and computability,comp. set comp. number}.

    If $r=0$, we take the theory $\Tpt$ from \Cref{example SI density}, axiomatized by $\{\psi_{\geq 2^{n+1}}\vee\bigvee_{i=1}^{n}\psi_{=2^{n}} : n\in\No\}$; 
    if $r=1$, we take the theory $\Tnpt$ from \Cref{example gentle density}, axiomatized by $\{\neg\psi_{=2^{n}} : n\in\No\}$. 
    We already know $\mu(\T_{0})=0$ and $\mu(\T_{1})=1$:
    since their spectra are, respectively, the sets of power of two and non powers of two, both computable, we have by \Cref{cmmf and computability} that both have computable minimal model functions.


    With these cases out of the way, we can assume that $0<r<1$, and thus there exist computable sequences (since $r$ is computable) $\{a_{n}\}_{n\in\mathbb{N}}$ in $\mathbb{N}$, and $\{b_{n}\}_{n\in\mathbb{N}}$ in $\No $ such that $r=\LIM \fr{a_{n}}{b_{n}}$ with $0<a_{n}<b_{n}$ for all $n\in\mathbb{N}$. 
    We then take the function $f$ associated with $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$, from \Cref{definition of f}, and define $\T$ to be axiomatized by $\{\psi_{\geq f(n+1)}\vee\bigvee_{i=1}^{n}\psi_{=f(i)} : n\in\No \}$, from what it is clear that $\spec{\T}=\{f(n) : n\in\No \}$. Since $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$ are computable, so is $f$: 
    indeed, the computability of $\{b_{n}\}_{n\in\mathbb{N}}$ implies $M=\sum_{i=0}^{m}b_{i}$ is computable;
    and then the computability of $\{a_{n}\}_{n\in\mathbb{N}}$ implies $f(n)=n$, for $M+1\leq n\leq M+a_{m}$, and $f(n)=n+a_{m}$, for $M+a_{m}+1\leq n\leq M+b_{m}$, are computable. 
    Therefore $\spec{\T}$ is computable: 
    indeed, as $\spec{\T}$ is the image of the non-decreasing function $f$, and $f(1+\sum_{i=0}^{m}b_{i})=1+\sum_{i=0}^{m}b_{i}$, it is enough, to test whether $n\in\spec{\T}$, to check if $n\in\{f(1),\ldots,f(1+\sum_{i=0}^{n}b_{i})\}$ (recall $\{b_{n}\}_{n\in\mathbb{N}}$ is a computable sequence of positive numbers, so $\sum_{i=0}^{n}b_{i}\geq n$). 
    From \Cref{cmmf and computability} we have $\T$ has a computable minimal model function, and thus from \cite[Theorem~4]{LPAR} we have $\T$ is finitely witnessable.
    Finally, $\mu(\T)$ will equal the limit of partial mediants as defined in \Cref{mediant}, if the latter is well-defined, what the result further shows it is and equals in turn $r$: indeed, assuming for an inductive argument that $\fr{|\Spec_{M}{\T}|}{M}$ equals $\fr{(a_{0}+\cdots+a_{m})}{(b_{0}+\cdots+b_{m})}$ for $M=b_{0}+\cdots+b_{m}$, since $f(n)=n$ for $M+1\leq n\leq M+a_{m+1}$ we obtain 
    \[\frac{|\specn{\T}|}{n}=\frac{a_{0}+\cdots+a_{m}+(n-M)}{n}=\frac{a_{0}+\cdots+a_{m}+(n-M)}{b_{0}+\cdots+b_{m}+(n-M)}\]
    for these values; and for $M+a_{m+1}+1\leq n\leq M+b_{m+1}$ we have $f(n)=n+a_{m}$, so for these values
    \[\frac{|\specn{\T}|}{n}=\frac{a_{0}+\cdots+a_{m}+a_{m+1}}{n}=\frac{a_{0}+\cdots+a_{m}+a_{m+1}}{b_{0}+\cdots+b_{m}+(n-M-a_{m+1})},\]
    and in both cases we obtain the aforementioned partial mediants.
\end{proof}

\section{\tp{Proof of \Cref{FW density general case}}{Proof of result \ref{FW density general case}}}

\FWdensitygeneralcase*

\begin{proof}
We divide the proof in two big cases: when $r$ is not computable, and when it is.
\begin{enumerate}
    \item Of course $0<r<1$, as both $0$ and $1$ are computable: because $r$ can be written in decimal notation as $0.0\cdots0d_{0}d_{1}d_{2}\cdots$, for digits $d_{i}\in\{0,1,\ldots, 9\}$ and $d_{0}\neq 0$, we can write $r$ as the limit of $\fr{a_{n}}{b_{n}}$, where $a_{n}=d_{0}\cdots d_{n}$, $b_{n}=10^{M+n}$, and $M$ is the number of zeros before $d_{0}$ (including the one before the decimal dot); this way, $0<a_{n}<b_{n}$ for all $n\in\mathbb{N}$. By the fact that $r$ is not computable, and since $\{b_{n}\}_{n\in\mathbb{N}}$ is certainly computable, $\{a_{n}\}_{n\in\mathbb{N}}$ cannot be so. We take the function $f$ associated with $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$, as in \Cref{definition of f}, and the theory $\T$ axiomatized by $\{\psi_{\geq f(n+1)}\vee\bigvee_{i=1}^{n}\psi_{=f(i)} : n\in\No \}$: the theory is not strongly finitely witnessable because it is not smooth (see \cite[Theorem~7]{CADE}); furthermore, since $\{b_{n}\}_{n\in\mathbb{N}}$ is computable but $\{a_{n}\}_{n\in\mathbb{N}}$ is not, $f$ is also not computable, and since $\spec{\T}=\{f(n) : n\in\No \}$, we have that $\T$ does not have a computable minimal model function (\Cref{cmmf and computability}).

    Is is clear that $\mu(\T)$ is the limit of the mediants $\fr{(a_{0}+\cdots+a_{n})}{(b_{0}+\cdots+b_{n})}$, which from \Cref{mediant} is $\LIM \fr{a_{n}}{b_{n}}=r$; so we only have left to prove that $\T$ has a witness. For a quantifier-free formula $\phi$, let $N$ be the smallest $n\geq M$ such that $10^{N}\geq|\vars(\phi)|$, define $N(\phi)=\sum_{i=M}^{N}10^{i}$, and
    \[\wit(\phi)=\phi\wedge\bigwedge_{i=1}^{N(\phi)}x_{i}=x_{i}\]
    where the $x_{i}$ are fresh variables: we claim this function is a witness, obviously mapping quantifier-free formulas into quantifier-free formulas, and being computable, given that finding $|\vars(\phi)|$ and $N$ are both computable procedures. Furthermore, for $\overarrow{x}=\vars(\wit(\phi))\setminus\vars(\phi)$, it is clear that $\Exists{\overarrow{x}}\wit(\phi)$ and $\phi$ are $\T$-equivalent, given that in fact $\phi$ and $\wit(\phi)$ are themselves equivalent. Suppose then that $\A$ is a $\T$-interpretation that satisfies $\phi$, take a set $X$ disjoint from $\dom{\A}$ with cardinality $N(\phi)-|\vars(\phi)^{\A}|$, and we construct an interpretation $\B$ by making: $\dom{\B}=\vars(\phi)^{\A}\cup X$ (so $|\dom{\B}|=N(\phi)$, which is a cardinality in $\spec{\T}$); $x^{\B}=x^{\A}$ for all $x\in\vars(\phi)$; $x\in\{x_{i} : 1\leq i\leq N(\phi)\}\mapsto x^{\B}$ an injective function; and $x^{\B}$ can be set arbitrarily for all other variables. Then it is true that $\B$ satisfies $\wit(\phi)$ and $\dom{\B}=\vars(\wit(\phi))^{\B}$, finishing the proof.

\item Because $0\leq r\leq 1$ is computable, there are computable sequences $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$ such that $0<a_{n}<b_{n}$ and $\LIM \fr{a_{n}}{b_{n}}=r$. Now, take a non-computable function $g:\No\rightarrow\{0,1\}$. We then define a function $\mf:\No\rightarrow\{0,1\}$ by induction.
    \begin{enumerate}
        \item 
        \begin{enumerate}
          \item $\mf(1)=g(1)$.
          \item $\mf(n)=0$ for: $2\leq n\leq 2(b_{0}-a_{0})$ (since $b_{0}>a_{0}$, $2(b_{0}-a_{0})\geq 2$) if $g(1)=0$; and $2\leq n\leq 2(b_{0}-a_{0})+1$ if $g(1)=1$.
          \item $\mf(n)=1$ for: $2(b_{0}-a_{0})+1\leq n\leq 2b_{0}$ if $g(1)=0$; and $2(b_{0}-a_{0})+2\leq n\leq 2b_{0}$ (since $b_{0}>a_{0}$, $2b_{0}\geq 2(b_{0}-a_{0})+2$) if $g(1)=1$.
        \end{enumerate}
        \item Now, assume $\mf(n)$ has been defined for $1\leq n\leq 2\sum_{i=0}^{m}b_{i}$.
        \begin{enumerate}
            \item $\mf(1+2\sum_{i=0}^{m}b_{i})=g(m+2)$;
            \item $\mf(n)=0$ for: $2+2\sum_{i=0}^{m}b_{i}\leq n\leq 2(b_{m+1}-a_{m+1})+2\sum_{i=0}^{m}b_{i}$ if $g(m+2)=0$; and $2+2\sum_{i=0}^{m}b_{i}\leq n\leq 1+2(b_{m+1}-a_{m+1})+2\sum_{i=0}^{m}b_{i}$ if $g(m+2)=1$.
            \item $\mf(n)=1$ for: $1+2(b_{m+1}-a_{m+1})+2\sum_{i=0}^{m}b_{i}\leq n\leq +2\sum_{i=0}^{m+1}b_{i}$ if $g(m+2)=0$; and $2+2(b_{m+1}-a_{m+1})+2\sum_{i=0}^{m}b_{i}\leq n\leq +2\sum_{i=0}^{m+1}b_{i}$ if $g(m+2)=1$.
        \end{enumerate}
    \end{enumerate}
    We see that $\mf$ is not computable because: the function $\rho:\No\rightarrow\No$ given by $\rho(1)=1$ and $\rho(m)=1+2\sum_{i=0}^{m-1}b_{i}$, for $m>1$, is computable, given that $\{b_{n}\}_{n\in\mathbb{N}}$ is computable; and, despite that, $\mf\circ\rho(m)=g(m)$, which is not computable.

    We can finally define the $\Sigma_{1}$-theory by the axiomatization 
    \[\{\psi_{\geq f(n+1)}\vee\bigvee_{i=1}^{n}\psi_{=f(i)} : n\in\No \},\]
    where $f:\No\rightarrow\No$ is defined as $f(n)=\min\{m\geq n : \mf(m)=1\}$, so that $\spec{\T}=\{f(n) : n\in\No\}$, and $|\specn{\T}|=|\{1\leq i\leq n : \mf(i)=1\}|$: this means $|\Spec_{2\sum_{i=0}^{m}b_{i}}(\T)|=2\sum_{i=0}^{m}a_{i}$, leading us again to partial mediants; from \Cref{mediant} we get $\mu(\T)$ equals $\LIM \fr{2a_{n}}{2b_{n}}$, which is precisely $r$. From the fact that $\mf$ is not computable it follows that $\spec{\T}$ is not computable, so from \Cref{cmmf and computability} $\T$ does not have a computable minimal model function. It only remains for us to show that $\T$ has a witness: so, for a quantifier-free formula $\phi$, let $N(\phi)$ be the minimum of $2\sum_{i=0}^{m}b_{i}$ greater than or equal to $|\vars(\phi)|$; this value is computable given the sequences $\{a_{n}\}_{n\in\mathbb{N}}$ and $\{b_{n}\}_{n\in\mathbb{N}}$ are themselves computable. For $x_{i}$ fresh variables, we define 
    \[\wit(\phi)=\phi\wedge\bigwedge_{i=1}^{N(\phi)}x_{i}=x_{i}:\]
    this obviously maps quantifier-free formulas into themselves, and is computable given that finding $N(\phi)$ from $\phi$ can be done algorithmically. It is also clear that $\phi$ and $\Exists{\overarrow{x}}\wit(\phi)$ are $\T$-equivalent, for $\overarrow{x}=\vars(\wit(\phi))\setminus\vars(\phi)$, since $\wit(\phi)$ is the conjunction of $\phi$ and a tautology. Finally, suppose that $\A$ is a $\T$-interpretation that satisfies $\phi$, and take a set $X$ disjoint from $\dom{\A}$ with $N(\phi)-|\vars(\phi)^{\A}|$ elements. We define an interpretation $\B$ by making: $\dom{\B}=\vars(\phi)^{\A}\cup X$ (so $|\dom{\B}|=N(\phi)$, and since $N(\phi)=2\sum_{i=0}^{m}b_{i}$ and $\mf(2\sum_{i=0}^{m}b_{i})=1$, we obtain $\B$ is a $\T$-interpretation); $x^{\B}=x^{\A}$ for all $x\in\vars(\phi)$; $x_{i}\in\{x_{i} : 1\leq i\leq N(\phi)\}\mapsto x_{i}^{\B}\in \dom{\B}$ an injective map; and arbitrarily for all other variables. We then have that $\B$ is a $\T$-interpretation that satisfies $\phi$, and $\dom{\B}=\vars(\wit(\phi))^{\B}$.
\end{enumerate}
\end{proof}






\section{\tp{Proof of \Cref{SI FMP non empty}}{Proof of result \ref{SI FMP non empty}}}

\SIFMPnonempty*

\begin{proof}
    Suppose $\T$ is not stably infinite, and thus there exists a quantifier-free formula $\phi$ such that no infinite $\T$-interpretation satisfies $\phi$. 
    This means there exists an $M\in\mathbb{N}$ such that no $\T$-interpretation $\A$ that satisfies $\phi$ has $|\dom{\A}|>M$: 
    were that not true, we could obtain a sequence of $\T$-interpretations $\A_{n}$ that satisfy $\phi$, with $|\dom{\A_{n}}|\geq n$; since $\A_{n}$ satisfies the axiomatization of $\T$, $\phi$ and $\{\psi_{\geq 1}, \ldots , \psi_{\geq n}\}$, we get by \Cref{compactness} that the axiomatization of $\T$, $\phi$ and $\{\psi_{\geq n}:n\in \mathbb{N}\}$ are simultaneously satisfiable, leading to a contradiction. So $\specn{\T,\phi}=\Spec_{M}(\T,\phi)$ for $n\geq M$, giving us $\mu(\T,\phi)\leq \LIM\fr{M}{n}=0$, and the result for stable infiniteness follows from the contrapositive.

    If $\T$ does not have the finite model property, there exists a quantifier-free formula $\phi$ such that no finite $\T$-interpretation satisfies $\phi$: that means $\spec{\T,\phi}=\emptyset$, and so $\mu(\T,\phi)=0$, the result for the finite model property easily following.
\end{proof}

\section{\tp{Proof of \Cref{smooth non empty}}{Proof of result \ref{smooth non empty}}}

\smoothnonempty*

\begin{proof}
    If $\T$ is smooth and has the finite model property, for every quantifier-free $\T$-satisfiable formula $\phi$ there exists $M\in\mathbb{N}$ such that for all $n\geq M$ there exists a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=n$. That means $[1,n]\setminus\specn{\T,\phi}\subseteq [1,M]$, for $n\geq M$, and so $\mu(\T,\phi)\geq \LIM\fr{(n-M)}{n}=1$.
\end{proof}


\section{\tp{Proof of \Cref{SFW non empty}}{Proof of result \ref{SFW non empty}}}

The following technical lemma is a version of \cite[Theorem~7]{CADE}, modified to hold locally, that is, for every quantifier-free formula.

\begin{lemma}\label{CADE like result}
    If $\T$ is a strongly finitely witnessable theory, for all quantifier-free formulas $\phi$, we have that: 
    either $\phi$ is not satisfied by any infinite $\T$-in\-ter\-pre\-ta\-tions;
    or there exists $M\in\mathbb{N}$ such that, for all cardinals $M\leq\kappa\leq\aleph_{0}$, there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=\kappa$.
\end{lemma}

\begin{proof}
    Suppose that $\phi$ is satisfied by an infinite $\T$-interpretation $\A$: We may assume that $|\dom{\A}|=\aleph_{0}$ by \Cref{LowenheimSkolem}.
    Since $\phi$ and $\Exists{\overarrow{x}}\wit(\phi)$ are $\T$-equivalent, for $\overarrow{x}=\vars(\wit(\phi))\setminus\vars(\phi)$, we may change the value assigned to some variables by $\A$ in order to obtain a $\T$-interpretation $\A^{\prime}$ that satisfies $\wit(\phi)$ which still has $|\dom{\A^{\prime}}|=\aleph_{0}$. 
    Let $U$ be $\vars(\wit(\phi))$, and $\delta_{U}$ the arrangement on $U$ such that $x$ is associated with $y$ iff $x^{\A^{\prime}}=y^{\A^{\prime}}$, meaning that $\A^{\prime}$ satisfies $\delta_{U}$.
    From that, $\A^{\prime}$ satisfies $\wit(\phi)\wedge\delta_{U}$, meaning there is a $\T$-interpretation $\B$ (from the fact that $\wit$ is a strong witness) that satisfies $\wit(\phi)\wedge\delta_{U}$, and thus $\phi$, with $\dom{\B}=\vars(\wit(\phi)\wedge\delta_{U})^{\B}=U^{\B}$.

    We state it is now possible to find a $\T$-interpretation $\C$ that satisfies $\phi$ with any cardinality $\kappa$ between $M=|\dom{\B}|$ and $\aleph_{0}$. 
    Indeed, if $\kappa=M$ we are done. 
    Otherwise, take a fresh set of variables $U^{\prime}$ with cardinality $\kappa-M$, and define an arrangement $\delta_{V}$ on $V=U\cup U^{\prime}$ such that $x$ is related to $y$ according to $\delta_{V}$ iff either $x=y$, or $x,y\in U$ and $x^{\B}=y^{\B}$;
    notice we can write 
    \[\delta_{V}=\delta_{U}\wedge\delta_{U^{\prime}}\wedge\bigwedge_{x\in U, y\in U^{\prime}}\neg(x=y),\]
    where $\delta_{U^{\prime}}$ corresponds to the identity on $U^{\prime}$. 
    Notice now that $\wit(\phi)\wedge\delta_{V}$ is $\T$-satisfiable: 
    indeed, $\A^{\prime}$ satisfies $\wit(\phi)\wedge\delta_{U}$, and by changing at most the values assigned by $\A^{\prime}$ to the (fresh) variables in $U^{\prime}$, we get a $\T$-interpretation $\A^{\prime\prime}$ that satisfies $\wit(\phi)\wedge\delta_{V}$.

    This means, again from the fact that $\wit$ is a strong witness, that there is a $\T$-interpretation $\C$ that satisfies $\wit(\phi)\wedge\delta_{V}$, with $\dom{\C}=\vars(\wit(\phi)\wedge\delta_{V})^{\C}=V^{\C}$.
    Since $\C$ satisfies $\wit(\phi)$, it satisfies $\Exists{\overarrow{x}}\wit(\phi)$ and thus $\phi$. 
    And since $\dom{\C}=V^{\C}$, where $U^{\C}$ must have $M$ elements (since $\C$ satisfies $\delta_{U}$), and $(U^{\prime})^{\C}$ must have another $\kappa-M$ elements (since $\C$ satisfies $\delta_{V}$), we get $|\dom{\C}|=\kappa$, as we wanted to show.

\end{proof}

\SFWnonempty*

\begin{proof}
     By \Cref{CADE like result}, either $\phi$ is not satisfied by an infinite $\T$-interpretation, or $\spec{\T,\phi}$ contains all elements greater than or equal to some $M$: from the second case it clearly follows that $\mu(\T,\phi)\geq\LIM\fr{(n-M+1)}{n}=1$. 
     In the first, we state $\spec{\T,\phi}$ must be finite: otherwise we should be able to get an infinite $\T$-interpretation that satisfies $\phi$ by using \Cref{compactness}.
     This way, $\spec{\T,\phi}$ must be bounded by some $M$, and so $\mu(\T,\phi)\leq\LIM\fr{M}{n}=0$.
\end{proof}

\section{\tp{Proof of \Cref{cmmf and computability gen}}{Proof of result \ref{cmmf and computability gen}}}

\cmmfcomputabilitygen*


\begin{proof}
     Suppose that $\T$ has a computable minimal model function $\minmod_{\T}$, and we shall consider two cases: 
     one where $\spec{\T,\phi}$ is finite, and one where it is infinite. 
     If $\spec{\T,\phi}$ is finite we have nothing left to do, as it is enough to simply hardcode these values into an algorithm that decides whether an element is in $\spec{\T,\phi}$. 
     If $\spec{T,\phi}$ is instead infinite, $\phi$ is $\T$-satisfiable (as $\spec{\T,\phi}$ is not empty) and, in addition, the formulas $\phi\wedge\NNEQ{x}$ are $\T$-satisfiable for all $n\in\mathbb{N}$: 
     indeed, since $\spec{\T,\phi}$ is infinite, we can always find $m\in\spec{\T,\phi}$ such that $m\geq n$, and thus there exists a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=m$; 
     by changing at most the value assigned to the variables $x_{1},\ldots,x_{n}$ (assumed fresh), we get a $\T$-interpretation that satisfies $\phi\wedge\NNEQ{x}$. 
     Given then $n$, we define $f(0)=\minmod_{\T}(\phi)$, and assuming $f(m)$ defined $f(m+1)=\minmod_{\T}(\phi\wedge\NNNEQ{x}{f(m)+1})$, and then we state that $n\in\spec{\T,\phi}$ iff $n\in\{f(0),\ldots,f(n)\}$. 

    That this results in a decision procedure follows from the fact that $\minmod_{\T}$ is assumed to be computable, and so is producing the formulas $\NNNEQ{x}{f(m)+1}$; 
    we have left to prove that it is both sound and complete. 
    If $n\in\{f(0),\ldots,f(n)\}$, there exists an $0\leq m< n$ such that $n=\minmod_{\T}(\phi\wedge\NNNEQ{x}{f(m)+1})$, and so there is a $\T$-interpretation $\A$ that satisfies $\phi\wedge\NNNEQ{x}{f(m)+1}$ with $|\dom{\A}|=n$; of course $\A$ is a $\T$-interpretation that satisfies $\phi$ with $|\dom{\A}|=n$, so $n\in\spec{\T,\phi}$ and indeed the algorithm is sound. 
    Reciprocally, if $n\in\spec{\T,\phi}$, suppose that $f(m)<n<f(m+1)$ for some $0\leq m<n$ (there is either such an element or $n=f(m)$ and we have nothing to prove, since $f(m+1)\geq f(m)+1$): 
    because $n$ is in $\spec{\T,\phi}$, there is a $\T$-interpretation $\A$ that satisfies $\phi$ with $|\dom{\A}|=n$; 
    but since $n>f(m)$, $n\geq f(m)+1$, and so $\A$ satisfies $\phi\wedge\NNNEQ{x}{f(m)+1}$. 
    This, in combination with the fact that $f(m+1)>n$, contradicts that $f(m+1)=\minmod_{\T}(\phi\wedge\NNNEQ{x}{f(m)+1})$, proving that the algorithm is also complete and finishing the proof.
\end{proof}

\section{\tp{Proof of \Cref{CMMF non empty}}{Proof of result \ref{CMMF non empty}}}

\CMMFnonempty*

\begin{proof}
If $\T$ has a minimal model function, \Cref{cmmf and computability gen} guarantees all $\spec{\T,\phi}$ are computable, and by \Cref{comp. set comp. number} it follows that all $\mu(\T,\phi)$ are computable. 

Finally, for every computable $r$, we get a theory $\T$ with a computable minimal model function and $\mu(\T)=r$ from \Cref{cmmf density}, and it follows that for any tautology $\phi$ it is true that $\mu(\T,\phi)=r$.

\end{proof}

\section{\tp{Proof of \Cref{FW non empty}}{Proof of result \ref{FW non empty}}}

\FWnonempty*

\begin{proof}
    Follows trivially from \Cref{FW density general case}: taking, for any $0\leq r\leq 1$, a finitely witnessable theory $\T$ (without a computable minimal model function) with $\mu(\T)=r$, and a tautology $\phi$, $\mu(\T,\phi)=r$.
