\figref{fig:illu_single} shows the equal distance ratio circles for $b=1$ and $\rho^{2}=2,3,5,10,20$.
Interpreted in a wireless context,
the circles represent the locations on the plane at which an SIR of exactly
$\rho^{2}$ is achieved
in a line-of-sight environment if the desired transmitter is at $(0,0)$ and the interferer at $(b,0)$. 
Letting $r_1=\sqrt{x^2+y^2}$ and $r_2=\sqrt{(x-b)^2+y^2}$ be the distances from $(x,y)$ to $(0,0)$ and $(b,0)$,
respectively, the
SIR is given by the squared distance ratio
\[ \sir_{(x,y)} = \frac{r_1^{-2}}{r_2^{-2}}=\frac{(x-b)^2+y^2}{x^2+y^2} .\]
Hence the locations at which $\sir=\rho^2$ form a circle as given by Lemma \ref{lem:edrc}.

For $\rho>1$, $\sir>\rho^2$ is achieved at locations inside the circle, while for $\rho<1$, it is achieved at locations
outside the circle.
This fact is compactly represented using a M\"obius transform on the complex plane.

\begin{lemma}[M\"obius transform characterization]
Let $\z,\z'\in\C$ denoted the locations of the desired transmitter and interferer in the complex plane.
For $\rho\neq 1$, let 
\begin{equation}
 f_{\rho}(z)\triangleq c+\rho|c|\frac{z-\rho c}{z+\rho c}, \quad z\in\C,
\label{mobi}
\end{equation}
where $c=\|\z'-\z\|/(1-\rho^2)$. 
For $\rho=1$, $f_1(z)\triangleq z+\|\z'-\z\|/2$.

Then, for $\w\in\C$,
\begin{equation}
  \frac{|\w-\z'|}{|\w-\z|}>\rho \quad\Leftrightarrow \quad \w\in \z+f_\rho(H^-)e^{\iu\arg(\z'-\z)}, 
   \label{sirw}
\end{equation}
where $H^-\triangleq \{z\in\C\colon \Re(z)<0\}$ is the open left half-plane of $\C$.
\label{lem:mobi}
\end{lemma}
\begin{IEEEproof}
The modulus of the fraction in \eqref{mobi} is $1$ on the imaginary axis while its argument
ranges from $-\pi$ to $\pi$, so the axis is mapped onto
the circle of radius $\rho|c|$ centered at $c$. The half-plane $H^-$ is mapped inside the circle
if $\rho>1$, since $\Re(z)<0$ decreases the modulus for $c<0$. Conversely,
$\rho<1$, $\Re(z)<0$ increases the modulus since $c>0$.
The rotation and translation in \eqref{sirw} place the disk in the correct position relative to $\z,\z'$.
\end{IEEEproof}
{\em Remarks.}
\begin{itemize}
\item The transform \eqref{mobi} is a generalization of the bilinear transform 
that maps $H^-$ to $|z|<1$
commonly used in digital signal
processing for the continuous time-to-discrete time mapping of
 system functions.
\item Applying the transform to the imaginary axis, with $\z=0$ and $\z'=b$, 
yields the circle in Lemma \ref{lem:edrc} for
$\rho\neq 1$. For $\rho=1$, the definition of $f_1$ ensures that this equivalence extends to the case of
equidistant points to $0$ and $b$, and that $b/(1+\rho)$ lies in the image of the imaginary axis for any $\rho$.
\end{itemize}

\section{Coverage and Stringency}
\subsection{Network Model}
Let $\calX=\{\x_1,\x_2,\ldots\}\subset\R^2$ be a countable set of transmitter locations with at least two elements.
For $\y\in\R^2$, we let $\calX_{-\y}\triangleq\{\x_i-\y\}_{i\in\N}$
be the translated set, and we let $r_i$ be the $i$-th smallest element of $\|\calX_{-\y}\|$,
such that $r_1$ is the distance from $\y$ to the closest transmitter.

With nearest-transmitter association, a path loss exponent $\alpha$, and unit transmit powers, the SIR at location $\y$ is
\[\sir_\y = \frac{h_1 r_1^{-\alpha}}{\sum_{i>1} h_i r_i^{-\alpha}}
 = \frac1{\sum_{i>1} \frac{1}{H_i} \big(\frac{r_1}{r_i}\big)^\alpha}   , \]
where the coefficients $H_i\triangleq h_1/h_i$, $i>1$, are identically distributed with cdf $F_H$.
All $(h_i)_{i\in\N}$ are independent with $\E h_i=1$, and for $i>1$, they are identically distributed.
This formulation allows for different fading distributions for the desired transmitter and the interferers.
In particular, we consider Nakagami fading with parameter $p>0$ for $h_1$ and parameter $q>0$ for $h_i$, $i>1$,
which we refer to as Nakagami-$(p,q)$ fading\footnote{Nakagami-$m$ refers to the symmetric
case $p=q=m$.}.
In this case
\begin{equation}
   F_H(x)=B_{p,q}\left(\frac{px}{px+q}\right) = B_{p,q}\big(\mh{(x\tfrac pq)}\big), 
   \label{gamma_rat}
\end{equation}
where
\[ B_{p,q}(x)\triangleq \frac{\Gamma(p+q)}{\Gamma(p)\Gamma(q)} \int_0^x t^{p-1}(1-t)^{q-1}\dd t, \quad x\in[0,1] ,\]
is the regularized incomplete beta function\footnote{In Matlab, {\tt betainc(x,p,q)}.}, \ie,
the cdf of the beta distribution.
It satisfies $B_{p,q}(1-x)\equiv 1-B_{q,p}(x)$, which reflects the fact that the distribution of $1/H_i$ is related to that
of $H_i$ by flipping $p$ and $q$.
Its inverse\footnote{In Matlab, {\tt betaincinv(u,p,q)}.}
is denoted as $B_{p,q}^{-1}$, \ie, $B_{p,q}(B_{p,q}^{-1}(u))\equiv u$. 


\iffalse
