\section{Bounding the Coverage Manifold Using Q Cells}
\subsection{Q Cells}
\begin{definition}[Q cell]
The Q cell of transmitter $\x\in\calX$, denoted as $Q_\x$, is defined as
\begin{equation}
   Q_{\x}(\rho)\triangleq\Big\{\y\in\R^2\colon \frac{\|\calX\setminus\{\x\}-\y\|}{\|\x-\y\|}>\rho\Big\},\quad \rho>0, 
   \label{defq}
\end{equation}
where $\|\calX\setminus\{\x\}-\y\|$ is the distance to the interferer closest to $\y$.
\end{definition}
The next lemma shows that the Q cell can be analytically described using the M\"obius transform put forth in Lemma \ref{lem:mobi}.
\begin{lemma}[Complex Q cell characterization]
For $\z\in\calX^\sharp$, let
\begin{equation}
   Z_{\z}(\rho) \triangleq \z+\bigcap_{\z'\in\calX^\sharp\setminus\{\z\}} f_\rho(H^-)e^{j\arg(\z'-z)},
   \label{qcell}
\end{equation}
with $f_\rho$ given in \eqref{mobi}. Then $Q_{\x}(\rho)\equiv Z_{\x^\sharp}^\flat(\rho)$.
\end{lemma}
\begin{IEEEproof}
The right side of \eqref{qcell} consists of the locations at which the distance
ratio $|\z'|/|\z|>\rho$ for each interferer $\z'$. This is equivalent to the condition in \eqref{defq} since
if the condition is satisfied for the nearest interferer, it is satisfied for all interferers.
\end{IEEEproof}
{\em Remarks.}
\begin{itemize}
\item For $\rho=1$, the Q cell $Q_\x$ corresponds to the interior of the Voronoi cell $V_\x$,
which is defined as the intersection of the half planes
delineated by the perpendicular bisectors of $\z$ and $\z'$.
\item For $\rho\neq 1$, the Q cell is
the intersection of the regions whose boundaries are the equal distance ratio
circles in Lemma \ref{lem:edrc}.
\begin{itemize}
\item For $\rho>1$, the half planes get morphed into disks per $f_\rho$, and the Q cell is the intersection of these
$|\calX|-1$ disks.
\item For $\rho<1$, the Q cell consists of $\R^2$ (or $\C$) minus a union of exclusion disks for each interferer. 
\end{itemize}
For a given stringency, increasing $\alpha$ reduces $\rho$ if $\rho>1$, resulting in larger Q cell.
If $\rho<1$, increasing $\alpha$ increases $\rho$, which enlarges the exclusions disks.

\item Not every interferer contributes to the shaping of the Q cell. Those that do are termed {\em strong interferers}.

\end{itemize}

\begin{definition}[Strong and dominant interferers]
$\x'$ is a {\em strong interferer} to $\x$ for a given $\rho$ if the removal of $\x'$ increases the Q cell.

A {\em dominant interferer} at location $\y$ is an interferer that by itself is strong enough to cause $\y$ to be uncovered.
\end{definition}

{\em Remarks.}
\begin{itemize}
\item For $\rho<1$, every interferer is strong.
\item For $\rho>1$, the intersection of the $|\calX|-1$ disks in the definition of $Q_\x$ can be reduced to the
intersection of the disks of the strong interferers to $\x$. By Lemma \ref{lem:inter}, their number determines the number of arcs $\na_\x$ that define the boundary of $Q_{\x}$. $\na_\x$ equals the number of Delaunay neighbors of $\x$.
The number of dominant interferers at $\y$
equals the number of disks that $\y$ is outside of. For $\y\in Q_\x$, there are no dominant interferers.
\item For $\rho\downarrow 1$, the number of strong interferers to $\x$ tends to the number of sides
of the Voronoi cell of $\x$. As $\rho\to\infty$, the number may decrease to $1$. 
\item
Denote by $V_{\x\x'}$ the second-order Voronoi cell of $\x$ and $\x'$, \ie, the set of locations that have
$\x$ and $\x'$ as their two closest points in $\calX$ \cite{net:Lee82tcomp,net:Giovanidis15twc}. If 
\[ \y\in (V_{\x}\cap V_{\x\x'})\setminus Q_\x ,\]
$\x'$ is the dominant interferer at $\y$. %, \ie, the interference from $\x'$ alone causes $\y$ to be not covered.
\item By construction, the corner points of the Q cell lie on an edge of the second-order Voronoi diagram.
These are the locations that have exactly two dominant interferers at equal distance. This property will be
exploited in Subsec.~\ref{sec:cutting}. 
\end{itemize}
An example Q cell for $\rho=\sqrt 2$ with the dominant interferers and their equal distance ratio circles is shown in \figref{fig:qcell_map}. As stipulated, the corner points of the Q cell lie on edges of the second-order Voronoi diagram,
which are shown in white.

