 \sum_{n\in {\mathcal N}^{i}_{r}}\tau_{r,n}^{i}  & \leq \sum_{j\in {\mathcal O}}S^{j\rightarrow i}_{t,r} , \ \forall {i} \in {\mathcal O}, \forall{r} \in {\mathcal R}.
 \label{maxschedule_staticsharing} 
%\nonumber
  % \\& & & \left(Q_{min}-Q^{i}_{r,n} (\tau_{r,n}^{i}) +\alpha\right)_+ \leq  \alpha (1-0.95\rho^i_{r,n})\nonumber
