\begin{algorithm}
\caption{LLM as Surrogate Model}\label{algo: LLM as surrogate}
\begin{algorithmic}[1]
\REQUIRE $X$, $Y$, $U$, $LLM$, $Opt$.
\ENSURE $\tilde{Y}$.
\STATE $\tilde{Y} \gets \emptyset$
\STATE $X, U \gets \text{Preprocessing}(X, U)$
\FOR{$u \in U$}
    \STATE $prompt \gets \text{GeneratePrompt}(X, Y, u, Opt)$
    \STATE $response \gets \text{Inference}(LLM, prompt)$
    \STATE $y \gets \text{PostProcessing}(response, Opt)$
    \STATE $\tilde{Y} \gets \tilde{Y} \cup y$
\ENDFOR
\end{algorithmic}
\end{algorithm}

