\begin{algorithm}
\caption{Pseudo code of LMEA}\label{alg: LMEA}
\begin{algorithmic}[1]
\REQUIRE Optimization problem $T$, maximum generations $G$, population size $N$
\ENSURE Best found solution $s^*$
\STATE Initialize population $P$ with $N$ random solutions for $T$
\STATE Set generation counter $g \gets 1$
\WHILE{$g \leq G$}
    \STATE Construct a prompt based on $T$ and $P$
    \STATE Generate $N$ offspring solutions $P'$ using LLM with the constructed prompt
    \STATE Select the top $N$ solutions from $P \cup P'$
    \STATE Adjust LLM parameters (e.g., temperature) if necessary
    \STATE Increment generation counter $g \gets g + 1$
\ENDWHILE
\STATE Select the best solution $s^*$ from $P$
\RETURN $s^*$
\end{algorithmic}
\end{algorithm}

