\section{Petri Nets} \label{def-sec}
%
%%% 

\begin{definition}\label{multiset}{\bf (Multiset)}\index{Multiset}
Let $\nat$ be the set of natural numbers. 
A {\em multiset} over a finite set $S$ is a function $m: S \rightarrow\nat$. 
The {\em support set} $dom(m)$ of $m$ is $\{ s \in S \mid m(s) \neq 0\}$. 
The set of all multisets 
over $S$,  denoted by ${\mathcal M}(S)$, is ranged over by $m$. 
We write $s \in m$ if $m(s)>0$.
The {\em multiplicity} of $s$ in $m$ is given by the number $m(s)$. The {\em size} of $m$, denoted by $|m|$,
is the number $\sum_{s\in S} m(s)$, i.e., the total number of its elements.
A multiset $m$ such 
that $dom(m) = \emptyset$ is called {\em empty} and is denoted by $\theta$.
We write $m \subseteq m'$ if $m(s) \leq m'(s)$ for all $s \in S$. 
{\em Multiset union} $\_ \oplus \_$ is defined as follows: $(m \oplus m')(s)$ $ = m(s) + m'(s)$; it 
is commutative, associative and has $\theta$ as neutral element. 
{\em Multiset difference} $\_ \ominus \_$ is defined as 
$(m_1 \ominus m_2)(s) = max\{m_1(s) - m_2(s), 0\}$.
The {\em scalar product} of a number $j$ with $m$ is the multiset $j \cdot m$ defined as
$(j \cdot m)(s) = j \cdot (m(s))$. By $s_i$ we also denote the multiset with $s_i$ as its only element.
Hence, a multiset $m$ over $S = \{s_1, \ldots, s_n\}$
can be represented as $k_1\cdot s_{1} \oplus k_2 \cdot s_{2} \oplus \ldots \oplus k_n \cdot s_{n}$,
where $k_j = m(s_{j}) \geq 0$ for $j= 1, \ldots, n$.
\fine
\end{definition}


\begin{definition}\label{pt-net-def}{\bf (Place/Transition Petri net)}
A labeled {\em Place/Transition} Petri net (P/T net, for short) is a tuple $N = (S, A, T)$, where
\begin{itemize}
\item 
$S$ is the finite set of {\em places}, ranged over by $s$ (possibly indexed),
\item 
$A$ is the finite set of {\em labels}, ranged over by $a, b, c, ...$ (possibly indexed), and
\item 
$T \subseteq {(\mathcal M}(S) \setminus \{\theta\}) \times A \times {\mathcal M}(S)$ 
is the finite set of {\em transitions}, 
ranged over by $t$ (possibly indexed).
\end{itemize}

Given a transition $t = (m, a, m')$,
we use the notation $\pre t$ to denote its {\em pre-set} $m$ (which cannot be an empty multiset) of tokens to be consumed, $\ell(t)$ for its {\em label} $a$, and $\post t$ to denote its {\em post-set} $m'$ of tokens to be produced.
%Hence, transition $t$ can be represented as $\pre t \deriv{\ell(t)} \post t$.
We define the  function
$\mathsf{flow}: (S \times T) \cup (T \times S) \rightarrow \nat$ as follows:
for all $s \in S$, for all $t \in T$,
$\mathsf{flow}(s,t) = \pre{t}(s)$ and $\mathsf{flow}(t,s) = \post{t}(s)$
(note that $\pre{t}(s)$ and $\post{t}(s)$ are integers, representing the multiplicity of $s$ in $\pre{t}$ and $\post{t}$, respectively).
We denote by $F$ the {\em flow relation} 
$\{(x,y) \mid x,y \in S \cup T \, \wedge \, \mathsf{flow}(x,y) > 0\}$.
Finally, we 
define pre-sets and post-sets for places as follows: $\pre s = \{t \in T \mid s \in \post t\}$
and $\post s = \{t \in T \mid s \in \pre t\}$. 
%Note that while the pre-set (post-set) of a transition is, 
%in general, a multiset, the pre-set (post-set) of a place is a set. 
\fine
\end{definition}

Graphically, a place is represented by a little circle and a transition by a little box. These are 
connected by directed arcs, which
may be labeled by a positive integer, called the {\em weight}, to denote the number of tokens 
consumed (when the arc goes from a place to the transition) or produced (when the arc goes form the transition to a
place) by the execution of the transition;
if the number is omitted, then the weight default value of the arc is $1$.

\begin{definition}\label{net-system}{\bf (Marking, P/T net system)}
Given a P/T Petri net $N = (S, A, T)$, a multiset over $S$  is called a {\em marking}. Given a marking $m$ and a place $s$, 
we say that the place $s$ contains $m(s)$ {\em tokens}, graphically represented by $m(s)$ bullets
inside place $s$.
A {\em P/T net system} $N(m_0)$ is a tuple $(S, A, T, m_{0})$, where $(S,A, T)$ is a P/T net and $m_{0}$ is  
a marking over $S$, called
the {\em initial marking}. We also say that $N(m_0)$ is a {\em marked} net.
\fine
\end{definition}


\begin{definition}\label{firing-system}{\bf (Enabling, firing sequence, reachable marking, safe net)}
Given a P/T Petri net $N = (S, A, T)$, a transition $t $ is {\em enabled} at a marking $m$, 
denoted by $m[t\rangle$, if $\pre t \subseteq m$. 
The execution (or {\em firing}) of  $t$, enabled at $m$, produces the marking $m' = (m \ominus  \pre t) \oplus \post t$. 
This is written $m[t\rangle m'$. 
A {\em firing sequence} starting at $m$ is defined inductively as follows:
\begin{itemize}
\item $m[\epsilon\rangle m$ is a firing sequence (where $\epsilon$ denotes an empty sequence of transitions) and
\item if $m[\sigma\rangle m'$ is a firing sequence and $m' [t\rangle m''$, then
$m [\sigma t\rangle m''$ is a firing sequence. 
\end{itemize}
The set of {\em reachable markings} from $m$ is 
$[m\rangle = \{m' \mid  \exists \sigma.$ $
m[\sigma\rangle m'\}$. 
The P/T net system $N = $ $(S, A, T, m_0)$ is  {\em safe} if  for each 
$m \in [m_0\rangle$ and for all $s \in S$, we have $m(s) \leq 1$.
\fine
\end{definition}

Note that the reachable markings of a P/T net can be countably infinitely many when the net is not bounded, i.e.,
when the number of tokens on some places can grow unboundedly.

Now we recall a simple behavioral equivalence on P/T nets, defined directly over the markings of the net, which 
compares two markings with respect to their sequential behavior.

\begin{definition}\label{def-int-bis}{\bf (Interleaving Bisimulation)}
Let $N = (S, A, T)$ be a P/T net. 
An {\em interleaving bisimulation} is a relation
$R\subseteq {\mathcal M}(S) \times {\mathcal M}(S)$ such that if $(m_1, m_2) \in R$
then
\begin{itemize}
\item $\forall t_1$ such that  $m_1[t_1\rangle m'_1$, $\exists t_2$ such that $m_2[t_2\rangle m'_2$ 
with $\ell(t_1) = \ell(t_2)$ and $(m'_1, m'_2) \in R$,
\item $\forall t_2$ such that  $m_2[t_2\rangle m'_2$, $\exists t_1$ such that $m_1[t_1\rangle m'_1$ 
with $\ell(t_1) = \ell(t_2)$ and $(m'_1, m'_2) \in R$.
\end{itemize}
Two markings $m_1$ and $m_2$ are {\em interleaving bisimilar}, 
denoted by $m_1 \sim_{int} m_2$, if there exists an interleaving bisimulation $R$ such that $(m_1, m_2) \in R$.
\fine
\end{definition}

Interleaving bisimilarity was proved undecidable in \cite{Jan95} for P/T nets having at least two unbounded places, 
with a proof based on the comparison of two {\em sequential} P/T nets, 
where a P/T net is sequential if it does not offer any concurrent behavior. Hence, interleaving bisimulation equivalence is 
undecidable even for the subclass of sequential finite P/T nets. Esparza observed in \cite{Esp98} that over sequential P/T nets
all the non-interleaving 
bisimulation-based equivalences (in the spectrum ranging from interleaving bisimilarity to fully-concurrent bisimilarity \cite{BDKP91})
collapse to interleaving bisimilarity.
Hence, the proof in \cite{Jan95} applies to all these
non-interleaving bisimulation equivalences as well.


%%%
\subsection{Place Bisimulation}\label{place-bis-sec}
%%%

We now present the place bisimulation idea, introduced originally in \cite{ABS91}.
This proposal is an 
improvement of a behavioral relation proposed earlier by Olderog in \cite{Old} on safe 
nets (called {\em strong bisimulation}), which was not transitive. 
First, an auxiliary definition.

\begin{definition}\label{add-eq}{\bf (Additive closure)}
Given a P/T net $N = (S, A, T)$ and a {\em place relation} $R \subseteq S \times S$, we define a {\em marking relation}
$R^\oplus \, \subseteq \, {\mathcal M}(S) \times {\mathcal M}(S)$, called 
the {\em additive closure} of $R$,
as the least relation induced by the following axiom and rule.\\

$\begin{array}{lllllllllll}
 \bigfrac{}{(\theta, \theta) \in  R^\oplus} & \;   &   \; 
 \bigfrac{(s_1, s_2) \in R \quad  (m_1, m_2) \in R^\oplus }{(s_1 \oplus m_1, s_2 \oplus m_2) \in  R^\oplus }  \\
\end{array}$
\\[-.2cm]
\fine
\end{definition}

Note that, by definition, two markings are related by $R^\oplus$ only if they have the same size; 
in fact, the axiom states that
the empty marking is related to itself, while the rule, assuming by induction 
that $m_1$ and $m_2$ have the same size, ensures that $s_1 \oplus m_1$ and
$s_2 \oplus m_2$ have the same size.

\begin{proposition}\label{fin-k-add}
For each relation $R \subseteq S \times S$,  if $(m_1, m_2) \in R^\oplus$, 
then $|m_1| = |m_2|$.
\fine
\end{proposition}

Note also that the membership $(m_1, m_2) \in R^\oplus$ may be proved in several different 
ways, depending on the chosen order of the elements
of the two markings and on the definition of $R$. For instance, if $R = \{(s_1, s_3),$ 
$(s_1, s_4),$ $(s_2, s_3), (s_2, s_4)\}$,
then $(s_1 \oplus s_2, s_3 \oplus s_4) \in R^\oplus$ can be proved by means 
of the pairs $(s_1, s_3)$ and $(s_2, s_4)$,
as well as by means of $(s_1, s_4), (s_2, s_3)$.
An alternative way to define that two markings $m_1$ and $m_2$
are related by $R^\oplus$ is to state that $m_1$ can be represented as $s_1 \oplus s_2 \oplus \ldots \oplus s_k$, 
$m_2$ can be represented as $s_1' \oplus s_2' \oplus \ldots \oplus s_k'$ and $(s_i, s_i') \in R$ for $i = 1, \ldots, k$. 

\begin{proposition}\label{add-prop1}\cite{Gor17b,Gor25a}
For each relation $R \subseteq S \times S$, the following hold:
\begin{enumerate}
\item If $R$ is an equivalence relation, then $R^\oplus$ is an equivalence relation.
\item If $R_1 \subseteq R_2$, then $R_1^\oplus \subseteq R_2^\oplus$, i.e., the additive closure is monotone.
\item If $(m_1, m_2) \in R^\oplus$ and $(m_1', m_2') \in R^\oplus$,
then $(m_1 \oplus m_1', m_2 \oplus m_2') \in R^\oplus$, i.e., the additive closure is additive.
\item If $R$ is an equivalence relation, $(m_1 \oplus m_1', m_2 \oplus m_2') \in  R^\oplus$ and $(m_1, m_2) \in R^\oplus$,
then $(m_1', m_2') \in R^\oplus$, i.e., the additive closure is subtractive.
\item  If $(m_1, m_2) \in  R^\oplus$ and $m_1' \subseteq m_1$, then there exists $m_2' \subseteq m_2$
such that $(m_1', m_2') \in R^\oplus$ and $(m_1 \ominus m_1', m_2 \ominus m_2') \in R^\oplus$. \\[-1cm]
\end{enumerate}
\fine
\end{proposition}

We are now ready to introduce place bisimulation, which is a non-interleaving behavioral 
relation defined over the net places.

\begin{definition}\label{def-place-bis}{\bf (Place Bisimulation)}
Let $N = (S, A, T)$ be a P/T net. 
A {\em place bisimulation} is a relation
$R\subseteq S \times S$ such that if $(m_1, m_2) \in R^\oplus$
then
\begin{itemize}
\item $\forall t_1$ such that  $m_1[t_1\rangle m'_1$, $\exists t_2$ such that $m_2[t_2\rangle m'_2$ 
with $(\pre{t_1}, \pre{t_2}) \in R^\oplus$, $\ell(t_1) = \ell(t_2)$,  $(\post{t_1}, \post{t_2}) \in R^\oplus$ and, moreover, 
$(m_1', m_2') \in R^\oplus$; and symmetrically,
\item $\forall t_2$ such that  $m_2[t_2\rangle m'_2$, $\exists t_1$ such that $m_1[t_1\rangle m'_1$ 
with $(\pre{t_1}, \pre{t_2}) \in R^\oplus$, $\ell(t_1) = \ell(t_2)$,  $(\post{t_1}, \post{t_2}) \in R^\oplus$ and, moreover, 
$(m_1', m_2') \in R^\oplus$.
\end{itemize}
Two markings $m_1$ and $m_2$ are  {\em place bisimilar}, denoted by
$m_1 \sim_p m_2$, if there exists a place bisimulation $R$ such that $(m_1, m_2) \in R^\oplus$.
\fine
\end{definition}

Note that the two matching transitions $t_1$ and $t_2$ in the place bisimulation game must have essentially the same shape 
because $(i)$ $(\pre{t_1}, \pre{t_2}) \in R^\oplus$ implies that
$|\pre{t_1}| = |\pre{t_2}|$, then $(ii)$ $\ell(t_1) = \ell(t_2)$ and, finally, $(iii)$  
from $(\post{t_1}, \post{t_2}) \in R^\oplus$
we derive that $|\post{t_1}| = |\post{t_2}|$. 

\begin{proposition}\label{place-bis-eq}\index{Bisimulation!equivalence}\cite{ABS91,Gor21decid,Gor25a}
For each P/T net $N = (S, A, T)$, relation $\sim_p \; \subseteq  \mathcal{M}(S) \times  \mathcal{M}(S)$ is an
equivalence relation.
\fine
\end{proposition}

\begin{proposition}\label{place-int-prop}{\bf (Place bisimilarity is finer than interleaving bisimilarity)}
Given a P/T net $N = (S, A, T)$ and two markings $m_1, m_2$, if $m_1 \sim_p m_2$, then $m_1 \sim_{int} m_2$.
\proof
If $m_1 \sim_p m_2$, then there exists a place bisimulation $R$ such that $(m_1, m_2) \in R^\oplus$.
Note that if $R$ is a place bisimulation, then $R^\oplus$ is an interleaving bisimulation, and so $m_1 \sim_{int} m_2$.
\fine
\end{proposition}

The implication above is strict, i.e., one can find two markings that are interleaving bisimilar 
but not place bisimilar. For instance, the markings $s_1$ (that is a singleton)
and $s_4 \oplus s_5$ (that has size 2) in Figure~\ref{p>int-fig} are not place bisimilar, as they have different size, but are clearly interleaving bisimilar.


