\subsection{Structure-preserving Bisimulation}\label{sp-bis-sec}
%
%%%

In order to introduce this behavioral relation \cite{G15}, some auxiliary notation is needed.

\begin{definition}\label{link-def}{\bf (Link and linking)}\index{Link}\index{Linking}
Let $N = (S, A, T)$ be a P/T Petri net. 
A {\em link} is a pair $(s_1, s_2) \in S \times S$. 
A {\em linking} $l$
is a multiset of links, i.e.,
$l: S \times S \rightarrow \nat$ where $dom(l)$ is finite as $S$ is finite.
With abuse of notation, we denote by $\theta$ the empty linking, i.e., the empty multiset of links.
Given a set $L$ of links, we denote by $\mathcal{M}(L)$ the set of all the linkings over $L$. 
Given a linking $l$, the two projected markings $m_1$ and $m_2$ can be defined as

$m_1(s_1) = \pi_1(l)(s_1) =  \sum_{s_2 \in S} l(s_1, s_2)$ and 
$m_2(s_2) = \pi_2(l)(s_2) =  \sum_{s_1 \in S} l(s_1, s_2)$. 

\noindent
For instance, if $l = \{(s_1, s_2), (s_1', s_2')\}$, then $\pi_1(l) = s_1 \oplus s_1'$
and $\pi_2(l) = s_2 \oplus s_2'$. %; instead, if $l = \theta$, then $\pi_1(l) = \theta$
%and $\pi_2(l) = \theta$, i.e., $l$ is projected on the empty marking.
Note that the notation $(m_1, m_2) \in R^\oplus$ actually means that there exists a 
linking $l \in \mathcal{M}(R)$ such that
$\pi_1(l) = m_1$ and $\pi_2(l) = m_2$. As a matter of fact, a linking $l$ can be seen as a triple 
$(m_1, f, m_2)$, where $m_1$ and $m_2$ are
markings of the same size, and $f$ is a bijection between them.

We will use $l$, $\overline{l}$, $h$, $\overline{h}$, $c$ and $\overline{c}$, possibly indexed, to range over linkings.
As linkings are multisets, we can use the operations defined over multisets, such as union 
$\oplus$ and difference $\ominus$.
For instance, $(l \oplus c)(s_1, s_2) = l(s_1, s_2) + c(s_1, s_2)$. Moreover, a linking 
composed of a single link $(s_1, s_2)$
is denoted simply by its element, as we did for multisets in general. So, for instance, the 
linking $l = \{(s_1, s_2), (s_1', s_2')\}$
is often simply denoted by $l = (s_1, s_2) \oplus (s_1', s_2')$. 
\fine
\end{definition}


 \begin{definition}\label{def-sp1-bis}{\bf (Structure Preserving Bisimulation)}
Let $N = (S, A, T)$ be a P/T Petri net. 
A {\em structure-preserving bisimulation} (sp-bisimulation, for short)
is a set $R$ of linkings such that if $l \in R$, then $\forall c \subseteq l$, 
\begin{enumerate}
\item $\forall t_1$ such that $\pre{t_1} = \pi_1(c)$, there exist a transition $t_2$ 
such that $\ell(t_1) = \ell(t_2)$, $\pre{t_2} = \pi_2(c)$, and a linking $\overline{c}$ such that 
$\post{t_1} = \pi_1(\overline{c})$, $\post{t_2} = \pi_2(\overline{c})$ and $(l \ominus c) \oplus \overline{c} = \overline{l}  \in R$; 
\item $\forall t_2$ such that $\pre{t_2} = \pi_2(c)$, there exist a transition $t_1$ 
such that $\ell(t_1) = \ell(t_2)$, $\pre{t_1} = \pi_1(c)$, and a linking $\overline{c}$ such that 
$\post{t_1} = \pi_1(\overline{c})$, $\post{t_2} = \pi_2(\overline{c})$ and $(l \ominus c) \oplus \overline{c} = \overline{l} \in R$.
\end{enumerate}
Two markings $m_1$ and $m_2$ are  {\em structure-preserving} bisimulation equivalent (or, simply, sp-bisimilar), denoted by
$m_1 \sim_{sp} m_2$, if there exists a linking $l$ in a structure preserving bisimulation 
$R$ such that $m_1 = \pi_1(l)$
and $m_2 = \pi_2(l)$.
\fine
\end{definition}\index{Structure-preserving bisimulation!equivalence}

Note that the two matching transitions $t_1$ and $t_2$ in the structure-preserving bisimulation 
game must have essentially the same shape 
because $(i)$ $\pre{t_1} = \pi_1(c)$ and $\pre{t_2} = \pi_2(c)$ implies that
$|\pre{t_1}| = |\pre{t_2}|$, then $(ii)$ $\ell(t_1) = \ell(t_2)$ and, finally, $(iii)$  from $\post{t_1} = \pi_1(\overline{c})$ and $\post{t_2} = \pi_2(\overline{c})$
we derive that $|\post{t_1}| = |\post{t_2}|$. 

It is possible to prove that the definition of structure-preserving bisimulation is coinductive, as the 
union of sp-bisimulations is an sp-bisimulation. Moreover, for each P/T Petri net $N = (S, A, T)$, 
$\sim_{sp}$ is an equivalence relation. Moreover, $\sim_{sp}$ is decidable on bounded nets \cite{CG21a},
while the decidability on finite P/T Petri nets is open, as the observation in \cite{Esp98} does not apply to it.

Moreover, it is also possible to prove \cite{G15,Gor25a} that if $R$ is a place 
bisimulation, then $\mathcal{M}(R)$ is a
structure-preserving bisimulation, hence proving that $m_1 \sim_p m_2$ implies $m_1 \sim_{sp} m_2$. 
This implication is strict, as illustrated by the following example.


