\subsection{Fully Concurrent Bisimulation}\label{fc-bis-sec}
%
%%%

Causal-net bisimilarity observes not only the partial order of generated events, but also the size of the
current distributed state, as it observes the causal nets. A coarser behavioral equivalence, ignoring the size 
of the distributed state and the shape of transitions, is
{\em fully concurrent bisimulation} (fc-bisimulation, for short) \cite{BDKP91}, whose definition
was inspired by previous equivalence notions on other concurrency models:
{\em history-preserving bisimulation}, originally defined in \cite{RT88} under the name of {\em behavior-structure bisimulation}, and 
then elaborated on in \cite{vGG89} (who called it by this name) and also independently defined in \cite{DDM89} 
(who called it {\em mixed ordering bisimulation}). Its definition follows.

\begin{definition}\label{sfc-bis-def}{\bf (Fully concurrent bisimulation)}
Given a P/T net $N = (S, A, T)$, a {\em fully concurrent bisimulation} (fc-bisimulation, for short)
is a relation $R$, composed of 
triples of the form $(\pi_1, g, \pi_2) $, where, for $i = 1,2$, 
$\pi_i = (C_i, \rho_i)$ is a process of $N(m_{0i})$ for some $m_{0i}$ and
$g$ is an event isomorphism between $\mathsf{E}_{C_1}$ and $\mathsf{E}_{C_2}$, such that  
if $(\pi_1, g, \pi_2) \in R$ then
\begin{enumerate}
\item 
$\forall t_1, \pi_1'$ such that $\pi_1 \deriv{e_1} \pi_1'$ with $\rho_1'(e_1) = t_1$, 
$\exists t_2, \pi_2', g'$ such that
\begin{enumerate} 
%$(i)$ 
\item $\pi_2 \deriv{e_2} \pi_2'$ with $\rho_2'(e_2) = t_2$;
% $(ii)$ 
\item $g' = g \cup \{(e_1, e_2)\}$, and finally,
%$(iii)$ 
\item $(\pi_1', g', \pi_2') \in R$;
\end{enumerate}
\item and symmetrically, if $\pi_2$ moves forward first.
\end{enumerate}
Two markings $m_1, m_2$ are fully concurrent bisimilar,
denoted $m_1 \sim_{fc} m_2$, if a fully concurrent bisimulation R exists,
containing a triple $(\pi^0_1, \emptyset, \pi^0_2)$ where 
$\pi^0_i = (C^0_i, \rho^0_i)$ is such that 
$C^0_i$ contains no events (i.e., $E^0_i = \emptyset$) and 
$\rho^0_i(Min(C^0_i))  = \rho^0_i(Max(C^0_i))$ $ = m_i\;$ for $i = 1, 2$.
\fine
\end{definition}


\begin{definition}\label{hsfc-bis-def}{\bf (Hereditary fully concurrent bisimulation)}
Given a P/T net $N = (S, A, T)$, a {\em hereditary} fully concurrent bisimulation
(hfc-bisimulation, for short) is an fc-bisimulation such that  
if $(\pi_1, g, \pi_2) \in R$, then % and $E_1 \neq \emptyset \neq E_2$, then
\begin{enumerate}
\item
$\forall t_1, \pi_1'$ such that $\pi_1' \deriv{e_1} \pi_1$ with $\rho_1(e_1) = t_1$, 
$\exists t_2, \pi_2', g'$ such that
%\begin{enumerate}
%\item 
$(i)$ $\pi_2' \deriv{e_2} \pi_2$ with $\rho_2(e_2) = t_2$;
 $(ii)$ $g' = g \setminus \{(e_1, e_2)\}$, and finally,
$(iii)$ $(\pi_1', g', \pi_2') \in R$;
%\end{enumerate}
\item and symmetrically, if $\pi_2$ moves backward first.
\end{enumerate}
Two markings $m_1, m_2$ are hereditary fully concurrent bisimilar,
denoted $m_1 \sim_{hfc} m_2$, if a hereditary fully concurrent bisimulation R exists,
containing a triple $(\pi^0_1, \emptyset, \pi^0_2)$ where 
$\pi^0_i = (C^0_i, \rho^0_i)$ is such that 
$C^0_i$ contains no events (i.e., $E^0_i = \emptyset$) and 
$\rho^0_i(Min(C^0_i))  = \rho^0_i(Max(C^0_i))$ $ = m_i\;$ for $i = 1, 2$.
\fine
\end{definition}

Of course, $\sim_{cn} = \sim_{hcn}$ is finer than $\sim_{hfc}$. 
This can be proved by observing that 
if $R_1$ is a causal-net bisimulation,
then 
$R_2 = \{(C, \rho_1), id, (C, \rho_2) $ $\mid (\rho_1, C, \rho_2) \in R_1\}$, 
 where $id$ is 
the identity function on $E$, is an hfc-bisimulation.

We can summarize the relationships among the behavioral equivalences discussed in this paper as follows: 
$\sim_p \subset \sim_{hcn} = \sim_{cn} = \sim_{sp} \subset \sim_{hfc} \subset \sim_{fc} \subset \sim_{int}$. In words,
place bisimilarity is the finest behavioral equivalence, which
is finer than (hereditary) causal-net bisimilarity (or, equivalently, 
sp-bisimilarity), in turn finer than hereditary fully concurrent bisimilarity,
in turn finer than fully concurrent bisimilarity, in turn finer than interleaving bisimilarity. All inclusions are strict.
An example showing that $\sim_p$ is finer than $\sim_{cn}$ is outlined in Figure \ref{net-sp-place};
examples showing that causal-net bisimilarity is finer than hereditary fully concurrent bisimilarity are 
outlined in Figure \ref{net-fc-place} and Figure \ref{cn-vs-icn-fig}.


